var EXPLAIN = {
"1": {"point": "「踏切」は訓読みで「ふみきり」。動詞「踏み切る」の連用形が名詞になった語で、「踏」は連用形の「ふみ」、「切」は連濁せず「きり」と読む。", "meaning": "鉄道の線路と道路が同じ高さで交差している所。", "kr": "건널목", "opts": ["ふむきり：「踏む」の終止形の形。名詞は連用形「ふみ」から作るので誤り", "", "ふむぎり：「ふむ」も「ぎり」も誤り", "ふみぎり：「切」は連濁せず「きり」"], "ex": "電車が近づいて、<b>踏切</b>の警報機が鳴り始めた。"},
"2": {"point": "「緩い」は「ゆるい」。締め方が足りず、すき間やゆとりがある様子。「緩む（ゆるむ）」「緩める（ゆるめる）」と同じ読み。音読みは「カン」（緩和）。", "meaning": "締まり方が足りず、ゆとりがありすぎる様子。", "kr": "느슨하다, 헐겁다", "opts": ["もろい＝脆い（壊れやすい）。「緩」の読みではない", "かたい＝固い・硬い。「緩」の読みではない", "きつい：締まりすぎている様子で、「緩い」とは反対の意味", ""], "ex": "ベルトが<b>緩く</b>なったので、穴を一つずらした。"},
"3": {"point": "「姿勢」は音読みで「しせい」。「姿（シ）」「勢（セイ）」とも清音。「せー」と長く発音される音も、仮名では「せい」と書く（先生＝せんせい）。", "meaning": "体の構え。また、物事に取り組む態度・心構え。", "kr": "자세", "opts": ["", "しぜい：「勢」は濁らない（「大勢＝おおぜい」のように濁る語もあるが、「姿勢」は「せい」）", "しせえ：発音は「せー」と聞こえるが、仮名で書くと「しせい」", "しぜえ：濁音も表記も誤り"], "ex": "長時間パソコンを使うときは、<b>姿勢</b>に気をつけたほうがいい。"},
"4": {"point": "「慎重」は「しんちょう」。「慎（シン）」は「慎む（つつしむ）」の音読み。「重」はここでは「チョウ」と読む（貴重・尊重と同じ）。", "meaning": "注意深く、軽々しく行動しないこと。", "kr": "신중", "opts": ["ちんちょう：「慎」はチンと読まない（「珍重＝珍しいものとして大切にする」は別の語）", "", "ちんじゅう：「慎」も「重」も読みが違う（「珍獣＝珍しい動物」は別の語）", "しんじゅう：「重」をジュウと読む誤り（「心中」は別の語）"], "ex": "大切な契約なので、<b>慎重</b>に検討してから決めたい。"},
"5": {"point": "「懐く」は訓読みで「なつく」。動物や子どもが人に慣れて親しむこと。「懐かしい（なつかしい）」と同じ「なつ」。音読みは「カイ」（懐中）、ほかの訓読みに「ふところ」がある。", "meaning": "人に慣れて、親しみを持ってそばに寄ってくる。", "kr": "따르다, 길들다", "opts": ["まごついて＝まごつく（どうしてよいかわからず迷う）。ふつう仮名で書く語", "なげいて＝嘆いて（悲しんで、ため息をつく）", "そむいて＝背いて（逆らう・従わない）。意味はほぼ反対", ""], "ex": "引っ越してきた子猫が、ようやく家族に<b>懐いて</b>きた。"},
"6": {"point": "「既に」は「すでに」。「もう・それより前に」という意味の副詞。音読みは「キ」（既婚・既存）。", "meaning": "もう。その時より前に。", "kr": "이미, 벌써", "opts": ["さらに＝更に（その上、もっと）", "いかに＝如何に（どれほど・どのように）", "", "いやに（妙に、ひどく）。「既」の読みではない"], "ex": "駅に着いたときには、最終電車は<b>既に</b>出てしまっていた。"},
"7": {"point": "「思惑が外れる」は、前もって考えていた見込みや期待のとおりにならないこと。「〜が外れて残念そう」とあるので、見込み・期待の意味の「思惑」が合う。", "meaning": "前もって考えていた見込み・期待。", "kr": "생각, 예상, 의도", "opts": ["魂胆＝心の中に隠したたくらみ（「何か魂胆がある」）。悪い意味が強く、「外れる」とは結びつかない", "下心＝表に出さない、よくないたくらみ。「下心が外れる」とは言わない", "本音＝本当の気持ち。「外れる」ものではない", ""], "ex": "雨で客が来ず、店の<b>思惑</b>は大きく外れた。"},
"8": {"point": "「てっきり〜と思っていた」は、確かにそうだと思い込んでいたが実際は違った、という言い方。後ろに「思っていた」があるので「てっきり」。", "meaning": "（後に「〜と思った」が続いて）きっとそうだと思い込んでいた様子。", "kr": "당연히 ~인 줄 (알았다)", "opts": ["めっきり＝変化がはっきり感じられる様子（「めっきり寒くなった」）", "", "こってり＝味や色が濃い様子（「こってりしたラーメン」）", "きっかり＝数量や時間がちょうど（「きっかり3時」）"], "ex": "<b>てっきり</b>休みだと思っていたら、店は開いていた。"},
"9": {"point": "「目標に向かって突き進む」は、困難をものともせず、まっすぐ勢いよく進むこと。努力を続ける様子をよい意味で表す。", "meaning": "勢いよく、まっすぐに進んでいく。", "kr": "돌진하다, 매진하다", "opts": ["", "突き飛ばして＝突き飛ばす（人などを強く突いて倒す）。対象が必要で、ここでは使えない", "突き落として＝突き落とす（突いて高い所から落とす）。対象が必要", "突っ走って＝突っ走る（勢いよく走る）。比喩では「周りを見ずに強引に進める」という響きがあり、目標に向かって努力する様子には「突き進む」が自然"], "ex": "彼女は夢に向かってひたすら<b>突き進んで</b>いる。"},
"10": {"point": "「〜に抗議する」は、相手の行為や決定に反対の意見を強く申し立てること。住民が建設に反対し工事が止まったので「抗議」。", "meaning": "相手の言動や決定に対して、反対の意見を強く申し立てること。", "kr": "항의", "opts": ["反論＝相手の意見や主張に、反対の論を述べること。意見に対して使い、「建設」のような行為には使いにくい", "", "口論＝言い争い。「〜に口論する」とは言わない", "反逆＝国や権力に背いて逆らうこと。住民の反対には大げさ"], "ex": "選手たちは審判の判定に強く<b>抗議</b>した。"},
"11": {"point": "「体力が衰える」は、年齢などで力が弱くなること。「衰えてきた」で、少しずつ弱くなってきた変化を表す。", "meaning": "勢いや力が弱くなる。", "kr": "쇠약해지다, 약해지다", "opts": ["さびて＝錆びる（金属がさびる）。体力には使わない", "やつれて＝やつれる（病気や心配で、顔や体が痩せ衰える）。見た目の変化で、「体力が」には合わない", "", "にぶって＝鈍る（「腕・勘・決心が鈍る」）。「体力が鈍る」とは普通言わない"], "ex": "年をとって、記憶力が<b>衰えて</b>きた。"},
"12": {"point": "「壮大な計画・プロジェクト」は、規模が大きく立派な様子。新社長が大規模な計画を発表する文脈に合う。", "meaning": "規模が大きく立派な様子。", "kr": "웅장한, 장대한", "opts": ["", "豪壮な＝建物などが大きく堂々としている様子（「豪壮な邸宅」）。計画には使わない", "広壮な＝建物が広く立派な様子（「広壮な屋敷」）。計画には使わない", "壮厳な：正しくは「荘厳（そうごん）」と書き、重々しく尊い様子。計画には使わない"], "ex": "宇宙の歴史を描いた<b>壮大な</b>物語に心を打たれた。"},
"13": {"point": "「ローテーションを組む」は、何人かが順番に交代して仕事をする計画を作ること。5人の医師が交代で24時間対応している。", "meaning": "順番に交代すること。交代の順番。", "kr": "교대, 로테이션", "opts": ["セクション＝部門・区分", "ロケーション＝場所・立地。撮影の現地", "ポジション＝地位・持ち場", ""], "ex": "店員は週ごとの<b>ローテーション</b>で休みを取っている。"},
"14": {"point": "「濁る」は訓読みで「にごる」。水などが透き通らなくなること。音読みは「ダク」（濁音・濁流）。", "meaning": "液体や空気に混ざり物があって、透明でなくなる。", "kr": "탁해지다, 흐려지다", "opts": ["", "くもって＝曇って（空が雲で覆われる・ガラスがぼんやりする）。水には「濁る」を使う", "どもって＝吃って（言葉がつかえて、すらすら出ない）", "たまって＝溜まって（水などが一か所に集まる）"], "ex": "雨の後は、川の水が茶色く<b>濁る</b>。"},
"15": {"point": "「怪しい」は「あやしい」。正体がわからず疑わしい様子。音読みは「カイ」（怪物・怪談）。", "meaning": "正体がわからず疑わしい。普通と違っていて気味が悪い。", "kr": "수상하다", "opts": ["めずらしい＝珍しい（めったにない）", "いやしい＝卑しい（品がない・下品だ）", "", "たくましい＝逞しい（体や心が強い）"], "ex": "夜中に家の前を<b>怪しい</b>人がうろうろしていた。"},
"16": {"point": "「納得」は「なっとく」。「納」は普通「ノウ」（納入）だが、この語では「ナッ」と読み、「得（トク）」が続く。", "meaning": "他人の考えや物事の理由をよく理解して、受け入れること。", "kr": "납득", "opts": ["のうどく：「納」も「得」も読みが違う", "のうとく：「納」を「ノウ」と読む誤り。この語では「なっ」", "なっどく：「得」は濁らず「とく」", ""], "ex": "説明を聞いて、ようやく<b>納得</b>がいった。"},
"17": {"point": "「厳か」は訓読みで「おごそか」。重々しく、近寄りがたい雰囲気。音読みは「ゲン・ゴン」（厳重・荘厳）、ほかの訓読みに「きびしい」がある。", "meaning": "重々しく、身が引き締まるような様子。", "kr": "엄숙하다", "opts": ["", "はなやか＝華やか（明るく派手で美しい）", "おろそか＝疎か（いいかげんにする様子）。形が似ているので注意", "しとやか＝淑やか（動作や話し方が上品で落ち着いている）"], "ex": "神社では新年の儀式が<b>厳か</b>に行われた。"},
"18": {"point": "「解除」は「かいじょ」。「解（カイ）」＋「除（ジョ）」。「除」は「削除（さくじょ）・掃除（そうじ）」のように「ジョ・ジ」と読み、「ショ」とは読まない。", "meaning": "制限・禁止・契約などを取りやめて、元の状態に戻すこと。", "kr": "해제", "opts": ["かいしょ：「除」を清音で読む誤り。正しくは「じょ」", "", "げしょ：「解」をゲと読むのは「解熱（げねつ）・解毒（げどく）」など一部の語だけ。「除」も清音で誤り", "げじょ：「解」をゲと読む誤り。この語は「かい」"], "ex": "台風が過ぎ去り、大雨警報が<b>解除</b>された。"},
"19": {"point": "「設ける」は訓読みで「もうける」。機会・場所・規則などを新しく作って用意すること。音読みは「セツ」（設置・設備）。「儲ける（もうける＝利益を得る）」とは同じ読みの別の語。", "meaning": "物事を行うための場所・機会・制度などを新たに用意する。", "kr": "마련하다, 설치하다", "opts": ["しつける＝躾ける（礼儀作法を教え込む）", "", "しかける＝仕掛ける（相手に働きかける・装置を取り付ける）", "さずける＝授ける（目上の者が与える）"], "ex": "会社は社員の意見を聞く場を<b>設けた</b>。"},
"20": {"point": "「大人になるために必要なプロセス」は、成長の途中で通る過程という意味。反抗期を成長の一段階として受け止める文脈に合う。", "meaning": "物事が進む道筋。過程。", "kr": "과정, 프로세스", "opts": ["アレンジ＝配置・手配。曲の編曲", "", "タイミング＝ちょうどよい時機", "セクション＝部門・区分"], "ex": "結果だけでなく、そこに至る<b>プロセス</b>も大切だ。"},
"21": {"point": "動詞の連用形＋「込む」で、その動作に熱中して長く続ける意味になる（話し込む・考え込む・眠り込む）。友人と思わず1時間も話した、という文脈に合う。", "meaning": "（動詞の連用形について）熱中して長く〜する。", "kr": "(오래) 열중해서 ~하다", "opts": ["通して＝〜通す（最後まで続けてやり抜く。「歩き通す」）。「つい〜てしまった」という無意識の様子に合わない", "詰めて＝〜詰める（「思い詰める・問い詰める」）。「話し詰める」とは普通言わない", "かけて＝話しかける（相手に声をかける）。1時間続いた様子は表せない", ""], "ex": "難しい問題に、彼はじっと考え<b>込んで</b>いる。"},
"22": {"point": "「利益を社会へ還元する」は、得た利益を、それを生んだ社会や客に返して役立てること。決まった言い方。", "meaning": "得た利益などを、元の所（社会・客など）に返すこと。", "kr": "환원", "opts": ["", "返還＝借りた物・取り上げた物を元の持ち主に返すこと（「領土の返還」）。寄付や支援の意味はない", "募金＝寄付金を集めること（または募金に応じて寄付すること）。利益を社会に返す意味はない", "譲渡＝権利や財産を他人に譲り渡すこと。法律的な語で文脈に合わない"], "ex": "売り上げの一部は、地域の子どもたちに<b>還元</b>されている。"},
"23": {"point": "「養う」は、生活に必要なものを与えて世話をし、生活させること。兄が進学をあきらめて弟や妹の生活を支えた、という文脈に合う。", "meaning": "生活の面倒を見る。扶養する。", "kr": "부양하다, 먹여 살리다", "opts": ["", "稼いで＝稼ぐ（働いてお金を得る）。対象はお金で、「私たちを稼ぐ」とは言わない", "施して＝施す（恵みとして与える）。「人を施す」とは言わない", "労わって＝労わる（いたわる：弱い者を大切に扱う）。気づかいの意味で、生活を支える意味はない"], "ex": "彼は一人で働いて、家族四人を<b>養って</b>いる。"},
"24": {"point": "「あっけない」は、予想よりも簡単に終わってしまい、物足りない様子。振り返りもしない短い別れの様子に合う。", "meaning": "予想外に簡単で、物足りない。", "kr": "허무하다, 싱겁다", "opts": ["だらしない＝きちんとしていない・しまりがない", "なにげない＝特別な考えや意図がない様子", "", "きりがない＝終わりがない・限りがない"], "ex": "優勝候補のチームが一回戦で<b>あっけなく</b>負けた。"},
"25": {"point": "「守備が手薄だ」は、守る人数や備えが足りない様子。後ろの「攻撃すればすぐに点が奪える」と合う。", "meaning": "人手や備えが少なくて、十分でないこと。", "kr": "허술함, 손이 부족함", "opts": ["軽薄＝考えや言動が軽々しく、誠実さがないこと。人の性格に使う", "", "強固＝しっかりしていて揺るがない。点が取りやすいという文脈と反対", "頑丈＝作りがしっかりしていて壊れにくい。文脈と反対"], "ex": "夜間は警備が<b>手薄</b>になるので注意が必要だ。"},
"26": {"point": "「心配りができる」は、相手のことを考えてあれこれ気を配れること。人の長所としてほめる言い方。", "meaning": "相手のために、あれこれと気を配ること。", "kr": "배려, 마음 씀씀이", "opts": ["心当たり＝思い当たること（「心当たりがある」）", "気負い＝張り切りすぎる気持ち。「気負いができる」とは言わない", "", "気心＝その人の性質や考え方（「気心が知れた仲」）"], "ex": "客一人ひとりへの細やかな<b>心配り</b>が、この旅館の魅力だ。"},
"27": {"point": "「慌てる」は「あわてる」。急なことに落ち着きを失い、急いで行動すること。音読みは「コウ」（恐慌）。", "meaning": "驚いたり急いだりして、落ち着きを失う。", "kr": "당황하다, 허둥대다", "opts": ["あれてて：「慌」は「あわ」と読み、「あれ」とは読まない", "", "かれてて：「慌」の読みではない", "かわてて：「慌」の読みではない（「か」ではなく「あ」）"], "ex": "地震のときは<b>慌てず</b>、まず身の安全を確保しよう。"},
"28": {"point": "「道端」は訓読み＋訓読みで「みちばた」。「端（はた）」が連濁して「ばた」になる（井戸端＝いどばた、川端＝かわばた）。", "meaning": "道のすぐそば。道のへり。", "kr": "길가", "opts": ["", "みちはじ：「端」は「はし・はた」と読むが、「はじ」とは読まない", "どうたん：「道端」を音読みで読むことはない", "どうてん：「端」をテンとは読まない（「動転」は別の語）"], "ex": "<b>道端</b>に自転車を止めないでください。"},
"29": {"point": "「破裂」は「はれつ」。「破（ハ）」＋「裂（レツ）」。「裂」は「裂ける（さける）」の音読み（分裂・決裂）。内側からの圧力で勢いよく破れること。", "meaning": "内側からの力で、勢いよく裂けて破れること。", "kr": "파열", "opts": ["はかい＝破壊（壊すこと）。「裂」はカイと読まない", "", "ほうかい＝崩壊（崩れ落ちること）。別の語", "ほうれつ：「破」をホウと読む誤り"], "ex": "寒さで水道管が<b>破裂</b>した。"},
"30": {"point": "「柔軟」は「じゅうなん」。「柔（ジュウ）」は「柔道」の「じゅう」。「軟（ナン）」は「軟らかい（やわらかい）」の音読みで、「ネン」とは読まない。", "meaning": "やわらかく、しなやかなこと。考え方が一つにこだわらず、状況に合わせられること。", "kr": "유연", "opts": ["じゅうねん：「軟」をネンと読む誤り", "ゆうねん：「柔」も「軟」も読みが違う", "", "ゆうなん：「柔」をユウと読む誤り"], "ex": "予定が変わっても、<b>柔軟</b>に対応できる人は頼りになる。"},
"31": {"point": "「名残」は「なごり」と読む特別な読み方。物事が過ぎ去った後に残る気配や、別れるときの心残り。「名残惜しい」は、別れがつらく離れがたいという意味。", "meaning": "物事が過ぎた後に残る気配・影響。別れを惜しむ気持ち。", "kr": "아쉬움, 자취", "opts": ["", "のこり：「残」だけの読み（残り）。「名」が読まれていない", "めいざん：音読みを当てはめた誤り。「名残」はこう読まない", "みょうざん：音読みを当てはめた誤り"], "ex": "夏の<b>名残</b>を感じさせる暑い日が続いている。"},
"32": {"point": "「淡い」は「あわい」。色・味などが薄く軽い様子。音読みは「タン」（淡水・冷淡）。", "meaning": "色・味・香りなどが薄くて軽い。感情がかすかである。", "kr": "연하다, 옅다", "opts": ["しぶい＝渋い（地味で落ち着いている・渋い味）", "もろい＝脆い（壊れやすい）", "やわい（柔らかい・弱いの意の、くだけた言い方）。「淡」の読みではない", ""], "ex": "春らしい<b>淡い</b>ピンクのセーターを買った。"},
"33": {"point": "「発覚」は、隠れていた悪事や問題が表に出ること。「エラーが発覚する」のように、問題そのものを主語にして使える。", "meaning": "隠されていた悪事・秘密・問題などが明らかになること。", "kr": "발각, 드러남", "opts": ["開示＝情報などを明らかにして示すこと。人や組織が行う行為で、「エラーが開示する」とは言わない", "暴露＝秘密や悪事をあばいて公にすること（また、それが明るみに出ること）。隠された秘密・悪事に使い、プログラムのエラーには合わない", "摘発＝悪事をあばいて公にすること。主に警察などが行う", ""], "ex": "会社の不正が、内部の告発によって<b>発覚</b>した。"},
"34": {"point": "「番組を見逃す」は、見るつもりだったものを見る機会を失うこと。帰宅が遅く見られなかった、という文脈に合う。", "meaning": "見る機会を失う。見落とす。", "kr": "놓치다", "opts": ["", "見過ごして＝見過ごす（見ていながら気づかない・知っていて黙って許す）。番組を見られなかった意味ではない", "見通して＝見通す（先のことを予測する・遠くまで見る）", "見越して＝見越す（将来を予測して、それに備える）"], "ex": "楽しみにしていた試合の中継を<b>見逃して</b>しまった。"},
"35": {"point": "「ほほえましい」は、見ていて思わずほほえみたくなるような、心温まる様子。幼い娘が妹にお菓子を分ける姿に合う。", "meaning": "見ていて、思わずほほえみたくなる様子。", "kr": "흐뭇하다", "opts": ["ねづよくて＝根強い（なかなか変わらない・しっかり根を張っている）", "めざましくて＝目覚ましい（驚くほどすばらしい）。成長や活躍に使い、この場面には合わない", "", "おっかなくて＝おっかない（怖い。話し言葉）"], "ex": "公園で遊ぶ親子の姿が<b>ほほえましい</b>。"},
"36": {"point": "「目途（めど）が立つ」は、物事の見通しがつくこと。仕事が一段落する見通しがついたら連絡する、という文脈に合う。", "meaning": "目途（めど）：目標。物事の見通し。", "kr": "목표, 전망", "opts": ["", "展望＝広く見渡すこと・将来の見通し（「展望が開ける」）。「展望が立つ」とは言わない", "意図＝何かをしようとする考え・ねらい", "設計＝建物や機械などの計画を立てること"], "ex": "資金の<b>目途</b>が立ったので、工事を始めることにした。"},
"37": {"point": "「ねだる」は、甘えたり無理に頼んだりして、物を買ってもらうこと。子どもが父に時計を買ってもらった場面に合う。", "meaning": "甘えたり無理を言ったりして、ほしい物を求める。", "kr": "조르다", "opts": ["つつしんで＝慎んで・謹んで（控えめにして・うやうやしく）", "", "おもねて：「おもねる（気に入られようとこびる）」のことだが、て形は「おもねって」。意味も合わない", "へりくだって＝へりくだる（相手を敬い、自分を低くする）"], "ex": "子どもにおもちゃを<b>ねだられて</b>、つい買ってしまった。"},
"38": {"point": "「高度な文明」は、程度・水準が高い文明。技術や文化の発達の程度を表すには「高度な」を使う。", "meaning": "程度や水準が高いこと。", "kr": "고도의", "opts": ["上等な＝品質がよい（「上等な服」）。主に物に使う", "高尚な＝程度が高く上品な（「高尚な趣味」）。文明の発達の度合いには使わない", "上級な：「上級」は等級や学年が上のこと（「上級クラス」）。「上級な」という言い方はしない", ""], "ex": "この手術には<b>高度な</b>技術が必要だ。"},
"39": {"point": "「ドライ」は、感情に流されず、物事を割り切って考える性格のこと。「泣かないと思う」と合う。", "meaning": "感情に流されず、割り切っている様子。", "kr": "냉정하다, 감정에 휘둘리지 않다", "opts": ["インテリ＝知識人。泣く・泣かないとは関係がない", "", "ロマンチック＝夢や情緒を大切にする様子。泣きそうな性格で、文脈と反対", "タイト＝きつい・余裕がない（「タイトなスケジュール」）。性格には使わない"], "ex": "彼は仕事の人間関係を<b>ドライ</b>に割り切っている。"},
"40": {"point": "「厳重」は「げんじゅう」。「厳（ゲン）」＋「重（ジュウ）」。「重」は「慎重（しんちょう）」のようにチョウとも読むが、この語はジュウ。", "meaning": "少しの手落ちもないよう、きびしく行う様子。", "kr": "엄중", "opts": ["げんちょう：「重」をチョウと読む誤り。この語は「じゅう」", "がんじゅう：「厳」をガンと読む誤り", "", "がんじょう＝頑丈（作りが丈夫で壊れにくい）。別の語"], "ex": "重要な書類は金庫に<b>厳重</b>に保管されている。"},
"41": {"point": "「勝る」は「まさる」。他と比べて上である、優れているという意味。「これに勝る喜びはない」は「これ以上の喜びはない」という決まった言い方。「勝つ（かつ）」と同じ字だが読みが違う。", "meaning": "他と比べて、程度や価値が上である。", "kr": "낫다, 뛰어나다", "opts": ["", "たえる＝耐える・堪える（我慢する）", "かつる：「勝つ」と混同した形で、こういう語はない", "こえる＝超える・越える（ある程度より上になる）。意味は近いが「勝」の読みではない"], "ex": "健康に<b>勝る</b>宝はない。"},
"42": {"point": "「愚か」は「おろか」。考えが足りず、ばかげている様子。音読みは「グ」（愚問・愚痴）。", "meaning": "知恵や判断力が足りない様子。ばかげている。", "kr": "어리석다", "opts": ["おろそかな＝疎かな（いいかげんにする）。一字違いに注意", "おおらかな＝大らかな（心が広く、細かいことにこだわらない）", "おごそかな＝厳かな（重々しい）", ""], "ex": "同じ失敗を何度も繰り返すのは<b>愚かな</b>ことだ。"},
"43": {"point": "「催促」は「さいそく」。「催（サイ）」は「催す（もよおす）」、「促（ソク）」は「促す（うながす）」の音読み。早くするよう相手に求めること。", "meaning": "早くするように相手をせきたてること。", "kr": "재촉", "opts": ["そくせい：「催」をセイとは読まない（「促成・速成」は別の語）", "", "ようせい＝要請（必要なことを願い求める）。「催促」の読みではない", "とくそく＝督促（期限までに行うよう強く求める）。意味は近いが「催」はトクと読まない"], "ex": "家賃の支払いが遅れて、大家さんから<b>催促</b>された。"},
"44": {"point": "「枠」は訓読みで「わく」。周りを囲む縁取り、また決められた範囲。「採用の枠」は採用する人数の範囲。「枠」は日本で作られた字（国字）で、音読みはない。", "meaning": "周りを囲むもの。物事の決められた範囲・制限。", "kr": "틀, 테두리", "opts": ["", "いき＝域（ある範囲・段階。「名人の域」）。「枠」の読みではない", "みぞ＝溝（地面を細長く掘った所）", "ふち＝縁（物のへり）"], "ex": "予算の<b>枠</b>の中で計画を立てる。"},
"45": {"point": "「煩わしい」は「わずらわしい」。面倒で気が重い様子。動詞「煩う（わずらう）」から。音読みは「ハン・ボン」（煩雑・煩悩）。", "meaning": "面倒で、関わるのが嫌だと感じる様子。", "kr": "번거롭다, 귀찮다", "opts": ["いまわしい＝忌まわしい（不吉で嫌な感じがする）", "うるわしい＝麗しい（美しい・心温まる）", "", "そぐわしい：こういう語はない（「そぐわない＝似合わない」と混同しない）"], "ex": "毎日届くメールの整理が<b>煩わしい</b>。"},
"46": {"point": "「消費者のニーズに合わせる」は、消費者が求めていることに合わせること。売れる商品づくりの文脈に合う。", "meaning": "必要・要求。需要。", "kr": "니즈, 수요", "opts": ["", "ルーズ＝だらしない（「時間にルーズ」）", "ニュアンス＝言葉などの微妙な意味合い", "ケア＝世話・手入れ（「肌のケア」）"], "ex": "高齢者の<b>ニーズ</b>に応えるサービスが増えている。"},
"47": {"point": "「処方」は、医者が病気に合わせて薬の種類や量を決めること。「薬を処方してもらう」は決まった言い方。", "meaning": "医者が病状に合わせて薬の種類や量を指示すること。", "kr": "처방", "opts": ["処分＝不要な物を捨てる・違反を罰すること", "処遇＝人をどのように扱うか。待遇", "処理＝物事を片付けること（「データ処理」）", ""], "ex": "医者に<b>処方</b>された薬を、毎食後に飲んでいる。"},
"48": {"point": "「雄大」は、景色などが大きく堂々としている様子。山頂からの景色を見て自分の小ささを感じる、という文脈に合う。", "meaning": "規模が大きく、堂々としている様子。", "kr": "웅대하다, 웅장하다", "opts": ["過大＝大きすぎること（「過大評価」）", "盛大＝大規模で盛んなこと（「盛大なパーティー」）。景色には使わない", "", "大胆＝度胸があり、思い切ったことをする様子"], "ex": "飛行機の窓から、<b>雄大</b>な富士山が見えた。"},
"49": {"point": "「由緒ある」は、古くから続く立派な歴史や来歴がある、という意味の決まった言い方。江戸時代から続く店に合う。", "meaning": "物事の起こりと、今までの歴史。（「由緒ある」＝古くからの立派な歴史がある）", "kr": "유서", "opts": ["", "継承＝地位・財産・伝統などを受け継ぐこと。「継承ある」とは言わない", "経歴＝その人のこれまでの学業・仕事の歴史。主に人に使う", "因縁＝前から決まっている関係・宿命。言いがかりの意味もある（「因縁をつける」）"], "ex": "京都には<b>由緒</b>ある寺がたくさんある。"},
"50": {"point": "「変化に乏しい」は、変化が少ない、という意味。「〜に乏しい」の形で使う。同じことの繰り返しの毎日に合う。", "meaning": "少ない。十分でない。", "kr": "부족하다, 빈약하다", "opts": ["はかない＝儚い（すぐに消えてしまいそうで、むなしい）。「〜にはかない」とは言わない", "あさましい＝浅ましい（品がなく、心が卑しい）", "", "たわいない（取るに足りない・張り合いがない）。「〜にたわいない」とは言わない"], "ex": "この地域は天然資源に<b>乏しい</b>。"},
"51": {"point": "「言い張る」は、周りが何と言おうと自分の主張を曲げずに言い続けること。容疑者が犯行を否定し続けている文脈に合う。", "meaning": "自分の主張を強く言い続けて、曲げない。", "kr": "우기다, 끝까지 주장하다", "opts": ["言い付けて＝言い付ける（命令する・告げ口する）", "言い寄って＝言い寄る（好きな相手に近づいて口説く）", "言い聞かせて＝言い聞かせる（よくわかるように話して教える）", ""], "ex": "弟は自分は悪くないと<b>言い張って</b>、謝ろうとしない。"},
"52": {"point": "「そばをすする」は、音を立てて口に吸い込みながら食べること。勢いよく食べて汁がはねた、という文脈に合う。", "meaning": "汁や麺などを、音を立てて吸い込むように飲食する。", "kr": "후루룩 마시다(먹다)", "opts": ["つった＝釣る・吊る（魚を釣る・物を吊り下げる）", "", "あせった＝焦る（思うようにならず、いらいらする）", "うなった＝唸る（苦しそうな声や低い声を出す）"], "ex": "熱いスープをゆっくり<b>すすった</b>。"},
"53": {"point": "「控える」は「ひかえる」。ここでは、量や回数を少なめにする・やめておくという意味。音読みは「コウ」（控除）。", "meaning": "度を越さないように、量や回数を少なくする。", "kr": "삼가다, 자제하다", "opts": ["おさえて＝抑えて・押さえて（勢いを止める）。意味は近いが「控」の読みではない", "きたえて＝鍛えて（練習を重ねて強くする）", "そなえて＝備えて（前もって準備する）", ""], "ex": "医者に言われて、塩分を<b>控える</b>ようにしている。"},
"54": {"point": "「快く」は「こころよく」。気持ちよく、嫌な顔をせずに。「快い（こころよい）」の連用形。音読みは「カイ」（快適・愉快）。", "meaning": "気持ちよく。嫌がらずに喜んで。", "kr": "흔쾌히", "opts": ["", "いさぎよく＝潔く（未練を残さず、思い切りよく）", "ここちよく＝心地よく（気持ちがいい）。意味は近いが「快」一字ではこう読まない", "かっこよく＝格好よく（見た目や態度がすてきに）"], "ex": "先輩は急な頼みも<b>快く</b>聞いてくれた。"},
"55": {"point": "「織物」は「おりもの」。「織る（おる）」の連用形「おり」＋「物（もの）」。「織」の音読みは「ショク・シキ」（組織＝そしき）。", "meaning": "糸を縦横に組み合わせて作った布。", "kr": "직물", "opts": ["しきもつ：「織」をシキ、「物」をモツと読む誤り", "しきもの＝敷物（床に敷くもの）。別の語", "おりもつ：「物」はここでは「もの」と読む", ""], "ex": "京都の西陣は、高級な<b>織物</b>で知られている。"},
"56": {"point": "「検討」は「けんとう」。「検（ケン）」＋「討（トウ）」とも清音。よく調べて、良いか悪いかを考えること。同じ読みの「見当」と文脈で区別する。", "meaning": "よく調べて考えること。", "kr": "검토", "opts": ["", "げんとう：「検」は濁らない（「幻灯」は別の語）", "けんどう：「討」は濁らない（「剣道」は別の語）", "げんどう：どちらも濁らない（「言動」は別の語）"], "ex": "ご提案については、来週の会議で<b>検討</b>します。"},
"57": {"point": "「有無」は「うむ」。「有」は普通「ユウ」だが、この語では「ウ」と読む（有頂天＝うちょうてん）。「無」は「ム」。あるかないか、という意味。", "meaning": "あることとないこと。あるかないか。", "kr": "유무", "opts": ["ゆうむ：「有」をユウと読む誤り。この語は「う」", "ゆうぶ：「有」も「無」も読みが違う（「無」をブと読むのは「無事（ぶじ）」など）", "", "うぶ：「無」をブと読む誤り（「うぶ＝世慣れていない」は別の語）"], "ex": "経験の<b>有無</b>は問いません。"},
"58": {"point": "「田舎」は「いなか」と読む熟字訓。一字ずつの読みを当てはめても読めない特別な読み方。都会から離れた所、また故郷のこと。", "meaning": "都会から離れた、田畑や自然の多い地方。故郷。", "kr": "시골", "opts": ["でんしゃ：音読みを当てはめた誤り（「電車」とは別）", "", "たしゃ：「田」の訓「た」と「舎」の音「シャ」を当てはめた誤り", "いなが：濁らず「いなか」"], "ex": "夏休みに<b>田舎</b>の祖父母の家へ帰った。"},
"59": {"point": "「アクセスがいい」は、目的地への交通の便がいいこと。通勤が長くて嫌になったので会社に行きやすい家に引っ越した、という文脈に合う。", "meaning": "目的地までの交通の便。", "kr": "접근성, 교통편", "opts": ["リーチ＝手の届く範囲。主にボクシングなどで使う", "ロード＝道路", "", "ターミナル＝鉄道やバスの終点・発着所"], "ex": "このホテルは空港への<b>アクセス</b>がよい。"},
"60": {"point": "「打ち解ける」は、遠慮や警戒がなくなって親しくなること。「初対面の人ともすぐに」と合う。", "meaning": "遠慮がなくなって、心を開いて親しくなる。", "kr": "마음을 터놓다, 허물없이 지내다", "opts": ["打ち込む（熱中する・強く打って入れる）", "", "打ち合わせる＝前もって相談する", "打ち消す＝否定する"], "ex": "合宿で一緒に過ごすうちに、新しい仲間とも<b>打ち解けた</b>。"},
"61": {"point": "「赴任」は、仕事のために任地へ行くこと。「海外に赴任する」は決まった言い方。", "meaning": "命じられた任地へ行くこと。", "kr": "부임", "opts": ["転換＝方向・方針などを別のものに変えること", "", "任命＝ある役職につくよう命じること。「〜を…に任命する」の形で、「海外に任命する」とは言わない", "採用＝人を雇うこと・意見などを取り上げて使うこと"], "ex": "父は単身でシンガポールに<b>赴任</b>している。"},
"62": {"point": "「目覚ましい活躍」は、目が覚めるほどすばらしい活躍。年に5本の映画に出る、という後の文に合う。", "meaning": "目覚ましい（めざましい）：驚くほどすばらしい。", "kr": "눈부시다", "opts": ["相応しい（ふさわしい）＝よく似合う・釣り合っている。活躍の程度を表さない", "", "儚い（はかない）＝すぐに消えてしまいそうでむなしい。文脈と反対", "甚だしい（はなはだしい）＝程度がひどい。「甚だしい誤解」のように悪い意味で使う"], "ex": "この町は近年、<b>目覚ましい</b>発展を遂げた。"},
"63": {"point": "「温和な性格」は、穏やかで優しい性格。そういう人が怒っているから「余程のことがあった」と推測できる。", "meaning": "性格が穏やかで優しい様子。", "kr": "온화한", "opts": ["円滑な＝物事がすらすらと進む様子（「円滑な運営」）。性格には使わない", "良質な＝品質がよい。物に使う", "濃厚な＝味などが濃い・可能性が高い（「濃厚な味」）", ""], "ex": "祖父は<b>温和な</b>人で、怒った顔を見たことがない。"},
"64": {"point": "「手入れがしやすい髪型」は、自分で整えたり世話をしたりしやすい髪型。「手入れ」は、よい状態を保つために世話をすること。", "meaning": "よい状態を保つために、整えたり直したりすること。", "kr": "손질", "opts": ["", "手際＝物事を処理する腕前（「手際がいい」）。「手際がしやすい」とは言わない", "手触り＝手で触ったときの感じ", "手間＝ある事にかかる時間や労力（「手間がかかる」）"], "ex": "庭の木の<b>手入れ</b>を植木屋さんに頼んだ。"},
"65": {"point": "「声援」は、声を出して応援すること。「聞こえてきた」とあるので、耳に聞こえる応援の声。", "meaning": "声をかけて励まし、応援すること。", "kr": "성원, 응원", "opts": ["共鳴＝他人の考えに深く共感すること・音が響き合うこと", "期待＝よい結果を望んで待つこと。耳に「聞こえてくる」ものではない", "名声＝世間のよい評判", ""], "ex": "観客の<b>声援</b>を受けて、選手たちは最後まで走り抜いた。"},
"66": {"point": "「ことごとく」は「一つ残らず全部」という意味の副詞。案が一つ残らず却下された、ということなので「残らず全て」が最も近い。", "meaning": "残らず全部。すべて。", "kr": "모조리, 남김없이", "opts": ["", "次々と＝続けて、一つの後にまた一つ。数の多さではなく、続く様子", "即座に＝その場ですぐに。時間の早さで、量の意味はない", "容赦なく＝手加減せずに、厳しく"], "ex": "台風で、畑の野菜は<b>ことごとく</b>だめになった。"},
"67": {"point": "「気兼ね」は、相手の気持ちを気にして遠慮すること。「気兼ねする」≒「遠慮する」。", "meaning": "他人に気をつかって、遠慮すること。", "kr": "어려워함, 눈치 봄", "opts": ["考えすぎて＝必要以上に考えて。遠慮の意味はない", "悩んで＝どうしたらよいか苦しんで", "", "落ち込んで＝気分が沈んで"], "ex": "ここは自分の家だと思って、<b>気兼ね</b>なく過ごしてください。"},
"68": {"point": "「あやふや」は、はっきりせず、確かでない様子。「曖昧」も、はっきりしない様子を表すので最も近い。", "meaning": "はっきりせず、確かでない様子。", "kr": "애매함, 불확실함", "opts": ["簡潔＝短くて、要点がまとまっている様子", "", "無難＝欠点や危険がなく、特に問題がない様子", "無邪気＝素直で悪気がない様子"], "ex": "記憶が<b>あやふや</b>で、正確な日付が思い出せない。"},
"69": {"point": "「せわしい」は「忙しい・落ち着かない」という意味。引っ越しで忙しい日々なので「いそがしい」が最も近い。", "meaning": "用事が多くて落ち着かない。忙しい。", "kr": "바쁘다, 분주하다", "opts": ["むなしい＝空しい（中身がない・かいがない）", "", "わずらわしい＝煩わしい（面倒で嫌だ）。忙しさそのものではない", "おもいがけない＝思いがけない（予想していなかった）"], "ex": "年末は何かと<b>せわしい</b>。"},
"70": {"point": "「過ち」は、やりそこなうこと・間違い。「過ちを恐れず」は「失敗を恐れず」と言い換えられる。", "meaning": "やりそこない。間違い。", "kr": "잘못, 실수", "opts": ["非難＝相手の欠点や間違いを責めること", "指摘＝問題点などを具体的に示すこと", "危険＝危ないこと", ""], "ex": "若い頃の<b>過ち</b>を、今も後悔している。"},
"71": {"point": "「憤慨」は、ひどく腹を立てること。「激怒した」が最も近い。", "meaning": "不正や理不尽なことに、ひどく腹を立てること。", "kr": "분개", "opts": ["恐縮した＝相手に申し訳なく思って身が縮む思いをした", "共感した＝相手と同じ気持ちになった。反対に近い", "", "困惑した＝どうしてよいかわからず困った"], "ex": "不公平な判定に、観客は<b>憤慨</b>した。"},
"72": {"point": "「気さく」は、気取らず親しみやすい人の性格・態度を表す。「気さくな人」「気さくに話す」のように人について使う。④は森田さんの話しぶりなので正しい。", "meaning": "気取らず、親しみやすい様子。", "kr": "싹싹하다, 허물없다", "opts": ["「気さく」は人の性格に使い、会社には使わない → 自由な雰囲気の会社", "共感の仕方を表す語ではない → 素直に（すんなり）共感できる", "「無警戒に・簡単に」の意味はない → 気軽に（すぐに）ついて行ってしまう", ""], "ex": "社長は<b>気さくな</b>人で、新入社員にもよく話しかけてくれる。"},
"73": {"point": "「ほつれる」は、縫い目や編み目、束ねた髪などの糸がほどけて乱れること。②のタオルの糸が当てはまる。", "meaning": "縫い目・編み目・束ねた髪などがほどけて乱れる。", "kr": "올이 풀리다, 흐트러지다", "opts": ["結んだものがゆるむのは「ほどける」 → 帯がほどけないように", "", "気持ちがゆるむのは「ほぐれる」 → 緊張がほぐれた", "糸の乱れではない → 花束が崩れて（乱れて）"], "ex": "セーターの袖口が<b>ほつれて</b>きた。"},
"74": {"point": "「見込む」は、将来のことを予想して、それを計算に入れること。「〜を見込んで…する」の形で使う。④は観光客の増加を予想して施設を建てたので正しい。", "meaning": "将来どうなるかを予想して、計算に入れる。", "kr": "예상하다, 전망하다", "opts": ["頼りにする意味は「当てにする」 → 親の収入を当てにして", "根拠なく信じるのは「思い込む」 → いないと信じている（思い込んでいる）", "試験問題を推し量るのは「予想する」 → 出る問題を予想して（ヤマをかけて）", ""], "ex": "来年度は売り上げの増加が<b>見込まれて</b>いる。"},
"75": {"point": "「とっさに」は、考える時間もないほど急な場面で、反射的に何かをする様子。①は責められた瞬間に思わず嘘をついたので正しい。", "meaning": "考える間もなく、その瞬間に。", "kr": "순간적으로, 엉겁결에", "opts": ["", "指示を受けて行う仕事は反射的な動作ではない → すぐに（ただちに）報告書を仕上げた", "気づかないうちに寝るのは「いつの間にか」 → いつの間にか寝てしまった", "用が済んで急いで帰る様子は「さっさと」 → さっさと帰って行った"], "ex": "ボールが飛んできて、<b>とっさに</b>顔を手で覆った。"},
"76": {"point": "「手回し」は、前もって準備や手配をしておくこと。「手回しがいい」の形でよく使う。③は加藤さんの準備がよかったので正しい。", "meaning": "前もって準備・手配をしておくこと。", "kr": "사전 준비, 채비", "opts": ["物を配る意味はない → プリントを回して（配って）", "品物を用意する意味では使わない → 袋の用意（手配）をお願いした", "", "料理の準備は「下ごしらえ」 → 野菜を切って下ごしらえしておいた"], "ex": "彼女は<b>手回し</b>がよく、出発前にすべての予約を済ませていた。"},
"77": {"point": "「雑談」は、特に目的のない、気楽なおしゃべり。①は上司との気楽な話について述べているので正しい。", "meaning": "特に目的のない、気楽な話。", "kr": "잡담", "opts": ["", "雑談は書いて載せるものではない → アニメの感想（レビュー）を掲載している", "世間の騒ぎの意味はない → 大きな騒ぎ（話題）になってしまう", "人を笑わせる言葉は「冗談」。「雑談を言う」とは言わない → 冗談を言って"], "ex": "会議の前に少し<b>雑談</b>をして、場を和ませた。"},
"78": {"point": "「いくぶん」は「少し・いくらか」という意味。「やや」が最も近い。", "meaning": "少し。いくらか。", "kr": "다소, 약간", "opts": ["はなはだ＝非常に。程度が大きい", "", "きわめて＝この上なく。程度が大きい", "おおいに＝大いに、たくさん。程度が大きい"], "ex": "薬を飲んで、痛みは<b>いくぶん</b>和らいだ。"},
"79": {"point": "「復旧する」は、壊れたり止まったりしたものが元の状態に戻ること。「元通りになる」が最も近い。", "meaning": "壊れたものや止まったものが、元の状態に戻ること。", "kr": "복구되다", "opts": ["再起動する＝コンピューターなどをもう一度起動する。元に戻ることの一つの手段で、同じ意味ではない", "", "老朽化する＝古くなって役に立たなくなる", "廃れる（すたれる）＝使われなくなって衰える"], "ex": "地震で止まっていた電車が、夕方にようやく<b>復旧した</b>。"},
"80": {"point": "「おびえる」は、怖がってびくびくすること。「こわがっている」が最も近い。", "meaning": "怖がって、びくびくする。", "kr": "겁먹다, 무서워하다", "opts": ["", "うなっている＝唸る（低い声を出す）", "こごえている＝凍える（寒さで体が冷えて動かない）。寒い場面だが、気持ちの意味ではない", "うずくまっている＝体を丸めてしゃがみこむ。姿勢のことで、気持ちの意味ではない"], "ex": "雷の音に<b>おびえて</b>、犬がベッドの下に隠れた。"},
"81": {"point": "「窮屈だ」は、狭かったり小さかったりして、自由に動けない様子。首回りが窮屈なシャツは「きつい」シャツ。", "meaning": "狭くて自由に動けない。きつい。", "kr": "갑갑하다, 비좁다", "opts": ["心地よい＝気持ちがいい。反対の意味", "不快だ＝気分が悪い。窮屈だと不快かもしれないが、大きさが合わない意味はない", "", "ゆるい＝締まりがない。反対の意味"], "ex": "太ったせいで、去年のズボンが<b>窮屈</b>になった。"},
"82": {"point": "「ぞんざい」は、物事を丁寧にせず、いい加減に扱う様子。「いい加減に」が最も近い。", "meaning": "やり方が雑で、いい加減な様子。", "kr": "소홀히, 날림으로", "opts": ["", "気まぐれに＝その時の気分で、変わりやすく", "効率的に＝むだなく", "入念に＝細かいところまで念入りに。反対の意味"], "ex": "お客様の荷物を<b>ぞんざいに</b>扱ってはいけない。"},
"83": {"point": "「麓（ふもと）」は、山の下の方の、平地に続くあたり。「下の方」が最も近い。", "meaning": "山の下の方。山のすそ。", "kr": "기슭", "opts": ["頂上＝山のいちばん高い所。反対の意味", "中腹＝山の頂上と麓の中ほど", "", "上の方＝反対の意味"], "ex": "山の<b>麓</b>に小さな温泉宿がある。"},
"84": {"point": "「使い果たす」は、お金や力などを残らず全部使ってしまうこと。①はエネルギーを全部使って疲れ切ったので正しい。", "meaning": "残らず全部使ってしまう。", "kr": "다 써 버리다", "opts": ["", "使用が終わったという意味ではない → 使い終わったら", "物を最後まで使うのは「使い切る」 → きちんと使い切ってから", "時間を何かに使うのは「費やす」 → 部活動に費やしてしまった"], "ex": "旅行でお金を<b>使い果たして</b>しまった。"},
"85": {"point": "「かすむ」は、霧や涙などのために物がぼんやりして、はっきり見えなくなること。④は霧で目の前さえぼんやりしているので正しい。", "meaning": "霧・もや・涙などで、物がぼんやりして見えにくくなる。", "kr": "흐릿해지다, 뿌옇게 보이다", "opts": ["湯気でレンズが白くなるのは「曇る」 → 眼鏡が曇ってしまった", "朝日が昇るのは見えやすくなること。かすむのは見えにくくなること → 景色が明るくなってきた", "すれすれに触れて通るのは「かすめる」 → ボールが頭をかすめて", ""], "ex": "春の遠い山が<b>かすんで</b>見える。"},
"86": {"point": "「円満」は、争いや不満がなく、穏やかにうまくいっている様子。「円満な家庭」「円満に解決する」のように人間関係に使う。②が正しい。", "meaning": "争いや不満がなく、穏やかでうまくいっている様子。", "kr": "원만함", "opts": ["物事がとどこおりなく進むのは「円滑」 → 円滑な物資の輸送", "", "気持ちが満たされるのは「満足」 → ご満足のご様子（ご満悦）", "仕事の評価には使わない → 仕事ぶりは立派だ（申し分ない）"], "ex": "話し合いの結果、問題は<b>円満</b>に解決した。"},
"87": {"point": "「格差」は、収入・地位などの、上下の水準の差。①は都市部と農村部の収入の差なので正しい。", "meaning": "収入・地位・資格などの、程度や水準の差。", "kr": "격차", "opts": ["", "人を不当に区別する意味は「差別」。「格差的」とは言わない → 差別的な発言", "見た目の違いは上下の差ではない → 違いがわからない", "時間の長さの違いは単に「差」 → 所要時間に差はない"], "ex": "地域による医療の<b>格差</b>が問題になっている。"},
"88": {"point": "「延々と」は、終わりが見えないほど長く続く様子。③は友人と長く話し続けたので正しい。", "meaning": "終わりが見えないほど長く続く様子。", "kr": "끝없이, 장황하게", "opts": ["人の様子を表す語ではない → 生き生きとしている", "人が次々に来るのは「続々と」 → 乗客が続々と降りてきた", "", "髪の美しさは表さない → 髪の毛はつややか（さらさら）で"], "ex": "会議は結論が出ないまま<b>延々と</b>続いた。"},
"89": {"point": "「補足する」は、足りない部分を付け加えて補うこと。主に説明や情報について使う。④は資料にない部分を口で付け加えるので正しい。", "meaning": "足りないところを付け加えて補う。", "kr": "보충하다", "opts": ["物を強くするのは「補強」 → 窓が割れないように補強しておこう", "水分や栄養を取り入れるのは「補給」 → 水分を補給しないと", "欠けた人数を埋めるのは「補充」 → 欠員を補充する", ""], "ex": "先ほどの説明に、一点<b>補足</b>させてください。"},
"90": {"point": "「手分けする」は、一つの仕事を何人かで分けて受け持つこと。「何人かで協力して」が最も近い。", "meaning": "一つの仕事を、何人かで分担すること。", "kr": "분담하다, 나누어 맡다", "opts": ["あきらめないで＝最後まで続けて", "計画を練って＝よく考えて計画を作って", "手を抜かず＝いい加減にせず", ""], "ex": "家族で<b>手分けして</b>、部屋の掃除をした。"},
"91": {"point": "「いかにも」は、本当にそれらしい様子を表す。「いかにも兄がやりそうなこと」＝「まさに兄らしいこと」。", "meaning": "本当にそれらしく。まさに。", "kr": "정말로, 과연, 그야말로", "opts": ["なおさら＝いっそう、ますます", "", "わざわざ＝特別に手間をかけて", "かろうじて＝やっとのことで"], "ex": "<b>いかにも</b>高そうな時計をしている。"},
"92": {"point": "「すこやか」は、体も心も元気で丈夫な様子。「健康に」が最も近い。", "meaning": "体も心も元気で丈夫な様子。", "kr": "건강하게, 튼튼하게", "opts": ["おおらかに＝心が広く、細かいことにこだわらない様子で", "いさましく＝勇ましく（勇気があって力強く）", "優秀に：「優秀」は能力が優れていること。体の丈夫さの意味はない", ""], "ex": "子どもたちが<b>すこやかに</b>育つことを願っている。"},
"93": {"point": "「弁解」は、自分の失敗などについて事情を説明して、許してもらおうとすること。「言い訳」が最も近い。", "meaning": "言い訳。自分の立場を説明して、正当化しようとすること。", "kr": "변명", "opts": ["", "訂正＝誤りを直すこと", "知らんふり＝知っているのに知らないふりをすること", "後悔＝してしまったことを後で悔やむこと"], "ex": "遅刻の理由をいくら<b>弁解</b>しても、信じてもらえなかった。"},
"94": {"point": "「おだてる」は、ほめて相手をいい気分（得意）にさせること。「得意にさせないで」が最も近い。", "meaning": "ほめて、相手をいい気にさせる。", "kr": "추켜세우다, 치켜올리다", "opts": ["怒らせないで＝腹を立てさせないで", "馬鹿にしないで＝見下さないで。ほめる「おだてる」とは反対の方向", "誘惑しないで＝悪いことに誘い込まないで", ""], "ex": "<b>おだてられて</b>、つい高い服を買ってしまった。"},
"95": {"point": "「見苦しい」は、見ていて不快で、体裁が悪い様子。「みっともない」が最も近い。", "meaning": "見ていて不快である。体裁が悪い。", "kr": "꼴사납다, 보기 흉하다", "opts": ["あらっぽい＝荒っぽい（乱暴だ・大ざっぱだ）", "せわしない＝落ち着かない、忙しい", "", "めんどうくさい＝手間がかかって嫌だ"], "ex": "負けてから言い訳をするのは<b>見苦しい</b>。"},
"96": {"point": "「緩和する」は、厳しさや激しさの程度をやわらげること。「痛み・規制・混雑を緩和する」のように使う。④が正しい。", "meaning": "厳しさや激しさの程度をやわらげる。", "kr": "완화하다", "opts": ["雪が水になるのは「解ける」 → 雪が解けて流れ出す", "景気がよくなるのは「回復する」 → 景気が回復して", "締め付けのない服は「ゆったりした」 → ゆったりした服", ""], "ex": "政府は輸入の規制を<b>緩和する</b>方針だ。"},
"97": {"point": "「いきさつ」は、物事がそうなるまでの事情・経緯。②は急に引っ越すことになった事情なので正しい。", "meaning": "物事がそうなるまでの事情。経緯。", "kr": "경위, 자초지종", "opts": ["研究結果の裏付けには使わない → 根拠（過程）がはっきりしていない", "", "道の進み方は「道順」 → 駅までの道順", "作業の流れは「手順」 → 納品までの手順（流れ）"], "ex": "二人が結婚するまでの<b>いきさつ</b>を聞いた。"},
"98": {"point": "「めくる」は、紙など重なった薄いものの端を持ち上げて裏返すこと。「ページ・カレンダー・トランプをめくる」。①が正しい。", "meaning": "重なった紙などの端を持ち上げて、裏返す。", "kr": "넘기다, 젖히다", "opts": ["", "貼ってあるものを取るのは「はがす」 → 古い絆創膏をはがして", "食べ物の上下を返すのは「裏返す」 → ステーキを裏返して", "袖を上へ折り上げるのは「まくる」 → 袖をまくって"], "ex": "本のページを<b>めくる</b>音だけが、図書館に響いていた。"},
"99": {"point": "「いたずらに」は、むだに、意味もなく、という意味。「いたずらに時間が過ぎる」は決まった言い方。②が正しい。", "meaning": "むだに。意味もなく。", "kr": "헛되이, 쓸데없이", "opts": ["勝手な行動の意味はない → 生徒たちが勝手に（こっそり）", "", "訪問の口実には使わない → ついでにお邪魔しても", "量の多さは表さない → 宝石がふんだんに使われていて"], "ex": "<b>いたずらに</b>不安をあおるような報道は控えるべきだ。"},
"100": {"point": "「突き止める」は、調べて、わからなかったことを明らかにすること。「原因・正体・居場所を突き止める」。④が正しい。", "meaning": "調べて、わからなかったことを明らかにする。", "kr": "밝혀내다, 알아내다", "opts": ["見つかる意味は「発見される」 → ジャングルの奥地で発見された", "自分の行動を確認するのは「確かめる」 → 消したか確かめたほうがいい", "人を選ぶのは「見極める」 → 適切な人材を見極める（選び出す）", ""], "ex": "警察はついに犯人の居場所を<b>突き止めた</b>。"},
"101": {"point": "「大ざっぱ」は、細かい点にこだわらず、全体をおおまかにとらえる様子。「大ざっぱに見積もる」が正しい。", "meaning": "細かいところにこだわらず、おおまかな様子。", "kr": "대략적임, 대충", "opts": ["部屋の状態には使わない → 部屋が散らかっている", "物の形には使わない → リンゴは形が不ぞろい（不格好）だが", "", "服装には使わない → ラフな（気軽な）服装で"], "ex": "細かい予定は決めず、<b>大ざっぱ</b>な計画だけ立てた。"},
"102": {"point": "「いっそ」は、中途半端より思い切って別の極端なほうを選ぶ気持ちを表す。「どうせ遅れるなら、むしろ休もう」と言い換えられる。", "meaning": "思い切って。むしろ。", "kr": "차라리, 아예", "opts": ["やけに＝妙に、ひどく（「今日はやけに寒い」）", "すでに＝もう、以前に", "とかく＝ともすれば、あれこれと（「とかく人は他人を気にする」）", ""], "ex": "こんなに古いなら、修理するより<b>いっそ</b>買い替えたほうがいい。"},
"103": {"point": "「そっけない」は、相手への思いやりや関心が感じられず、冷たい様子。「つれない」も、相手に冷淡な様子を表すので最も近い。", "meaning": "思いやりや関心が感じられず、冷たい。", "kr": "쌀쌀맞다, 무뚝뚝하다", "opts": ["", "あどけない＝子どもらしく無邪気でかわいい", "ぎこちない＝動作や言葉が不自然で、なめらかでない", "ふがいない＝情けない、だらしない"], "ex": "声をかけたが、<b>そっけない</b>返事しか返ってこなかった。"},
"104": {"point": "「うやむや」は、物事がはっきりしないまま、決着がつかない様子。「あいまいな」が最も近い。", "meaning": "はっきりしないまま、ぼかされている様子。", "kr": "흐지부지함", "opts": ["ややこしい＝複雑で、わかりにくい", "", "さえない＝ぱっとしない・元気がない", "いい加減な＝無責任な・でたらめな。はっきりしないという中心の意味とは違う"], "ex": "事故の原因は<b>うやむや</b>のまま、調査が打ち切られた。"},
"105": {"point": "「領土」は、その国が治めている土地。「国土」が最も近い。", "meaning": "一つの国が治めている土地。", "kr": "영토", "opts": ["地域＝ある範囲の土地。国のものという意味はない", "一帯＝そのあたり全体", "範囲＝ある限られた広がり", ""], "ex": "島の<b>領土</b>をめぐって、両国は長く対立している。"},
"106": {"point": "「きしむ」は、物がこすれ合ってギシギシと音を立てること。「音が鳴る」が最も近い。", "meaning": "物と物がこすれ合って、ギシギシと音を立てる。", "kr": "삐걱거리다", "opts": ["水漏れする＝水がもれる", "", "腐っている＝木などが腐ってだめになっている", "壊れている＝使えない状態になっている。きしむのは壊れる前の状態"], "ex": "古いドアは開けるたびに<b>きしむ</b>。"},
"107": {"point": "「誇張する」は、実際より大げさに表現すること。「オーバーに」が最も近い。", "meaning": "実際より大げさに表すこと。", "kr": "과장하다", "opts": ["", "タフに＝たくましく、粘り強く", "シンプルに＝簡単に、飾らずに", "ユニークに＝独特に、個性的に"], "ex": "その記事は、事故の被害を<b>誇張して</b>伝えていた。"},
"108": {"point": "「行き詰まる」は、物事がそれ以上うまく進められなくなること。「経営・研究・交渉に行き詰まる」。②が正しい。", "meaning": "物事がそれ以上進められなくなる。", "kr": "막히다, 난관에 부딪치다", "opts": ["自然に終わる意味ではない → 20歳くらいで止まる", "", "反対の意味になってしまう → 最後までやり遂げる（やり抜く）", "管の中で物が詰まるのは「詰まる」 → ゴミが詰まって"], "ex": "研究に<b>行き詰まった</b>ときは、少し休むのもいい。"},
"109": {"point": "「かろうじて」は、やっとのことで、ぎりぎりのところで、という意味。よい結果がどうにか得られたときに使う。④が正しい。", "meaning": "やっとのことで。ぎりぎりのところで。", "kr": "간신히, 가까스로", "opts": ["よくない結果には使わない → 惜しくも不合格になってしまった", "依頼や期限には使わない → 遅くとも終電までには", "これからの意志には使わない → 何とかして（無理をして）車を買う", ""], "ex": "最後の問題が解けて、<b>かろうじて</b>合格点に届いた。"},
"110": {"point": "「うろたえる」は、思いがけないことに慌てて、どうしてよいかわからなくなること。②は浮気を問い詰められて慌てたので正しい。", "meaning": "思いがけないことに慌てて、取り乱す。", "kr": "당황하다, 허둥대다", "opts": ["体の疲れには使わない → 少し運動しただけで息切れする（ばてる）", "", "うろうろ歩き回る意味ではない（「うろつく」と混同しない） → 不審な人がうろついていた", "喜びには使わない → 思いがけないプレゼントに驚いて"], "ex": "突然名前を呼ばれて、彼は<b>うろたえた</b>。"},
"111": {"point": "「〜た拍子に」は、ある動作をしたはずみで、思いがけないことが起こる様子。③は自転車をよけた動作のはずみでスマホを落としたので正しい。", "meaning": "（「〜た拍子に」の形で）その動作のはずみ。その瞬間。", "kr": "~한 순간, ~하는 바람에", "opts": ["帰宅の動作がきっかけで電話が来たわけではない → 帰宅したとたんに（と同時に）", "予定した時期のきっかけは「機に」 → 来年の3月を機に", "", "前に動作がないと使えない → 暗い道で不意に背後から"], "ex": "立ち上がった<b>拍子</b>に、テーブルのコップを倒してしまった。"},
"112": {"point": "「精巧」は、細かいところまで巧みに作られている様子。主に物の作りに使う。④は偽物の作りが細かく巧みなので正しい。", "meaning": "細かいところまで巧みにできている様子。", "kr": "정교함", "opts": ["助言には使わない → 的確に（丁寧に）アドバイスを", "話し方には使わない → 詳細に話してください", "確認の仕方には使わない → 入念に（綿密に）確認する", ""], "ex": "この時計は<b>精巧</b>な技術で作られている。"},
"113": {"point": "「ねばる」は、あきらめずに根気よく続けること。①は最後まであきらめなかったので正しい。", "meaning": "あきらめずに、根気よく続ける。", "kr": "끈질기게 버티다", "opts": ["", "話が盛り上がるのは「弾む」 → 話が弾んで", "効果が続くのは「続く・持続する」 → 効果が続きます（持続します）", "疲れが消えないのは「残る」 → 昨日の疲れが残り"], "ex": "最後まで<b>ねばった</b>が、結局一点差で負けた。"},
"114": {"point": "「再三」は、二度も三度も、何度も繰り返す様子。「たびたび」が最も近い。", "meaning": "何度も。たびたび。", "kr": "재삼, 여러 번", "opts": ["", "せっかく＝わざわざ努力したのに（むだになった）", "とっくに＝ずっと前に", "ふたたび＝もう一度。一回だけ繰り返す意味で、「何度も」とは違う"], "ex": "<b>再三</b>注意したのに、彼はまた同じミスをした。"},
"115": {"point": "「ありふれた」は、どこにでもあって珍しくない様子。「平凡な」が最も近い。", "meaning": "どこにでもあって、珍しくない。", "kr": "흔해 빠진, 평범한", "opts": ["質素な＝ぜいたくをせず、つつましい", "孤独な＝ひとりぼっちの", "", "半端な＝中途半端な、そろっていない"], "ex": "<b>ありふれた</b>材料でも、工夫すればおいしい料理になる。"},
"116": {"point": "「すみやか」は、時間をかけずにすばやく行う様子。「迅速に」が最も近い。", "meaning": "時間をかけずに、すばやく。", "kr": "신속하게", "opts": ["未然に＝まだ起こらないうちに", "着々と＝順調に一歩ずつ。速さの意味は弱い", "丁寧に＝注意深く、細かいところまで", ""], "ex": "地震の際は、<b>すみやかに</b>避難してください。"},
"117": {"point": "「思い返す」は、過去のことをもう一度思い出して考えること。「回顧する」が最も近い。", "meaning": "過去のことを、もう一度思い出して考える。", "kr": "돌이켜 보다, 회고하다", "opts": ["憶測する＝根拠もなく、いいかげんに推し量る", "推測する＝わかっていることから、わからないことを推し量る", "予期する＝前もって予想して待つ。未来のことに使う", ""], "ex": "子どもの頃を<b>思い返す</b>と、懐かしい気持ちになる。"},
"118": {"point": "「うっとうしい」は、じゃまに感じて気分がすっきりしない様子。何度もかかってくる電話を嫌がっているので「煩わしい」が最も近い。", "meaning": "じゃまで不快に感じる。気分が晴れない。", "kr": "성가시다, 짜증스럽다", "opts": ["腹立たしい＝腹が立つ。怒りが中心で、じゃまに感じる意味とは違う", "", "手ごわい＝相手が強くて、簡単には勝てない", "悩ましい＝悩みが多くて苦しい"], "ex": "前髪が伸びて目にかかり、<b>うっとうしい</b>。"},
"119": {"point": "「糸口」は、問題を解決するためのきっかけ・手がかり。「ヒント」が最も近い。", "meaning": "物事を解決するきっかけ。手がかり。", "kr": "실마리", "opts": ["", "サポート＝支援、手助け", "メリット＝利点、長所", "プラス＝利益になること、有利な点"], "ex": "彼の一言が、問題を解決する<b>糸口</b>になった。"},
"120": {"point": "「投げ出す」は、責任を持つべきことを途中で放棄してやめること。①は腹を立てて仕事を放り出したので正しい。", "meaning": "途中で放棄して、やめてしまう。", "kr": "내팽개치다, 포기하다", "opts": ["", "遊びを一時やめるだけなら「やめる」 → ゲームはやめて（切り上げて）", "不要な物を処分するのは「捨てる」 → 古くなったから捨ててしまおう", "店の判断でやめるのは「取りやめる」 → サラダの提供を取りやめて（中止して）"], "ex": "彼は困難な仕事を途中で<b>投げ出す</b>ような人ではない。"},
"121": {"point": "「禁物」は、悪い結果を招くので、してはいけないこと。「無理は禁物」「油断は禁物」のように使う。②が正しい。", "meaning": "悪い結果を招くので、避けるべきこと。", "kr": "금물", "opts": ["規則で禁じるのは「禁止」 → 持ち込みは禁止となっております", "", "取ってはいけない物の意味ではない → 許可なく他人の松茸を採ってはいけない", "法を破る行為は「罪」 → 若いころに罪を犯し"], "ex": "試験前の夜ふかしは<b>禁物</b>だ。"},
"122": {"point": "「忠実」には「誠実に務めを果たす」と「元のものをそのまま正確に再現する」の意味がある。①は映画の世界をそのまま再現しているので正しい（後者の意味）。", "meaning": "務めを誠実に果たす様子。元のものを正確に再現する様子。", "kr": "충실함", "opts": ["", "移動手段の確かさは「確実」 → 電車のほうが確実だ", "疑いがないことは「明らか」 → 飲みすぎたことであるのは明らかだ（事実だ）", "願いの強さは「切に」 → 成功することを切に（心から）願う"], "ex": "この映画は原作に<b>忠実</b>に作られている。"},
"123": {"point": "「にぎわう」は、人が大勢集まって活気があること。「〜でにぎわう」の形で場所を主語にして使う。④が正しい。", "meaning": "人が大勢集まって、活気がある。", "kr": "붐비다, 활기차다", "opts": ["人の集まり以外には使わない → 多様な生物が群れて（すんで）", "悩みが消えるのは「吹き飛ぶ」 → 悩みも一瞬で吹き飛んだ", "人を元気にする意味はない → 落ち込んでいる私を励ます（元気づける）ために", ""], "ex": "週末の商店街は、買い物客で<b>にぎわって</b>いる。"},
"124": {"point": "「動向」は、社会・人・物事が動いていく方向や、その様子。「景気・世論・台風の動向」。③が正しい。", "meaning": "物事や人が動いていく方向。その様子。", "kr": "동향", "opts": ["個人の行いは「行動」 → 思いつきで行動を起こしてしまう", "人の様子は「態度」 → 彼の真剣な態度（表情）", "", "これからの計画は「予定」 → リニューアルオープンする予定だ"], "ex": "投資家は為替の<b>動向</b>に注目している。"},
"125": {"point": "「漏れる」は、液体・気体・光・秘密などが、すき間から外に出ること。①は水筒のお茶が外に出たので正しい。", "meaning": "液体・気体・光・情報などが、すき間から外に出る。", "kr": "새다", "opts": ["", "味が中まで入るのは「染みる」 → 中まで味が染みた大根", "土に水分が行き渡るのは「潤う」 → 畑が十分に潤った", "氷が水になるのは「溶ける」 → 南極の氷が全て溶けると"], "ex": "会議の内容が外部に<b>漏れて</b>しまった。"},
"126": {"point": "「〜てでも」は、ある犠牲を払ってまで実現させるという強い意志を表す。前の「恩師の頼みとあれば（恩師の頼みという理由なら）」と合い、「仕事を休むという犠牲を払ってでも駆けつける」となる。", "opts": ["休まなくても＝休まない場合でも。「休まなくても駆けつける」では、犠牲を払う強い意志が表せない", "", "休まないまでも＝休むところまではしなくても（〜ないまでも：〜ほどではないが）。意志の強さと合わない", "休まなくとも＝「休まなくても」の書き言葉。①と同じ理由で合わない"], "ex": "徹夜し<b>てでも</b>、明日までにこの報告書を仕上げます。"},
"127": {"point": "「AであれBであれ」は「AであってもBであっても、例外なく」という意味。鳥も犬も含め、どんなペットも禁止という規約の厳しさを表す。", "opts": ["", "とて/とて：「とて」は「〜であっても（私とて人間だ）」の意で、「AとてBとて」と二つ並べる形は普通使わない", "なり/なり：「AなりBなり」は「どちらでもいいから選んで」という提案・命令に使い、禁止の文には合わない", "とやら/とやら：「とやら」は「〜とかいう」という不確かな伝聞で、意味が合わない"], "ex": "大人<b>であれ</b>子ども<b>であれ</b>、ルールは守らなければならない。"},
"128": {"point": "「〜といったところだ」は「だいたい〜くらいだ（多くはない）」と程度を軽く示す言い方。「せいぜい」と一緒に使われることが多く、参加者が多くても50人程度だったという意味になる。", "opts": ["までのことだった：「〜までのことだ」は「〜するだけのことだ（だめならあきらめるまでのことだ）」の意。数量には使わない", "", "に限ったことだった：普通「〜に限ったことではない（〜だけではない）」と否定の形で使う", "には至らないことだった：「〜に至らない」は「そこまでにならない」の意で、「せいぜい」と合わない"], "ex": "毎日の勉強時間は、せいぜい1時間<b>といったところ</b>だ。"},
"129": {"point": "前の文「食生活と運動を心がけることは大事だ」と、後の文「毎日実行するのは容易ではない」は反対の内容なので、逆接の接続詞「しかしながら」が入る。", "opts": ["それゆえ＝それだから（順接）。後の内容が前の結果になっていない", "ならびに＝および（並列）。名詞を並べるのに使う", "したがって＝だから（順接）。逆の内容をつなげない", ""], "ex": "計画は順調に進んでいる。<b>しかしながら</b>、予算の問題はまだ残っている。"},
"130": {"point": "「社長は金曜日にお戻りになると〜」の話し手は安田さんで、言ったのは社長。社長の行為「言う」を高める尊敬語「おっしゃる」を使い、「とおっしゃっていました」とするのが最も自然。", "opts": ["伺って：「聞く」の謙譲語で、聞いた自分（安田さん）の行為になる。社長が言った内容を伝える文では「おっしゃる」が自然", "お伝えして：自分が伝える謙譲表現。社長が言ったことにならない", "拝聴して：講演などを謹んで聞くという謙譲語で、予定を聞いた場面には大げさ", ""], "ex": "先生は、明日は休講だと<b>おっしゃって</b>いました。"},
"131": {"point": "「〜きらいがある」は、よくない傾向がある、という意味（動詞の辞書形・名詞＋の に接続）。「考えすぎる」という短所を控えめに指摘する文に合う。", "opts": ["ものと思われる：「〜と推測される」という書き言葉の推量。会話で人の短所を言う文に合わない", "", "極まりない：「失礼極まりない」のように、な形容詞・名詞について「この上なく〜だ」を表す。動詞には付かない", "にしのびない：「〜するのはつらくてできない（捨てるにしのびない）」の意で、意味が合わない"], "ex": "彼は何でも一人で抱え込む<b>きらいがある</b>。"},
"132": {"point": "「〜ことなく」は「〜しないで」という意味の書き言葉的な表現。ミスをした時も責めないで支えてくれた人たちに感謝する、という流れになる。", "opts": ["責めんがために戦った：「〜んがため（に）」は「〜するために」という目的。仲間に感謝する内容と合わない", "", "責めるに至った：「〜に至る」は「ついに〜するまでになる」。感謝の理由にならない", "責めるかのごとく戦った：「〜かのごとく」は「まるで〜かのように」。意味が通らない"], "ex": "彼は一度も休む<b>ことなく</b>、三年間働き続けた。"},
"133": {"point": "「〜ないものだろうか」は、実現が難しいことを何とかして実現させたいという強い願いを表す。後の「強く願う」と合う。", "opts": ["", "なくならないことだろうか：「〜ことだろう」は「どんなに〜ことだろう」のような感慨を表し、願望にならない", "なくなるものだろうか：「なくなるはずがない」という反語の意味になり、願いと合わない", "なくなることだろうか：疑問・感慨の形で、願望を表さない"], "ex": "もう少し安く海外旅行ができない<b>ものだろうか</b>。"},
"134": {"point": "「〜をもって」は「〜で・〜によって」という手段・方法を表す改まった言い方。「書面をもってお知らせします」は、採用の通知などに使われる決まった表現。", "opts": ["もとに：「〜をもとに」は「〜を材料・根拠にして」の意。知らせる手段は表さない", "おいて：「〜において」は「に」に付いて場所・時・分野を表す。「〜をおいて」は「〜以外に（〜をおいてほかにない）」の意で後に否定が来る。どちらも手段は表さない", "", "ふまえて：「〜をふまえて」は「〜を前提・判断の基礎にして」。手段は表さない"], "ex": "合否の結果は、後日メール<b>をもって</b>お知らせします。"},
"135": {"point": "「〜ずにはおかない」は「必ず〜する・自然に〜させてしまう」という意味。動詞のない形の「ない」を取って「ず」を付ける（及ぼさない→及ぼさず）。価格高騰が生活に必ず影響を与える、という意味になる。", "opts": ["及ぶ：自動詞で「影響が及ぶ」と使う。「影響を」と合わず、形も「ずにはおかない」に接続しない", "及ぼす：辞書形は「ずにはおかない」に接続しない", "及ぼさない：「〜ないにはおかない」という形はない", ""], "ex": "彼の熱のこもった演説は、聞く人の心を動かさ<b>ずにはおかない</b>。"},
"136": {"point": "「〜たら〜たで」は、同じ動詞を繰り返して「もしそうなった場合でも、それはそれで（別の問題がある）」という意味を表す。", "steps": "「多忙な生活を送っていると」の後には、その結果の「仕事を辞めたくなるが」が来る。逆接の「が」の後に反対の状況「暇になったらなったで」を置く。「今までとは違う」は名詞「悩み」を修飾するので「悩みが出てくる」の前に置き、「出てくる」が文末の「だろう」につながる。", "ex": "お金がないと困るが、あったら<b>あったで</b>使い道に悩むものだ。"},
"137": {"point": "「AくらいならB（ほうがいい）」は「Aのような望ましくないことをするよりは、Bのほうがましだ」という意味。", "steps": "「くらい」は動詞の辞書形に付き、「なら」はその後に付く（食べないでやせる→くらい→なら）。後半の「思い切って食べて」は、文末の「その分走ったほうがいい」に直接つながる。", "ex": "途中でやめる<b>くらいなら</b>、初めからやらないほうがいい。"},
"138": {"point": "「〜とあって」は「〜という特別な事情なので（当然こうなる）」、「〜とみえる」は「様子から判断すると〜らしい」という意味。", "steps": "「ついに」は「おじいちゃんになった」を修飾し、その後に理由の「とあって」が付く。その結果が「喜びを隠せない」で、話し手の推測「とみえる」が最後に来る。", "ex": "人気歌手が来る<b>とあって</b>、会場には朝から長い列ができた。"},
"139": {"point": "「〜にかまけて」は「〜に気を取られて、ほかの大切なことをおろそかにする」という意味。不満や非難を込めて使う。", "steps": "「仕事や」と「付き合いに」が並んで「仕事や付き合いに」となり、その後に「かまけて」が来る。おろそかにしている内容「家事に協力的ではない」が、文末の「と愚痴っている」につながる。", "ex": "忙しさ<b>にかまけて</b>、家族と過ごす時間を作れずにいる。"},
"140": {"point": "「AはおろかBすら（〜ない）」は「Aは言うまでもなく、もっと簡単なBさえ〜ない」という意味。Bには程度の低いものが来る。", "steps": "目的だった「手に入れること」に「はおろか」を付け、より簡単な「予約券をもらうこと」に「すら」を付けて、文末の「できなかった」につなげる。", "ex": "忙しくて、旅行<b>はおろか</b>週末に休むこと<b>すら</b>できない。"},
"141": {"point": "「すなわち」は、前の語を別の言葉で言い換えるときに使う。「西洋史」＝「ヨーロッパの歴史」なので「すなわち」。", "opts": ["ないしは＝または。どちらか一方を選ぶ意味で、言い換えにならない", "", "ただし＝前の内容に条件や例外を付け加える", "それだけに＝それだからなおさら"], "ex": "日本の首都、<b>すなわち</b>東京には多くの人が集まる。"},
"142": {"point": "「お召しになる」は「着る」の尊敬語。社長の奥様が着物を着ていた、という意味になる。", "opts": ["お越しになっていました：「来る・行く」の尊敬語。「着物をお越しになる」とは言わない", "うけたまわっておりました：「聞く・引き受ける」の謙譲語。着物とは結びつかない", "", "おあがりになっていました：「食べる・（家に）上がる」の尊敬語。着物とは結びつかない"], "ex": "奥様は、すてきなドレスを<b>お召しになって</b>いた。"},
"143": {"point": "「〜にたえる」は「〜するだけの価値がある」という意味（見るにたえる・鑑賞にたえる）。「子ども向けとはいえ」と逆接でつながり、大人が見ても十分価値がある、と勧めている。", "opts": ["", "大人が見るまでもないものだけどね：「〜までもない」は「〜する必要がない」。見に行くことを勧める前の文と合わない", "大人には見かねるものだよ：「見かねる」は「見ていられない（見かねて手伝う）」の意で、勧める文と合わない", "大人が見ようにも見られないものだったよ：「〜ようにも〜ない」は「〜したくてもできない」。意味が通らない"], "ex": "素人の作品だが、十分鑑賞<b>にたえる</b>出来だ。"},
"144": {"point": "「数量＋からある」は「〜もある、〜以上の」と数量の多さを強調する（主に重さ・長さ・大きさ）。きゃしゃな体なのに20キロもの荷物を持ち上げた驚きを表す。", "opts": ["からいる：数量を強調する言い方としては使わない", "だけする：こういう言い方はしない", "", "だけある：「〜だけ（のこと）はある」は「さすが〜にふさわしい」という評価の意味で、数量の強調ではない"], "ex": "彼は30キロ<b>からある</b>米袋を一人で運んだ。"},
"145": {"point": "「AもさることながらB」は「Aはもちろんのこと、Bも」という意味で、AもBもよいと評価するときに使う。デザインも機能性も優れている家具に合う。", "opts": ["をよそに＝〜を無視して（周囲の心配をよそに）。評価の文に合わない", "に至るまで＝範囲の端まで（細部に至るまで）。「機能性にも」とつながらない", "はおろか＝「Aは言うまでもなく、Bも（〜ない）」。「漢字はおろかひらがなも書けない」のように後に否定・マイナスの内容が来ることが多い", ""], "ex": "この店は料理の味<b>もさることながら</b>、サービスも素晴らしい。"},
"146": {"point": "「〜ものを」は「〜のに」という意味で、そうしなかったことへの残念な気持ち・不満を表す。言ってくれれば手伝いに行ったのに、という気持ち。", "opts": ["ものの＝「〜けれども」という逆接。後に文が続く必要がある", "ものか＝「絶対に〜しない」という強い否定・反語（行くものか）", "", "ものだ＝当然・回想・感慨を表す。残念な気持ちは表せない"], "ex": "一言相談してくれればよかった<b>ものを</b>。"},
"147": {"point": "「動詞のた形＋までだ」は「特別な理由ではなく、ただ〜しただけだ」と、すでにした行為を控えめに説明する言い方。ほめられた佐藤くんの返事に合う。", "opts": ["", "する：「辞書形＋までだ」は「〜するしかない（だめなら別の方法を探すまでだ）」という決意で、すでにした行為には使わない", "させた：使役形で、誰かにさせたことになり文脈に合わない", "させる：使役形。③と同じく誰かにさせたことになり、また辞書形は②と同じく既にした行為に使えない"], "ex": "私は思ったことを正直に言った<b>までです</b>。"},
"148": {"point": "「〜ともなると」は「〜という特別な時期・立場になると、当然…」という意味。紅葉の名所で、10月の週末という特別な時期になると渋滞する、という流れ。", "opts": ["と相まって＝「〜と一緒になって（効果が高まる）」。「好天と相まって」のように使う", "", "ならでは＝「〜だけが持つ（名詞＋ならではの）」。後に「の」＋名詞が必要", "たるもの＝「〜という立場にある者は（教師たるもの…べきだ）」。時期には使わない"], "ex": "年末<b>ともなると</b>、街は買い物客でいっそうにぎわう。"},
"149": {"point": "「泣くに泣けない」は、泣きたいほどつらいのに、自分のせいなどで泣くこともできない、という気持ち。自分の不注意でスマホを落とした場面に合う。", "opts": ["泣くだけ泣いた＝思う存分泣いた。「なんとも言われぬ気持ち」とつながりにくい", "泣くともなく泣いた：「〜ともなく」は「はっきりした意図なく」の意（見るともなく見る）。意味が合わない", "泣きに泣いた＝ひたすら泣き続けた。自分のせいで泣けないつらさは表せない", ""], "ex": "旅行の当日に寝坊して飛行機に乗り遅れ、<b>泣くに泣けない</b>思いをした。"},
"150": {"point": "「〜を禁じ得ない」は「〜という気持ちを抑えることができない」という書き言葉。「と同時に」で後の「嫌悪を感じた」と並び、失望も嫌悪も感じたという意味になる。", "opts": ["失望するのに反して：「〜に反して」は「〜とは反対に」。後の嫌悪と並ばない", "", "失望には当たらないばかりか：「〜には当たらない」は「〜する必要はない」。発言を批判する文と合わない", "失望しないまでも：「〜ないまでも」は「〜ほどではないが」。強い嫌悪と合わない"], "ex": "被害者の話を聞いて、涙<b>を禁じ得なかった</b>。"},
"151": {"point": "「〜がてら」は「〜を兼ねて・〜のついでに」という意味。名詞や動詞のます形に付く。", "steps": "「退職」には「した今」が付いて「退職した今」になる。「暇つぶし」に「がてら」が付き、本来の動作「見返す」が「には（〜するのには）」の前に来る。", "ex": "散歩<b>がてら</b>、駅前の本屋に寄った。"},
"152": {"point": "「〜かたわら」は「本業の〜をする一方で、別のこともする」という意味。動詞の辞書形・名詞＋の に付く。", "steps": "「主役を務める」がひとまとまりになり、その後に「かたわら」が来る。もう一つの活動「劇団を」は、後の「立ち上げ」の目的語になる。", "ex": "彼は会社に勤める<b>かたわら</b>、小説を書いている。"},
"153": {"point": "「生まれながらにして」は「生まれた時から・生まれつき」という意味の書き言葉。", "steps": "「チェンバロという」の後には、その楽器を説明する「形がピアノに似た楽器を弾き」が来る。続いて「5歳で作曲をしたと言われており」と経歴を述べ、「生まれながらにして」が「音楽の才能を備えていた」を修飾して「と言える」につながる。", "ex": "人は<b>生まれながらにして</b>自由であり、平等である。"},
"154": {"point": "「名詞＋まみれ」は、汚いものが一面についている様子（ほこりまみれ・泥まみれ・汗まみれ）。", "steps": "「掃除」には「したら」が付く。その結果として「全身」「ほこり」「まみれ」が並び、「になった」につながる。「ほこりまみれ」で一語になる。", "ex": "雨の中で試合をして、選手たちは泥<b>まみれ</b>になった。"},
"155": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」、「今回ほど〜ことはない」は「今回がいちばん〜だ」という意味。", "steps": "文末の「実感したことはありません」と呼応する「今回ほど」を最初に置く。「お客様」に「あっての」が付いて名詞「仕事」を修飾し、「仕事なのだ」となる。", "ex": "ファン<b>あっての</b>プロ野球だということを忘れてはいけない。"},
"156": {"point": "「〜（よ）うとも」は「たとえ〜ても」という逆接の仮定。「どんなに」と呼応して、どんなにつらいことが起こっても、という意味になる。", "opts": ["起こるにたえて：「〜にたえる」は「〜する価値がある・我慢できる」の意で、意味が通らない", "", "起こるにひきかえ：「〜にひきかえ」は「〜とは反対に（比べて）」。仮定を表さない", "起こらんがために：「〜んがため」は「〜するために」という目的。意味が合わない"], "ex": "誰に何と言われ<b>ようとも</b>、私はこの道を進む。"},
"157": {"point": "「〜ではあるまいし」は「〜ではないのだから（当然〜だ）」という意味で、相手の言葉への反論や不満に使う話し言葉。初心者ではないのだから、そんなミスはしない、という意味。", "opts": ["", "ともなれば＝「〜という立場になれば」。「初心者ともなれば」では意味が通らない", "ときたら＝「〜は（不満を込めて）」と話題を取り上げる。反論の文にならない", "はおろか＝「〜は言うまでもなく」。後に「も」の文が必要"], "ex": "子ども<b>ではあるまいし</b>、一人で帰れるよ。"},
"158": {"point": "「もしくは」は「または」という意味で、二つのうちどちらか一方を選ぶことを表す。郵送か電子メールのどちらかで送る、という意味。", "opts": ["いわゆる＝世間でよく言われる（いわゆる天才）", "いわば＝たとえて言えば", "", "はじめ＝「〜をはじめ（として）」で代表例を挙げる"], "ex": "黒<b>もしくは</b>青のペンで記入してください。"},
"159": {"point": "「〜と言わんばかりに」は、実際には言わないが、今にもそう言いそうな態度で、という意味。自分には関係ないという態度で行ってしまった様子を表す。", "opts": ["", "言うが早いか：「〜が早いか」は「〜するとすぐに」。実際に言ったことになり、「とでも」と合わない", "言ってこのかた：「〜てこのかた」は「〜して以来」。意味が通らない", "言うべからず：「〜べからず」は「〜してはならない」という禁止"], "ex": "彼は「早く帰れ」と<b>言わんばかりに</b>時計を見た。"},
"160": {"point": "「〜には当たらない」は「〜するほどのことではない・〜する必要はない」という意味。前輪が曲がっただけでけがもないので、心配する必要はない、と答えている。", "opts": ["心配したかいがありました：「かいがある」は努力が報われること。相手を安心させる文に合わない", "", "心配極まりないです：「極まりない」は「この上なく〜だ」。前の「けがもない」と矛盾する", "心配を禁じ得ません：「〜を禁じ得ない」は「〜という気持ちを抑えられない」。前の内容と矛盾する"], "ex": "少し遅れたくらいで、謝る<b>には当たらない</b>よ。"},
"161": {"point": "「可能形＋ものなら」は「もし〜できるなら（実際は難しいが）」という仮定で、後に願望が来る。帰ることはできないが、帰れるなら今すぐ帰りたい、という気持ち。", "opts": ["帰ろう：「意向形＋ものなら」は「もし〜したら（大変なことになる）」の意で、後に悪い結果が来る。願望の文と合わない", "帰せる：「帰す（帰らせる）」の可能形で、自分が帰る意味にならない", "帰った：た形は「ものなら」に接続しない", ""], "ex": "やり直せる<b>ものなら</b>、高校時代からやり直したい。"},
"162": {"point": "「名詞＋ならでは（の）」は「〜だけが持っている、〜でなければ得られない」という意味。この土地でしか食べられない食材、という意味になる。", "opts": ["ずくめ＝「〜ばかり（黒ずくめ・いいことずくめ）」。土地には使わない", "の極み＝最高の程度（贅沢の極み）。「土地の極み」では意味が通らない", "を踏まえて＝「〜を前提にして」。食材の特徴を表さない", ""], "ex": "これは職人<b>ならでは</b>の技だ。"},
"163": {"point": "「何のお構いもせず（しませんで）」は、客を十分にもてなせなかったことをわびる決まり文句。帰る客に主人側が言う。", "opts": ["", "ご奉仕もせず：「奉仕」は報酬を求めずに尽くすこと。もてなしのあいさつには使わない", "お世話もせず：決まった言い方ではなく、客に対するあいさつとして不自然", "ご遠慮もせず：自分が遠慮しなかったという意味になり、もてなした側のあいさつにならない"], "ex": "遠いところをお越しいただいたのに、何の<b>お構いもできず</b>申し訳ありません。"},
"164": {"point": "「〜に則って（のっとって）」は、規則・法律・基準などに従って、という意味。法律に従って裁かれる権利、となる。", "opts": ["を兼ねて＝一つで二つの役目を果たす（散歩を兼ねて）", "を境に＝〜を区切りにして（それを境に変わった）", "", "にかまけて＝〜に気を取られて、他のことをおろそかにする"], "ex": "試合は国際ルール<b>に則って</b>行われる。"},
"165": {"point": "「〜をものともせず」は、困難や障害を問題にせず、立ち向かって何かを成し遂げる様子。夢を叶えた鈴木君への評価に合う。", "opts": ["", "障害もさることながら：「〜もさることながら」は「〜はもちろん（…も）」。後に並べる内容がない", "障害をはばからず：「〜をはばからず」は「遠慮しないで（人目をはばからず）」。障害には使わない", "障害のいかんによらず：「〜のいかんによらず」は「〜がどうであっても」。困難に立ち向かう意味は弱い"], "ex": "彼は足のけが<b>をものともせず</b>、最後まで走り抜いた。"},
"166": {"point": "「Aとは言わないまでも（B）」は「Aというほどではないが、せめてBくらいは」という意味。", "steps": "「せっかくの」の後には名詞の「夏休みなので」が来る。「人気のリゾート地」に「とは言わない」「まで」が続き、文中の「も」と合わせて「とは言わないまでも」となる。", "ex": "毎日<b>とは言わないまでも</b>、週に一度は運動したい。"},
"167": {"point": "「AなくしてはB（ない）」は「AがなければBはできない」という意味の書き言葉。感謝を述べるときによく使う。", "steps": "「山口教授の」は名詞「的確なご指導」を修飾し、その後に「なくしては」が来る。後半は「この論文を書き上げること」が、文末の「は不可能だった」の主語になる。", "ex": "皆様のご協力<b>なくしては</b>、この大会の成功はありませんでした。"},
"168": {"point": "「Aを契機に（して）B」は「Aをきっかけにして、Bをする・Bが変わる」という意味。", "steps": "「母親の再婚」に「を」「契機」「に」が続いて「を契機に」となる。そのあとに新しく始めたこと「一人暮らし」が来て、「を始めた」につながる。", "ex": "入院<b>を契機に</b>、たばこをやめた。"},
"169": {"point": "「AにとどまらずB」は「Aだけでなく、Bにまで範囲が広がる」という意味。", "steps": "「日本国内に」に「とどまらず」が付き、範囲が広がった先の「海外からも」が続く。「注文が入って」が文末の「くる」につながる。", "ex": "この問題は一つの地域<b>にとどまらず</b>、国全体に広がっている。"},
"170": {"point": "「Aならいざ知らずB」は「Aならともかく、Bは（〜だ）」という意味で、Bについて驚きや批判を述べるときに使う。", "steps": "「普段から」の後に「運動している人」が来て、「なら」「いざ知らず」が続く。対比される「君のように」は、後の「家にこもってばかりいる人」につながる。", "ex": "子ども<b>ならいざ知らず</b>、大人がそんなことを言うなんて。"},
"171": {"point": "「ちなみに」は、前の話に関連することを付け加えるときに使う。物件の話のついでにスーパーの有無を尋ねている。", "opts": ["", "おまけに＝その上（さらに〜だ）。事実を付け加えるときに使い、質問の前には不自然", "あるいは＝または。二つのうちのどちらかを表す", "さりとて＝そうかといって（逆接）。意味がつながらない"], "ex": "明日は創立記念日で休みです。<b>ちなみに</b>、来週の月曜日も休みです。"},
"172": {"point": "「想像にかたくない」は「簡単に想像できる」という意味の決まった言い方。あざだらけの体から、虐待されていたことが容易に想像できる。", "opts": ["たえない：「聞くにたえない（聞いていられない）」「感謝にたえない」のように使い、「想像にたえない」とは言わない", "たりない：「〜にたりない」は「〜する価値がない（恐れるにたりない）」。意味が合わない", "", "しのびない：「見るにしのびない」のように「つらくて〜できない」。「想像に」とは結びつかない"], "ex": "彼女がどれほど悲しんだかは、想像<b>にかたくない</b>。"},
"173": {"point": "「〜のいかんによらず」は「〜がどうであるかに関係なく」という意味。人種や性別に関係なく、すべての人に権利がある、となる。", "opts": ["いかんで＝「〜次第で（決まる）」。後の内容と合わない", "いかんでは＝「〜次第では（そうなることもある）」。「すべての人に」と合わない", "", "いかんによっては＝「〜によっては」。一部の場合を表し、「すべての人」と矛盾する"], "ex": "理由の<b>いかんによらず</b>、無断欠席は認めません。"},
"174": {"point": "「〜に恥じない」は「〜の名や評判を汚さない、〜にふさわしい」という意味。先代の社長の名にふさわしい経営をしたい、という意気込みになる。", "opts": ["加えて＝「〜に加えて（その上に）」。意味が通らない", "", "ひきかえ＝「〜にひきかえ（〜と比べて反対に）」。意味が通らない", "もまして＝「〜にもまして（〜以上に）」。名に「もまして」では意味が通らない"], "ex": "優勝チームの名<b>に恥じない</b>試合をしたい。"},
"175": {"point": "「辞書形＋べくして＋同じ動詞」は「そうなるのが当然で、実際にそうなった」という意味。出会うのが運命だった、という意味になる。", "opts": ["出会い：「べくして」はます形の語幹に接続しない", "出会って：て形は「べくして」に接続しない", "", "出会おう：意向形は「べくして」に接続しない"], "ex": "準備不足だったのだから、この失敗は起こる<b>べくして</b>起こったと言える。"},
"176": {"point": "「〜のをいいことに」は「〜という状況を都合のいい機会にして（よくないことをする）」という意味。先生が来ないのをチャンスに騒いでいる様子を表す。", "opts": ["入るか入るまいか：「入ろうかどうしようか迷う」の意で、先生の行為として意味が通らない", "", "入ってきたのをさかい：「〜を境に」は「〜を区切りに」だが、形が不完全で、騒ぐ理由にならない", "入らずとも：「入らなくても」の意で、後の内容とつながらない"], "ex": "親が留守な<b>のをいいことに</b>、弟は一日中ゲームをしていた。"},
"177": {"point": "「〜をぬきにして」は「〜を除いて・〜なしで」という意味。飲み会の場なので、堅い仕事の話はやめて楽しもう、という意味になる。", "opts": ["もとより＝「もちろん」。「堅い話はもとより」では後の文とつながらない", "おろか：「〜はおろか」の形で使い、「〜は言うまでもなく」の意。意味も形も合わない", "", "ものともせず＝「〜を問題にせず」。困難に立ち向かうときに使う"], "ex": "冗談は<b>ぬきにして</b>、そろそろ本題に入りましょう。"},
"178": {"point": "「AにせよBにせよ」は「AでもBでも、どちらの場合でも」という意味。進学しても就職しても資格は役に立つから取っておいたほうがいい、という意味になる。", "opts": ["とか/とか：例を並べる話し言葉で、「どちらの場合でも」の意味は出ない", "やら/やら：「AやらBやらで大変だ」のように、いろいろなものを並べる", "なり/なり：「AなりBなりしなさい」と、どちらかを選ぶよう提案するときに使う。後の文と合わない", ""], "ex": "行く<b>にせよ</b>行かない<b>にせよ</b>、早めに連絡してください。"},
"179": {"point": "「〜てなるものか」は「絶対に〜しない」という強い決意を表す。一度負けた相手なので「今度こそ負けたくない」とがんばった、という意味になる。", "opts": ["負けようがない＝「負ける可能性がない」。決意の表現ではない", "", "負けるよりほかない＝「負けるしかない」。意味が反対", "負けるものではない：「〜ものではない」は「〜するべきではない（一般的な忠告）」「普通は〜しない」の意。自分の強い決意は表さない"], "ex": "こんなところで、あきらめ<b>てなるものか</b>。"},
"180": {"point": "「賜る」は「もらう」の謙譲語で、「いただく」よりさらに改まった言い方。式典で社長から挨拶をいただきたい、という司会の言葉に合う。", "opts": ["", "傾聴したい：「傾聴」は熱心に耳を傾けて聞くこと。「挨拶を傾聴したい」は不自然", "差し上げたい：「あげる」の謙譲語。社長に挨拶をあげることになり、方向が逆", "お受けしたい：「受ける」の謙譲語で、依頼や注文を引き受けるときに使う"], "ex": "本日は多くの方々からご支援を<b>賜り</b>、心より感謝申し上げます。"},
"181": {"point": "「〜ときたら」は、ある物事を話題に取り上げて、話し手の強い評価や感情（多くは不満・驚き）を述べる。「目も当てられない」は「見ていられないほどひどい」。", "steps": "「その」の後に「映像から見て取れる」が来て「事故現場の悲惨さ」を修飾する。それを話題にする「ときたら」が続き、評価の「目も当てられないほど」が文末の「であった」につながる。", "ex": "うちの兄<b>ときたら</b>、休みの日は昼まで寝ている。"},
"182": {"point": "「AならまだしもB」は「Aならまだ許せるが、Bは困る・驚く」という意味。", "steps": "初対面でも聞かれて普通な「名前や職業」に「ならまだしも」を付ける。驚いた内容「家庭環境まで」を後に置き、「聞かれた」が「ので」につながる。", "ex": "一度<b>ならまだしも</b>、何度も同じミスをされては困る。"},
"183": {"point": "「〜ですら」は「〜でさえも」という意味で、極端な例を挙げて「ほかはなおさらだ」と示す。「稀代（きたい）」は「世にもまれな」という意味。", "steps": "「その道に優れた」は「稀代の名人」を修飾し、「ですら」が続く。その後に「時には失敗をする」「ということ」が来て、「を例えた」につながる。", "ex": "専門家<b>ですら</b>、この問題には答えられなかった。"},
"184": {"point": "「〜とでもいうべき」は「〜と呼んでもいいような」という意味で、物事をたとえて評価するときに使う。", "steps": "「システム設計の」の後に名詞「落とし穴」が来る。「とでも」「いうべき」と続け、名詞「もの」が文末の「だった」につながる。", "ex": "この発見は、医学の革命<b>とでもいうべき</b>出来事だ。"},
"185": {"point": "「AたるものB」は「Aという立場にある者は、当然Bするべきだ」という意味の書き言葉。", "steps": "「国家の」の後に「最高責任者」が来て、「たるもの」が続く。何をすべきかは後に述べ、「国民」「のこと」が「を第一に考えた」の目的語になる。", "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"186": {"point": "「〜とはいうものの」は「〜とは言っても（実際は予想と違う）」という逆接。昇進したと言っても給料はあまり変わらない、という意味。", "opts": ["からには＝「〜した以上は（当然…すべきだ）」。後に義務や決意が来る", "とあれば＝「〜という理由なら」。後に「どんなことでもする」などが来る", "だけあって＝「〜にふさわしく、さすがに」。後にプラスの評価が来る", ""], "ex": "春<b>とはいうものの</b>、まだ寒い日が続いている。"},
"187": {"point": "「お気に召す」は「気に入る」の尊敬語。送ったお菓子を相手が気に入ってくれたらうれしい、という意味になる。", "opts": ["お気になさって：「気にする」の尊敬語で「心配する」の意。意味が合わない", "", "頂戴して：「もらう」の謙譲語で、相手の行為には使えない", "お目にかかって：「会う」の謙譲語。意味が合わない"], "ex": "このデザインは<b>お気に召しました</b>か。"},
"188": {"point": "「名詞＋なりに」は「その立場にふさわしい程度に・それ相応に」という意味。学生には学生なりの大変さがある、という意味になる。", "opts": ["にして：「〜にして（〜であって同時に・〜になってやっと）」。意味が合わない", "", "に則って：「〜に従って」。規則などに使う", "ならでは：「〜だけが持つ」。後に「の＋名詞」が必要で、意味も合わない"], "ex": "子どもは子ども<b>なりに</b>、家族のことを心配している。"},
"189": {"point": "「〜をよそに」は「〜を気にせず・無視して」という意味。周囲の反対を無視して危険な地域に向かった、という意味になる。", "opts": ["", "めぐって：「〜をめぐって」は「〜について（争う・議論する）」。後の行動と合わない", "もとに：「〜をもとに」は「〜を材料・根拠にして」。意味が合わない", "機に：「〜を機に」は「〜をきっかけに」。反対をきっかけに出発するのは不自然"], "ex": "親の心配<b>をよそに</b>、息子は一人で旅に出た。"},
"190": {"point": "「AかれBかれ」は、い形容詞の語幹に「かれ」を付けて「AでもBでも、いずれにしても」を表す古い形（遅かれ早かれ・多かれ少なかれ・良かれ悪しかれ）。語幹「遅・早」が入る。", "opts": ["遅い/早い：「遅いかれ」という形はない", "遅く/早く：「遅くかれ」という形はない", "遅くな/早くな：こういう形はない", ""], "ex": "<b>遅かれ早かれ</b>、本当のことはわかるだろう。"},
"191": {"point": "「名詞＋かたがた」は「〜を兼ねて」という意味で、手紙や訪問のあいさつに使う改まった言い方。名詞の「報告」に直接付く。", "opts": ["報告する：辞書形は「かたがた」に接続しない", "報告し：ます形の語幹は「かたがた」に接続しない", "", "報告の：「の」は入れず、名詞に直接付ける"], "ex": "先日のお礼<b>かたがた</b>、ご挨拶に伺いました。"},
"192": {"point": "「〜だにしない」は「〜さえしない」という意味の書き言葉（想像だにしない・微動だにしない）。有名な女優と結婚するなど想像さえしなかった、という意味。", "opts": ["するべからず：「〜べからず」は「〜してはならない」という禁止", "しないではすまなかった：「〜しないではすまない」は「〜しなければならない」", "してはかなわない：「〜てはかなわない」は「〜ては困る・たまらない」", ""], "ex": "こんな結果になるとは、夢に<b>だに</b>思わなかった。"},
"193": {"point": "「〜に由来する」は、名前や物事の起こりが〜にあるという意味。市の名前がトヨタの本社があることから来ている、という文に合う。", "opts": ["まつわる：「〜にまつわる」は「〜に関係する（〜にまつわる伝説）」。後に名詞が必要", "ともなう：「〜にともなう」は「〜と一緒に起こる」。名前の起こりは表さない", "", "起因する：「〜に起因する」は、事故や問題の原因が〜にあること。悪い出来事に使う"], "ex": "この地名は、昔ここにあった大きな池に<b>由来する</b>。"},
"194": {"point": "「〜か否か」は「〜かどうか」の書き言葉。合格できるかどうかはっきりとは言えない、という意味になる。", "opts": ["", "できるや否や：「〜や否や」は「〜するとすぐに」。意味が合わない", "しようがしまいが：「してもしなくても（関係ない）」。後の「はっきりとは言えない」と合わない", "しようかしまいか：「しようかやめようか（迷う）」。合格は自分の意志で決められない"], "ex": "計画を実行する<b>か否か</b>は、来週の会議で決める。"},
"195": {"point": "「〜に越したことはない」は「〜のほうがいい（それより良いことはない）」という意味。家族のために入っているほうがいいが、という前半と、後の「が」の逆接が合う。", "opts": ["", "入るといったらない：「〜といったらない」は「非常に〜だ（悔しいといったらない）」という感情の表現", "入っていることはない：「〜ことはない」は「〜する必要はない」。前の「家族のためにも」と合わない", "入るおそれがある：「〜おそれがある」は悪いことが起こる可能性。意味が合わない"], "ex": "安全のためには、用心する<b>に越したことはない</b>。"},
"196": {"point": "「AともあろうB」は「Aという立派な立場にある人が（そんなことをするとは）」という意味で、驚きや非難を表す。", "steps": "「政治家」に「ともあろう」が付き、「人が言ってはいけない」が続いて「差別的な発言」を修飾する。「差別的な発言」が文末の「をした」につながる。", "ex": "警察官<b>ともあろう</b>者が、交通違反をするとは。"},
"197": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉（「するべく」は「すべく」とも言う）。", "steps": "「歌手になる」「という」が「幼少期からの夢を」の内容を説明する。その後に目的を表す「実現するべく」が来て、後の「歌やダンスのレッスンを受ける」につながる。", "ex": "留学の資金を貯める<b>べく</b>、アルバイトを始めた。"},
"198": {"point": "「Aをおいてほかにいない（ない）」は「A以外に適当な人（もの）はいない」という意味。", "steps": "「私の」は「大事な顧客を」を修飾し、「任せられるのは」が続く。そのあとに候補の「森山さんを」が来て、「おいてほかにいない」が「と考えていた」につながる。", "ex": "この役を演じられるのは、彼<b>をおいてほかにいない</b>。"},
"199": {"point": "「〜たところで」は「〜しても（むだだ・結果は変わらない）」、「AもののB」は「AけれどもB」という意味。", "steps": "「今さら」の後には「悔やんだところで」が来て、その結果「結果が変わることはない」が続く。逆接の「ものの」の後に前向きな内容「失敗から学べる」が来て、「こと」を修飾する。", "ex": "今から急いだ<b>ところで</b>、もう間に合わない。"},
"200": {"point": "「言うまでもなく」は「当然のことだが・わざわざ言う必要もないが」という意味。", "steps": "文中の「言う」に「までもなく」が付く。そのあと「裸で」「街を歩く」「こと」がひとまとまりになり、「は犯罪である」の主語になる。", "ex": "<b>言うまでもなく</b>、健康は何よりも大切だ。"},
"201_0": {"point": "直後の文「あるいは、〜と考えているのではないだろうか」と並ぶ形で、筆者は孤独を不幸と思う人の無意識の考え方を推測している。同じ推測の「〜ているのではないだろうか」が入る。", "opts": ["前提にさせないのである：使役の形で、主語の「そう考える人は」と合わない", "", "前提にしないようにしているのだ：意識して避けている意味になり、「無意識のうちに」と矛盾する", "前提にせざるを得ないと思っている：本人が自覚していることになり、「無意識のうちに」と矛盾する"], "ex": "彼が来ないのは、何か理由がある<b>のではないだろうか</b>。"},
"201_1": {"point": "孤独は不幸だという常識に対して、わざと疑問を投げかけている。「困難や反対があるのを承知で、わざわざ」という意味の「あえて」が入る。", "opts": ["あらかじめ＝前もって。問いかける時期の話ではない", "いっそ＝思い切って（極端な方を選ぶ）。問いかけの様子に合わない", "おそるおそる＝怖がりながら。筆者の態度に合わない", ""], "ex": "反対されるとわかっていたが、<b>あえて</b>自分の意見を言った。"},
"201_2": {"point": "孤独の負の感情を並べている部分。「誰も（自分を）理解してくれない」と、孤独な人の側から見た不満を表す「〜てくれない」が入る。", "opts": ["理解させない：使役で「他人に理解することを許さない」意味になり、孤独な人の気持ちと合わない", "理解させられない：「理解させることができない」の意で、自分の説明不足の話になる", "", "理解してやらない：自分が他人を理解しない意味になり、方向が逆"], "ex": "誰も私の気持ちをわかって<b>くれない</b>。"},
"201_3": {"point": "「すると、」で始まる文なので、距離を置いて考えた結果として予想されることが来る。肯定の推量「気づくだろう」が入り、次の「決して『孤独であること＝不幸』ではないのだ」につながる。", "opts": ["気づかない：否定で、ポジティブな側面があるという後の主張と矛盾する", "", "気づくのか：疑問の形で、「すると」の結果を述べる文にならない", "気づくまい：「気づかないだろう」という否定の推量で、後の主張と矛盾する"], "ex": "落ち着いて考えれば、彼も自分の間違いに<b>気づくだろう</b>。"},
"201_4": {"point": "「そう思えた時」、つまり孤独を成熟の時間と受け止められた時点で、すでに心豊かな人生へ向かい始めている、と筆者は評価している。「一歩踏み出したと言えるだろう」が入る。", "opts": ["", "一歩踏み出そうとするのだろう：これから踏み出すという推測で、「そう思えた時」の評価として弱い", "一歩踏み出す必要がなくなるのだろう：「心豊かな人生に向けて」と意味がつながらない", "一歩踏み出せなくなっていくのだろう：孤独を肯定する文章の結論と反対になる"], "ex": "自分の弱さを認められた時、人は成長への一歩を踏み出した<b>と言えるだろう</b>。"},
"202_0": {"point": "「名詞＋いかんで」は「〜次第で・〜によって（結果が変わる）」という意味。前の「どのような姿勢で臨むかによって、…大きく変わってきます」を「つまり」で言い換えている。", "opts": ["", "にかぎり＝「〜だけは（特別に）」。条件によって変わる意味は出ない", "のみならず＝「〜だけでなく」。後の文とつながらない", "にかかわらず＝「〜に関係なく」。つき合い方で変わるという前の内容と反対になる"], "ex": "交渉の結果<b>いかんで</b>、計画を見直すことになる。"},
"202_1": {"point": "前の段落は「失敗を怖れて何もしない慎重な人」、この段落は「失敗をまったく考えずに突き進む人」で、反対のタイプを対比している。「これとは正反対に」が入る。", "opts": ["これと同様に：同じタイプを続ける言い方で、反対の人物の説明と合わない", "これに比例して：数量が一緒に増減する関係を表す", "", "これとは別に：別の話題を加える言い方で、対比の関係が表せない"], "ex": "兄はおとなしい。<b>これとは正反対に</b>、弟はとても活発だ。"},
"202_2": {"point": "後に「まわりをごまかすための言い訳に終始する」とあるので、原因の究明を「しようとしないで」という意味の「行おうとせず」が入る。", "opts": ["行うべく：「〜べく」は「〜するために」。言い訳に終始する人の説明と合わない", "行わんがために：「〜んがため」も目的を表す。①と同じ理由で合わない", "行おうか否か：「行うかどうか（迷う）」。後の文とつながらない", ""], "ex": "彼は人の意見を聞こう<b>とせず</b>、自分の考えを押し通した。"},
"202_3": {"point": "「失敗は避けられない。しかし、それが致命的になってはいけない」という逆接の関係なので、「〜とはいえ（〜けれども）」が入る。", "opts": ["避けられるともすれば：「ともすれば」は「ややもすると」という副詞で、この形では使わない", "", "避けられるとばかりに：「〜とばかりに」は「今にも〜と言いそうな様子で」。意味が通らない", "避けられないとあって：「〜とあって」は理由を表し、後の内容と逆接の関係が表せない"], "ex": "仕事<b>とはいえ</b>、毎晩遅くまで働くのはつらい。"},
"202_4": {"point": "予想される失敗の知識を念頭に置いて行動すれば、致命的な失敗やむだな失敗を前もって防げる。「不必要な失敗を避ける」が入る。", "opts": ["必要な失敗を繰り返す：同じ失敗を何度も繰り返す人を批判した前の段落と矛盾する", "必要な挑戦を選ぶ：失敗の知識を生かすという話から外れる", "不必要な挑戦はしない：挑戦を控える意味になり、「行動しなければ何も起こらない」という筆者の主張と合わない", ""], "ex": "事前に道を調べておけば、むだな遠回りを<b>避ける</b>ことができる。"},
"203_0": {"point": "「好むと好まざるとにかかわらず」は「好きでも嫌いでも、本人の気持ちに関係なく」という意味の決まった言い方。近代以前の不自由さを表している。", "opts": ["まつわり：「〜にまつわる」は「〜に関係する」。この決まった言い方には使わない", "", "かこつけて：「〜にかこつけて」は「〜を口実にして」。意味が通らない", "よっては：「〜によっては」は「〜の場合には」。この言い方には使わない"], "ex": "好むと好まざると<b>にかかわらず</b>、新しい制度に従わなければならない。"},
"203_1": {"point": "近代以前の不自由な時代を経て、ついに「どのような価値観を持とうが自由」という合意を手に入れた、という歴史の到達点を述べている。「ついに〜するまでになった」という意味の「〜にいたりました」が入る。", "opts": ["獲得するばかりなのです：「〜ばかりだ」は「その方向にどんどん進む（悪化するばかり）」。合意の成立を表せない", "獲得するにかたくありません：「〜にかたくない」は「想像にかたくない」のように使い、意味が通らない", "獲得するきらいがあるのです：「〜きらいがある」はよくない傾向。筆者が評価する内容と合わない", ""], "ex": "長い話し合いの末、両国は合意する<b>にいたった</b>。"},
"203_2": {"point": "「皮肉なことに」は「期待とは逆の結果になって」という意味の決まった言い方。自由のための価値観の多様化が、新たな問題を生んだことを表す。", "opts": ["もの：「皮肉なものだ」とは言うが、「皮肉なものに」とは言わない", "", "ところ：「皮肉なところに」とは言わない", "よう：「皮肉なように」とは言わない"], "ex": "<b>皮肉なことに</b>、便利になればなるほど人は忙しくなった。"},
"203_3": {"point": "明確な価値の拠り所を失った結果、私たちは空気を読み合う人間関係を送るしかない状況になっている、という今日の問題を述べている。「〜なければならなくなっている」が入る。", "opts": ["", "送ったことになっているのです：「〜ことになっている」は「事実でなくてもそう扱われる・決まりだ」の意。問題の説明にならない", "送るに越したことはないのです：「そうするほうがよい」という勧めになり、問題を述べる文と合わない", "送るまでもないのです：「その必要はない」の意で、前の内容と矛盾する"], "ex": "人手が足りず、毎日残業をし<b>なければならなくなって</b>いる。"},
"203_4": {"point": "「〜などというわけにはいかない」で否定されているのは、「多様な価値観を再び一つにまとめるべきだ」という考え。「統合しなければならない」が入る。筆者は多様性の承認こそが自由の条件だと考えている。", "opts": ["統合すべきではない：これは筆者自身の考えで、「〜というわけにはいかない」で否定する内容にならない", "統合するまでもない：「その必要がない」の意で、後の「わけにはいかない」とつながらない", "", "統合しようもない：「統合する方法がない」の意で、筆者の理由（多様性の承認）と合わない"], "ex": "一度決めたことだから、今さらやめる<b>というわけにはいかない</b>。"},
"204_0": {"point": "直前の「見直しの動きは鈍い」を裏付けるので、時短に踏み切った店が少ないことを表す「〜に過ぎない（ただ〜だけだ）」が入る。", "opts": ["約4%に限らない：「〜に限らない」は「〜だけではない」。少なさを表せない", "", "約4%にとどまらない：「〜にとどまらない」は「〜を超えて広がる」。「鈍い」と矛盾する", "約4%に相違ない：「〜に相違ない」は「きっと〜だ」という確信。少なさを強調できない"], "ex": "会議に出席したのは、わずか10人<b>に過ぎなかった</b>。"},
"204_1": {"point": "「〜ほど」は、一方の程度が変わるにつれて、もう一方も変わる（比例）ことを表す。売上高が伸びれば伸びるだけ本部の収益も増える仕組み。", "opts": ["", "くらい：程度の目安を表し、比例の関係は表せない", "さえ：「〜さえ〜ば」の形で条件を表すが、ここでは「ば」がなく形が合わない", "より：比較を表し、比例の関係は表せない"], "ex": "年をとる<b>ほど</b>、時間が早く過ぎるように感じる。"},
"204_2": {"point": "前の段落は本部の立場（営業時間を長くして売上を増やしたい）、この段落は加盟店の立場（深夜営業はデメリットが大きい）で、二つを対比している。「これに対し」が入る。", "opts": ["これにしては：「〜にしては」は「〜から予想されるのとは違って」。対比にならない", "これにつけて：「〜につけ」は「〜するたびに（何かにつけて）」。意味が通らない", "", "これに向けて：「〜に向けて」は目標に向かうこと。意味が通らない"], "ex": "兄は文系に進んだ。<b>これに対し</b>、弟は理系を選んだ。"},
"204_3": {"point": "近くに同じチェーンの店が集まると客を奪い合うので、収益が悪くなるおそれがある。「〜かねない（〜するおそれがある）」が入る。", "opts": ["悪化するというものではない：「必ずしも悪化するわけではない」の意で、加盟店の不利を述べる流れと合わない", "悪化しないとでもいうべきだ：意味が通らない", "悪化しない次第である：「〜次第だ」は事情の説明で、意味が反対になる", ""], "ex": "このまま放っておくと、大きな事故につながり<b>かねない</b>。"},
"204_4": {"point": "公取が改革を迫る理由を、前の段落の「社会インフラとしての機能」から筆者が推測している。「〜したためだろう」が入る。", "opts": ["考慮するというのだ：「〜というのだ」は言い換えや伝聞で、理由の推測にならない", "", "考慮するのだそうだ：伝聞で、筆者が推測する文脈と合わない", "考慮したまでのことだ：「ただそれだけのことだ」の意で、意味が合わない"], "ex": "道が混んでいるのは、近くで祭りがある<b>ためだろう</b>。"},
"205_0": {"point": "お母さんがしてくれることを次々に挙げている。前の内容に加えて、さらに付け加えるので「それだけではなく」が入る。", "opts": ["そうとはいえ：「そうは言っても」という逆接。後に同じ方向の例が続くので合わない", "それにせよ：「いずれにせよ（どちらにしても）」に近い意味で、例を付け加える接続にはならない", "それにしては：「それから予想されるのとは違って」の意で、意味が通らない", ""], "ex": "この店は安い。<b>それだけではなく</b>、味もいい。"},
"205_1": {"point": "結婚するとどうなるかを一般的に説明している部分なので、「〜のです」で事情を説明する「見始めるのです」が入る。", "opts": ["見始めてきたのです：「〜てきた」はこれまでの変化の経過を表し、結婚後に起こることを一般的に説明するこの文には合わない", "", "見始めてはいられません：「〜てはいられない」は「〜している余裕がない」。意味が通らない", "見始めるまでのことです：「ただそれだけのことだ」の意で、説明の流れと合わない"], "ex": "一緒に暮らし始めると、相手の細かい習慣が気になり始める<b>のです</b>。"},
"205_2": {"point": "「果ては（最後には）」と呼応して、普通なら気にならないような小さなこと「さえ」気になり始める、という極端さを表す「まで」が入る。", "opts": ["", "より：比較を表し、意味が通らない", "は：取り立ての「は」では、「果ては」が表す極端さが出ない", "ぐらい：「せめて〜ぐらい」のように最低限を表し、極端な例の強調にならない"], "ex": "緊張して、自分の名前<b>まで</b>忘れてしまった。"},
"205_3": {"point": "前の文「社会に出たら、絶対に1人暮らしをするべきです」に続き、そうして家事の面倒さを体で知るべきだ、と勧めている。「身をもって知るべきです」が入る。", "opts": ["身をもって知ったのです：過去の事実を述べる形で、読者への勧めになっていない", "身をもって知る限りです：「〜限りだ」は「うれしい限りだ」のように感情を強めるときに使い、不自然", "", "身をもって知ったわけです：過去の結論を述べる形で、勧めの文脈と合わない"], "ex": "失敗の痛みは、自分で経験して<b>身をもって知るべきだ</b>。"},
"205_4": {"point": "自分で家事の面倒さを知れば、相手のやり方が多少違っても「自分がやるよりはいい」と思えるので、愚痴を言わなくてよい。「〜ずに済む」が入る。", "opts": ["こぼしてやみません：「〜てやまない」は「心から〜し続ける（願ってやまない）」で、愚痴には使わない", "", "こぼすにかたくありません：「〜にかたくない」は「想像にかたくない」のように使い、意味が通らない", "こぼすのだそうです：伝聞で、筆者の主張の結論にならない"], "ex": "早めに準備しておけば、当日慌て<b>ずに済む</b>。"},
"20026": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、後には人が集まる・喜ぶなど、その事情から当然起こる様子が来る。講演会が無料という特別な事情でファンが詰めかけた。", "opts": ["にして：「〜にして」は「〜であって同時に（医者にして作家）」や「〜になってやっと（40歳にして）」の意。理由は表さない", "にあって：「〜にあって」は「〜という状況・立場で（非常時にあって）」。理由と結果の関係が表せない", "として：「〜として」は立場や資格（代表として）。「無料として」では意味が通らない", ""], "ex": "連休初日<b>とあって</b>、高速道路はどこも渋滞している。"},
"20027": {"point": "「〜につけ」は「〜するたびに、いつも」という意味で、「聞くにつけ・見るにつけ」の形で、ある気持ちが自然に起こることを表す。後の「つくづく感じる」と合う。", "opts": ["", "なり：「〜なり」は「〜するとすぐに（帰るなり寝た）」。毎回自然に感じる気持ちは表せない", "とは：「〜とは」は定義や驚き（〜とは知らなかった）。意味が通らない", "にしてみると：「〜にしてみると」は「〜の立場から考えると（親にしてみると）」で、人を表す名詞に付く"], "ex": "故郷の写真を見る<b>につけ</b>、子どもの頃を思い出す。"},
"20028": {"point": "「〜に〜にと」は、例を並べて「〜にも〜にも、いろいろと」という意味を表す。後の「何にでも使えて」とつながる。", "opts": ["は：「揚げ物には」では、いろいろな例を並べる意味にならない", "", "や：「〜や」は名詞を並べるときに使い、「〜に〜にや」という形は不自然", "か：「〜か」は選択を表し、「何にでも」と合わない"], "ex": "週末は掃除に洗濯に<b>と</b>、休む暇がない。"},
"20029": {"point": "「〜させられたあげく」は、嫌なのに〜させられて、その末によくない結果になった、という意味。主語は「私」で、担当者に質問に答えさせられた（使役受身）。「あげく」は過去の出来事なので、た形が入る。", "opts": ["させた：使役で、私が担当者に答えさせたことになり、意味が逆", "させられる：使役受身だが、「あげく」には過去のた形が付く", "させる：使役で意味が逆。また「あげく」にはた形が付く", ""], "ex": "さんざん待たされた<b>あげく</b>、今日は診察できないと言われた。"},
"20030": {"point": "「〜ではないか」は、驚いて思いがけないことに気づいたときの言い方（「なんと〜た」）。動詞のた形に直接付く。電車が反対方向に走り始めたことに驚いている。", "opts": ["ではない：否定になり、後の「後悔した」と矛盾する", "", "のではない：「〜のではない」は否定の説明で、驚きを表さない", "のではないか：推量（〜だろう）を表し、目の前の事実に驚く表現にならない"], "ex": "箱を開けてみると、中は空っぽ<b>ではないか</b>。"},
"20031": {"point": "「お客様に食事を出す」のは店側（自分）の行為なので、謙譲語の「お出しする」を使う。「〜以上」は「〜するからには、当然…」という意味で、後の「何よりも注意しております」と合う。", "opts": ["お出しになる以上：「お〜になる」は尊敬語で、自分の行為には使わない", "お出しになるうえ：尊敬語で誤り。また「〜うえ（に）」は「その上さらに」の意", "", "お出しするうえ：謙譲語は正しいが、「〜うえ」は追加を表し、「当然〜する」という意味にならない"], "ex": "引き受けた<b>以上</b>、最後まで責任を持ってやります。"},
"20032": {"point": "「〜でしかない」は「〜にすぎない」という意味。「気付いていなかった」の対象を表す「〜ことに」が付いて、「世界のほんの小さな一部分でしかないことに気付いていなかった」となる。", "opts": ["でないことにしか：「〜にしか気付いていなかった」となり、意味が逆になる", "", "にないことでしか：「一部分にない」は意味が通らない", "にしかないことで：「一部分にしかない」は意味が通らず、「ことで」も「気付く」と合わない"], "ex": "それがうわさ<b>でしかない</b>ことに、彼は最後まで気付かなかった。"},
"20033": {"point": "「〜くらい」は程度を表し、「今までの苦労がばかばかしく思えるほど簡単に計算できた」となる。「思える」は自然にそう感じられること。", "opts": ["ばかばかしい思いをするもので：「〜もので」は理由の説明になり、「簡単に計算できた」の程度を表せない", "ばかばかしく思えるもので：①と同じく理由の形で、程度を表せない", "ばかばかしい思いをするくらい：「ばかばかしい思いをする」はばかにされたような嫌な経験をすることで、意味が合わない", ""], "ex": "それまでの悩みがうそに思える<b>くらい</b>、気分がすっきりした。"},
"20034": {"point": "原稿ができていない木村先生が、あと3日待ってほしいと出版社の人に頼んでいる。「〜ていただくわけにはいきませんか」は、相手に丁寧に頼む言い方。", "opts": ["待っておいでになります：尊敬語で、相手が待っていることを述べるだけになり、頼む文にならない", "お待ち申し上げております：謙譲語で、自分が待っている意味になる", "待たせていただくことにしましょうか：自分が待つ意味になり、立場が逆", ""], "ex": "申し訳ありませんが、締め切りを延ばしていただく<b>わけにはいきませんか</b>。"},
"20035": {"point": "「〜かっていうと」は「〜かというと（そうではない）」という話し言葉。後の「そうじゃないんです」と呼応し、初めから宇宙飛行士になるつもりだったわけではない、という意味になる。", "opts": ["", "つもりなのかっていわれたら：今のつもりを聞かれたことになり、「医者になろうと思っていましたから」という過去の話と合わない", "つもりじゃなかったのかっていわれたら：否定の形で、「そうじゃないんです」と組み合わせると意味が逆になる", "つもりがなかったかっていうと：否定の形で、「そうじゃない」と言うと「つもりがあった」ことになり、後の話と矛盾する"], "ex": "毎日料理をする<b>かっていうと</b>、そうでもないんです。"},
"20036": {"point": "「〜ということのないように」は「〜ということが起こらないように」という意味で、望ましくない事態を防ぐために前もって何かをするときに使う。", "steps": "「迷ってしまった」の後に「という」が来て、名詞化する「ことの」が続く。「ない」「ように」で「ことのないように」となり、目的を表して「事前に見学しておくとよい」につながる。", "ex": "忘れ物をする<b>ということのないように</b>、前の晩に準備しておこう。"},
"20037": {"point": "「〜てまで」は「そこまで極端なことをして」、「〜となると」は「そういう場合になると」という意味。極端な手段を取ることへの批判を表す。", "steps": "「犠牲」には「にして」が付いて「犠牲にして」、極端さを表す「まで」が続く。そのあと「となる」「と」で「となると」となり、「それはちょっと問題です」につながる。", "ex": "借金をし<b>てまで</b>ブランド品を買う必要はない。"},
"20038": {"point": "「たとえ〜ても」は「仮に〜でも」、「〜だとして」は「〜だと考えて・〜だということにして」という意味。", "steps": "「たとえ」は「〜ても」と呼応するので、「自分には責任」「がなくても」が続く。そのあと「自分の責任」「だとして」で、部下の失敗を自分のこととみなす意味になり、「部下の失敗も引き受ける」につながる。", "ex": "たとえ失敗し<b>ても</b>、挑戦したことに意味がある。"},
"20039": {"point": "「今でこそ〜が」は「今は〜だが、以前はそうではなかった」という意味。過去と現在を対比するときに使う。", "steps": "「今でこそ」で始め、現在の様子「一流企業と言われる」が「我が社だが」を修飾する。逆接の「が」の後に、以前の様子を表す「もともとは」が来て、「小さな町工場だった」につながる。", "ex": "<b>今でこそ</b>人気の店だが、開店当初は客がほとんど来なかった。"},
"20040": {"point": "「〜かと思いきや」は「〜と思ったが、意外にもそうではなかった」という意味。予想と違う結果を述べるときに使う。", "steps": "「役作りに悩んでいる」に疑問の「のか」が付き、「と」「思いきや」が続く。予想とは違う結果「そうでもない」が、伝聞の「という」につながる。", "ex": "簡単に勝てる<b>かと思いきや</b>、試合は延長戦になった。"},
"20041_0": {"point": "後に「が、モンダイはその入り方のタイミングだ」と逆接が続くので、まずＣＭが入ること自体は認めている。「入るのはいい（入ること自体はかまわない）」が入る。", "opts": ["入るのにいい：「〜のにいい」は「〜するのに適している」の意で、意味が通らない", "入るのがいいのか：疑問の形で、後の「が、モンダイは〜」とつながらない", "", "入るのでいいのか：疑問の形で、ＣＭが入ること自体を疑うことになり、後の流れと合わない"], "ex": "安いの<b>はいい</b>が、品質が心配だ。"},
"20041_1": {"point": "筆者は広告主に「お願いをしたい」と書いている。せこいＣＭの入れ方をやめてもらいたいという、相手への要望の「やめてほしいのだ」が入る。", "opts": ["やめようと思う：自分がやめる意味になる。ＣＭを入れているのは筆者ではない", "", "やめるのだろうか：疑問・推量で、お願いの文にならない", "やめられるものではない：「やめることはできない」の意で、筆者の主張と逆"], "ex": "夜遅くに大きな音で音楽を聴くのは、<b>やめてほしい</b>。"},
"20041_2": {"point": "「たしかに〜ことは間違いない。が、〜」は、相手の言い分をいったん認めてから反論する形。身を乗り出している瞬間にＣＭを入れれば見られることは確かだが、そのやり方はさもしい、という流れになる。", "opts": ["やはり／ところだった：「〜ところだった」は「もう少しで〜しそうだった」の意で、意味が通らない", "いったい／のか：疑問の形で、後の「が、〜」という反論の流れにならない", "といっても／わけでもない：「見られるわけでもない」と否定すると、後の反論とつながらない", ""], "ex": "<b>たしかに</b>便利になった<b>ことは間違いない</b>。が、失ったものも多い。"},
"20041_3": {"point": "企業が視聴者に、いやでもＣＭを見させる、という意味。主語は企業（ＣＭの出し方）で、視聴者に見させるので使役の「見させてしまう」が入る。", "opts": ["", "身を乗り出させる：身を乗り出すのは番組の盛り上がりによるもので、ＣＭの出し方が強制していることではない", "見られてしまう：受身で、企業の側が見られる意味になり、主語と合わない", "身を乗り出される：受身で、意味が通らない"], "ex": "子どもに嫌いな野菜を無理に食べ<b>させる</b>のはよくない。"},
"20041_4": {"point": "「ぼくだけじゃない、みんな（も）だいぶ前から怒ってるよ」となる。筆者自身（ぼく）が不満を述べてきた文章なので、筆者だけでなく視聴者みんなが怒っている、と結んでいる。", "opts": ["", "広告主／みんな：怒っているのは視聴者側で、広告主ではない", "広告主／ぼくも：②と同じく、広告主が怒っていることになり不自然", "ぼく／広告主も：広告主は筆者がお願いしている相手で、「品がねえぞ」と怒る側ではない"], "ex": "<b>ぼく</b>だけじゃない、<b>みんな</b>そう思っているよ。"},
"21026": {"point": "「〜をよそに」は「〜を気にしないで・関係ないという態度で」という意味。混雑を気にせずパソコンを広げている様子を表す。", "opts": ["含めて：「〜を含めて」は「〜も入れて」。意味が通らない", "もとに：「〜をもとに」は「〜を材料・根拠にして」。意味が通らない", "除いて：「〜を除いて」は「〜以外」。混雑を除くことはできない", ""], "ex": "家族の心配<b>をよそに</b>、彼は一人で山に登った。"},
"21027": {"point": "「ます形の語幹＋もしないで」は「当然すべき〜さえしないで」と強く非難する言い方。漫画を読みさえしないで批判する父への不満を表す。", "opts": ["読まない：「読まないもしないで」という形はない", "", "読もう：意向形は「もしないで」に接続しない", "読んで：て形は「もしないで」に接続しない"], "ex": "彼はろくに調べ<b>もしないで</b>、無理だと決めつけた。"},
"21028": {"point": "「もっとも」は、前に述べたことに補足や少し反対の内容を付け加えるときに使う（ただし）。チームワークの大切さを痛感したが、実は気づいたのは去年だった、と付け加えている。", "opts": ["要するに：前の内容をまとめる言い方。後の内容はまとめになっていない", "あるいは：「または」の意。二つのうちのどちらかを表す", "", "ついては：「そのことに関連して（お願いがあります）」と、依頼や案内を続けるときに使う"], "ex": "この店の料理はおいしい。<b>もっとも</b>、値段は少し高いが。"},
"21029": {"point": "主語は90歳の元村長の東山さんなので、尊敬語を使う。「〜ておいでになる」は「〜ていらっしゃる」と同じ尊敬語で、「覚えておいでになり」となる。", "opts": ["", "差し上げ：「あげる」の謙譲語。「覚えて差し上げる」では意味が通らない", "まいり：「行く・来る」の謙譲語で、相手の行為には使えない", "申し上げ：「言う」の謙譲語で、相手の行為には使えない"], "ex": "先生は、私が卒業した年のことを今も覚えて<b>おいでになる</b>。"},
"21030": {"point": "「〜に越したことはない」は「〜であるほうがいい（が、絶対に必要というわけではない）」という意味。後の「が、それよりも人柄や姿勢を重視しています」と逆接でつながる。", "opts": ["にすぎません：「〜にすぎない」は「ただ〜だけだ」。「知識はあるにすぎません」では意味が通らない", "ことは否めません：「〜ことは否めない」は「〜ことは否定できない」。応募者を安心させる回答と合わない", "", "といっても過言ではありません：「〜と言っても言いすぎではない」。後の「それよりも人柄を重視」と矛盾する"], "ex": "経験はある<b>に越したことはない</b>が、なくても応募できる。"},
"21031": {"point": "「〜次第では」は「〜によっては（その結果、ある事態になることもある）」という意味。復旧状況によっては営業再開が遅れる可能性がある、となる。", "opts": ["次第には：こういう形はない", "次第に：副詞「次第に」は「だんだん」の意で、意味が通らない", "", "次第：「名詞＋次第」は「〜によって決まる」だが、「遅れる可能性がある」につなげるには「次第では」が自然"], "ex": "天候<b>次第では</b>、試合が中止になることもある。"},
"21032": {"point": "クレジットカードの番号は、他人に知られると困る情報。受身の「知られる」に「〜ては困る」が付いて、「知られては困る」となる。", "opts": ["知っていても：他人が知っていても、の意で、「困る」とつながらない", "知っていなくても：意味が通らない", "知らなくては：「知らなくては困る」は「知らないと困る」で、意味が逆", ""], "ex": "人に見られ<b>ては困る</b>書類は、引き出しにしまっておこう。"},
"21033": {"point": "「〜ばいいというものではない」は「〜すればそれで十分だとは言えない」という意味。前の「いかに成果を上げるかが大切」と合わせ、時間をかけてがんばるだけでは不十分だ、という意見になる。", "opts": ["がんばることだといってもおかしくない：「がんばることだと言える」の意で、前の内容と矛盾する", "", "がんばることでしかない：「がんばることにすぎない」の意で、意味が通らない", "がんばりようがない：「がんばる方法がない」の意で、意味が通らない"], "ex": "安けれ<b>ばいいというものではない</b>。品質も大切だ。"},
"21034": {"point": "「〜ものと思われる」は「〜だろうと考えられる」と客観的に推量する書き言葉。主語の「地質構造が」に合わせて自動詞「なる」を使い、「明らかになるものと思われる」となる。", "opts": ["", "するという思いがある：「明らかにする」は他動詞で主語と合わない。「思いがある」も個人的な気持ちを表す", "なったかに思える：「すでに明らかになったように見える」の意で、「いずれ近いうちに」と合わない", "するだろうと思う：他動詞「する」が主語と合わない。「〜と思う」も個人的な言い方で、論文調の文に合わない"], "ex": "新しい薬は、来年には販売される<b>ものと思われる</b>。"},
"21035": {"point": "「〜させてもらおうかと思って」は、自分がしたいことを、相手の許しを得る形で控えめに伝える言い方。後に西村先輩が「辞める？」と聞き返しているので、山下さんが辞めたいと伝えている。", "opts": ["辞めてしまわれたのでしょうか：尊敬語で、相手が辞めたかを尋ねる形になる", "辞めてしまったのかと思って：すでに辞めたと思ったという意味で、これから辞める話と合わない", "辞めさせたらどうでしょうか：誰かを辞めさせることを提案する意味になる", ""], "ex": "今日は体調が悪いので、早めに帰ら<b>せてもらおうかと思って</b>。"},
"21036": {"point": "「〜に由来する」は「〜がもとになっている・〜から来ている」という意味。名前や言葉の起こりを説明するときに使う。", "steps": "「アセビには」の後に「有毒成分があり」が来る。続いて「馬が食べると酔ったような」が「状態になることに」を修飾し、「由来する」が文末の「そうです」につながる。", "ex": "この町の名前は、昔ここにあった大きな寺に<b>由来する</b>。"},
"21037": {"point": "「人に〜を気づかせる」は、使役の形で「その人が〜に気づくようにする」という意味。「〜てくれる」で、それがありがたいという気持ちを表す。", "steps": "「つい」は「仕事に夢中になりすぎる」を修飾し、それが「私に」を説明する。気づかせる内容「本当に大切なものは何なのか」の後に「気づかせてくれる」が来て、「ありがたい存在です」を修飾する。", "ex": "この本は、私に読書の楽しさを<b>気づかせてくれた</b>。"},
"21038": {"point": "「〜ことに対し」は「〜ことについて」という意味で、相手の行為に反論・抗議するときによく使う。「など」は内容をぼかして引用する言い方。", "steps": "「脱税を行った」は「疑いがあるなどと」につながり、「報じられた」が続く。そのあと「ことに対し」が来て、反論の内容「事実とは全く」が文の「異なり」につながる。", "ex": "住民の要望<b>に対し</b>、市は早急に対応すると答えた。"},
"21039": {"point": "「〜てのことだ」は「〜したうえでのことだ・〜したからだ」という意味で、ある行動の理由を説明する。文末の「という」は伝聞。", "steps": "「判断」に「して」が付き、「の」「ことだ」が続いて「判断してのことだ」となる。最後に伝聞の「という」が来る。", "ex": "彼が厳しいことを言うのも、君のためを思っ<b>てのことだ</b>。"},
"21040": {"point": "「〜ほど…ない」は「〜と言えるほど…ではない」という意味。「資格を取っただけで希望の職につける」と言えるほど、世間は甘くない。", "steps": "「資格を取った」に「だけ」「で」が付いて「取っただけで」となる。そのあと「希望の職につける」が来て、程度を表す「ほど」が文末の「世間は甘くない」につながる。", "ex": "一晩勉強しただけで合格できる<b>ほど</b>、試験は簡単ではない。"},
"21041_0": {"point": "マニュアル通りに動く機械と違って、生き物には個性がある。「あちらに通用したことが、こちらに通用するとは限らない」という意味の「こちらにいえるとは限らない」が入る。", "opts": ["こちらにはいえないこともない：「言えなくはない（少しは言える）」の意で、生き物の違いを強調する前の文と合わない", "", "こちらにもいえるとは思わなかった：「同じだと思わなかった」の意で、前の文とつながらない", "こちらにはいえないと思うのか：反問の形で、文章の流れと合わない"], "ex": "高ければよいもの<b>とは限らない</b>。"},
"21041_1": {"point": "前の段落の「ねこを飼い始めた当座は、何も分からなかった」時期を受けて、「そういう時に」と指している。", "opts": ["", "する：「する時に」では、何をする時か分からない", "あの：「あの時」は話し手と聞き手が共通に知っている過去を指す。直前の内容を受けるには「そういう」が自然", "やろうという：「やろうという時に」では何をやろうとするのか分からない"], "ex": "引っ越したばかりで何もわからなかった。<b>そういう</b>時に助けてくれたのが隣の人だった。"},
"21041_2": {"point": "「中でも納得したのが、〜」と、マニュアルの中で特に納得した内容を、名詞で取り上げている。次の段落でトイレの説明が引用されるので「トイレのことだ」が入る。", "opts": ["", "トイレのことであるに違いない：自分が納得した内容を推量するのは不自然", "トイレだからである：理由を述べる形で、「納得したのが」と合わない", "トイレだと聞いている：伝聞で、自分で読んで納得した話と合わない"], "ex": "この本で一番印象に残ったのは、最後の場面<b>のことだ</b>。"},
"21041_3": {"point": "マニュアル通りに遠慮していたのに、実際のゆずは人のいるトイレにわざわざ入ってくる。予想と違う展開を導く「ところがである」が入る。", "opts": ["もっともである：前の内容に賛成する言い方で、後の意外な展開と合わない", "当然である：①と同じく、後の意外な内容と合わない", "", "例えばである：例を挙げる言い方で、前と反対の展開を導けない"], "ex": "準備は完璧だと思っていた。<b>ところがである</b>、当日になって大雪が降った。"},
"21041_4": {"point": "ゆずのトイレの出来事は、生き物には個性があることを改めて感じさせられる出来事だった、と文章をまとめている。「認識させられる出来事だった」が入る。", "opts": ["認識させられたことがある：経験の有無を言う形で、この出来事のまとめにならない", "認識させられたおかげだ：「〜おかげだ」は恩恵の理由を表し、意味が通らない", "認識させられる話があった：他人から聞いた話のようになり、自分の体験のまとめにならない", ""], "ex": "健康の大切さを改めて考えさせられる<b>出来事だった</b>。"},
"22026": {"point": "「〜ねばならない」は「〜なければならない」の書き言葉。火山灰が降っている間、住民は屋内で過ごす必要がある、という意味になる。", "opts": ["", "過ごすほどのことではない：「そこまでする必要はない」の意で、火山灰が降る状況と合わない", "過ごすにあたらない：「〜にあたらない」は「〜する必要はない」。状況と合わない", "過ごしてもさしつかえない：「〜してもかまわない」という許可で、必要性を表さない"], "ex": "約束は守ら<b>ねばならない</b>。"},
"22027": {"point": "「ます形の語幹＋もしないで」は「当然すべき〜さえしないで」と強く非難する言い方。企画書を読みさえしないで放っておいた上司への不満を表す。", "opts": ["読もう：意向形は「もしないで」に接続しない", "読め：命令形は「もしないで」に接続しない", "読まない：「読まないもしないで」という形はない", ""], "ex": "彼はろくに調べ<b>もしないで</b>、無理だと決めつけた。"},
"22028": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」と、程度や範囲をおおよそ示す言い方。航空券の値段の目安を述べている。", "opts": ["ときたら：「〜ときたら」は話題を取り上げて不満などを述べる。値段の目安を表さない", "としたところ：「〜としたところ」は「〜したら（結果）」の意で、意味が通らない", "というわけ：「〜というわけだ」は結論や理由の説明で、おおよその範囲を表さない", ""], "ex": "通勤時間は、片道30分<b>といったところ</b>です。"},
"22029": {"point": "インタビューで相手に気持ちを話してもらうよう頼んでいる。「お聞かせ願えますか」は「聞かせてもらえますか」の丁寧な依頼表現。", "opts": ["ご説明なさいますか：尊敬語で相手に説明するかどうかを尋ねる形になり、依頼にならない", "申し上げてください：「申し上げる」は謙譲語で、相手の行為には使えない", "お聞きください：自分の話を相手に聞いてもらう依頼になり、立場が逆", ""], "ex": "今後の目標を<b>お聞かせ願えますか</b>。"},
"22030": {"point": "「〜ゆえに」は「〜ので・〜から」という意味の硬い書き言葉。乾燥が火事の原因の一つであるから、注意が必要だ、という理由と結果の関係。", "opts": ["べく：「〜べく」は「〜するために」という目的。「あるべく」では意味が通らない", "", "や否や：「〜や否や」は「〜するとすぐに」。意味が通らない", "ごとく：「〜ごとく」は「〜のように」。理由を表さない"], "ex": "若さ<b>ゆえに</b>、失敗することもある。"},
"22031": {"point": "電車が止まっているので、これから時間に間に合わないだろうと推測して、先に始めていいと伝えている。「間に合わなさそうだ」は「間に合わないようだ」という様子からの推量。", "opts": ["間に合いそうだから：間に合うなら先に始める必要がなく、意味が矛盾する", "間に合いそうになかったから：過去の形で、これからのことを伝える文に合わない", "", "間に合わなかったから：送別会はまだ始まっておらず、過去の形は合わない"], "ex": "雨はしばらく止ま<b>なさそう</b>だから、タクシーで帰ろう。"},
"22032": {"point": "「〜ようがない」は「〜する方法がない・〜しようとしてもできない」という意味。連絡が取れないので、伝えたくても伝える方法がない。", "opts": ["", "伝えたって仕方がありません：「伝えても意味がない」の意で、「伝えたくても」と合わない", "伝わないではおかないです：「伝う（つたう）」の形になってしまい（「伝える」なら「伝えないではおかない」）、意味も通らない", "伝えばいいというものではないです：「伝う（つたう）」の形になってしまい（「伝える」なら「伝えればいい」）、意味も通らない"], "ex": "住所がわからないので、手紙の送り<b>ようがない</b>。"},
"22033": {"point": "「ます形の語幹＋次第」は「〜したらすぐに」という意味で、お知らせなどの改まった文で使う。点検が終わったらすぐに営業を再開する。", "opts": ["", "次第には：こういう形はない", "次第に：副詞の「次第に」は「だんだん」の意。「終わり次第に」とは言わない", "次第では：「名詞＋次第では」は「〜によっては」の意で、ます形には付かない"], "ex": "詳しいことがわかり<b>次第</b>、ご連絡いたします。"},
"22034": {"point": "「〜たところで」は「〜しても（期待する結果にはならない・むだだ）」という意味。後の「時間の無駄だよ」と合う。", "opts": ["後悔しただけに：「〜だけに」は「〜なのでなおさら」の意で、後の内容とつながらない", "", "後悔したところを：「〜ところを」は「〜している場面を（見られた）」などの意で、意味が通らない", "後悔はさておき：「〜はさておき」は「〜は後回しにして」の意で、意味が通らない"], "ex": "今から急いだ<b>ところで</b>、もう間に合わない。"},
"22035": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」という意味。体調を崩して何もかもうまくいかなくなったので、すべては健康があってこそだ、と実感している。", "opts": ["", "からある：「数量＋からある」は数量の多さを強調する（20キロからある荷物）。名詞「健康」には合わない", "ながらの：「〜ながらの」は「〜のままの（昔ながらの）」の意で、意味が通らない", "ならではの：「〜ならではの」は「〜だけが持つ」。健康の大切さを表せない"], "ex": "お客様<b>あっての</b>商売だということを忘れてはいけない。"},
"22036": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉。", "steps": "「歯止めをかける」に「べく」が付いて目的を表す。そのあと「様々な」が「取り組みが」を修飾し、「行われている」で文が終わる。", "ex": "夢を実現する<b>べく</b>、毎日努力を続けている。"},
"22037": {"point": "「AもさることながらB（も）」は「Aはもちろん、Bも」という意味で、AもBもよいと評価するときに使う。", "steps": "「性能も」の後に「さることながら」が来て、もう一つの長所「値段もリーズナブルで」が続く。その結果の「売り上げが」「ますます伸びている」で文が終わる。", "ex": "この店は料理の味<b>もさることながら</b>、店員の対応も素晴らしい。"},
"22038": {"point": "「〜つつある」は「〜している途中だ」と、変化が少しずつ進んでいることを表す書き言葉。", "steps": "「経済低迷が続く中」の後に主語の「失業者は」が来て、「増えつつあり」が続く。そのあと「経済的に」が「苦しんでいる」を修飾し、「人々」を説明する。", "ex": "この町の人口は、年々減り<b>つつある</b>。"},
"22039": {"point": "「〜と言わんばかりの」は「今にも〜と言いそうな」という意味で、後に名詞が来る。「〜でさえ」は「〜でも（ほかはなおさら）」。", "steps": "「辞任の表明をする」は「記者会見でさえ」を修飾する。そのあと「自分には」「責任がないと」が続き、「言わんばかりの」が文末の「態度だった」を修飾する。", "ex": "彼は「早く帰れ」と<b>言わんばかりの</b>顔で私を見た。"},
"22040": {"point": "「〜を契機に」は「〜をきっかけにして」という意味。", "steps": "「遠隔医療」に「を契機に」が付く。そのあと「通信インフラが」「整備され」が続き、「医療費増加問題」が文中の「の解決」につながる。", "ex": "留学<b>を契機に</b>、海外の文化に関心を持つようになった。"},
"22041_0": {"point": "「半端ではない」は「程度が普通ではない・ものすごい」という意味の話し言葉。夏の暑さが非常に厳しかったことを表す。", "opts": ["", "半端になった：「中途半端になった」の意で、暑さの厳しさを表さない", "半端ならざるを得なかった：こういう言い方はしない", "中途半端だった：「どっちつかずだった」の意で、続く「風が完全に熱風だった」と合わない"], "ex": "この店のラーメンは、量が<b>半端ではない</b>。"},
"22041_1": {"point": "「〜わけにもいかない」は「事情があって〜することもできない」という意味。夜は氷まくらでしのげたが、日中は氷をぶらさげておくこともできず、つらかった。", "opts": ["", "ぶらさげておくわけがなく：「〜わけがない」は「〜はずがない」の意で、意味が通らない", "ぶらさげておくわけで：「〜わけで」は理由や結論の説明。「つらかった」とつながらない", "ぶらさげておくわけではなく：「〜わけではない」は部分否定で、意味が通らない"], "ex": "熱があったが、大事な会議なので休む<b>わけにもいかず</b>、出社した。"},
"22041_2": {"point": "前の「動くクロをほとんど見ることなく、この夏が過ぎました」が原因で、後の「体重増加」が結果。順接の「なので」が入る。", "opts": ["むしろ：「どちらかといえば」の意で、比較を表す", "ところが：逆接で、因果関係が表せない", "", "一方で：対比を表し、因果関係が表せない"], "ex": "雨が降っていた。<b>なので</b>、出かけるのをやめた。"},
"22041_3": {"point": "暑くても夏バテしない理由を、筆者が推測している。「よく食べ、よく寝ているからでしょうか」と理由を控えめに述べる形が入る。", "opts": ["よく寝ているぐらいでしょう：「ぐらい」は程度を表し、理由にならない", "よく寝ているせいです：「〜せい」は悪い結果の原因に使い、夏バテしないというよい結果には合わない", "よく寝ているからだとは限らないです：理由を否定することになり、前の内容と合わない", ""], "ex": "最近元気なのは、毎朝散歩している<b>からでしょうか</b>。"},
"22041_4": {"point": "今日の煮豚の作り方について、筆者が自分で決めたことを述べている。「〜ことにしました」が入る。", "opts": ["仕上げずにはおかないです：「必ず〜する」の硬い表現で、料理の話に合わない", "", "仕上げるのをお勧めします：読者への勧めになり、「今日は」という自分の話と合わない", "仕上げればよかったです：後悔を表し、これから作る話と合わない"], "ex": "健康のため、毎朝30分歩く<b>ことにしました</b>。"},
"23026": {"point": "先生に論文について質問したいので、「聞く・尋ねる」の謙譲語「伺う」を使う。", "opts": ["拝見したい：「見る」の謙譲語。「先生に拝見したい」は意味が通らない", "", "お目にかかりたい：「会う」の謙譲語。「先生にお目にかかりたいことがある」とは言わない", "お聞きになりたい：尊敬語で、自分の行為には使えない"], "ex": "来週のご予定について、少し<b>伺いたい</b>のですが。"},
"23027": {"point": "「〜を余儀なくされる」は「望まないが、〜しなければならなくなる」という意味。輸出額の減少で、給料の削減をせざるを得なくなった。", "opts": ["しようにもできない：「したくてもできない」の意で、削減したいわけではない文脈と合わない", "せずにはおかない：「必ず〜する」の意で、主語との関係が合わない", "", "するまでもない：「する必要がない」の意で、前の状況と矛盾する"], "ex": "台風のため、イベントは中止<b>を余儀なくされた</b>。"},
"23028": {"point": "「〜とあって」は「〜という特別な事情なので」という意味。ベストセラー作家の新作という特別な事情なので、予約が殺到している。", "opts": ["ごとき：「〜ごとき」は「〜のような（私ごとき）」。理由を表さない", "", "あっての：「〜あっての」は「〜があるからこそ成り立つ」。後に名詞が必要で、意味も合わない", "とはいえ：「〜とはいえ」は逆接で、予約が殺到する結果と合わない"], "ex": "人気の歌手が出演する<b>とあって</b>、チケットはすぐに売り切れた。"},
"23029": {"point": "パワハラが辛いという話の後なので、会社を辞めたいほどだ、と気持ちの強さを表している。「辞めさせてもらいたい」は「（許しを得て）辞めたい」、「ぐらい」は程度の大きさを表す。", "opts": ["", "辞めてしまえばいいもんなんだから：「辞めればいい」と突き放す言い方で、自分の辛さを訴える文と合わない", "辞めさせられても仕方がないんだから：自分に責任があって辞めさせられる意味になり、パワハラの被害の話と合わない", "辞めてみせるんだから：「〜てみせる」は強い決意で、辛さを訴える文と合わない"], "ex": "毎日残業ばかりで、もう逃げ出したい<b>ぐらい</b>なんだ。"},
"23030": {"point": "「〜といったらありゃしない」は「とても〜だ」という意味の話し言葉（「〜といったらない」のくだけた形）。安全性を証明したのに副作用を訴える人が出て、非常に困っている気持ちを表す。", "opts": ["", "ほどのことではない：「それほどではない」の意で、困っている状況と合わない", "きらいがある：「よくない傾向がある」の意で、「困っている」には付かない", "とは限らない：「必ずしも〜ではない」の意で、意味が通らない"], "ex": "夜中に隣の犬がほえて、うるさい<b>といったらありゃしない</b>。"},
"23031": {"point": "「見るに見かねて」は「黙って見ていられなくなって」という意味。誰も席を譲らない様子を見ていられず、僕が譲った。", "opts": ["うってかわって：「がらりと変わって」の意で、意味が通らない", "", "といっても：前の内容を少し否定・修正する言い方で、つながらない", "とはいえ：逆接で、前の内容とつながらない"], "ex": "後輩が困っているのを<b>見るに見かねて</b>、手伝ってあげた。"},
"23032": {"point": "「〜するだに」は「〜するだけでも」という意味で、「想像するだに・考えるだに」の形で後に「恐ろしい」などの感情が来る。", "opts": ["", "の極み：「〜の極み」は最高の程度（光栄の極み）。「想像の極み」では意味が通らない", "のあまり：「〜のあまり」は「〜しすぎて」の意で、「心配のあまり」のように感情の名詞に付く", "にひきかえ：「〜にひきかえ」は「〜と比べて反対に」。意味が通らない"], "ex": "あの事故のことは、思い出す<b>だに</b>胸が痛む。"},
"23033": {"point": "「〜にて」は「〜で」の硬い言い方で、手段や場所を表す。お知らせや案内文でよく使う。", "opts": ["", "とて：「〜とて」は「〜であっても（私とて）」の意で、手段を表さない", "にして：「〜にして」は「〜であって同時に・〜になってやっと」の意", "たりとて：「一円たりとも」のように「〜でさえも（ない）」と最小を強調する言い方"], "ex": "ご質問は、受付窓口<b>にて</b>承ります。"},
"23034": {"point": "「〜に即して（則して）」は「〜に従って・〜に合わせて」という意味。ガイドラインに従って適切に対処する、となる。", "opts": ["にまつわって：「〜にまつわる」は「〜に関係する（〜にまつわる話）」で、動詞を修飾する形は普通使わない", "にいたって：「〜にいたって」は「〜という段階になって（やっと）」。意味が通らない", "にして：「〜にして」は「〜であって同時に・〜になってやっと」。意味が通らない", ""], "ex": "実情<b>に即して</b>、計画を見直す必要がある。"},
"23035": {"point": "「〜にかこつけて」は「〜を口実にして（本当の目的は別）」という意味。行政視察を口実に接待を受けていた疑い、となる。", "opts": ["", "とあって：「〜という特別な事情なので」。疑いの内容を表せない", "を踏まえて：「〜を前提にして」。意味が通らない", "を皮切りに：「〜を最初にして（次々に）」。意味が通らない"], "ex": "彼は出張<b>にかこつけて</b>、観光を楽しんでいた。"},
"23036": {"point": "「〜に転じる」は「（状態や方向が）〜に変わる」という意味。「〜見込みだ」は「〜と予想される」。", "steps": "「男性喫煙者数が」の後に、時を表す「今年」「初めて」が来る。続いて「減少に転じる」が「見込みだ」につながり、「という報告」となる。", "ex": "売り上げは、三年ぶりに増加<b>に転じた</b>。"},
"23037": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉。", "steps": "「大掃除をして」の後に「年越しそばを食べる」が来て「風習があり」を修飾する。そのあと時を表す「新年になると」が続き、目的の「初詣にいくべく」が「神社やお寺を訪れる」につながる。", "ex": "新しい技術を学ぶ<b>べく</b>、海外の研修に参加した。"},
"23038": {"point": "「AはおろかBさえ（〜ない）」は「Aは言うまでもなく、もっと簡単なBさえ〜ない」という意味。", "steps": "「あまりにも」は「悲惨な事故に」を修飾する。そのあと「声を出すことは」「おろか」が続き、より簡単な「目をそむけること」が文中の「さえできなかった」につながる。", "ex": "熱が高くて、起き上がること<b>はおろか</b>、話すこと<b>さえ</b>できなかった。"},
"23039": {"point": "「〜にしても」は「〜としても」という意味の逆接で、「〜には及ばない」は「〜ほどではない」。「Aには及ばないにしても、それなりに〜」で、完全ではないがある程度はよい、と評価する。", "steps": "「大手」の後に「には及ばない」が来て、「にしても」が続く。そのあと「それなりに」が「整っている」を修飾し、「と思う」につながる。", "ex": "プロ<b>には及ばないにしても</b>、彼の料理の腕はなかなかのものだ。"},
"23040": {"point": "「名詞＋ならではの」は「〜だけにある特別な」という意味。", "steps": "「地元」に「ならではの」が付き、「こだわりの食材や」を修飾する。そのあと「職人の手によって」「作り上げられた」が文中の「品々」を修飾する。", "ex": "この祭りでは、京都<b>ならではの</b>伝統芸能が見られる。"},
"23041_0": {"point": "部族が大きくなると、遠くの人とのコミュニケーションだけでなく、決まりや言い伝えを次の世代に伝える必要も生まれる。「伝える必要が出てきます」が入る。", "opts": ["", "伝えるまでもないです：「その必要がない」の意で、前の「〜なくてはなりません」と矛盾する", "伝えることは難しいです：問題点の指摘は次の段落で述べられる。ここでは必要性を述べている", "伝えかねます：「伝えることはできない」の丁寧な断りで、意味が通らない"], "ex": "会社が大きくなると、ルールを文書にする<b>必要が出てきます</b>。"},
"23041_1": {"point": "音声は耳で受け取るだけのものなので、話したとたんに消えてしまう。「〜た途端に」は「〜するとすぐに」という意味。", "opts": ["語っただけあって：「〜だけあって」は「さすが〜にふさわしく」の意で、意味が通らない", "", "語ったところで：「〜たところで」は「〜しても（むだだ）」の意で、「消えてしまう」とつながらない", "語ったからには：「〜からには」は「〜した以上は当然」の意で、意味が通らない"], "ex": "家を出た<b>途端に</b>、雨が降り出した。"},
"23041_2": {"point": "「とくに困るのは、〜ことです」の形で、困ることの内容を述べている。優れた語り手が亡くなると伝承が途切れてしまうことが困る。", "opts": ["途切れてもかまわないことです：困ることの説明と矛盾する", "", "途切れるとは思わなかったことです：意外だったという意味で、「とくに困るのは」と合わない", "途切れてしかるべきです：「途切れるのが当然だ」の意で、意味が反対"], "ex": "一番困るのは、急に予定が変わって<b>しまうことです</b>。"},
"23041_3": {"point": "絵は「ある瞬間をとらえて表現するもの」、話し言葉は「時間の流れに沿って展開するもの」で、二つの性質を対比している。「それに対して」が入る。", "opts": ["", "それにもかかわらず：逆接だが、「前の事実から予想されることと違う」場合に使い、対比には合わない", "それと同時に：同時に成り立つことを加える言い方で、対比にならない", "それに基づいて：前の内容を根拠にする言い方で、意味が通らない"], "ex": "兄は外で遊ぶのが好きだ。<b>それに対して</b>、弟は家で本を読むのが好きだ。"},
"23041_4": {"point": "話し言葉と同じく時間的に展開する「文字」に写すのが、最もよい方法だと結論づけている。「最も賢明な方法です」が入る。", "opts": ["", "最も賢明な方法だとは限らないです：結論を否定することになり、文章の流れと合わない", "最も賢明な方法であるがゆえのことです：理由を述べる形で、意味が通らない", "最も賢明な方法になりかねます：「〜かねる」は「〜できない」、「〜かねない」は悪い可能性を表し、どちらも意味が通らない"], "ex": "わからないことは専門家に聞くのが、最も<b>賢明な方法</b>だ。"},
"24026": {"point": "「〜を控えて」は「〜が近くに迫っている時に」という意味。首相の記者会見が迫っていて、会場の緊張が高まっている。", "opts": ["あたって：「〜にあたって」の形で使い、「を」とは結びつかない", "", "あって：「〜あって」では意味が通らない", "あいまって：「〜と相まって」の形で使い、「を」とは結びつかない"], "ex": "試験<b>を控えて</b>、学生たちは図書館で勉強している。"},
"24027": {"point": "「〜ないものか」は「何とかして〜できないだろうか」という強い願望を表す。前の「なんとかして」と呼応する。", "opts": ["ものの：「〜ものの」は「〜けれども」という逆接で、後に文が続く", "ものだ：「〜ないものだ」は「〜しないのが普通だ」という一般論で、願望を表さない", "", "ものを：「〜ものを」は「〜のに」という不満・残念な気持ち"], "ex": "もっと楽に英語が覚えられ<b>ないものか</b>。"},
"24028": {"point": "「〜をよそに」は「〜に関係なく・〜を気にせず」という意味。当初の予想（売れないだろう）に反して、新製品が売れている。", "opts": ["含めて：「〜を含めて」は「〜も入れて」。意味が通らない", "除いて：「〜を除いて」は「〜以外」。意味が通らない", "", "もとに：「〜をもとに」は「〜を材料にして」。予想に基づいて売り上げが伸びるのは不自然"], "ex": "周囲の心配<b>をよそに</b>、彼女は手術から一週間で仕事に戻った。"},
"24029": {"point": "「〜においてさえ」は「〜でも」という意味で、極端な例を挙げて「ほかの場合はなおさらだ」と示す。研究が進んだ現代でも、地震の予知は難しい。", "opts": ["", "においてこそ：「〜でこそ」は「まさに〜で」と強調し、後の「難しい」と逆接の関係にならない", "に対してさえ：「〜に対して」は相手・対象を表し、時代には使わない", "に対してこそ：②③と同じ理由で合わない"], "ex": "医学が進んだ今日<b>においてさえ</b>、治せない病気は多い。"},
"24030": {"point": "「〜を余儀なくされる」は「仕方なく〜しなければならなくなる」という意味。不景気のため、工場を止めざるを得なくなった。", "opts": ["", "の至り：「〜の至り」は「光栄の至り」のように、感情が最高の程度であることを表す", "にかたくない：「想像にかたくない」の形で使い、意味が通らない", "にたえない：「感謝にたえない・聞くにたえない」のように使い、意味が通らない"], "ex": "大雪のため、列車は運休<b>を余儀なくされた</b>。"},
"24031": {"point": "「〜ゆえに」は「〜が原因で・〜ので」という硬い言い方。論文が独創的だったため、当初は理解できる人がいなかった、という理由と結果の関係。", "opts": ["としても：「〜としても」は仮定の逆接。意味が通らない", "からには：「〜からには」は「〜した以上は（当然…）」の意で、名詞に直接は付かない", "といえば：「〜といえば」は話題の提示。理由を表さない", ""], "ex": "その美しさ<b>ゆえに</b>、この花は多くの人に愛されている。"},
"24032": {"point": "「〜べきところを」は「本当は〜するべきなのに（そうしないで）」という意味。素直に謝るべきなのに反抗して、退学処分になった。", "opts": ["謝るべく：「〜べく」は「〜するために」という目的。反抗したことと合わない", "", "謝るべきところに：「ところに」は「ちょうどその時に」の意で、逆接の意味にならない", "謝るまじき：「〜まじき」は「〜してはならない（教師にあるまじき行為）」の意で、後に名詞が必要"], "ex": "本来なら私が伺う<b>べきところを</b>、わざわざお越しいただき恐縮です。"},
"24033": {"point": "主語は90歳の元村長なので、尊敬語を使う。「〜ておいでになる」は「〜ていらっしゃる」と同じ尊敬語で、「覚えておいでになり」となる。", "opts": ["差し上げ：「あげる」の謙譲語。「覚えて差し上げる」では意味が通らない", "まいり：「行く・来る」の謙譲語で、相手の行為には使えない", "", "申し上げ：「言う」の謙譲語で、相手の行為には使えない"], "ex": "先生は、私が卒業した年のことを今も覚えて<b>おいでになる</b>。"},
"24034": {"point": "「どうやら〜ようだ」は「はっきりとは言えないが、どうも〜らしい」という推量。快晴で気温も上がったことから、台風が過ぎ去ったと推測している。文末の「ようだ」と呼応する。", "opts": ["仮に：「仮に〜としたら」のように仮定を表し、「ようだ」と呼応しない", "必ずしも：「必ずしも〜ない」のように後に否定が必要", "くれぐれも：「くれぐれも気をつけて」のように依頼・注意に使う", ""], "ex": "<b>どうやら</b>明日は雨になるようだ。"},
"24035": {"point": "「〜ないとも限らない」は「〜する可能性もある」という意味。今はお説教としか思っていなくても、いつか役に立つかもしれない、と伝えている。", "opts": ["", "立つまでだ：「〜までだ」は「〜するだけだ・〜するしかない」の意で、意味が通らない", "立ってやまない：「〜てやまない」は「願ってやまない」のように心から思い続ける気持ちを表す", "立たないではすまない：「〜ないではすまない」は「〜しなければ許されない」の意で、意味が通らない"], "ex": "油断していると、思わぬ事故が起き<b>ないとも限らない</b>。"},
"24036": {"point": "「〜はともかく」は「〜は別として（今は問題にしない）」、「〜すら」は「〜さえ」という意味。", "steps": "「原因は」に「ともかく」が付く。そのあと「上司への」が「報告すら」を修飾し、「しなかった」が文中の「ことを咎められた」につながる。", "ex": "結果<b>はともかく</b>、最後まであきらめなかったことが大切だ。"},
"24037": {"point": "「AなくしてB（ない）」は「AがなければBはできない」という意味の書き言葉。", "steps": "「労働条件」の後に「の」「改善」が来て、「なくして」が続く。そのあと「あり得ない」が文中の「ことだ」につながる。", "ex": "努力<b>なくして</b>成功はあり得ない。"},
"24038": {"point": "「何かしら（の）」は「はっきりとはわからないが、何か（の）」という意味。", "steps": "「何かしらの」は名詞を修飾するので、「譲れない」「こだわりを」が続く。そのあと「持っていて」が文中の「最高の物を作る」につながる。", "ex": "誰にでも、<b>何かしらの</b>悩みはあるものだ。"},
"24039": {"point": "「〜ともなると」は「〜という段階・立場になると、当然…」、「〜かねない」は「〜するおそれがある」という意味。", "steps": "「海外移住」に「ともなると」が付く。そのあと「国によっては」が続き、「後悔する」「ことにもなりかねない」が文中の「ので」につながる。", "ex": "このまま放っておくと、大きな事故につながり<b>かねない</b>。"},
"24040": {"point": "「〜からには」は「〜のだから、当然…」という意味で、後に義務・決意などが来る。「〜としては」は「〜の立場から言うと」。", "steps": "「特に」は「日本酒に興味のある」を修飾し、「私としては」が続く。そのあと「それを知ったからには」が来て、「それを味わわずに」が文末の「帰ることはできない」につながる。", "ex": "引き受けた<b>からには</b>、最後まで責任を持ってやり遂げる。"},
"24041_0": {"point": "「AはもとよりB」は「Aはもちろん、Bも」という意味。ニュース番組はもちろん、コマーシャルもインタビュー番組も、じかに語りかけてくる、と例を並べている。", "opts": ["をよそに：「〜を無視して」の意で、例を並べる文に合わない", "", "にひきかえ：「〜とは反対に」の意で、同じ特徴を持つものを並べる文に合わない", "といい：「AといいBといい」と二つ以上並べて使う形で、ここでは形が合わない"], "ex": "この映画は子ども<b>はもとより</b>、大人も楽しめる。"},
"24041_1": {"point": "日本とアメリカのニュースで、なぜ「これほど大きく」違う印象を与えるのか、と疑問を投げかけている。程度を強める「これほどまでにも」が入る。", "opts": ["これ見よがしに：「わざと見せびらかすように」の意で、意味が通らない", "こともなげに：「何でもないことのように平気で」の意で、意味が通らない", "", "こともあろうに：「よりによって（ほかに方法もあるのに）」の意で、意味が通らない"], "ex": "どうして彼は、<b>これほどまでにも</b>努力できるのだろう。"},
"24041_2": {"point": "「次の事実に思い当たった」を受けて、その「事実」の内容を「日本人は〜という事実に」と言い換えている。言い換えの「すなわち」が入る。", "opts": ["", "しかしながら：逆接で、前の内容を言い換える文にならない", "もしくは：「または」の意で、どちらか一方を選ぶときに使う", "とはいえ：「そうは言っても」の逆接で、意味が通らない"], "ex": "日本の首都、<b>すなわち</b>東京には多くの人が集まる。"},
"24041_3": {"point": "直前で「カメラのレンズを直視することにためらいを覚えるのも、同じ理由にもとづいている」と述べている。目をどこに向けるかという「視線」もまた日本語（相手との関係で言葉を変える習慣）に支配されている、という意味。「もまた」は、言葉だけでなく〜も、ということ。", "opts": ["言葉：日本語の支配下にあるのは当然で、「もまた」と付け加える意味がない", "上下関係：上下関係は日本語の使い分けの原因で、日本語に支配されるものではない", "礼儀：直前の「レンズを直視することのためらい」と直接つながらない", ""], "ex": "人の<b>視線</b>が気になって、うまく話せなかった。"},
"24041_4": {"point": "「むろん、アメリカ人も〜。だが、それは二義的なことにすぎない」という流れで、相手によって言葉を変えることもないわけではない、と部分的に認めている。「〜ないわけではない」が入る。", "opts": ["変えないものでもない：「〜ないものでもない」は「〜することもあり得る」という意味で近いが、主に話し手の意志・判断について使い、ここでは「〜ないわけではない」が自然", "", "変えるにあたらない：「変える必要はない」の意で、後の「だが、それは二義的」とつながらない", "変えるきらいがある：「変えるというよくない傾向がある」の意で、意味が通らない"], "ex": "辛い料理が食べられ<b>ないわけではない</b>が、あまり好きではない。"},
"32001": {"point": "「洪水」は「こうずい」。「洪」は音読み「こう」、「水」は連濁して「ずい」になる。「香水（こうすい）」と混同しないこと。", "meaning": "大雨などで川の水があふれ出ること。", "kr": "홍수", "opts": ["こうすい：「水」は連濁して「ずい」。「こうすい」は「香水」の読み", "", "きょうすい：「洪」は「こう」と読み、「きょう」とは読まない", "きょうずい：「洪」は「こう」"], "ex": "台風の大雨で川があふれ、<b>洪水</b>が起きた。"},
"32002": {"point": "「迅速」は「じんそく」。「迅」は濁って「じん」、「速」は「そく」。促音化はしない。", "meaning": "物事の進み方や行動が非常に速いこと。", "kr": "신속", "opts": ["", "しんそく：「迅」は濁って「じん」", "じっそく：促音化はせず「じんそく」", "しっそく：「迅」は「じん」。「しっそく」は「失速」の読み"], "ex": "事故の知らせを受け、消防は<b>迅速</b>に対応した。"},
"32003": {"point": "「合併」は「がっぺい」。「合」は「がっ」と促音化し、促音の後の「併（へい）」は半濁音化して「ぺい」になる。", "meaning": "二つ以上の会社・組織などが一つにまとまること。", "kr": "합병", "opts": ["がっへい：促音の後の「へい」は「ぺい」になる", "ごうへい：「合」は「がっ」、「併」は「ぺい」", "", "ごうぺい：「合」は「ごう」ではなく「がっ」"], "ex": "隣の町と<b>合併</b>して、新しい市が生まれた。"},
"32004": {"point": "「修行」は「しゅぎょう」。「修」は短く「しゅ」、「行」は「行列」と同じ「ぎょう」。「修」の「しゅう」と迷わせる問題。", "meaning": "学問・技芸・仏道などを身につけるため、努力して自分をきたえること。", "kr": "수행, 수련", "opts": ["", "しゅうぎょう：「修」は短く「しゅ」。「しゅうぎょう」は「就業」などの読み", "しゅこう：「行」は「ぎょう」。「しゅこう」は「趣向」の読み", "しゅうこう：「しゅう」も「こう」も誤り"], "ex": "父は若いころ、京都で料理人の<b>修行</b>を積んだ。"},
"32005": {"point": "「楽観」は「らっかん」。「楽」は「らく」で、後ろの「か」の前で促音化して「らっ」になる。「音楽」の「がく」と迷わせる問題。", "meaning": "物事がうまくいくと明るく考え、心配しないこと。", "kr": "낙관", "opts": ["がくかん：「楽観」の「楽」は「がく」ではなく「らく」", "がっかん：「楽」は「らっ」", "らくかん：「らく」は「か」の前で促音化して「らっ」", ""], "ex": "医者は、病状は<b>楽観</b>できないと言った。"},
"32006": {"point": "「圧迫」は「あっぱく」。「圧（あつ）」が促音化して「あっ」、その後の「迫（はく）」は半濁音化して「ぱく」になる。", "meaning": "強く押さえつけること。また、勢いや力で相手を苦しめること。", "kr": "압박", "opts": ["あっばく：促音の後は「ばく」ではなく「ぱく」", "あつばく：「圧」は促音化して「あっ」、「迫」は「ぱく」", "", "あつはく：促音化と半濁音化が起こって「あっぱく」"], "ex": "増え続ける医療費が国の財政を<b>圧迫</b>している。"},
"32007": {"point": "「治療」は「ちりょう」。「治」には「じ」（政治）の読みもあるが、ここは「ち」。「療」は長音で「りょう」。", "meaning": "病気やけがを治すために手当てをすること。", "kr": "치료", "opts": ["", "ちりょ：「療」は長音で「りょう」", "じりょう：「治」は「政治」の「じ」もあるが、「治療」では「ち」", "じりょ：「ち」「りょう」の両方が誤り"], "ex": "虫歯の<b>治療</b>のため、毎週歯医者に通っている。"},
"32008": {"point": "「恋愛」は「れんあい」。「恋」は「れん」、「愛」は「あい」。「ん」の後でも「な」行に変わることはない。", "meaning": "互いに恋をし、愛し合うこと。", "kr": "연애", "opts": ["れんない：「ん」の後でも「愛」は「あい」のまま", "", "れあい：「恋」は「れん」", "れない：「恋」は「れん」、「愛」は「あい」"], "ex": "姉は大学時代からの長い<b>恋愛</b>の末に結婚した。"},
"32009": {"point": "「復興」は「ふっこう」。「復（ふく）」が「こ」の前で促音化して「ふっ」になる。「興」は「こう」で、「興味」の「きょう」と迷わせる問題。", "meaning": "衰えたり壊れたりしたものが、再び盛んになること。", "kr": "부흥", "opts": ["ふっきょう：「興」は「こう」。「きょう」は「興味」の読み", "ふくきょう：「ふく」は促音化し、「興」も「こう」", "", "ふくこう：「復」は「こ」の前で促音化して「ふっ」"], "ex": "地震の後、町の<b>復興</b>には十年近くかかった。"},
"32010": {"point": "「事業」は「じぎょう」。「事」は「じ」、「業」は「ぎょう」。「企業（きぎょう）」と混同しないこと。", "meaning": "社会的・経済的な目的をもって、計画的に行う仕事。", "kr": "사업", "opts": ["きごう：「事」は「じ」、「業」は「ぎょう」。「きごう」は「記号」の読み", "じごう：「業」は「ぎょう」。「ごう」は「自業自得」などの読み", "きぎょう：「事」は「じ」。「きぎょう」は「企業」の読み", ""], "ex": "兄は会社を辞めて、小さな<b>事業</b>を始めた。"},
"32011": {"point": "「意向」は「いこう」。「向」は長音で、濁らずに「こう」と読む（方向・傾向）。", "meaning": "どうするつもりかという考え・気持ち。", "kr": "의향", "opts": ["いご：「向」は「こう」。「いご」は「以後」「囲碁」の読み", "いごう：「向」は濁らず「こう」", "いこ：「向」は長音で「こう」", ""], "ex": "会社は社員の<b>意向</b>を聞いてから計画を決めた。"},
"32012": {"point": "「内緒」は「ないしょ」。「緒」は短く「しょ」と読む。「情緒（じょうちょ）」の「ちょ」と迷わせる問題。", "meaning": "他人に知られないように隠しておくこと。秘密。", "kr": "비밀, 몰래", "opts": ["", "ないしょう：「緒」は短く「しょ」", "ないじょ：「緒」は濁らない", "ないちょ：「緒」は「情緒」の「ちょ」もあるが、「内緒」では「しょ」"], "ex": "このことはみんなには<b>内緒</b>にしておいてね。"},
"32013": {"point": "「海峡」は「かいきょう」。「峡」は音読み「きょう」（峡谷）。形の似た「狭（きょう）」と同じ音。", "meaning": "陸地にはさまれて、海が狭くなっている所。", "kr": "해협", "opts": ["かいこう：「峡」は「きょう」。「かいこう」は「海溝」「開港」の読み", "かいそう：「峡」は「きょう」。「かいそう」は「海草」「改装」の読み", "", "かいしょう：「峡」は「きょう」。「かいしょう」は「解消」の読み"], "ex": "船は夜のうちに<b>海峡</b>を渡った。"},
"32014": {"point": "「大衆」は「たいしゅう」。「大」は「だい」ではなく「たい」（大会・大切と同じ）、「衆」は長音で「しゅう」。", "meaning": "社会の大多数をしめる一般の人々。", "kr": "대중", "opts": ["だいしゅう：「大衆」の「大」は濁らず「たい」", "だいすう：「だいすう」は「代数」の読み。「衆」は「しゅう」", "", "たいすう：「衆」は「しゅう」"], "ex": "演歌は昔から<b>大衆</b>に愛されてきた。"},
"32015": {"point": "「誇張」は「こちょう」。「誇」は短く「こ」（訓は「ほこる」）、「張」は「ちょう」。促音化もしない。", "meaning": "実際よりも大げさに表すこと。", "kr": "과장", "opts": ["", "こうちょう：「誇」は短く「こ」。「こうちょう」は「校長」「好調」の読み", "こうちょ：「こう」も「ちょ」も誤り", "こっちょう：促音化はせず「こちょう」"], "ex": "彼の話はいつも少し<b>誇張</b>されている。"},
"32016": {"point": "「接触」は「せっしょく」。「接（せつ）」が「し」の前で促音化して「せっ」、「触」は「しょく」（訓は「ふれる」）。", "meaning": "近づいてふれること。また、人と関わりを持つこと。", "kr": "접촉", "opts": ["せっそく：「触」は「しょく」", "せつぞく：「せつぞく」は「接続」の読み", "", "ぜつじょく：「接」も「触」も濁らない"], "ex": "コードの<b>接触</b>が悪く、電気がついたり消えたりする。"},
"32017": {"point": "「領域」は「りょういき」。「領」は長音で「りょう」、「域」は濁らず「いき」（地域・区域）。", "meaning": "ある力や権限が及ぶ範囲。また、学問などで専門とする範囲。", "kr": "영역", "opts": ["りょいき：「領」は長音で「りょう」", "", "ろういき：「領」は「りょう」", "りょういぎ：「域」は濁らず「いき」"], "ex": "これは私の専門の<b>領域</b>ではないので、よくわからない。"},
"32018": {"point": "「訴訟」は「そしょう」。「訴」は短く「そ」（訓は「うったえる」）、「訟」は長音で「しょう」。長音の位置を迷わせる問題。", "meaning": "裁判所に訴えて、判決を求めること。", "kr": "소송", "opts": ["そうしょ：「訴」は短く「そ」、「訟」は長く「しょう」で、逆になっている", "そしょ：「訟」は長音で「しょう」", "そうしょう：「訴」は短く「そ」", ""], "ex": "住民たちは工場を相手に<b>訴訟</b>を起こした。"},
"32019": {"point": "「無念」は「むねん」。「無」には「ぶ」（無事・無難）の読みもあるが、ここは「む」。意味の近い「残念」と迷わせる問題。", "meaning": "悔しく思うこと。残念に思う気持ち。", "kr": "원통함, 분함", "opts": ["ざんねん：意味は近いが「残念」の読み。「無」は「ざん」と読まない", "なしねん：「無」を訓読みで読むのは誤り", "ぶねん：「無」には「ぶ」の読みもあるが、「無念」では「む」", ""], "ex": "決勝で一点差で負け、<b>無念</b>の涙を流した。"},
"32020": {"point": "「操縦」は「そうじゅう」。「操」は「そう」、「縦」は長音の「じゅう」（訓は「たて」）。", "meaning": "飛行機や機械などを思いどおりに動かすこと。また、人を思いどおりに動かすこと。", "kr": "조종", "opts": ["そうじゅ：「縦」は長音で「じゅう」", "", "そうじょ：「縦」は「じゅう」", "そうじょう：「縦」は「じゅう」。「そうじょう」は「相乗」などの読み"], "ex": "彼は子どものころからの夢をかなえ、旅客機を<b>操縦</b>している。"},
"32021": {"point": "「運輸」は「うんゆ」。「輸」は短く「ゆ」と読む（輸出・輸入と同じ）。", "meaning": "旅客や貨物を運ぶこと。", "kr": "운수, 운송", "opts": ["うんゆう：「輸」は短く「ゆ」", "うんしゅう：「輸」は「しゅ」とは読まない", "", "うんしゅ：「輸」は「ゆ」"], "ex": "鉄道や航空などの<b>運輸</b>業界は、燃料費の値上がりに苦しんでいる。"},
"32022": {"point": "「著名」は「ちょめい」。「著」は短く「ちょ」（著者）、「名」は「めい」。「名字（みょうじ）」の「みょう」と迷わせる問題。", "meaning": "名前が世の中に広く知られていること。", "kr": "저명", "opts": ["ちょうみょう：「著」は短く「ちょ」、「名」は「めい」", "ちょうめい：「著」は短く「ちょ」", "ちょみょう：「名」は「みょう」ではなく「めい」", ""], "ex": "その会議には<b>著名</b>な学者が大勢参加した。"},
"32023": {"point": "「衝突」は「しょうとつ」。「衝」は濁らず「しょう」（衝撃・折衝）、「突」は「とつ」。", "meaning": "ぶつかること。また、意見や利害が対立して争うこと。", "kr": "충돌", "opts": ["そうとつ：「衝」は「しょう」", "ぞうとつ：「衝」は「しょう」で、濁らない", "", "じょうとつ：「衝」は濁らず「しょう」"], "ex": "会議で二人の意見が正面から<b>衝突</b>した。"},
"32024": {"point": "「患者」は「かんじゃ」。「者」は「しゃ」だが、「ん」の後で濁って「じゃ」になる。「患」は「かん」（訓は「わずらう」）。", "meaning": "病気やけがで、医者の治療を受ける人。", "kr": "환자", "opts": ["かんしゃ：「者」は濁って「じゃ」。「かんしゃ」は「感謝」の読み", "ちゅうしゃ：「患」は「かん」。「ちゅうしゃ」は「注射」の読み", "", "ちゅうじゃ：「患」は「かん」"], "ex": "冬になると、かぜの<b>患者</b>が増える。"},
"32025": {"point": "「寿命」は「じゅみょう」。「寿」は短く「じゅ」、「命」は「めい」ではなく「みょう」と読む。", "meaning": "生物が生きている期間。また、物が使える期間。", "kr": "수명", "opts": ["じゅうみょう：「寿」は短く「じゅ」", "", "じゅうめい：「寿」は「じゅ」、「命」は「みょう」", "じゅめい：「命」は「生命」の「めい」ではなく「みょう」"], "ex": "この電池は<b>寿命</b>が長いので、取り替える手間が少ない。"},
"32026": {"point": "「赴任」は「ふにん」。「赴」は音読み「ふ」（訓は「おもむく」）、「任」は濁らず「にん」。", "meaning": "命じられた勤務地へ行くこと。", "kr": "부임", "opts": ["", "ふじん：「任」は「にん」。「ふじん」は「夫人」「婦人」の読み", "とにん：「赴」は「ふ」で、「と」とは読まない", "とじん：「ふ」「にん」の両方が誤り"], "ex": "父は来月から大阪へ単身<b>赴任</b>することになった。"},
"32027": {"point": "「優秀」は「ゆうしゅう」。「優」も「秀」も長音で、「ゆう」「しゅう」と読む。", "meaning": "他よりも特にすぐれていること。", "kr": "우수", "opts": ["", "ゆうしゅ：「秀」は長音で「しゅう」", "ゆうすう：「秀」は「しゅう」", "ゆしゅう：「優」は長音で「ゆう」"], "ex": "彼女はクラスで最も<b>優秀</b>な学生だ。"},
"32028": {"point": "「保障」は「ほしょう」。「保」は短く「ほ」、「障」は「しょう」（故障・障害）。", "meaning": "ある状態や権利が損なわれないように守ること。", "kr": "보장", "opts": ["ほうしょう：「保」は短く「ほ」", "", "ほうそう：「ほうそう」は「放送」「包装」の読み", "ほそう：「障」は「しょう」。「ほそう」は「舗装」の読み"], "ex": "憲法は国民の基本的人権を<b>保障</b>している。"},
"32029": {"point": "「妨害」は「ぼうがい」。「妨」は「方（ほう）」と違って濁って「ぼう」（訓は「さまたげる」）、「害」は「がい」。", "meaning": "他人のじゃまをすること。", "kr": "방해", "opts": ["ほうかい：「ぼう」「がい」の両方が誤り。「ほうかい」は「崩壊」の読み", "ほうがい：「妨」は濁って「ぼう」", "ぼうかい：「害」は濁って「がい」", ""], "ex": "工事の騒音で睡眠を<b>妨害</b>された。"},
"32030": {"point": "「秩序」は「ちつじょ」。「秩」は促音化せず「ちつ」、「序」は短く「じょ」（順序）。", "meaning": "社会や物事が正しい順序・決まりに従って整っている状態。", "kr": "질서", "opts": ["ちつじょう：「序」は短く「じょ」", "", "ちっじょう：「秩」は「ちつ」、「序」は「じょ」", "ちっじょ：「秩」は促音化せず「ちつ」"], "ex": "災害の後も、人々は<b>秩序</b>を守って列に並んだ。"},
"32031": {"point": "「収穫」は「しゅうかく」。「収」は長音で「しゅう」、「穫」は濁らず「かく」（「獲」と同じ音）。", "meaning": "農作物を取り入れること。また、得られた成果。", "kr": "수확", "opts": ["しゅうがく：「穫」は濁らず「かく」。「しゅうがく」は「修学」の読み", "", "しゅがく：「収」は「しゅう」、「穫」は「かく」", "しゅかく：「収」は長音で「しゅう」"], "ex": "今年はりんごの<b>収穫</b>が例年より多かった。"},
"32032": {"point": "「弁解」は「べんかい」。「解」は「かい」（解決・理解）。「解熱（げねつ）」の「げ」の読みもあるが、ここは「かい」。", "meaning": "失敗や過ちについて、言い訳をすること。", "kr": "변명", "opts": ["べんじょう：「解」は「かい」", "べんしょう：「解」は「かい」。「べんしょう」は「弁償」の読み", "べんがい：「解」は濁らず「かい」", ""], "ex": "遅刻の理由をいくら<b>弁解</b>しても、聞いてもらえなかった。"},
"32033": {"point": "「暖房」は「だんぼう」。「暖」は「だん」、「房」は長音で「ぼう」。反対語「冷房（れいぼう）」と迷わせる問題。", "meaning": "部屋などを暖めること。また、その装置。", "kr": "난방", "opts": ["れいぼう：「冷房」の読み。「暖」は「だん」", "れいぼ：「暖」は「だん」、「房」は長音で「ぼう」", "", "だんぼ：「房」は長音で「ぼう」"], "ex": "この部屋は<b>暖房</b>が効きすぎて暑い。"},
"32034": {"point": "「炭素」は「たんそ」。「炭」は濁らず「たん」（訓は「すみ」）、「素」も濁らず「そ」。", "meaning": "元素の一つ。木炭やダイヤモンドなどを形作っている。", "kr": "탄소", "opts": ["", "たんぞ：「素」は濁らず「そ」", "だんそ：「炭」は濁らず「たん」", "だんぞ：「炭」も「素」も濁らない"], "ex": "二酸化<b>炭素</b>の排出を減らす取り組みが進んでいる。"},
"32035": {"point": "「先端」は「せんたん」。「端」は音読み「たん」で濁らない。訓の「はし」と迷わせる問題。", "meaning": "細長い物の一番先の部分。また、時代や流行の一番先。", "kr": "첨단, 끝", "opts": ["せんだん：「端」は濁らず「たん」", "せんばし：「端」は訓の「はし」ではなく音の「たん」", "", "せんはし：「先」は音、「端」は訓の混ぜ読みで誤り"], "ex": "この研究所では最<b>先端</b>の医療技術を開発している。"},
"32036": {"point": "「瞬間」は「しゅんかん」。「瞬」は「しゅん」（訓は「またたく」）、「間」は「かん」。", "meaning": "きわめて短い時間。また、ある事が起こったちょうどその時。", "kr": "순간", "opts": ["すんかん：「瞬」は「しゅん」", "", "ずんかん：「瞬」は濁らず「しゅん」", "じゅんかん：「瞬」は濁らず「しゅん」。「じゅんかん」は「循環」の読み"], "ex": "ゴールが決まった<b>瞬間</b>、スタジアムは歓声に包まれた。"},
"32037": {"point": "「改革」は「かいかく」。「革」は「かく」（革命・変革）、訓は「かわ」。", "meaning": "制度や組織などを改めて、よりよく変えること。", "kr": "개혁", "opts": ["かいさん：「革」は「かく」。「かいさん」は「解散」の読み", "かいこう：「革」は「かく」。「かいこう」は「開校」などの読み", "かいてい：「革」は「かく」。「かいてい」は「改定」「改訂」の読み", ""], "ex": "新しい首相は税制の<b>改革</b>に取り組んでいる。"},
"32038": {"point": "「故障」は「こしょう」。「障」は「しょう」（障害・保障）、訓は「さわる」。", "meaning": "機械や体などの働きが悪くなること。", "kr": "고장", "opts": ["", "こせい：「障」は「しょう」。「こせい」は「個性」の読み", "こしゅう：「障」は「しょう」", "こすい：「障」は「しょう」。「こすい」は「湖水」の読み"], "ex": "エレベーターが<b>故障</b>して、階段で上がった。"},
"32039": {"point": "「探検」は「たんけん」。「探」は「たん」（訓は「さがす」）、「検」は「けん」で、どちらも濁らない。", "meaning": "危険をおかして、知られていない土地などを調べに行くこと。", "kr": "탐험", "opts": ["たんげん：「検」は濁らず「けん」", "", "だんげん：「探」も「検」も濁らない。「だんげん」は「断言」の読み", "だんけん：「探」は濁らず「たん」"], "ex": "子どもたちは裏山へ<b>探検</b>に出かけた。"},
"32040": {"point": "「外来」は「がいらい」。二字とも音読みで、「外」は「がい」、「来」は「らい」。訓読みとの混ぜ読みに注意。", "meaning": "外から来ること。また、病院に通って診察を受けること。", "kr": "외래", "opts": ["そとき：「外」も「来」も音読みで「がいらい」", "そとらい：「外」は訓の「そと」ではなく音の「がい」", "がいき：「来」は「らい」", ""], "ex": "<b>外来</b>の受付は午前十一時までです。"},
"32041": {"point": "「閉鎖」は「へいさ」。「鎖」は濁らず「さ」（訓は「くさり」）。", "meaning": "出入り口などを閉ざすこと。また、施設などの活動をやめること。", "kr": "폐쇄", "opts": ["へいさつ：「鎖」は「さ」で、「つ」は付かない", "へいざつ：「鎖」は濁らず「さ」", "", "へいざ：「鎖」は濁らず「さ」"], "ex": "大雪のため、高速道路の一部が<b>閉鎖</b>された。"},
"32042": {"point": "「基礎」は「きそ」。「礎」は短く「そ」（訓は「いしずえ」）。", "meaning": "建物の土台。また、物事が成り立つもとになるもの。", "kr": "기초", "opts": ["", "きそう：「礎」は短く「そ」", "きしょう：「礎」は「そ」。「きしょう」は「気象」「起床」の読み", "きしょ：「礎」は「そ」"], "ex": "外国語は<b>基礎</b>をしっかり身につけることが大切だ。"},
"32043": {"point": "「名簿」は「めいぼ」。「名」は「めい」、「簿」は「帳簿（ちょうぼ）」と同じく濁って「ぼ」。", "meaning": "関係者の名前や住所などを書き並べた帳面。", "kr": "명부, 명단", "opts": ["ほいほ：「名」は「めい」、「簿」は「ぼ」", "", "めいふ：「簿」は「ふ」ではなく「ぼ」", "めいぶ：「簿」は「ぶ」ではなく「ぼ」"], "ex": "参加者は受付で<b>名簿</b>に名前を書いてください。"},
"32044": {"point": "「考慮」は「こうりょ」。「考」は濁らず「こう」、「慮」は短く「りょ」（配慮・遠慮）。", "meaning": "いろいろな事情をよく考えに入れること。", "kr": "고려", "opts": ["ごうりょう：「考」は濁らず「こう」、「慮」は短く「りょ」", "ごうりょ：「考」は濁らず「こう」", "こうりょう：「慮」は短く「りょ」。「こうりょう」は「香料」などの読み", ""], "ex": "相手の立場も<b>考慮</b>して、返事をするべきだ。"},
"32045": {"point": "「抽選」は「ちゅうせん」。「抽」は長音で「ちゅう」、「選」は「せん」。", "meaning": "くじを引くこと。くじ引き。", "kr": "추첨", "opts": ["", "ちゅせん：「抽」は長音で「ちゅう」", "ちょうせん：「抽」は「ちゅう」。「ちょうせん」は「挑戦」の読み", "ちょせん：「抽」は「ちゅう」"], "ex": "商店街の<b>抽選</b>で旅行券が当たった。"},
"32046": {"point": "「宣伝」は「せんでん」。「伝」は音読み「でん」（伝言・伝統）で、「てん」とは読まない。", "meaning": "商品や考えなどを、多くの人に広く知らせること。", "kr": "선전, 광고", "opts": ["せんせん：「伝」は「でん」。「せんせん」は「宣戦」の読み", "せんぜん：「伝」は「でん」", "せんてん：「伝」は濁って「でん」", ""], "ex": "新しい映画の<b>宣伝</b>が駅のあちこちに貼られている。"},
"32047": {"point": "「汚染」は「おせん」。「汚」は音読み「お」（訓は「よごれる」「きたない」）、「染」は「せん」（訓は「そめる」）。", "meaning": "空気・水・土などが有害な物質でよごれること。", "kr": "오염", "opts": ["ごせん：「汚」は「お」", "", "ごぜん：「汚」は「お」、「染」は「せん」。「ごぜん」は「午前」の読み", "おぜん：「染」は濁らず「せん」"], "ex": "工場の排水による川の<b>汚染</b>が問題になっている。"},
"32048": {"point": "「秘密」は「ひみつ」。「秘」は「ひ」、「密」は「みつ」。形の似た「機密（きみつ）」と迷わせる問題。", "meaning": "他人に知られないように隠していること。", "kr": "비밀", "opts": ["", "ひびつ：「密」は「みつ」", "きみつ：「秘」は「ひ」。「きみつ」は「機密」の読み", "きびつ：「ひ」「みつ」の両方が誤り"], "ex": "二人が付き合っていることは、まだ<b>秘密</b>だ。"},
"32049": {"point": "「取材」は「しゅざい」。「取」は音読み「しゅ」（訓は「とる」）、「材」は「ざい」（材料）。", "meaning": "記事や作品の材料を、人に会ったり現地へ行ったりして集めること。", "kr": "취재", "opts": ["しょざい：「取」は「しゅ」。「しょざい」は「所在」の読み", "しょうざい：「取」は「しゅ」", "", "しゅうざい：「取」は短く「しゅ」"], "ex": "記者は被災地で住民に<b>取材</b>した。"},
"32050": {"point": "「安静」は「あんせい」。「静」は濁らず「せい」（静止・冷静）。「安定（あんてい）」と混同しないこと。", "meaning": "病気などのとき、体を動かさずに静かに休むこと。", "kr": "안정(安靜)", "opts": ["あんでい：「静」は「せい」", "あんてい：「静」は「せい」。「あんてい」は「安定」の読み", "あんぜい：「静」は濁らず「せい」", ""], "ex": "熱が下がるまで、家で<b>安静</b>にしていてください。"},
"32051": {"point": "「老い」は「おい」。動詞「老いる（おいる）」の連用形が名詞になった語。音読みは「ろう」（老人）。", "meaning": "年をとること。年をとって体や心が衰えること。", "kr": "늙음, 노화", "opts": ["やまい：「病（やまい）」の読み", "とい：「問い」の読み", "ふい：「不意」の読み", ""], "ex": "最近、階段を上るのがつらくなり、<b>老い</b>を感じる。"},
"32052": {"point": "「臨む」は「のぞむ」。ここでは「海に臨む」で、場所が海に面しているという意味。「望む」と同じ読みで、音読みは「りん」（臨時）。", "meaning": "（場所が）海や川などに面する。また、ある場面・事態に向かい合う。", "kr": "면하다, 임하다", "opts": ["", "はずむ：「弾む」の読み", "めぐむ：「恵む」の読み", "はげむ：「励む」の読み"], "ex": "選手たちは万全の態勢で決勝に<b>臨んだ</b>。"},
"32053": {"point": "「誤って」は「あやまって」。「誤る（あやまる）」は判断ややり方を間違えること。音読みは「ご」（誤解）。意味の近い「まちがって」と迷わせる問題。", "meaning": "判断や方法を間違える。", "kr": "그르치다, 잘못하다", "opts": ["まちがって：意味は近いが「間違って」の読み。「誤」の訓は「あやまる」", "", "しくじって：意味は近いが「誤」の読みではない", "あやつって：「操って」の読み"], "ex": "道を<b>誤って</b>、知らない村に出てしまった。"},
"32054": {"point": "「健やか」は「すこやか」。体や心が丈夫で元気な様子。音読みは「けん」（健康）。同じ「〜やか」の形容動詞と迷わせる問題。", "meaning": "体や心が丈夫で元気な様子。", "kr": "건강하다, 튼튼하다", "opts": ["なごやか：「和やか」の読み", "すみやか：「速やか」の読み", "", "さわやか：「爽やか」の読み"], "ex": "赤ちゃんは<b>健やか</b>に育っている。"},
"32055": {"point": "「大幅」は「おおはば」。「大」も「幅」も訓読みで、「おお」＋「はば」。音読みの「だい」「ふく」との混ぜ読みに注意。", "meaning": "数量や程度の変化が大きいこと。", "kr": "대폭", "opts": ["おおふく：「幅」は訓の「はば」。「ふく」は「振幅」などの音読み", "だいふく：音読みは誤り。「だいふく」は「大福」の読み", "", "だいはば：「大」も訓で「おお」"], "ex": "台風の影響で、電車のダイヤが<b>大幅</b>に乱れた。"},
"32056": {"point": "「真心」は「まごころ」。訓読みで「ま」＋「こころ」、「心」が連濁して「ごころ」になる。", "meaning": "うそや飾りのない、誠実な心。", "kr": "진심, 정성", "opts": ["まこころ：「心」は連濁して「ごころ」", "", "しんしん：音読みは誤り。「しんしん」は「心身」の読み", "しんじん：音読みは誤り。「しんじん」は「信心」などの読み"], "ex": "母の<b>真心</b>のこもった手紙に、思わず涙が出た。"},
"32057": {"point": "「人質」は「ひとじち」。「人」は訓「ひと」、「質」は「質屋（しちや）」の「しち」が連濁して「じち」になる特別な読み。", "meaning": "要求を通すために、捕らえて自由を奪っておく人。", "kr": "인질", "opts": ["にんしつ：「人」は「ひと」、「質」は「じち」", "ひとしち：「しち」は連濁して「じち」", "ひとじつ：「質」は「しつ」ではなく「しち」が濁った「じち」", ""], "ex": "犯人は<b>人質</b>を解放して、警察に投降した。"},
"32058": {"point": "「訪れた」は「おとずれた」。「訪れる（おとずれる）」は人や場所をたずねること。音読みは「ほう」（訪問）。", "meaning": "人や場所をたずねる。また、季節などがやってくる。", "kr": "방문하다, 찾아오다", "opts": ["すたれた：「廃れた」の読み", "ふくれた：「膨れた」の読み", "", "みだれた：「乱れた」の読み"], "ex": "長い冬が終わり、ようやく春が<b>訪れた</b>。"},
"32059": {"point": "「悪者」は「わるもの」。「悪（わる）」＋「者（もの）」の訓読み。音読みの「あくしゃ」とは読まない。", "meaning": "悪いことをする人。悪人。", "kr": "나쁜 사람, 악역", "opts": ["", "おもの：「悪」は「わる」。「お」は「悪寒」などの音読み", "あくしゃ：音読みは誤り。訓読みで「わるもの」", "あくじゃ：音読みは誤り。訓読みで「わるもの」"], "ex": "本当は彼のせいではないのに、いつも<b>悪者</b>にされる。"},
"32060": {"point": "「献立」は「こんだて」。「献」は普通「けん」（献血）だが、この語では特別に「こん」と読む。「立」は訓「たて」が連濁して「だて」。", "meaning": "料理の種類や組み合わせ、出す順序などの計画。メニュー。", "kr": "식단, 메뉴", "opts": ["", "こんりつ：「立」は「だて」", "けんだて：「献」は「けん」が普通だが、「献立」では「こん」", "けんりつ：「けんりつ」は「県立」の読み"], "ex": "今夜の<b>献立</b>は、焼き魚とみそ汁だ。"},
"32061": {"point": "「催して」は「もよおして」。「眠気を催す」は、眠気などの感覚が自然に起こること。「会を催す」（開く）の意味もある。音読みは「さい」（開催）。", "meaning": "ある気持ちや体の状態が起こる。また、会などを開く。", "kr": "(졸음 등을) 느끼다, 개최하다", "opts": ["みたして：「満たして」の読み", "", "はたして：「果たして」の読み", "ひやかして：「冷やかして」の読み"], "ex": "町内会では毎年夏に盆踊りを<b>催して</b>いる。"},
"32062": {"point": "「煩わしい」は「わずらわしい」。手間がかかってめんどうな様子。「煩う（わずらう）」と同じ読みで、音読みは「はん」（煩雑）。", "meaning": "手間がかかってめんどうだ。うっとうしい。", "kr": "번거롭다, 귀찮다", "opts": ["うるわしい：「麗しい」の読み", "いやわしい：このような語はない", "まぎらわしい：「紛らわしい」の読み", ""], "ex": "書類の手続きが多くて<b>煩わしい</b>。"},
"32063": {"point": "「素直」は「すなお」。「素」を「す」（素顔・素足の「す」）、「直」を「なお」と読む特別な読み方。意味の近い「率直（そっちょく）」と混同しないこと。", "meaning": "性格や態度にひねくれたところがなく、ありのままである様子。", "kr": "솔직하다, 순순하다", "opts": ["", "そちょく：音読みを並べた形だが、そういう読みはない", "そっちょく：「率直」の読み。意味は近いが漢字が違う", "すじき：「直」を「じき」と読むのは「正直（しょうじき）」など。この語では「なお」"], "ex": "子どもは注意されると、<b>素直</b>に謝った。"},
"32064": {"point": "「音色」は「ねいろ」。「音」を訓読みの「ね」（本音・音を上げるの「ね」）、「色」を「いろ」と読む。「おと」と読みたくなるのが落とし穴。", "meaning": "その楽器や声に特有の音の感じ。", "kr": "음색", "opts": ["おとしき：「音」は「ね」、「色」は「いろ」。「しき」は「景色」などの読み", "ねしき：「色」は訓読みで「いろ」", "おといろ：「音」はこの語では「ね」と読む", ""], "ex": "このギターは柔らかい<b>音色</b>が魅力だ。"},
"32065": {"point": "「描く」は「えがく」（「かく」とも読む）。絵や文章で様子を表すこと。音読みは「ビョウ」（描写）。", "meaning": "絵や文章などで、物事の姿や様子を表現すること。", "kr": "그리다, 묘사하다", "opts": ["", "きずいた＝築いた。「描」の読みではない", "さばいた＝裁いた・捌いた。「描」の読みではない", "もがいた＝苦しんで手足を動かした。「描」の読みではない"], "ex": "この小説は戦後の若者の姿をリアルに<b>描いて</b>いる。"},
"32066": {"point": "「傾ける」は「かたむける」。「傾く（かたむく）」の他動詞で、「心を傾ける」は一つのことに心を集中させること。音読みは「ケイ」（傾向）。", "meaning": "斜めにすること。「心・耳を傾ける」の形で、そのことに心を集中すること。", "kr": "기울이다", "opts": ["むけて＝向けて。「傾」の読みではない", "さずけて＝授けて。「傾」の読みではない", "", "もうけて＝設けて・儲けて。「傾」の読みではない"], "ex": "彼は部下の意見に熱心に耳を<b>傾けた</b>。"},
"32067": {"point": "「整える」は「ととのえる」。乱れたものをきちんとした状態にすること。「整う（ととのう）」と同じ読み。音読みは「セイ」（整理）。", "meaning": "乱れているものをきちんとした状態にすること。", "kr": "가다듬다, 정돈하다", "opts": ["そなえて＝備えて・供えて。「整」の読みではない", "ひかえて＝控えて。「整」の読みではない", "ふまえて＝踏まえて。「整」の読みではない", ""], "ex": "面接の前に、鏡の前で髪を<b>整えた</b>。"},
"32068": {"point": "「劣る」は「おとる」。能力や価値が他より低いこと。音読みは「レツ」（劣等・劣悪）。反対の意味の「勝る（まさる）」と混同しないこと。", "meaning": "能力や価値が他より低いこと。", "kr": "뒤떨어지다, 못하다", "opts": ["ほこる＝誇る。「劣」の読みではない", "", "まさる＝勝る・優る。「劣る」とは反対の意味", "はかる＝計る・測る・図る。「劣」の読みではない"], "ex": "値段は安いが、品質は他社の製品に<b>劣らない</b>。"},
"32069": {"point": "「黙る」は「だまる」。何も言わないでいること。音読みは「モク」（沈黙・黙読）。", "meaning": "何も言わないでいること。口を閉じること。", "kr": "잠자코 있다, 입을 다물다", "opts": ["かたって＝語って。「黙」の読みではない", "もぐって＝潜って。「黙」の読みではない", "", "すわって＝座って。「黙」の読みではない"], "ex": "彼は何を聞かれても<b>黙った</b>まま下を向いていた。"},
"32070": {"point": "「練り直す」は「ねりなおす」。「練る（ねる）」＋「直す（なおす）」で、計画や案をもう一度よく考え直すこと。音読みは「レン」（練習）。", "meaning": "計画や案などを、もう一度よく考えて作り直すこと。", "kr": "다시 짜다, 재검토하다", "opts": ["ひねりだした＝捻り出した。「練」の読みではない", "やりなおした＝やり直した。「練」を「や」とは読まない", "", "ぬりなおした＝塗り直した。「塗」の読みで、「練」ではない"], "ex": "予算が足りないので、企画を一から<b>練り直す</b>ことにした。"},
"32071": {"point": "「見逃す」は「みのがす」。「逃す（のがす）」は「逃げる（にげる）」と同じ漢字だが読みが違うので注意。ここでは、悪いことを知りながら許すという意味。", "meaning": "見ていながら気づかずにいること。また、悪いことを知りながらとがめずに許すこと。", "kr": "눈감아 주다, 놓치다", "opts": ["みにげして：「にげ」は「逃げる」の読み。「見逃す」は「のがす」", "", "みはがして：「はがす」は「剥がす」。「逃」の読みではない", "みなおして＝見直して。「逃」の読みではない"], "ex": "一度だけなら、この失敗は<b>見逃して</b>あげよう。"},
"32072": {"point": "「値引き」は「ねびき」。「値」を訓読みの「ね」（値段の「ね」）と読み、「引き」は連濁して「びき」になる。", "meaning": "決まっている値段から、いくらか安くすること。", "kr": "할인, 가격 인하", "opts": ["あたいびき：「値」を「あたい」と読むのは「値する」など。この語では「ね」", "あたいひき：「値」は「ね」、「引き」は連濁して「びき」", "", "ねひき：「引き」は連濁して「びき」"], "ex": "閉店前になると、弁当が半額に<b>値引き</b>される。"},
"32073": {"point": "「操る」は「あやつる」。人を陰から思いどおりに動かすこと。音読みは「ソウ」（操作・体操）。", "meaning": "人を陰から思いどおりに動かすこと。また、道具や言葉などをうまく使いこなすこと。", "kr": "조종하다, 다루다", "opts": ["まかなって＝賄って。「操」の読みではない", "とどこおって＝滞って。「操」の読みではない", "さえぎって＝遮って。「操」の読みではない", ""], "ex": "彼女は五か国語を自由に<b>操る</b>。"},
"32074": {"point": "「手薄」は訓読みで「てうす」。「手」を「て」、「薄」を「うす」（薄いの「うす」）と読む。音読みの「ハク」（薄弱）と混同しないこと。", "meaning": "人手や物の数量が少なく、不十分なこと。", "kr": "허술함, 부족함", "opts": ["てはく：「薄」は訓読みで「うす」", "", "しゅはく：両方音読みにした形。この語は訓読み", "しゅうす：「手」は「て」と読む"], "ex": "夜間は警備が<b>手薄</b>になりやすい。"},
"32075": {"point": "「間柄」は訓読みで「あいだがら」。「間」を「あいだ」と読み、「柄（がら）」は連濁して「がら」。人と人との関係を表す。", "meaning": "人と人との関係。親族関係や付き合いの関係。", "kr": "사이, 관계", "opts": ["まへい：「柄」の音読み「ヘイ」は「横柄」などで使う。この語は「あいだがら」", "けんへい：「間」「柄」の音読みを並べた形。この語は訓読み", "まがら：「間」はここでは「あいだ」", ""], "ex": "彼とは何でも話せる<b>間柄</b>だ。"},
"32076": {"point": "「慰める」は「なぐさめる」。悲しみや苦しみをやわらげること。音読みは「イ」（慰安・慰労）。", "meaning": "悲しみや苦しみをやわらげ、心を楽にさせること。", "kr": "위로하다, 달래다", "opts": ["ながめた＝眺めた。「慰」の読みではない", "ちぢめた＝縮めた。「慰」の読みではない", "", "めざめた＝目覚めた。「慰」の読みではない"], "ex": "試合に負けた後輩を、先輩たちが優しく<b>慰めた</b>。"},
"32077": {"point": "「地元」は「じもと」。「地」を「じ」（地面・地震の「じ」）、「元」を訓読みの「もと」と読む重箱読み。", "meaning": "その物事に直接関係のある土地。また、自分が住んでいる土地。", "kr": "그 고장, 현지", "opts": ["ちげん：両方音読みにした形。この語は「じもと」", "ちもと：「地」はこの語では「じ」", "じげん：「元」は「もと」。「じげん」は「次元」の読み", ""], "ex": "大学を卒業した後、<b>地元</b>の企業に就職した。"},
"32078": {"point": "「焦る」は「あせる」。思うようにいかず、気持ちが落ち着かないこと。同じ字の「焦げる（こげる）」と読みが違う。音読みは「ショウ」（焦点）。", "meaning": "思うようにならず、早くしようとして落ち着きを失うこと。", "kr": "초조해하다, 조급해하다", "opts": ["とどこおって＝滞って。「焦」の読みではない", "とどまって＝留まって・止まって。「焦」の読みではない", "さとって＝悟って。「焦」の読みではない", ""], "ex": "時間がないからといって<b>焦る</b>と、かえってミスが増える。"},
"32079": {"point": "「手際」は「てぎわ」。「際（きわ）」が連濁して「ぎわ」になる（「窓際（まどぎわ）」と同じ）。音読みの「サイ」（国際）と混同しないこと。", "meaning": "物事を処理するやり方や腕前。", "kr": "솜씨, 수완", "opts": ["てきわ：「際」は連濁して「ぎわ」", "", "しゅさい：音読みにした形。「主催」と同じ音で、この語の読みではない", "しゅざい：音読みにした形。「取材」と同じ音で、この語の読みではない"], "ex": "彼女は<b>手際</b>よく夕食の準備を済ませた。"},
"32080": {"point": "「目覚ましい」は「めざましい」。「目覚ます（めざます）」から来た形容詞で、「覚」は連濁して「ざ」になる。驚くほどすばらしい様子を表す。", "meaning": "驚くほどすばらしい様子。", "kr": "눈부시다, 놀랍다", "opts": ["めさましい：「覚」は連濁して「ざ」", "", "まさましい：「目」はここでは「め」。「覚」も連濁して「ざ」", "まざましい：「目」はここでは「め」"], "ex": "この国の経済は<b>目覚ましい</b>発展を遂げた。"},
"32081": {"point": "「踏む」は「ふむ」。「手続きを踏む」は、決められた順序どおりに物事を行うこと。音読みは「トウ」（踏襲）。", "meaning": "足で押さえつけること。「手続き・段階を踏む」の形で、決められた順序どおりに行うこと。", "kr": "밟다, 거치다", "opts": ["", "かむ＝噛む。「踏」の読みではない", "のむ＝飲む。「踏」の読みではない", "はげむ＝励む。「踏」の読みではない"], "ex": "正式な手順を<b>踏んで</b>、申請を行ってください。"},
"32082": {"point": "「尋ねる」は「たずねる」。わからないことを人に聞くこと。同じ音の「訪ねる（訪問する）」と使い分ける。音読みは「ジン」（尋問）。", "meaning": "わからないことを人に聞くこと。", "kr": "묻다, 질문하다", "opts": ["かさねよう＝重ねよう。「尋」の読みではない", "つらねよう＝連ねよう。「尋」の読みではない", "たばねよう＝束ねよう。「尋」の読みではない", ""], "ex": "駅員に乗り換えの方法を<b>尋ねた</b>。"},
"32083": {"point": "「懲りる」は「こりる」で、「懲りず」はひどい目にあってもやめずに、という意味。音読みは「チョウ」（懲役・懲罰）。", "meaning": "（「懲りる」）ひどい目にあって、もうしないと思うこと。「懲りず」は、それでもやめずに、の意味。", "kr": "질리지 않고, 단념하지 않고", "opts": ["かりず：「借りず」の読み。「懲」の読みではない", "", "おりず：「降りず・下りず」の読み。「懲」の読みではない", "ちょうりず：音読み「チョウ」を混ぜた形で、そういう読みはない"], "ex": "彼は何度断られても<b>懲りずに</b>誘い続けている。"},
"32084": {"point": "「隠れる」は「かくれる」。人に見えない所に身を置くこと。音読みは「イン」（隠居）。", "meaning": "人に見えない所に身を置くこと。", "kr": "숨다", "opts": ["すたれた＝廃れた。「隠」の読みではない", "のがれた＝逃れた。「隠」の読みではない", "", "たれた＝垂れた。「隠」の読みではない"], "ex": "子どもたちはカーテンの後ろに<b>隠れて</b>遊んでいる。"},
"32085": {"point": "「励ます」は「はげます」。元気づけてやる気を起こさせること。「励む（はげむ）」と同じ読み。音読みは「レイ」（激励・奨励）。", "meaning": "元気づけて、やる気を起こさせること。", "kr": "격려하다", "opts": ["れいまして：音読み「レイ」を使った形で、そういう読みはない", "", "すまして＝済まして・澄まして。「励」の読みではない", "なやまして＝悩まして。「励」の読みではない"], "ex": "友人たちに<b>励まされて</b>、もう一度挑戦する気になった。"},
"32086": {"point": "「避ける」は「さける」。好ましくないものに近づかないようにすること。音読みは「ヒ」（避難・回避）。", "meaning": "好ましくないものに近づかないようにすること。", "kr": "피하다", "opts": ["もうけて＝設けて・儲けて。「避」の読みではない", "", "かたむけて＝傾けて。「避」の読みではない", "うけて＝受けて。「避」の読みではない"], "ex": "混雑を<b>避けて</b>、朝早く出かけた。"},
"32087": {"point": "「強める」は「つよめる」。「強い（つよい）」から来た動詞で、力や程度を強くすること。意味の近い「高める（たかめる）」と混同しないこと。", "meaning": "力や程度を強くすること。", "kr": "강화하다, 세게 하다", "opts": ["かためて＝固めて。「強」の読みではない", "さだめて＝定めて。「強」の読みではない", "", "たかめて＝高めて。意味は近いが「高」の読み"], "ex": "警察は飲酒運転の取り締まりを<b>強めて</b>いる。"},
"32088": {"point": "「眺める」は「ながめる」。遠くや全体をじっと見ること。「つくづく眺める」は、しみじみと見つめること。音読みは「チョウ」（眺望）。", "meaning": "遠くや全体をじっと見ること。また、見つめながら物思いにふけること。", "kr": "바라보다", "opts": ["そめる＝染める。「眺」の読みではない", "しずめる＝沈める・静める。「眺」の読みではない", "さだめる＝定める。「眺」の読みではない", ""], "ex": "窓から夕日に染まる海を<b>眺めた</b>。"},
"32089": {"point": "割合を表す「割」は訓読みで「わり」。「1割」は10パーセント。音読みの「カツ」は「分割・割愛」などの熟語で使う。", "meaning": "全体を十等分したうちの一つ分。10パーセント。", "kr": "할(10퍼센트)", "opts": ["", "かつ：音読み「カツ」は「分割」などの熟語の読み。割合を表すときは「わり」", "たし：「足し」の読み。「割」の読みではない", "かけ：「掛け」の読み。「割」の読みではない"], "ex": "会員になると、全商品が2<b>割</b>引きになる。"},
"32090": {"point": "「透き通る」は「すきとおる」。「透く（すく）」＋「通る（とおる）」。「通る」は「とおる」と長音を「お」で書く。音読みは「トウ」（透明）。", "meaning": "物を通して向こうがはっきり見えること。また、声などが澄んでいること。", "kr": "투명하다, 비쳐 보이다", "opts": ["", "ときとおる：「透」は訓読みで「す（く）」", "つきとおる：「突き通る」の読み。「透」は「す（く）」", "はきとおる：「透」を「は」とは読まない"], "ex": "この湖の水は底まで<b>透き通って</b>いる。"},
"32091": {"point": "「上回る」は「うわまわる」。「上」を「うわ」と読むのは「上着・上履き」などと同じ。反対語は「下回る（したまわる）」。", "meaning": "ある数量や程度を超えること。", "kr": "웃돌다, 상회하다", "opts": ["", "したたまわる：「上」を「した」とは読まない。「した」は「下」の読み", "うえまわる：この語では「上」は「うわ」", "しもまわる：「上」を「しも」とは読まない。「しも」は「下」の読み"], "ex": "今年の売り上げは、去年を大きく<b>上回った</b>。"},
"32092": {"point": "「経る」は「へる」で、「〜を経て」はある場所や段階を通って、という意味。同じ字の「経つ（たつ）」は時間が過ぎる意味で、ここには合わない。音読みは「ケイ」（経由）。", "meaning": "ある場所や段階を通って過ぎること。", "kr": "거치다", "opts": ["えて＝得て。「経」の読みではない", "そって＝沿って。「経」の読みではない", "", "たって：「経つ」は時間が過ぎる意味。「〜を経て（場所を通って）」は「へて」"], "ex": "彼は営業部を<b>経て</b>、現在は企画部で働いている。"},
"32093": {"point": "「雷」は訓読みで「かみなり」。音読みは「ライ」（落雷・雷雨）。", "meaning": "雲と雲、雲と地面の間で起こる放電。また、それによって起こる大きな音。", "kr": "천둥, 벼락", "opts": ["みなもと＝源。「雷」の読みではない", "おもむき＝趣。「雷」の読みではない", "たましい＝魂。「雷」の読みではない", ""], "ex": "遠くで<b>雷</b>が鳴り始めたので、急いで家に帰った。"},
"32094": {"point": "「取引」は「とりひき」。「取り引き」の送り仮名を省いた形で、「引」は連濁せず「ひき」と読む。", "meaning": "商売として、物やお金をやりとりすること。", "kr": "거래", "opts": ["とりびき：「引」は連濁せず「ひき」", "じゅいん：「取」の音読みは「シュ」。この語は訓読み", "", "しゅいん：音読みを並べた形。この語は訓読みで「とりひき」"], "ex": "その会社とは十年以上<b>取引</b>が続いている。"},
"32095": {"point": "「交わす」は「かわす」。「議論・言葉を交わす」のように、互いにやりとりすること。音読みは「コウ」（交換）。", "meaning": "やりとりすること。互いに〜し合うこと。", "kr": "주고받다, 나누다", "opts": ["", "がわした：語の初めは濁らず「か」", "あわした：「合わした」の読み。「交」の読みではない", "こわした＝壊した。「交」の音読み「コウ」と混同しないこと"], "ex": "二人は笑顔で握手を<b>交わした</b>。"},
"32096": {"point": "「雪崩」は熟字訓で「なだれ」。一字ずつの読み（「雪＝ゆき」「崩＝くず・ほう」）とは関係なく、二字まとめて読む。", "meaning": "山の斜面に積もった大量の雪が、一度に崩れ落ちること。", "kr": "눈사태", "opts": ["ゆくえ＝行方（熟字訓）。「雪崩」の読みではない", "", "せつほう：音読み「セツ・ホウ」を並べた形。この語は熟字訓", "ゆきだれ：一字ずつ訓読みしたような形で、誤り"], "ex": "春先は気温が上がり、<b>雪崩</b>が起きやすい。"},
"32097": {"point": "「合間」は訓読みで「あいま」。「合」を「あい」（話し合いの「あい」）、「間」を「ま」（すき間の「ま」）と読む。", "meaning": "物事と物事の間の、短い空き時間。", "kr": "짬, 틈", "opts": ["あいかん：「間」は訓読みで「ま」", "", "ごうま：「合」は訓読みで「あい」", "ごうかん：両方音読みにした形で、誤り"], "ex": "仕事の<b>合間</b>にコーヒーを飲んで一息ついた。"},
"32098": {"point": "「醜い」は「みにくい」。見た目や行いが見苦しいこと。「醜い争い」は見苦しい争い。音読みは「シュウ」（醜悪・醜態）。", "meaning": "見た目が悪い様子。また、行いや態度が見苦しく、恥ずかしい様子。", "kr": "추하다, 보기 흉하다", "opts": ["", "こころよい＝快い。「醜」の読みではない", "いちじるしい＝著しい。「醜」の読みではない", "いさぎよい＝潔い。「醜」の読みではない"], "ex": "遺産をめぐって、兄弟が<b>醜い</b>争いを続けている。"},
"32099": {"point": "「稲」は訓読みで「いね」。複合語では「いな」と読むこともある（稲作・稲妻）。音読みは「トウ」（水稲）。", "meaning": "米を実らせる植物。主に水田で育てる。", "kr": "벼", "opts": ["くき＝茎。「稲」の読みではない", "しお＝塩・潮。「稲」の読みではない", "つつ＝筒。「稲」の読みではない", ""], "ex": "秋になると、田んぼの<b>稲</b>が黄金色に実る。"},
"32100": {"point": "「競う」は「きそう」。互いに負けまいと張り合うこと。意味の近い「争う（あらそう）」と混同しないこと。音読みは「キョウ・ケイ」（競争・競馬）。", "meaning": "互いに負けまいと張り合うこと。", "kr": "겨루다, 경쟁하다", "opts": ["あらそって＝争って。意味は近いが「争」の読み", "", "ただよって＝漂って。「競」の読みではない", "たたかって＝戦って・闘って。「競」の読みではない"], "ex": "子どもたちは<b>競って</b>手を挙げた。"},
"32101": {"point": "「痛い出費」は、生活に響くほど大きなお金の支払いのこと。結婚式のご祝儀などで家計からお金が出ていったという文脈なので、支出を表す「出費」が合う。", "meaning": "費用を出すこと。また、その費用。", "kr": "지출, 비용", "opts": ["浪費＝お金や時間を無駄に使うこと。祝儀は無駄遣いではないので合わない", "経費＝事業や仕事を行うのにかかる費用。会社などで使い、家計には合わない", "実費＝実際にかかった費用（「交通費は実費で支給」）。「痛い実費」とは言わない", ""], "ex": "車の修理代が十万円もかかり、思わぬ<b>出費</b>になった。"},
"32102": {"point": "「煙たい」は、煙が目や喉にしみて苦しい様子。主語が「たばこの煙」なので「けむたかった」が合う。", "meaning": "煙が立ちこめて、息苦しく目にしみる様子。", "kr": "냅다, 매캐하다", "opts": ["まずしい＝貧しい。お金や物が少ない様子で、煙には使わない", "するどい＝鋭い。刃物の先がとがっている、感覚が優れている様子", "", "まぶしい＝光が強くて目を開けていられない様子。光について言い、煙には使わない"], "ex": "たき火の風下に立つと、<b>煙たくて</b>涙が出てきた。"},
"32103": {"point": "おぼれた子どもを危険を恐れずに助けた若者なので、恐れずに立ち向かう様子を表す「勇敢な」が合う。", "meaning": "危険や困難を恐れず、勇ましく立ち向かう様子。", "kr": "용감하다", "opts": ["愉快な＝楽しく面白い様子。人命救助の行為とは結びつかない", "膨大な＝量や規模が非常に大きい様子。人には使わない", "迅速な＝物事の処理が非常に速い様子。「迅速な若者」とは言わない", ""], "ex": "火事の現場で<b>勇敢な</b>消防士が住民を救い出した。"},
"32104": {"point": "「おのずから明らかになる」は、何もしなくても自然にはっきりする、という決まった言い方。真相が自然にわかる、という文脈なので「おのずから」。", "meaning": "自然に。ひとりでに。", "kr": "저절로, 자연히", "opts": ["", "いやいや＝気が進まないまま、しかたなく（「いやいや勉強する」）", "ぼつぼつ＝少しずつ物事を始める様子（「ぼつぼつ出かけよう」）", "ちやほや＝人をおだてて甘やかす様子（「ちやほやされる」）"], "ex": "努力を続けていれば、結果は<b>おのずから</b>ついてくるものだ。"},
"32105": {"point": "入学した新入生に対して、学校の仕組みや生活について説明する会が開かれる、という文脈なので「オリエンテーション」。「〜が開かれる」とも結びつく。", "meaning": "新しく入った人に、環境や仕事の内容などを説明し、慣れさせるための説明会。", "kr": "오리엔테이션", "opts": ["アンケート＝多くの人に同じ質問をして意見を集める調査。「開かれる」ものではない", "オートメーション＝機械による作業の自動化", "レポート＝報告書。学生が書いて出すもので、「開かれる」とは言わない", ""], "ex": "新入社員向けの<b>オリエンテーション</b>が本社の会議室で行われた。"},
"32106": {"point": "「虫がいい」は、自分の都合ばかり考えて、ずうずうしい様子を表す慣用句。人のノートで100点をとろうとするのは自分勝手な考えなので「むし」。", "meaning": "（「虫がいい」の形で）自分に都合のいいことばかり考えて、ずうずうしい様子。", "kr": "뻔뻔하다, 제멋대로다", "opts": ["ねこ＝「猫をかぶる」「猫の手も借りたい」などに使う。「ねこがいい」とは言わない", "うま＝「馬が合う」は気が合うこと。「うまがいい」とは言わない", "あじ＝「味がいい」は食べ物がおいしいことで、ずうずうしさの意味はない", ""], "ex": "何もしないで給料だけ上げてほしいなんて、<b>虫</b>がいい話だ。"},
"32107": {"point": "「核実験」は核兵器を爆発させて性能を調べる実験。影響が完全には予測できない実験、という文脈に合うのは「核」。", "meaning": "原子核。「核〜」で核兵器・核エネルギーに関わることを表す。", "kr": "핵", "opts": ["某＝名前をはっきり言わない語（「某会社」「某氏」）。「某実験」は不自然", "微＝ごく小さいこと（「微生物」「微調整」）。「微実験」とは言わない", "", "貴＝相手を敬う語（「貴社」「貴校」）。実験には付かない"], "ex": "その国の<b>核</b>実験に対して、各国が強く抗議した。"},
"32108": {"point": "「使い果たす」は、残らず全部使ってしまうこと。「貯金をすべて」とあるので、「〜果たす（すっかり〜する）」の「はたして」が合う。", "meaning": "（動詞の連用形について）すっかり〜してしまう。「使い果たす」で全部使い切ること。", "kr": "다 써 버리다, 탕진하다", "opts": ["", "使いあげる＝このような複合動詞はない", "使いぬく＝最後まで使い通すこと。「貯金を使いぬく」とは言わない", "使いとおす＝一つのものを最後まで使い続けること。貯金には合わない"], "ex": "旅行先で財布の中のお金を<b>使い果たして</b>しまった。"},
"32109": {"point": "人間が動物と違うのは、新しい文化を作り出すこと。「文化を創造する」が自然な組み合わせ。", "meaning": "それまでなかったものを新しく作り出すこと。", "kr": "창조", "opts": ["", "想像＝実際にないことを心の中に思い浮かべること。「文化を想像する」は不自然", "構想＝計画や考えの組み立てを練ること（「新事業を構想する」）", "創作＝小説・絵などの芸術作品を作ること。文化全体には使わない"], "ex": "芸術家は常に新しい価値を<b>創造</b>しようとしている。"},
"32110": {"point": "国が独立したことを国の内外に正式に発表するのは「独立を宣言する」。「独立宣言」という語もある。", "meaning": "考えや方針を外に向かって公式に表明すること。", "kr": "선언", "opts": ["明言＝はっきり言うこと。個人の発言に使い、「独立を明言する」は不自然", "断言＝自信をもってきっぱり言い切ること。正式な表明の意味はない", "公言＝人前で堂々と言うこと（「優勝すると公言する」）。国の正式な発表には使わない", ""], "ex": "議長が開会を<b>宣言</b>して、会議が始まった。"},
"32111": {"point": "暗がりから思いがけなく急に人が出てきた、という場面。「不意に」は予期しないときに突然、という意味で「現れる」と結びつく。", "meaning": "思いがけないときに突然起こる様子。", "kr": "갑자기, 불시에", "opts": ["意外＝思っていたことと違う様子。「意外に人が現れた」は不自然", "案外＝予想と違って（「テストは案外易しかった」）。突然の意味はない", "", "微妙＝簡単に言い表せない細かな様子。出現の様子には使わない"], "ex": "<b>不意に</b>名前を呼ばれて、思わず振り返った。"},
"32112": {"point": "不況で会社が人員を減らした、という文脈。人数や費用を減らすことは「削減」で、「人員削減」はよく使う組み合わせ。", "meaning": "数量・金額などを削って減らすこと。", "kr": "삭감, 감축", "opts": ["削除＝文章やデータの一部を削って取り除くこと。人員には使わない", "", "軽減＝負担や苦痛を軽くすること（「負担を軽減する」）。人員には使わない", "加減＝程度を調節すること（「力を加減する」）"], "ex": "経費<b>削減</b>のため、会議室の照明をこまめに消すことになった。"},
"32113": {"point": "「突き詰める」は、物事をとことんまで追究すること。スキルを磨いて最後まで深めていく、という文脈なので「つめて」。", "meaning": "物事を最後のところまで深く考え、追究すること。", "kr": "끝까지 파고들다, 철저히 추구하다", "opts": ["突き捨てる＝このような複合動詞はない", "突き合わせる＝二つのものを比べて確かめること（「書類を突き合わせる」）", "", "突き果たす＝このような複合動詞はない"], "ex": "問題の原因を<b>突き詰めて</b>考えると、管理体制の甘さに行き着く。"},
"32114": {"point": "「理想郷」は、理想として思い描く、すばらしい世界のこと。「理想郷を描く」で、理想の世界を思い描くという意味になる。", "meaning": "（「〜郷」の形で）その性質を持つ土地・場所。「理想郷」で理想的な世界。", "kr": "-향(이상향), 고장", "opts": ["帯＝ある範囲の地域・時間（「地震帯」「時間帯」）。「理想帯」とは言わない", "", "孔＝あな（「鼻孔」）。「理想孔」とは言わない", "臭＝におい、また「〜くさい」様子（「役人臭」）。「理想臭」とは言わない"], "ex": "その小さな島は、争いのない<b>理想郷</b>として知られていた。"},
"32115": {"point": "クラブがどのような仕組みで運営されているか尋ねる文。組織や制度の仕組みを表す「システム」が合う。", "meaning": "全体をまとめる仕組み。制度・組織。", "kr": "시스템, 체계, 구조", "opts": ["オートマチック＝自動式。機械の仕組みに使い、クラブの運営には合わない", "", "レギュラー＝正選手、また正規・定期のもの。「どういうレギュラー」は不自然", "サイクル＝周期、また自転車。仕組みの意味はない"], "ex": "この店では、ポイントがたまると割引になる<b>システム</b>を導入している。"},
"32116": {"point": "「肩を持つ」は、対立している一方の味方をすること、ひいきすること。「君のことばかり〜をもつ」なので「かた」。", "meaning": "（「肩を持つ」の形で）一方の味方をする。ひいきする。", "kr": "편을 들다", "opts": ["あたま＝「頭を持つ」という慣用句はない（「頭を抱える」「頭が固い」など）", "こし＝「腰を持つ」という慣用句はない（「腰が低い」「腰を据える」など）", "", "あし＝「足を持つ」という慣用句はない（「足を引っ張る」など）"], "ex": "母はいつも弟の<b>肩</b>を持つので、私は不満だ。"},
"32117": {"point": "「活発に活動する」は、元気よく盛んに動く様子。若いピアニストが盛んに演奏活動をしているという文脈なので「活発」。", "meaning": "元気がよく、勢いのある様子。動きが盛んな様子。", "kr": "활발하다", "opts": ["", "自在＝思いのままにできる様子（「自由自在」）。活動の盛んさは表さない", "不調＝調子が悪い様子。「不調に演奏活動をする」とは言わない", "敏感＝わずかな刺激にもすぐ反応する様子。活動の様子には使わない"], "ex": "この地域では住民によるボランティア活動が<b>活発</b>に行われている。"},
"32118": {"point": "「ちょくちょく」は、たびたび、よく、という意味の副詞。「訪ねる」という繰り返しの行動と結びつく。", "meaning": "何度も繰り返す様子。たびたび。", "kr": "자주, 종종", "opts": ["つくづく＝心の底から深く感じる様子（「つくづく嫌になる」）", "", "じっくり＝落ち着いて時間をかける様子（「じっくり考える」）", "なるたけ＝できるだけ（「なるたけ早く来て」）。頻度は表さない"], "ex": "近所に住む姉が、<b>ちょくちょく</b>野菜を持ってきてくれる。"},
"32119": {"point": "「しぶとく」は、簡単にあきらめず、ねばり強い様子。自分の意見にいつまでもこだわって譲らない様子に合う。", "meaning": "ねばり強くて、簡単にはあきらめたりくじけたりしない様子。", "kr": "끈질기다, 끈덕지다", "opts": ["そっけなく＝相手への思いやりがなく冷たい様子（「そっけなく断る」）", "", "あっけなく＝予想に反して簡単に終わってしまう様子（「あっけなく負けた」）", "ややこしく＝複雑でわかりにくい様子。こだわり方には使わない"], "ex": "最下位のチームが最後まで<b>しぶとく</b>戦い、引き分けに持ち込んだ。"},
"32120": {"point": "「微妙な違い」は、はっきりとは言えないほど細かい違いのこと。「〜な違い」とナ形容詞で修飾できるのは「微妙」。", "meaning": "細かい点に複雑な意味や味わいがあり、簡単には言い表せない様子。", "kr": "미묘하다", "opts": ["", "微量＝ごくわずかな量。名詞で、「微量な違い」とは言わない", "微力＝力が弱いこと。自分の力を謙遜して言う（「微力ながら」）", "特徴＝他と比べて目立つ点。名詞で、「特徴な違い」とは言わない"], "ex": "この二つの色には<b>微妙な</b>差があって、並べないとわからない。"},
"32121": {"point": "病院で入院患者に会うことができる時間は「面会時間」。病院の決まりとして使われる語。", "meaning": "訪ねてきた人と会うこと。", "kr": "면회", "opts": ["対面＝顔を合わせて向き合うこと（「初対面」）。「対面時間」は病院で使わない", "面接＝試験などのために直接会って話すこと", "会見＝公式に人と会うこと（「記者会見」）", ""], "ex": "祖父が入院している病院へ<b>面会</b>に行った。"},
"32122": {"point": "高い授業料を払うために家計にかかる重みを表すのは「負担」。「家計の負担が大きい」はよく使う言い方。", "meaning": "仕事・責任・費用などを引き受けること。また、その重み。", "kr": "부담", "opts": ["", "責任＝引き受けなければならない務め。「家計の責任」は意味が違う", "役割＝割り当てられた役目。費用の重さには使わない", "分担＝仕事などを分けて受け持つこと（「家事を分担する」）"], "ex": "医療費の自己<b>負担</b>が増えると、生活は苦しくなる。"},
"32123": {"point": "初めての演説なのに口調がよどみなかった、という文脈。話し方がつかえずにすらすら進む様子は「なめらかな口調」。", "meaning": "表面がすべすべしている様子。また、話などがよどみなく進む様子。", "kr": "매끄럽다, 유창하다", "opts": ["のどかな＝穏やかでのんびりしている様子（「のどかな田舎」）", "すこやかな＝体や心が健康な様子（「すこやかに育つ」）", "", "すみやかな＝行動がすばやい様子（「すみやかに退場する」）"], "ex": "彼女は英語を<b>なめらか</b>に話し、聞き手を驚かせた。"},
"32124": {"point": "単語をばらばらに覚えるのと対比して、文章を全部ひとまとめに覚える、という文脈なので「まるごと」。", "meaning": "分けずに、そのまま全部。", "kr": "통째로", "opts": ["もっぱら＝ほかのことはせず、そればかり（「休日はもっぱら寝ている」）", "ひたすら＝ほかのことを考えず、一つのことに集中する様子", "", "なおさら＝なお一層、ますます。前の内容を受けて程度が上がることを表す"], "ex": "リンゴを皮ごと<b>まるごと</b>かじった。"},
"32125": {"point": "インターネットは情報を伝える手段なので、新聞・テレビなどと同じ「メディア」。", "meaning": "情報を伝える手段。新聞・テレビ・インターネットなど。", "kr": "미디어, 매체", "opts": ["テレックス＝文字を送受信する昔の通信装置。新しいものではない", "トランジスタ＝電子部品の一つ。社会を変える情報手段ではない", "ワット＝電力の単位", ""], "ex": "その事件は多くの<b>メディア</b>で大きく取り上げられた。"},
"32126": {"point": "「ひどい目にあう」は、つらい経験やいやな経験をすること。急いでいたのに渋滞で1時間もかかった、という文脈に合う慣用句。", "meaning": "（「〜目にあう」の形で）そのような経験をすること。「ひどい目にあう」でつらい思いをすること。", "kr": "(혼)나다, 봉변을 당하다", "opts": ["", "あし＝「足」を使った慣用句に「ひどい足にあう」はない", "て＝「ひどい手にあう」とは言わない（「手を焼く」などはある）", "みみ＝「耳」を使った慣用句に「ひどい耳にあう」はない（「耳が痛い」などはある）"], "ex": "旅行先で財布を盗まれて、ひどい<b>目</b>にあった。"},
"32127": {"point": "「文字盤」は、時計で数字や目盛りが書かれた平らな面のこと。腕時計のデザインの話なので「盤」。", "meaning": "（「〜盤」の形で）平らな台・板状のもの。「文字盤」は時計の数字が書かれた面。", "kr": "-판(문자판)", "opts": ["欄＝紙面の区切られた部分（「記入欄」「投書欄」）。時計には使わない", "簿＝書き記す帳面（「名簿」「家計簿」）", "碑＝石に文字を刻んで立てたもの（「記念碑」）", ""], "ex": "暗い所でも見えるように、<b>文字盤</b>が光る時計を買った。"},
"32128": {"point": "「作り上げる」は、苦労して完全なものに作り終えること。父親が苦労して作った会社、という文脈なので「あげた」。", "meaning": "（動詞の連用形について）すっかり〜し終える。「作り上げる」で完成させること。", "kr": "만들어 내다, 이룩하다", "opts": ["作り入れる＝このような複合動詞はない", "", "作りかける＝作り始めて途中であること。苦労して完成させた意味にならない", "作りそびれる＝作る機会を逃すこと。会社をつぶす話とつながらない"], "ex": "チーム全員で一つの作品を<b>作り上げた</b>。"},
"32129": {"point": "高いがけから車ごと転げ落ちる、という場面。高い所から落ちることは「転落」。", "meaning": "高い所から転がり落ちること。また、地位や状態が急に悪くなること。", "kr": "추락, 전락", "opts": ["堕落＝生活や考えが悪い方へ落ちること。物理的に落ちることには使わない", "", "没落＝栄えていたものが衰えること（「名家が没落する」）", "倒産＝会社がつぶれること"], "ex": "足をすべらせて、階段から<b>転落</b>した。"},
"32130": {"point": "親しくもないのに親しいかのような態度をとる、という文脈なので「なれなれしい」。「なれなれしい口をきく」で、遠慮のない話し方をすること。", "meaning": "親しくないのに、ひどく親しそうにふるまう様子。", "kr": "버릇없이 친한 척하다, 허물없이 굴다", "opts": ["でかい＝大きい（くだけた言い方）。「でかい口をきく」は偉そうに言うことで、「親しくもないのに」と合わない", "", "いやらしい＝不快な感じ、下品な様子。親しさとは関係がない", "このましい＝好ましい。良い感じで、注意する理由にならない"], "ex": "初対面なのに<b>なれなれしく</b>肩をたたかれて、不快だった。"},
"32131": {"point": "「人生は〜だった」と、人生の状態を表すのは「孤独」。ひとりぼっちで寂しい人生、という意味になる。", "meaning": "仲間や身寄りがなく、ひとりぼっちで寂しいこと。", "kr": "고독", "opts": ["", "孤立＝周りから離れて一つだけになること（「孤立した村」）。「孤立する」と動詞で使い、人生の様子には合わない", "独立＝他から離れて自分の力でやっていくこと。寂しさの意味はない", "自立＝人に頼らず、自分の力でやっていくこと"], "ex": "都会で一人暮らしをしていると、<b>孤独</b>を感じることがある。"},
"32132": {"point": "「ミチオ」と「ミチヨ」は似ていて区別しにくい。似ていて間違えやすい様子は「まぎらわしい」。", "meaning": "よく似ていて、区別がつきにくい様子。", "kr": "헷갈리기 쉽다, 혼동하기 쉽다", "opts": ["ひとしい＝等しい。同じである様子。「困る」理由にならない", "ふさわしい＝似合っている、適している様子", "", "のぞましい＝望ましい。そうあってほしい様子"], "ex": "この二つの薬は名前が<b>紛らわしい</b>ので、取り違えないように注意しよう。"},
"32133": {"point": "「しとやかに」は、言葉づかいや動作が上品で落ち着いている様子。おじぎの仕方に使える。", "meaning": "動作や話し方が上品で落ち着いている様子。", "kr": "얌전하다, 정숙하다", "opts": ["さわやかに＝気分がすっきりして気持ちがいい様子（「さわやかな朝」）。動作の上品さではない", "こまやかに＝心配りが細かく行き届いている様子（「こまやかな配慮」）", "きよらかに＝汚れがなく美しい様子（「清らかな水」）", ""], "ex": "着物姿の女性が<b>しとやかに</b>お茶をいれてくれた。"},
"32134": {"point": "「AのみならずひいてはB」は、Aだけでなく、それが広がって最終的にBにまで及ぶ、という言い方。業界→国家へと範囲が広がっているので「ひいては」。", "meaning": "それが原因・きっかけとなって、さらに進んで。", "kr": "나아가서는", "opts": ["のきなみ＝どれもこれもみな（「のきなみ値上がりした」）", "", "ひたすら＝一つのことに集中する様子", "いまさら＝今になって（「いまさら謝っても遅い」）"], "ex": "一人一人の努力が、<b>ひいては</b>社会全体を変えることにつながる。"},
"32135": {"point": "雨で試合が途中で止まった、という文脈。続いていたものが途中で一時止まるのは「中断」。「〜が中断する」と自動詞でも使える。", "meaning": "続いていた物事が途中で一時止まること。また、止めること。", "kr": "중단", "opts": ["決断＝はっきりと心を決めること", "", "休止＝活動を一時やめること（「運転休止」）。予定的な停止に使い、雨で途中で止まる場面では「中断」が自然", "休憩＝疲れを取るために休むこと。人がするもので、試合が主語にならない"], "ex": "停電で工場の作業が一時<b>中断</b>した。"},
"32136": {"point": "「一括して提出する」は、いくつもの書類を一つにまとめて出すこと。", "meaning": "いくつかのものを一つにまとめること。", "kr": "일괄", "opts": ["一連＝ひと続きの関係にあるもの（「一連の事件」）", "一帯＝その辺り全体（「この地域一帯」）", "一同＝そこにいる人全員（「社員一同」）", ""], "ex": "代金は分割ではなく<b>一括</b>で支払った。"},
"32137": {"point": "SFは小説の種類の一つなので、分野・種類を表す「ジャンル」。", "meaning": "芸術作品などの種類・分野。", "kr": "장르", "opts": ["デザイン＝形・色などの意匠", "モデル＝手本、型、また作品の題材になる人", "", "デッサン＝絵の下書き、素描"], "ex": "彼はクラシックからロックまで、幅広い<b>ジャンル</b>の音楽を聞く。"},
"32138": {"point": "悪いことをしていないのに疑われて怒った、という文脈。「腹が立つ」は怒りを感じることを表す慣用句。", "meaning": "（「腹が立つ」の形で）怒る。しゃくにさわる。", "kr": "화가 나다", "opts": ["はな＝「鼻が高い」は得意な様子。「鼻が立つ」とは言わない", "みみ＝「耳が立つ」とは言わない（「耳を立てる」は聞こうとすること）", "くち＝「口が立つ」は話がうまいこと。怒りの意味はない", ""], "ex": "約束を破られて、さすがに<b>腹</b>が立った。"},
"32139": {"point": "アレルギー性の病気の名前なので「花粉症」。病名に付けて症状・病気を表す「〜症」。", "meaning": "（「〜症」の形で）病気・症状。", "kr": "-증(화분증), 증상", "opts": ["病＝「〜病」も病名を作るが（「心臓病」）、花粉には付かない", "炎＝炎症を表す（「胃炎」「皮膚炎」）。「花粉炎」とは言わない", "傷＝きず（「切り傷」「外傷」）", ""], "ex": "春になると<b>花粉症</b>で目がかゆくなる。"},
"32140": {"point": "「疲れ果てる」は、すっかり疲れてしまうこと。「心身ともに」とあるので、程度が極まる「〜果てる」が合う。", "meaning": "（動詞の連用形について）すっかり〜する。「疲れ果てる」でくたくたに疲れること。", "kr": "녹초가 되다, 몹시 지치다", "opts": ["", "疲れつける＝このような複合動詞はない", "疲れあわせる＝このような複合動詞はない", "疲れつくす＝一般には使わない。「〜尽くす」は「食べ尽くす」のように他動詞に付く"], "ex": "一日中歩き回って、<b>疲れ果てて</b>しまった。"},
"32141": {"point": "財産目当ての結婚という、品性が低くて情けない行為を非難する文。「あさましい」は、心がいやしく、見ていて情けない様子。", "meaning": "心がいやしく、見苦しくて情けない様子。", "kr": "치사하다, 비열하다, 한심하다", "opts": ["", "とぼしい＝乏しい。量が少ない様子", "いやしい＝卑しい。身分や品性が低い様子。近い意味だが、行為に対するあきれた気持ちを表すには「あさましい」が自然", "たくましい＝体や精神が強い様子。非難の意味はない"], "ex": "人の不幸を利用してもうけようとするなんて、<b>あさましい</b>考えだ。"},
"32142": {"point": "だれからも好かれる人の性格として、楽しくて面白い様子の「ゆかいな」が合う。", "meaning": "楽しくて、面白い様子。", "kr": "유쾌하다", "opts": ["", "さかんな＝勢いがよい様子（「スポーツがさかんな町」）。人の性格には使わない", "あわれな＝かわいそうな様子。好かれる理由にならない", "びみょうな＝はっきり言えない複雑な様子。人の性格には使わない"], "ex": "<b>愉快な</b>仲間と一緒に、楽しい旅行をした。"},
"32143": {"point": "服のサイズが自分の体にちょうど合う様子は「きっちりと」。すき間やずれがなく、ぴったりの様子。", "meaning": "すき間やずれがなく、ぴったりと合う様子。", "kr": "꼭, 딱 맞게", "opts": ["", "ほっと＝安心する様子（「ほっとする」）", "がっちりと＝体格ががっしりしている、また固くしっかりした様子", "げっそりと＝急にやせる、またはひどくがっかりする様子"], "ex": "ふたが<b>きっちりと</b>閉まっているか確かめた。"},
"32144": {"point": "「猫の額」は、土地などが非常に狭いことのたとえ。池も作れない狭い庭なので「ねこのひたい」。", "meaning": "（「猫の額ほど」の形で）土地や場所が非常に狭いことのたとえ。", "kr": "손바닥만 함(아주 좁음)", "opts": ["", "すずめのなみだ＝ごくわずかな量のたとえ。金額などに使い、広さには使わない", "水のあわ＝努力が無駄になること（「努力が水の泡になる」）", "上の空＝他のことに気を取られて注意が向かない様子"], "ex": "<b>猫の額</b>ほどの畑で、家族が食べる分の野菜を育てている。"},
"32145": {"point": "ひどいことをしてはいけないと感じる心は「良心」。「良心があれば〜できないはずだ」は自然な言い方。", "meaning": "善悪を判断し、正しく行動しようとする心。", "kr": "양심", "opts": ["", "誠心＝まごころ（「誠心誠意」）。単独ではあまり使わない", "感心＝りっぱだと思って心を動かされること", "肝心＝最も大切なこと（「肝心な点」）"], "ex": "うそをつくたびに、<b>良心</b>が痛んだ。"},
"32146": {"point": "長く続いた政権がだめになって終わる、という文脈。組織や体制が崩れてなくなることは「崩壊」。", "meaning": "建物や組織・体制などが崩れて壊れること。", "kr": "붕괴", "opts": ["破棄＝書類を破り捨てる、また契約などを一方的に取り消すこと（「契約を破棄する」）", "放棄＝権利や責任などを捨てて使わないこと（「権利を放棄する」）", "廃棄＝不要な物を捨てること（「廃棄処分」）", ""], "ex": "地震でビルが<b>崩壊</b>し、多くの人が閉じ込められた。"},
"32147": {"point": "旅行に行きたいという頼みを父親が聞き入れて許すこと。人の頼みや申し出を引き受けることは「承諾」で、「承諾を得る」とよく使う。", "meaning": "相手の頼みや申し出を聞き入れ、引き受けること。", "kr": "승낙", "opts": ["承認＝正式なものとして認めること。国・会社・会議など公的な場面で使うことが多い", "承合＝このような語は一般に使わない", "", "承知＝事情を知っていること、また頼みを聞き入れること。「承知を得る」とは言わない"], "ex": "写真を載せる前に、本人の<b>承諾</b>を得なければならない。"},
"32148": {"point": "経営者の行動が会社の評判を下げてしまう、という文脈なので「イメージダウン」。「〜になる」とも結びつく。", "meaning": "評判やイメージが悪くなること。", "kr": "이미지 실추, 이미지 하락", "opts": ["ブーム＝一時的な流行。会社に悪い影響を与える意味はない", "メッセージ＝伝えたい内容、伝言", "ロマンチック＝甘く夢のような様子。ナ形容詞で、「〜になるような行動」と合わない", ""], "ex": "選手の不祥事は、チームにとって大きな<b>イメージダウン</b>になった。"},
"32149": {"point": "「未決囚」は、裁判の判決がまだ出ていない、捕らえられている人のこと。「囚」は捕らえられた人を表す。", "meaning": "（「〜囚」の形で）捕らえられて牢に入れられている人。", "kr": "-수(죄수), 수감자", "opts": ["士＝資格を持つ専門家（「弁護士」「会計士」）。「未決士」とは言わない", "", "隊＝まとまった集団（「探検隊」）", "家＝その道の専門の人（「作家」「専門家」）"], "ex": "その<b>死刑囚</b>は、刑務所の中で手記を書き続けた。"},
"32150": {"point": "「泣き明かす」は、一晩中泣いて朝を迎えること。「一晩じゅう」とあるので、夜を過ごして朝になる意味の「〜明かす」。", "meaning": "（動詞の連用形について）夜通し〜して朝を迎える。「泣き明かす」で一晩中泣くこと。", "kr": "밤새 울다", "opts": ["泣き果たす＝このような複合動詞はない", "", "泣き尽くす＝ふつうは使わない。「一晩じゅう」と結びつくのは「明かす」", "泣き回す＝このような複合動詞はない"], "ex": "友人と朝まで語り<b>明かした</b>。"},
"32151": {"point": "見ようと思っていたのに忙しくて行けなかった、という文脈。「〜そびれる」は、する機会を逃してしまうこと。", "meaning": "（動詞の連用形について）〜する機会を逃す。", "kr": "~할 기회를 놓치다, ~하지 못하다", "opts": ["行きかける＝行こうとし始めること。行けなかった意味にならない", "行きつける＝何度も行って慣れていること（「行きつけの店」）", "行きつめる＝「行き詰まる」なら進めなくなること。「行きつめる」とは言わない", ""], "ex": "話が盛り上がって、お礼を言い<b>そびれて</b>しまった。"},
"32152": {"point": "「会計士」は、会計の専門資格を持つ人。国家試験で資格を取る職業に付く「〜士」が合う。", "meaning": "（「〜士」の形で）資格や専門的な技能を持つ人。", "kr": "-사(회계사)", "opts": ["陣＝集団・顔ぶれ（「報道陣」「首脳陣」）", "句＝言葉のひと区切り（「文句」「俳句」）", "人＝「〜人」は人を表すが、「会計人」は資格名ではない", ""], "ex": "兄は<b>弁護士</b>を目指して、毎日勉強している。"},
"32153": {"point": "隠しごとをしない性格なので、隠さずありのままを見せる「オープンな」が合う。", "meaning": "隠しだてがなく、開放的な様子。", "kr": "개방적이다, 솔직하다", "opts": ["ドライな＝感情に流されず割り切った様子。隠しごとをしない理由にならない", "ルーズな＝時間やお金にだらしない様子", "ユニークな＝独特な様子", ""], "ex": "彼女は何でも<b>オープンに</b>話してくれるので、付き合いやすい。"},
"32154": {"point": "人が入ってきた途端にみんなが話をすばやくやめた、という場面。動作がすばやい様子は「さっと」。", "meaning": "動作がすばやい様子。", "kr": "재빨리, 휙", "opts": ["ぐっと＝力を入れる、また程度が大きく変わる様子（「ぐっとこらえる」）", "ひょっと＝思いがけず。「ひょっとすると」の形で使う", "ちらっと＝ほんの一瞬見えたり見たりする様子", ""], "ex": "先生が入ってくると、生徒たちは<b>さっと</b>席に着いた。"},
"32155": {"point": "計画を実現させた原因は山田さんの強い気持ち。「〜の熱意で」と名詞で使えるのは「熱意」。", "meaning": "物事に対する熱心な気持ち。", "kr": "열의, 열정", "opts": ["懸念＝気にかかって心配すること。実現の理由にならない", "", "懸命＝力の限りがんばる様子。ナ形容詞で「懸命に」の形で使い、「〜の懸命で」とは言わない", "熱心＝一つのことに打ち込む様子。ナ形容詞で、「山田さんの熱心で」とは言わない"], "ex": "彼の<b>熱意</b>に負けて、とうとう協力することにした。"},
"32156": {"point": "「水を差す」は、うまくいっている物事や盛り上がった雰囲気をじゃますること。「〜ようなことを言うな」と結びつく慣用句。", "meaning": "（「水を差す」の形で）うまくいっている関係や雰囲気をじゃまする。", "kr": "찬물을 끼얹다", "opts": ["ながす＝「水に流す」は過去のことをなかったことにする意味。「水をながす」は慣用句ではない", "いれる＝「水を入れる」は文字どおりの意味しかない", "", "のむ＝「水を飲む」は文字どおりの意味しかない"], "ex": "せっかく盛り上がっているのに、<b>水を差す</b>ようなことを言わないでほしい。"},
"32157": {"point": "目標をなしとげることは「達成」。「目標を達成する」は決まった組み合わせ。", "meaning": "目標などをなしとげること。", "kr": "달성", "opts": ["到達＝ある地点や段階に行き着くこと（「頂上に到達する」）。「目標を到達する」とは言わない", "成功＝物事がうまくいくこと。「目標を成功する」とは言わない", "", "実行＝実際に行うこと。目標には「達成」を使う"], "ex": "今年の売り上げ目標を<b>達成</b>することができた。"},
"32158": {"point": "死ぬのではないかという悪いことが起こりそうな予感なので「不吉な」。「不吉な予感」はよく使う組み合わせ。", "meaning": "縁起が悪く、悪いことが起こりそうな様子。", "kr": "불길하다", "opts": ["不明な＝はっきりわからない様子", "不当な＝道理に合わない様子（「不当な扱い」）", "", "不審な＝疑わしい様子（「不審な人物」）"], "ex": "黒い猫が前を横切り、なんだか<b>不吉な</b>気がした。"},
"32159": {"point": "成績がはっきりわかるほど大きく上がった、という文脈。変化の程度が目立って大きい様子は「いちじるしく」。", "meaning": "程度がはっきりわかるほど目立つ様子。", "kr": "현저하게", "opts": ["ひさしく＝長い間（「ひさしく会っていない」）", "", "とうとく＝尊く。価値が高い様子で、変化の程度は表さない", "さびしく＝寂しく。成績の向上には合わない"], "ex": "新しい薬のおかげで、症状が<b>著しく</b>改善した。"},
"32160": {"point": "会費で費用のすべてがまかなわれる、という文脈。「一切の〜」で「すべての〜」を表す。", "meaning": "全部。すべて。", "kr": "일체, 모든", "opts": ["一層＝さらに、ますます（「一層努力する」）", "一様＝みな同じ様子（「一様に驚いた」）", "一律＝すべて同じ基準で扱うこと（「一律千円」）", ""], "ex": "この件について、私は<b>一切</b>関係ありません。"},
"32161": {"point": "「備え付ける」は、必要な物をその場所に置いておくこと。申し込み用紙がカウンターに置いてある、という意味なので「つけて」。", "meaning": "（「備え付ける」の形で）いつでも使えるように、その場所に置いておく。", "kr": "비치하다", "opts": ["そなえあわせる＝このような複合動詞はない（「兼ね備える」はある）", "そなえつくす＝このような複合動詞はない", "", "そなえこむ＝このような複合動詞はない"], "ex": "各部屋に消火器が<b>備え付けて</b>ある。"},
"32162": {"point": "時間が過ぎていくことは「経過」。「〜年が経過する」は決まった言い方。", "meaning": "時間が過ぎていくこと。また、物事の移り変わりの様子。", "kr": "경과", "opts": ["", "経緯＝物事のいきさつ、事情（「事件の経緯」）", "過程＝物事が進んでいく途中の段階（「成長の過程」）", "課程＝学校で学ぶべき内容の範囲（「博士課程」）"], "ex": "手術から一週間が<b>経過</b>し、ようやく歩けるようになった。"},
"32163": {"point": "社会の中では欲求をある程度おさえなければならない、という文脈。欲求や気持ちを無理におさえつけることは「抑圧」。", "meaning": "行動や欲求などを無理におさえつけること。", "kr": "억압", "opts": ["制定＝法律や規則を作って定めること", "", "圧迫＝強くおさえつけること。財政や胸などに使い（「財政を圧迫する」）、欲求には「抑圧」", "迫害＝弱い立場の人を苦しめること（「宗教的迫害」）"], "ex": "自由な発言が<b>抑圧</b>される社会では、創造的な考えは生まれにくい。"},
"32164": {"point": "探検のために組まれた集団は「探検隊」。集団を表す「〜隊」が合う。", "meaning": "（「〜隊」の形で）ある目的のために組織された集団。", "kr": "-대(탐험대)", "opts": ["弾＝たま（「弾丸」）、また回数（「第二弾」）", "", "師＝先生、またその技術の専門家（「美容師」）", "戦＝たたかい（「決勝戦」）"], "ex": "<b>救助隊</b>が山で遭難した人を見つけ出した。"},
"32165": {"point": "「お目が高い」は、ものを見る目があって、良い物を見分ける力があること。器をほめる人の鑑識眼を評価する言い方。", "meaning": "（「お目が高い」の形で）物の価値を見分ける力が優れている。", "kr": "보는 눈이 높다, 안목이 있다", "opts": ["おおきい＝「目が大きい」は文字どおりの意味で、鑑識眼の意味はない", "", "ひくい＝「目が低い」とは言わない", "ちいさい＝「目が小さい」は文字どおりの意味"], "ex": "それを選ぶとは、お客様はお<b>目が高い</b>ですね。"},
"32166": {"point": "外国映画の題名を訳すのはむずかしい、という文脈なので「タイトル」。", "meaning": "題名。表題。", "kr": "타이틀, 제목", "opts": ["タイピスト＝タイプライターを打つ職業の人", "", "タイマー＝時間を計る装置", "タイミング＝ちょうどよい時機"], "ex": "その映画は、日本では原作と違う<b>タイトル</b>で公開された。"},
"32167": {"point": "叱られると、反抗したい気持ちがさらに強くなる、という文脈。程度がもっと増すことを表すのは「なおさら」。", "meaning": "前よりも一層。ますます。", "kr": "더욱더, 한층", "opts": ["てんで＝（後ろに否定）まったく（「てんで話にならない」）", "なぜなら＝前の内容の理由を述べる接続詞", "", "さほど＝（後ろに否定）それほど（「さほど難しくない」）"], "ex": "だめだと言われると、<b>なおさら</b>やってみたくなる。"},
"32168": {"point": "倒産がうわさされるほど大量の赤字なので、数量が非常に大きい様子の「膨大な」。", "meaning": "数や量が非常に多く、大きい様子。", "kr": "방대하다, 막대하다", "opts": ["大胆な＝度胸があり、思い切ったことをする様子", "", "大体な＝このような言い方はしない（「大体」は副詞・名詞）", "盛大な＝集まりなどが大規模でにぎやかな様子（「盛大なパーティー」）"], "ex": "この研究には<b>膨大な</b>時間と費用がかかった。"},
"32169": {"point": "コンピューターの進歩が目を見張るほどすばらしい、という文脈。「めざましい進歩」はよく使う組み合わせ。", "meaning": "目が覚めるほどすばらしい様子。", "kr": "눈부시다, 놀랍다", "opts": ["こころよい＝気持ちがよい様子（「こころよい風」）", "あわただしい＝落ち着かず忙しい様子", "はかない＝もろくて長く続かない様子", ""], "ex": "その選手は今シーズン、<b>めざましい</b>活躍を見せた。"},
"32170": {"point": "山では一人だけで行動すると危険なので注意する、という文脈。「単独行動」は一人だけで行動すること。", "meaning": "ただ一人。また、他から離れて一つだけであること。", "kr": "단독", "opts": ["唯一＝ただ一つだけ（「唯一の方法」）。「唯一行動」とは言わない", "単一＝ただ一つで、他のものがまじらないこと（「単一民族」）", "", "孤独＝ひとりぼっちで寂しいこと。行動の仕方には使わない"], "ex": "犯人は<b>単独</b>で犯行に及んだとみられている。"},
"32171": {"point": "新聞などで読者の投書を載せる区切られた部分は「投書欄」。紙面の区切りを表す「〜欄」。", "meaning": "（「〜欄」の形で）新聞・書類などで区切られた部分。", "kr": "-란(투고란)", "opts": ["源＝みなもと（「資源」「電源」）", "制＝制度（「会員制」）。紙面の部分を表さない", "", "帯＝ある範囲（「時間帯」「地震帯」）"], "ex": "名前と住所を所定の<b>欄</b>に記入してください。"},
"32172": {"point": "共働きで忙しく、検診を受ける機会を逃してしまう、という文脈。「〜そこねる」は、しようとしてしそこなう、機会を逃すこと。", "meaning": "（動詞の連用形について）〜しようとしてうまくできない。〜する機会を逃す。", "kr": "~할 기회를 놓치다, ~하지 못하다", "opts": ["受けこなす＝このような複合動詞はない（「こなす」は「使いこなす」など）", "受けつめる＝このような複合動詞はない", "受けあかす＝このような複合動詞はない", ""], "ex": "寝坊して、いつものバスに乗り<b>そこねた</b>。"},
"32173": {"point": "「耳を傾ける」は、注意して熱心に聞くこと。「じっと」と結びついて、相手の話を熱心に聞く様子を表す。", "meaning": "（「耳を傾ける」の形で）注意して熱心に聞く。", "kr": "귀를 기울이다", "opts": ["だす＝「耳をだす」は文字どおりの意味しかない", "むける＝「顔を向ける」などは言うが、「耳を向ける」は慣用句ではない", "いれる＝「耳に入れる」は人に知らせることで、「耳をいれる」とは言わない", ""], "ex": "社長は社員の意見にも<b>耳を傾ける</b>人だ。"},
"32174": {"point": "ある地位を争う相手なので、競争相手を表す「ライバル」。", "meaning": "競争相手。好敵手。", "kr": "라이벌, 경쟁자", "opts": ["", "チームワーク＝チームの協力関係", "ファイト＝闘志、戦う気力", "ポイント＝点数、また要点"], "ex": "二人は高校時代からの<b>ライバル</b>で、いつも成績を競っていた。"},
"32175": {"point": "「一切〜ない」は、全く〜ない、という強い否定。後ろの「責任を持ちません」と結びつくのは「一切」。", "meaning": "（後に打ち消しを伴って）全く。少しも。", "kr": "일절, 전혀", "opts": ["", "断然＝他と比べて飛び抜けて（「断然安い」）。否定を強める語ではない", "突如＝急に、突然。責任の有無には合わない", "非常＝程度がはなはだしいこと。「非常に」の形でも否定とは結びつかない"], "ex": "会議の内容は<b>一切</b>外部に漏らさないでください。"},
"32176": {"point": "「結束する」は、多くの人が同じ目的のために固くまとまること。「すべての労働者が〜して経営者に当たった」とあるので、団結の意味の「結束」。", "meaning": "同じ目的を持つ人々が、固くまとまること。", "kr": "결속, 단결", "opts": ["緊密＝関係がすきまなく密接なこと（「緊密な連携」）。「緊密する」とは言わない", "親密＝仲がよく親しいこと。「親密する」とは言わない", "収束＝混乱などがおさまること（「事態が収束する」）。人がまとまる意味はない", ""], "ex": "地域の住民が<b>結束</b>して、ごみ処理場の建設に反対した。"},
"32177": {"point": "「論議する」は、ある問題について意見を出し合って論じ合うこと。「細かいことを〜していないで」とあるので、あれこれ議論する意味の「論議」が合う。", "meaning": "互いに意見を述べて論じ合うこと。", "kr": "논의", "opts": ["", "抗議＝相手のやり方に反対の意見を申し立てること。「細かいことを抗議する」は不自然", "審議＝議案などを詳しく調べて、よいか悪いかを話し合うこと。正式な場で使う", "会議＝集まって相談する会。「〜を会議する」とは言わない"], "ex": "新しい制度の是非をめぐって、国会で活発な<b>論議</b>が交わされた。"},
"32178": {"point": "「肌が敏感」は、肌が刺激に反応しやすいこと。化粧品を避ける理由として合うのは「敏感」。", "meaning": "刺激に対してすぐに反応する様子。", "kr": "민감하다, 예민하다", "opts": ["", "頻繁＝何度も繰り返し起こること（「頻繁に連絡する」）。肌の性質ではない", "真剣＝本気で取り組む様子。肌には使わない", "切実＝身にしみて強く感じる様子（「切実な問題」）。肌の性質ではない"], "ex": "この石けんは<b>敏感</b>な肌の人でも安心して使える。"},
"32179": {"point": "「はかない恋」は、長続きせずすぐに消えてしまう恋。「おわってみれば」とあるので、むなしく短い意味の「はかない」。", "meaning": "長続きせず、むなしく消えてしまう様子。", "kr": "덧없다, 허무하다", "opts": ["すばしこい＝動作がすばやい（「すばしこい子ども」）。恋には使わない", "ひらたい＝平らで高さがない。恋には使わない", "そっけない＝相手への態度が冷たく愛想がない。「恋」そのものを表す語ではない", ""], "ex": "夏の夜空に広がる花火は美しいが<b>はかない</b>。"},
"32180": {"point": "「〜に到達する」は、努力や移動の結果、ある地点・水準に行き着くこと。「合格圏内に」とあるので「到達」。", "meaning": "目的とする地点や水準に行き着くこと。", "kr": "도달", "opts": ["上達＝技術や能力が上手になること。「〜に上達する」とは言わない", "到着＝目的地に着くこと。場所に使い、「合格圏内」のような水準には使わない", "", "達成＝目標を成し遂げること。「〜を達成する」の形で、「〜に達成する」とは言わない"], "ex": "三日目の昼、登山隊はついに山頂に<b>到達</b>した。"},
"32181": {"point": "「栄養失調」は、栄養が足りず体の調子が崩れること。「栄養」と結びついて一語になるのは「失調」。", "meaning": "調和が崩れて、体の調子が悪くなること。", "kr": "실조", "opts": ["低調＝調子が出ず盛り上がらないこと（「低調な売れ行き」）", "不調＝調子が悪いこと。「栄養不調」とは言わない", "", "変調＝調子が変わること、普通の状態でなくなること（「体に変調をきたす」）。「栄養変調」とは言わない"], "ex": "戦後の食糧難の時代には、<b>栄養失調</b>になる子どもが多かった。"},
"32182": {"point": "「最先端」は、時代や技術のいちばん先。「通信技術の〜先端」なので、接頭語「最」が付く。", "meaning": "（「最先端」で）いちばん先。最も進んだところ。", "kr": "최첨단", "opts": ["", "核＝物事の中心（「核家族」）。「核先端」という語はない", "微＝ごく小さいこと（「微生物」）。「先端」には付かない", "緒＝物事の始まり（「端緒」）。「緒先端」という語はない"], "ex": "この研究所では医療の<b>最先端</b>の技術を研究している。"},
"32183": {"point": "「海外進出」は、企業などが外国の市場に新しく出て行って活動すること。「企業の海外〜」とあるので「進出」。", "meaning": "新しい方面・地域に進んで出て行くこと。", "kr": "진출", "opts": ["進入＝ある場所に進んで入ること（「車両進入禁止」）。企業の活動には使わない", "", "進展＝物事が進んで発展すること（「交渉が進展する」）。「海外進展」とは言わない", "推進＝物事を進めること（「計画を推進する」）。「海外推進」とは言わない"], "ex": "その自動車メーカーは十年前にアジア市場へ<b>進出</b>した。"},
"32184": {"point": "「ニュアンスの違い」は、言葉の意味や感じのごく細かい差。「微妙な」「二つの文の間」とあるので「ニュアンス」。", "meaning": "言葉・表現などの微妙な意味合いや感じ。", "kr": "뉘앙스", "opts": ["キャリア＝経歴、職業上の経験。文の違いには使わない", "チャンス＝機会。文の違いには使わない", "", "タイミング＝何かをするのにちょうどよい時機"], "ex": "同じ「すみません」でも、言い方によって<b>ニュアンス</b>が変わる。"},
"32185": {"point": "「有力」は、ある地位に就く見込みが大きいこと。「新しい首相は田中さんが〜だ」とあるので、可能性が高い意味の「有力」。", "meaning": "力や勢いがあること。見込みが大きいこと。", "kr": "유력", "opts": ["勢力＝人を従わせる勢い・力、またはその集団。「田中さんが勢力だ」とは言わない", "威力＝人を圧倒する強い力（「台風の威力」）", "", "権力＝人を支配し従わせる力。人が「権力だ」とは言わない"], "ex": "次の大会では、地元チームが優勝候補として<b>有力</b>視されている。"},
"32186": {"point": "「売り尽くす」は、商品を残らず全部売ること。30分で5000万円分が売れた、という文脈に合うのは「つくした」。", "meaning": "（「〜尽くす」で）残らず全部〜する。", "kr": "다 ~하다, 다 팔다", "opts": ["", "〜あかす＝「語り明かす」のように、夜明けまで〜する。「売りあかす」とは言わない", "〜かえす＝もう一度〜する、相手にやり返す（「読み返す」）。「売り返す」は意味が合わない", "〜わたす＝相手に移す（「売り渡す」）。売れた量の多さを表さない"], "ex": "閉店セールで、店の商品を全部<b>売り尽くした</b>。"},
"32187": {"point": "「手を焼く」は、扱いに困って持て余すこと。言うことをきかない妹に母が困っている、という意味になるのは「て」。", "meaning": "（「手を焼く」で）扱い方に困る。持て余す。", "kr": "애를 먹다, 골치를 앓다", "opts": ["「足を焼く」という慣用句はない", "", "「鼻を焼く」という慣用句はない", "「首を焼く」という慣用句はない"], "ex": "このパソコンは古くて動作が遅く、毎日<b>手</b>を焼いている。"},
"32188": {"point": "「単調な生活」は、変化がなく同じことの繰り返しの生活。「そろそろ飽きてきた」とあるので「単調な」。", "meaning": "変化がなく、一本調子な様子。", "kr": "단조롭다", "opts": ["大柄な＝体が大きい、模様が大きい。生活には使わない", "困難な＝非常に難しい。「飽きる」とは結びつかない", "", "複雑な＝込み入っている。変化が多いので、「飽きる」とは結びつかない"], "ex": "毎日同じ作業の繰り返しで、<b>単調な</b>仕事に眠くなる。"},
"32189": {"point": "「どうにか」は、苦労したり努力したりして、やっとのことで、という意味。「何度も読んでみて」とあるので、やっと理解できた意味の「どうにか」。", "meaning": "努力したりして、やっとのことで。なんとか。", "kr": "간신히, 그럭저럭, 겨우", "opts": ["とかく＝ややもすると、ともすれば（「とかく人は他人を批判しがちだ」）", "どうでも＝どのようであっても（「どうでもいい」）。「わかった」とは結びつかない", "すんなり＝つかえずに簡単に。「何度も読んでみて」と合わない", ""], "ex": "締め切りの前日に、<b>どうにか</b>レポートを書き上げた。"},
"32190": {"point": "「〜のが望ましい」は、そうであることがよい、理想的だ、という意味。需要と供給が一致するのが理想だ、という文なので「のぞましい」。", "meaning": "そうなることが願わしい。そうあってほしい。", "kr": "바람직하다", "opts": ["あらっぽい＝乱暴で雑な様子。状態の理想を表さない", "まちどおしい＝早く来てほしいと待ち遠しい様子。予定された出来事に使う", "", "わずらわしい＝面倒で気が重い様子。文意に合わない"], "ex": "試験の前日は早めに寝るのが<b>望ましい</b>。"},
"32191": {"point": "「体が不調」は、体の調子がよくないこと。「思うように仕事がはかどらなかった」の原因として合うのは「不調」。", "meaning": "調子がよくないこと。", "kr": "컨디션 난조, 상태가 나쁨", "opts": ["困難＝非常に難しいこと。体の状態には使わない", "", "自在＝思いのままにできること（「自由自在」）。仕事がはかどらない理由にならない", "気楽＝心配がなくのんびりしている様子。仕事がはかどらない理由にならない"], "ex": "エースの投手が肩の<b>不調</b>で試合を欠場した。"},
"32192": {"point": "「ぺこぺこ頭を下げる」は、何度も頭を下げて、相手にへつらう様子。お得意の客に対する店員の様子なので「ぺこぺこ」。", "meaning": "何度も頭を下げて、へつらう様子。", "kr": "굽실굽실", "opts": ["ぼつぼつ＝少しずつ物事が始まる様子（「ぼつぼつ出かけよう」）", "", "だらだら＝しまりなく長く続く様子（「だらだら話す」）", "ずるずる＝引きずる様子、けじめなく長引く様子"], "ex": "彼は上司の前ではいつも<b>ぺこぺこ</b>している。"},
"32193": {"point": "「異議がある」は、ある意見や決定に反対の考えを持っていること。「この問題に〜のある人」と出席者に問いかけているので「異議」。", "meaning": "他と違う意見。反対の意見。", "kr": "이의", "opts": ["意向＝どうしたいかという考え（「本人の意向」）。「問題に意向がある」とは言わない", "発見＝初めて見つけること。「発見のある人」は文意に合わない", "", "偏見＝かたよった見方。人に問いかける場面に合わない"], "ex": "この案に<b>異議</b>のある方は、手を挙げてください。"},
"32194": {"point": "「情けない」は、あまりにひどくて嘆かわしい、みじめだ、という気持ち。大学に入れそうにないほど悪い点数なので「なさけない」。", "meaning": "あまりにもひどくて、みじめで嘆かわしい。", "kr": "한심하다, 비참하다", "opts": ["こころぼそい＝頼るものがなく不安な様子。点数には使わない", "たやすい＝簡単だ。点数の悪さを表さない", "なにげない＝特に意図がない様子（「何気ない一言」）", ""], "ex": "こんな簡単なミスをするなんて、我ながら<b>情けない</b>。"},
"32195": {"point": "「交代で」は、順番に入れ替わって何かをすること。食堂が狭いので順番に入れ替わって食事をする、という意味になるのは「交代」。", "meaning": "役目などを入れ替わってすること。", "kr": "교대", "opts": ["交互＝二つのものが代わる代わる（「左右の足を交互に出す」）。「交互で」とは言わない", "", "交差＝線や道などが交わること", "交錯＝いくつかのものが入りまじること（「期待と不安が交錯する」）"], "ex": "夜中の運転は、二人で<b>交代</b>ですることにした。"},
"32196": {"point": "「法律を廃止する」は、それまで行われていた制度や法律をやめること。法律の場合は「廃止」を使う。", "meaning": "それまでの制度・法律・習慣などをやめること。", "kr": "폐지", "opts": ["", "廃棄＝不要な物を捨てること（「書類を廃棄する」）。法律には使わない", "禁止＝ある行為をしてはいけないと止めること。法律そのものをなくす意味ではない", "停止＝動きや活動を途中で止めること（「営業停止」）。法律をなくす意味ではない"], "ex": "その国では、数年前に死刑制度が<b>廃止</b>された。"},
"32197": {"point": "「口が軽い」は、言ってはいけないことまで簡単に話してしまうこと。雄弁家だが困った点、という文脈に合うのは「かるい」。", "meaning": "（「口が軽い」で）秘密などを軽々しく話してしまう。", "kr": "입이 가볍다", "opts": ["", "しつこい＝何度も繰り返して嫌になる様子。「口がしつこい」とは言わない", "きつい＝言い方がきびしい意味の「口がきつい」はあるが、雄弁家と対比する困った点としては「軽い」が合う", "つよい＝「口が強い」という慣用句はない"], "ex": "あの人は<b>口が軽い</b>から、大事なことは話さないほうがいい。"},
"32198": {"point": "「〜をリードする」は、他より先に立って進むこと。「ヨーロッパ諸国を〜している」とあるので、先を行く意味の「リード」。", "meaning": "先に立って導くこと。他より優位に立つこと。", "kr": "리드, 앞섬", "opts": ["ケース＝場合、事例。「〜をケースする」とは言わない", "ポーズ＝姿勢、ふり。文意に合わない", "", "レース＝競走。「〜をレースする」とは言わない"], "ex": "後半に入っても、ホームチームが2点を<b>リード</b>している。"},
"32199": {"point": "船を数える助数詞は「隻（せき）」。「軍艦が三隻」となる。", "meaning": "船を数える語。", "kr": "척(배를 세는 단위)", "opts": ["炉＝火をたく所（「原子炉」）。助数詞ではない", "欄＝紙面などの区切り（「投書欄」）。助数詞ではない", "", "艇＝小さい船（「救命艇」）。船の種類を表す語で、助数詞ではない"], "ex": "港には大型のタンカーが二<b>隻</b>停泊している。"},
"32200": {"point": "「割り込む」は、列などの間に無理に入り込むこと。順番を待っている人の列に入り、文句を言われたので「こんで」。", "meaning": "人の間や列などに、無理に入り込むこと。", "kr": "끼어들다, 새치기하다", "opts": ["「割りつける」は紙面などに配分すること。列に入る意味ではない", "", "「割りこなす」という語はない", "「割りあげる」という語はない（「割り上げ」は料理の言葉）"], "ex": "レジの列に<b>割り込んで</b>きた人に注意した。"},
"32201": {"point": "「抗病力」は、病気に抵抗する力。接頭語「抗」は、〜に逆らう・〜を防ぐの意味（「抗菌」「抗がん剤」）。", "meaning": "（接頭語）〜に逆らう。〜を防ぐ。", "kr": "항(抗)~", "opts": ["被＝〜を受ける（「被害」「被災」）。「被病力」という語はない", "", "乱＝みだれる（「乱用」）。「病力」には付かない", "微＝ごく小さい（「微生物」）。「病力」には付かない"], "ex": "このタオルは<b>抗</b>菌加工がされているので、においにくい。"},
"32202": {"point": "「使いこなす」は、道具や技術を十分に使い、思いのままに扱うこと。「かなりの技術が必要」とあるので「こなす」。", "meaning": "（「〜こなす」で）十分に〜して、思いのままに扱う。", "kr": "자유자재로 ~하다, 능숙하게 다루다", "opts": ["〜おわる＝〜し終える。技術とは関係がない", "〜はたす＝「使い果たす」は全部使ってなくすこと。技術の必要と合わない", "〜すてる＝「使い捨てる」は一度使って捨てること", ""], "ex": "祖母はスマートフォンを上手に<b>使いこなして</b>いる。"},
"32203": {"point": "「ニュースをキャッチする」は、情報をすばやくとらえること。「いちはやく」とあるので、受け止める意味の「キャッチ」。", "meaning": "とらえること。受け止めること。", "kr": "캐치, 포착", "opts": ["", "コントロール＝調節や管理をすること。ニュースには合わない", "チェンジ＝変えること、交代すること", "インテリ＝知識人。動作を表す語ではない"], "ex": "記者たちは事件の情報をいち早く<b>キャッチ</b>した。"},
"32204": {"point": "「鼻にかける」は、自慢して得意そうにすること。成績が上がったことを自慢している、という意味になるのは「はな」。", "meaning": "（「鼻にかける」で）自慢して得意がる。", "kr": "자랑하다, 뽐내다", "opts": ["「顔にかける」という慣用句はない", "", "「足にかける」という慣用句はない", "「首にかける」は物を首にぶら下げる意味で、自慢の意味はない"], "ex": "彼女は家が金持ちなのを<b>鼻</b>にかけている。"},
"32205": {"point": "「不審な人」は、様子がおかしく疑わしい人。警察（110番）に通報する対象なので「不審な」。", "meaning": "疑わしいと思われる様子。", "kr": "수상하다", "opts": ["不吉な＝悪いことが起こりそうな（「不吉な予感」）。人の様子には使わない", "不明な＝はっきりしない（「原因不明」）。通報する人の様子ではない", "", "不当な＝正当でない（「不当な扱い」）"], "ex": "夜中に家の前をうろうろする<b>不審な</b>男がいた。"},
"32206": {"point": "「ずらっと並ぶ」は、たくさんのものが一列に長く並んでいる様子。入場券を買う人々の列なので「ずらっと」。", "meaning": "多くのものが一列に並んでいる様子。", "kr": "죽, 줄줄이", "opts": ["ひょっと＝思いがけず、もしかすると（「ひょっとしたら」）", "ちらっと＝一瞬だけ見える様子（「ちらっと見る」）", "きちっと＝整っていて乱れのない様子。人数の多さを表さない", ""], "ex": "本棚には古い辞書が<b>ずらっと</b>並んでいる。"},
"32207": {"point": "「無報酬」は、働いても報酬（お礼のお金）がないこと。「無〜で働いている」とあるので「報酬」。", "meaning": "労働や仕事に対するお礼のお金や品物。", "kr": "보수", "opts": ["失礼＝礼儀に欠けること。「無失礼」という語はない", "礼儀＝社会生活での作法。「無礼儀」とは言わず「無礼」", "賃金＝労働の対価のお金。「無〜で働く」の形では「無報酬」「無給」がふつう", ""], "ex": "彼はボランティアとして、<b>報酬</b>を受け取らずに働いている。"},
"32208": {"point": "「歴史に名高い」は、歴史の上で名前がよく知られていること。織田信長が死んだ場所として有名だ、という意味なので「なだかい」。", "meaning": "名前がよく知られている。有名だ。", "kr": "유명하다, 이름 높다", "opts": ["", "みすぼらしい＝見た目が貧しくてみっともない", "だるい＝体が疲れて重い", "くわしい＝細かい所までよくわかっている。「歴史に詳しい」は人について言う"], "ex": "この地方は良質な米の産地として<b>名高い</b>。"},
"32209": {"point": "「企画書」は、新しい仕事や催しの計画を書いた書類。「次の仕事の〜書を作成する」とあるので「企画」。", "meaning": "新しい事業などの計画を立てること。", "kr": "기획", "opts": ["用意＝準備すること。「用意書」という語はない", "", "企業＝利益を目的に事業を行う組織。「企業書」とは言わない", "事業＝社会的・経済的な仕事。「事業書」はふつう言わない（「事業計画書」）"], "ex": "新商品の<b>企画</b>が会議で採用された。"},
"32210": {"point": "「処置」は、病気やけがに手当てをすること。歯医者に行って虫歯の手当てをしてもらう、という文なので「処置」。", "meaning": "状況に応じて取り扱うこと。特に、けがや病気の手当て。", "kr": "처치", "opts": ["", "処分＝不要な物を始末すること、罰を与えること。治療には使わない", "処理＝仕事や問題を片付けること（「データを処理する」）。治療には使わない", "対処＝問題に応じて対応すること。「〜してもらう」の形で治療を表さない"], "ex": "けがをした選手は、すぐに医務室で応急<b>処置</b>を受けた。"},
"32211": {"point": "「見合わせる」は、事情により実行をしばらく控えること。運転状況によって発売を一時やめる、という意味なので「あわせる」。", "meaning": "事情を考えて、実行を一時やめておく。", "kr": "보류하다, 미루다", "opts": ["「見習う」は手本にしてまねること", "「見逃す」は見落とすこと、大目に見ること", "", "「見込む」は予想すること、期待すること"], "ex": "大雨のため、本日の試合は<b>見合わせる</b>ことになった。"},
"32212": {"point": "「没趣味」は、趣味がまったくないこと。「仕事のほかは」とあるので、何の趣味もない、という意味の「没」。接頭語「没」は「〜がない」の意味。", "meaning": "（接頭語）〜がない。", "kr": "몰(沒)~, ~이 없음", "opts": ["某＝ある、名前を伏せた（「某氏」）", "密＝ひそかな、すきまがない（「密輸」）", "猛＝はげしい（「猛練習」）。「猛趣味」とは言わない", ""], "ex": "仕事一筋だった父は、自分のことを<b>没</b>趣味な人間だと言っている。"},
"32213": {"point": "「歯が立たない」は、相手が強すぎたり難しすぎたりして、まったくかなわないこと。「むずかしすぎて」とあるので「は」。", "meaning": "（「歯が立たない」で）難しすぎて、まったく手に負えない。", "kr": "감당할 수 없다, 상대가 안 되다", "opts": ["「口が立つ」は話が上手なこと。「口がたたない」は意味をなさない", "「耳が立たない」という慣用句はない", "", "「手が立たない」という慣用句はない"], "ex": "相手チームは強すぎて、私たちにはまったく<b>歯</b>が立たなかった。"},
"32214": {"point": "「分裂」は、一つにまとまっていたものがいくつかに分かれること。意見の対立でクラブが二つに分かれた、という意味なので「分裂」。", "meaning": "一つのものが、いくつかに分かれること。", "kr": "분열", "opts": ["分散＝ばらばらに散らばること。「二つに」とは結びつきにくい", "分担＝仕事などを分けて受け持つこと", "", "分離＝一つのものから別々に離すこと（「油と水が分離する」）。対立による組織の分かれ方には「分裂」"], "ex": "党内の意見が合わず、党は<b>分裂</b>した。"},
"32215": {"point": "「国外に脱出する」は、危険な場所や状況から抜け出して逃げること。犯人が逃げたので「脱出」。", "meaning": "危険な所や状態から抜け出して逃げること。", "kr": "탈출", "opts": ["外出＝用事で家などの外に出かけること", "退出＝その場から出て行くこと（「会場から退出する」）", "", "出張＝仕事で他の土地へ出かけること"], "ex": "火事に気づいた住民たちは、すぐにビルから<b>脱出</b>した。"},
"32216": {"point": "「ブーム」は、ある物事が一時的に大流行すること。若者の間でスニーカーが流行している、という意味なので「ブーム」。", "meaning": "一時的な大流行。", "kr": "붐, 유행", "opts": ["ポーズ＝姿勢、ふり", "", "ムード＝その場の雰囲気", "シート＝座席、薄く平たいもの"], "ex": "今、若い女性の間で登山が<b>ブーム</b>になっている。"},
"32217": {"point": "「やたらに」は、程度を超えて、むやみに〜する様子。食器を必要以上に買い込むくせ、という意味なので「やたらに」。", "meaning": "根拠や節度がなく、むやみに。", "kr": "마구, 함부로, 무턱대고", "opts": ["もろに＝まともに、直接に（「もろにぶつかる」）", "まことに＝本当に（「まことに申し訳ない」）", "", "とっさに＝その瞬間すぐに。くせには合わない"], "ex": "知らない人に<b>やたらに</b>個人情報を教えてはいけない。"},
"32218": {"point": "「切実な問題」は、自分の生活に直接かかわり、身にしみて感じる問題。物価の値上がりについて言うので「切実な」。", "meaning": "自分に直接かかわり、身にしみて強く感じる様子。", "kr": "절실하다", "opts": ["迅速な＝動作や対応が非常に速い", "", "温和な＝性格や気候がおだやか", "器用な＝手先や要領がよい"], "ex": "若者にとって、就職は<b>切実な</b>問題だ。"},
"32219": {"point": "「うっとうしい」は、気分が晴れず、わずらわしく感じること。面白くなさそうにしている様子から、彼にとってこの仕事が気の重いものだと推測している。", "meaning": "気分が晴れず、わずらわしい。", "kr": "귀찮다, 성가시다, 울적하다", "opts": ["ものたりない＝何か足りず満足できない。ただし「面白くなさそう」からはこの語も考えられる", "ひさしい＝長い時間がたっている", "", "おっかない＝こわい"], "ex": "梅雨の時期は毎日雨で、<b>うっとうしい</b>。"},
"32220": {"point": "「普段の認識」は、日ごろから一般に持たれている認識。日本で離婚が増えているということが日ごろの共通理解だ、という意味で「普段」を選ぶ。", "meaning": "いつも。日ごろ。", "kr": "평소", "opts": ["", "通常＝特別でなく、ふつうであること（「通常の業務」）", "正常＝異常がなく、正しい状態", "同様＝同じである様子"], "ex": "<b>普段</b>はおとなしい彼が、珍しく大きな声を出した。"},
"32221": {"point": "「陳列する」は、人に見せるために品物を並べておくこと。指輪を棚に並べて見せた、ということなので「並べた」が最も近い。", "meaning": "人に見せるために、品物を並べておくこと。", "kr": "진열하다", "opts": ["", "覆った＝上から全体にかぶせて隠した。並べる意味はない", "束ねた＝いくつかの物を一つにまとめてしばった", "操った＝道具や人を思うように動かした"], "ex": "店頭には新しい季節の商品が<b>陳列</b>されている。"},
"32222": {"point": "「心細い」は、頼るものがなくて不安な気持ちのこと。一人暮らしで不安になる、ということなので「不安に」が最も近い。", "meaning": "頼りになるものがなく、不安な様子。", "kr": "불안하다, 허전하다", "opts": ["", "平和に＝争いがなく穏やかに。不安とは逆の意味", "頻繁に＝何度も繰り返して。回数の意味", "活発に＝元気よく盛んに"], "ex": "知らない町で道に迷い、<b>心細く</b>なった。"},
"32223": {"point": "「著しい」は、違いや変化がはっきりと目立つ様子。「著しい対照」は違いがはっきりしていることなので「顕著な」が最も近い。", "meaning": "はっきりと目立つ様子。", "kr": "현저하다, 두드러지다", "opts": ["独特な＝そのものだけが持っている。目立つという意味ではない", "孤独な＝仲間がなく一人きりの", "敏感な＝わずかなことにもすぐ反応する", ""], "ex": "この十年で町の人口は<b>著しく</b>減少した。"},
"32224": {"point": "「うんざりする」は、同じことが続いてすっかりいやになること。「まいった」は、困り果てて閉口した気持ちを表し、最も近い。", "meaning": "物事に飽きて、すっかりいやになること。", "kr": "질리다, 지긋지긋하다", "opts": ["しまった＝失敗に気づいたときに言う言葉", "しめた＝思いどおりになって喜ぶときに言う言葉。逆の気持ち", "いたした＝「した」の謙譲語。気持ちを表さない", ""], "ex": "毎日同じ話を聞かされて、<b>うんざり</b>している。"},
"32225": {"point": "「ばったり」は、続いていたことが急にすっかり止まる様子。病気以来たばこを急にすっかり止めた、ということなので「完全に」が最も近い。", "meaning": "続いていたことが急に途絶える様子。", "kr": "뚝, 딱(끊다)", "opts": ["正確に＝間違いなく正しく", "", "正直に＝うそやごまかしがなく", "率直に＝飾らず、ありのままに"], "ex": "駅ができてから、この店の客足が<b>ばったり</b>途絶えた。"},
"32226": {"point": "「シナリオ」は映画などの脚本のことで、ここでは前もって考えた計画・筋書きの意味。「脚本」が最も近い。", "meaning": "映画・劇の脚本。転じて、前もって考えた計画や筋書き。", "kr": "시나리오, 각본", "opts": ["創作＝新しく作り出すこと、またその作品", "", "仮説＝説明のために仮に立てた考え", "架空＝事実ではなく想像で作ったこと"], "ex": "交渉は、こちらの<b>シナリオ</b>どおりに進んだ。"},
"32227": {"point": "「さっぱり」は、打ち消しやよくない意味の語と結び、まったくだめな様子を表す。「さっぱりです」は「全然うまくいきません」の意味。", "meaning": "（下に否定的な意味を伴って）まったくだめな様子。", "kr": "영 아니다, 신통치 않다", "opts": ["元気です＝体の調子がよい。よい状態を表す", "上々です＝非常によい。逆の意味", "まあまあです＝まずまず、ほどほど。だめという意味ではない", ""], "ex": "今年は雨が多くて、商売は<b>さっぱり</b>だ。"},
"32228": {"point": "「コレクション」は、趣味などで物を集めること、また集めた物。切手を集めているのだから「収集」が最も近い。", "meaning": "趣味などで物を集めること。また、集めた物。", "kr": "수집, 컬렉션", "opts": ["", "結束＝同じ目的のために固くまとまること", "募集＝人や作品などを広く呼びかけて集めること。趣味で集めるのではない", "拘束＝行動の自由をしばること"], "ex": "父の趣味は古いコインの<b>コレクション</b>だ。"},
"32229": {"point": "「やむをえず」は、ほかに方法がなく、仕方なくそうする様子。空港が閉鎖されて仕方なく泊まった、ということなので「しかたなく」が最も近い。", "meaning": "ほかに方法がなく、仕方なく。", "kr": "부득이, 어쩔 수 없이", "opts": ["まもなく＝少しの時間がたって。時間の意味", "思いがけなく＝予想もしないで", "", "限りなく＝終わりがなく、どこまでも"], "ex": "体調が悪く、<b>やむをえず</b>旅行を取りやめた。"},
"32230": {"point": "「ふんだんに」は、ありあまるほどたくさんある様子。水をたっぷり使う、ということなので「大量に」が最も近い。", "meaning": "ありあまるほど豊富な様子。", "kr": "충분히, 넉넉히, 듬뿍", "opts": ["普通に＝特に変わったところがなく", "適当に＝ほどよく、またはいいかげんに", "異常に＝普通とは違って。量の多さを表す語ではない", ""], "ex": "この料理には地元の野菜が<b>ふんだんに</b>使われている。"},
"32231": {"point": "「つくづく」は、念を入れてよくよく見る様子。自分の顔をよく時間をかけてながめた、ということなので「じっくり」が最も近い。", "meaning": "念を入れて、よくよく。心の底から深く感じる様子にも使う。", "kr": "곰곰이, 찬찬히, 절실히", "opts": ["こうこうと＝明かりが明るく光る様子", "きっちり＝すき間や過不足がなく正確な様子", "", "しっとり＝適度に湿っている様子、落ち着いた様子"], "ex": "古い写真を<b>つくづく</b>見ていると、昔のことが思い出された。"},
"32232": {"point": "「思惑」は、前もって考えている見込みやねらい。「思惑どおりに」は「考えていたとおりに」の意味なので「意図」が最も近い。", "meaning": "前もって考えていた見込み・ねらい。", "kr": "생각, 의도, 예상", "opts": ["", "目的＝実現しようとして目指す事柄。見込みの意味は弱い", "めじるし＝見つけたり区別したりするためのしるし", "めど＝目指す所、見通し"], "ex": "値上がりを期待したが、<b>思惑</b>が外れて損をした。"},
"32233": {"point": "「気がかりだ」は、どうなるかと心に引っかかって安心できない様子。将来がたいへん心配だ、ということなので「心配だ」が最も近い。", "meaning": "どうなるかと気になって、安心できない様子。", "kr": "걱정되다, 마음에 걸리다", "opts": ["愉快だ＝楽しくて気持ちがよい", "手近だ＝手の届く近い所にある", "盛大だ＝集まりなどが大がかりで立派だ", ""], "ex": "母の病気のことが<b>気がかり</b>で、仕事に集中できない。"},
"32234": {"point": "「意外にも」は、予想と違っていたことへの驚きを表す。予想に反して田中氏が選ばれた、ということなので「驚いたことに」が最も近い。", "meaning": "思っていたことと違って。予想に反して。", "kr": "의외로, 뜻밖에도", "opts": ["困ったことに＝迷惑・不都合だという気持ち。予想外の意味はない", "弱ったことに＝どうしてよいか困ったという気持ち", "", "幸いなことに＝運よく、という気持ち"], "ex": "<b>意外にも</b>、一番静かな彼がスピーチを引き受けた。"},
"32235": {"point": "「装う」は、衣服などで身なりを整えること。派手な服を着ていた、ということなので「着て」が最も近い。", "meaning": "衣服などで身なりを整え、飾ること。", "kr": "치장하다, 차려입다", "opts": ["", "寝て＝横になって眠って", "背いて＝従わずに逆らって", "焦って＝早くしようとして落ち着かずに"], "ex": "パーティーのために、彼女は着物で美しく<b>装って</b>いた。"},
"32236": {"point": "「かたくなに」は、自分の考えや態度をどうしても変えない様子。口を閉じて何も話そうとしない、ということなので「がんこに」が最も近い。", "meaning": "意地を張って、考えや態度を変えない様子。", "kr": "완고하게, 고집스럽게", "opts": ["しっかりと＝確かで、ゆるみがない様子。よい意味で使う", "あっさりと＝しつこくなく簡単に。逆の意味", "", "正確に＝間違いなく正しく"], "ex": "彼は周りの忠告を<b>かたくなに</b>拒み続けた。"},
"32237": {"point": "「わざと」は、そうと知りながら意識的にする様子。石を意識的に置いた、ということなので「故意に」が最も近い。", "meaning": "そうと知りながら、意識して。", "kr": "일부러, 고의로", "opts": ["並びに＝「および」と同じく、物事を並べてつなぐ接続詞", "ゆえに＝だから。理由を表す接続詞", "", "いまだに＝今になってもまだ"], "ex": "弟は<b>わざと</b>負けて、妹に勝たせてあげた。"},
"32238": {"point": "「わずらわしい」は、手間がかかったり気をつかったりして面倒に感じる様子。子どもの相手が面倒だ、ということなので「面倒だ」が最も近い。", "meaning": "手間がかかったり気をつかったりして、面倒な様子。", "kr": "번거롭다, 귀찮다", "opts": ["", "奇妙だ＝普通と違っていて不思議だ", "複雑だ＝入り組んでいて分かりにくい。面倒に感じる気持ちではない", "簡潔だ＝簡単で要領よくまとまっている"], "ex": "近所付き合いが<b>わずらわしく</b>て、マンションに引っ越した。"},
"32239": {"point": "「〜きらいがある」は、「〜しがちだ」「〜の傾向がある」という意味で、多くよくない傾向に使う。「傾向」が最も近い。", "meaning": "（「〜きらいがある」の形で）好ましくない傾向があること。", "kr": "경향, ~하는 면이 있다", "opts": ["", "区別＝違いによって分けること", "好み＝好きなこと。「嫌い」と混同させるわな", "様子＝外から見たありさま"], "ex": "彼は物事を大げさに言う<b>きらい</b>がある。"},
"32240": {"point": "「まばら」は、間があいていて数が少ない様子。観客が少なかった、ということなので「少なかった」が最も近い。", "meaning": "間があいていて、数が少ない様子。", "kr": "드문드문하다, 듬성듬성하다", "opts": ["", "多かった＝逆の意味", "ふまじめだった＝誠実さがなかった。人数の意味はない", "まじめだった＝誠実だった"], "ex": "平日の昼間の電車は、乗客も<b>まばら</b>だ。"},
"32241": {"point": "「反省する」は、自分の行いをふり返って、悪かったと考えること。謝罪の場面で使われており、「すまなく思っています」が最も近い。", "meaning": "自分の行いをふり返り、悪かった点を認めること。", "kr": "반성하다", "opts": ["がっかりしています＝期待が外れて力を落としている", "だめだと思っています＝見込みがないと思っている。謝る気持ちではない", "しっかりしています＝確かで、頼りになる", ""], "ex": "彼は自分の失言を深く<b>反省して</b>いる。"},
"32242": {"point": "「並ぶ」は、ここでは「同じ程度である、肩を並べる」の意味。数学で彼と同じくらいできる者はいない、ということなので「匹敵する」が最も近い。", "meaning": "能力などが同じ程度である。肩を並べる。", "kr": "견주다, 필적하다", "opts": ["挑戦する＝強い相手や難しいことに立ち向かう", "", "同盟する＝共通の目的のために手を結ぶ", "対処する＝問題に合わせて適切に処理する"], "ex": "料理の腕で彼女に<b>並ぶ</b>人はいない。"},
"32243": {"point": "「センス」は、物事の微妙なところを感じ取る能力。国際問題に対する鋭い感じ取り方のことなので「感覚」が最も近い。", "meaning": "物事の微妙な点を感じ取る能力。感覚。", "kr": "센스, 감각", "opts": ["", "推理＝分かっていることから筋道を立てて考えること", "政策＝政府などが行う政治の方針", "使命＝与えられた重要な務め"], "ex": "彼女は服の色の組み合わせの<b>センス</b>がいい。"},
"32244": {"point": "「堅実な」は、手堅く確実で、危なげがない様子。人生に対して確かな考えを持っている、ということなので「しっかりした」が最も近い。", "meaning": "手堅く確実で、危なげがない様子。", "kr": "견실한, 착실한", "opts": ["そっくりした＝よく似た（「そっくりな」）。考え方の性質ではない", "", "ゆったりした＝ゆとりがあって落ち着いた。手堅さの意味はない", "がっかりした＝期待が外れて力を落とした"], "ex": "彼は派手な投資はせず、<b>堅実な</b>貯金を続けている。"},
"32245": {"point": "「さっぱりだ」は、まったくよくない、だめな様子。景気がまったくよくない、ということなので「低調だ」が最も近い。", "meaning": "（よくない状態について）まったくだめな様子。", "kr": "영 신통치 않다, 형편없다", "opts": ["露骨だ＝気持ちなどを隠さず、むき出しにする", "高尚だ＝程度が高く、上品だ", "極端だ＝ひどく一方にかたよっている", ""], "ex": "勉強したのに、試験の結果は<b>さっぱり</b>だった。"},
"32246": {"point": "「抱える」は、ここでは人を雇って自分のもとに置く意味。運転手を雇った、ということなので「やとった」が最も近い。", "meaning": "人を雇って自分のもとに置くこと。", "kr": "고용하다, 거느리다", "opts": ["", "ののしった＝大声で悪く言った", "とがめた＝悪い点を責めた", "のっとった＝乗っ取った。奪って自分のものにした"], "ex": "その会社は千人の社員を<b>抱えて</b>いる。"},
"32247": {"point": "「弁解」は、自分の失敗などについて事情を説明して許してもらおうとすること。「言いわけ」が最も近い。", "meaning": "失敗などの事情を説明し、許しを求めること。", "kr": "변명", "opts": ["言いまわし＝言葉の言い表し方、表現", "", "言いかた＝話し方、ものの言い方", "言いつけ＝命令、指図"], "ex": "遅刻の理由をいくら<b>弁解</b>しても、先生は聞いてくれなかった。"},
"32248": {"point": "「ぺらぺら」は、外国語などをすらすらと上手に話す様子。英語をなめらかに話せる、ということなので「りゅうちょうだ（流暢だ）」が最も近い。", "meaning": "外国語などをすらすらと上手に話す様子。", "kr": "술술, 유창하다", "opts": ["おおざっぱだ＝細かいところまで気を配らない", "かんぺきだ＝完璧だ。欠点がない。話し方のなめらかさに限らない", "めちゃくちゃだ＝筋道がなく、ひどく乱れている", ""], "ex": "彼女は三年の留学で、フランス語が<b>ぺらぺら</b>になった。"},
"32249": {"point": "「丹念に」は、細かいところまで心をこめて、ていねいにする様子。本をていねいに時間をかけて読んだ、ということなので「じっくりと」が最も近い。", "meaning": "細かいところまで、心をこめてていねいに。", "kr": "정성껏, 꼼꼼히", "opts": ["", "ちらっと＝ほんの一瞬だけ", "ぼうっと＝ぼんやりして", "ざっと＝おおまかに、簡単に。逆の意味"], "ex": "祖母は古い着物を<b>丹念に</b>手入れしている。"},
"32250": {"point": "「倣う」は、手本としてまねをすること。人の作品をまねる、ということなので「模倣する」が最も近い。「習う（学ぶ）」との違いに注意。", "meaning": "手本としてまねること。", "kr": "따르다, 모방하다", "opts": ["", "学習する＝学んで身につける。「習う」の意味でここには合わない", "始末する＝後片付けをする", "改良する＝悪い点を直してよくする"], "ex": "前例に<b>ならって</b>、今年も式を簡単に行った。"},
"32251": {"point": "「ユニーク」は、ほかに例がなく、そのものだけの特色がある様子。「独特な」が最も近い。", "meaning": "ほかに類がなく、独自の特色がある様子。", "kr": "독특한, 유니크한", "opts": ["", "有名な＝広く名前が知られている", "美しい＝きれいだ", "すぐれた＝ほかより能力や質が上の"], "ex": "あの監督の映画は発想が<b>ユニーク</b>で面白い。"},
"32252": {"point": "「こつ」は、物事をうまく行うための大事な要点。魚を料理する要点を覚えた、ということなので「要領」が最も近い。", "meaning": "物事をうまく行うための大事な要点・やり方。", "kr": "요령", "opts": ["利点＝有利な点、長所", "修行＝技術などを身につけるために努めること", "", "製法＝品物の作り方"], "ex": "自転車に乗る<b>こつ</b>をつかむまで時間がかかった。"},
"32253": {"point": "「償い」は、相手に与えた損害を埋め合わせること。借りた車を壊したら損害を埋め合わせる、ということなので「補償」が最も近い。", "meaning": "与えた損害や罪を埋め合わせること。", "kr": "보상, 속죄", "opts": ["", "弁解＝言いわけ", "返還＝借りた物などを返すこと。損害の埋め合わせではない", "修理＝壊れた物を直すこと。損害を埋め合わせる意味とは違う"], "ex": "彼は一生かけて罪の<b>償い</b>をするつもりだ。"},
"32254": {"point": "「いかに〜ても」は、程度がどれほどであってもという逆接の強調。「どんなに苦しくても」と同じ意味なので「どんなに」が最も近い。", "meaning": "どれほど。どんなに。", "kr": "아무리, 얼마나", "opts": ["どうにか＝何とか、やっと", "", "どうして＝なぜ。理由を問う", "どうぞ＝人にすすめたり頼んだりするときの言葉"], "ex": "<b>いかに</b>急いでも、もう間に合わないだろう。"},
"32255": {"point": "「見合わせる」は、ここでは予定していたことを行うのをやめること。計画を取りやめると決めた、ということなので「中止する」が最も近い。", "meaning": "事情を考えて、予定していたことを行わずにおくこと。", "kr": "보류하다, 중지하다", "opts": ["変更する＝内容を変える。やめる意味ではない", "承認する＝正しいと認めて受け入れる", "実施する＝実際に行う。逆の意味", ""], "ex": "台風のため、電車は運転を<b>見合わせて</b>いる。"},
"32256": {"point": "「交代で」は、順番に入れかわって行う様子。ハンドルを順に入れかわってにぎった、ということなので「かわるがわる」が最も近い。", "meaning": "順番に入れかわって。", "kr": "교대로, 번갈아", "opts": ["くれぐれも＝何度も念を入れて（頼む）", "", "ことごとく＝残らず全部", "ちゃくちゃくと＝物事が順調に進む様子"], "ex": "夜は家族が<b>交代で</b>祖父の看病をした。"},
"32257": {"point": "「つつましい」は、遠慮深く控えめな様子。姉は控えめな人だ、ということなので「ひかえめな」が最も近い。", "meaning": "遠慮深く、控えめな様子。また、質素な様子。", "kr": "얌전하다, 조신하다, 검소하다", "opts": ["りっぱな＝すぐれていて堂々とした", "", "まずしい＝お金がなく生活が苦しい。「つつましい暮らし（質素）」とは違う", "のぞましい＝そうあってほしい"], "ex": "二人は小さな家で<b>つつましく</b>暮らしている。"},
"32258": {"point": "「くまなく」は、行き届かない所がなく、残らずすべての所に及ぶ様子。家の中を残らず捜した、ということなので「すみずみまで」が最も近い。", "meaning": "行き届かない所がなく、すみずみまで。", "kr": "샅샅이, 구석구석", "opts": ["", "ひととおり＝最初から最後まで大体", "とりあえず＝ほかのことはおいて、まず", "ありのままに＝実際のとおりに"], "ex": "警察は現場を<b>くまなく</b>調べた。"},
"32259": {"point": "「バトル」は、戦い・争いのこと。客を集める段階から競争だ、ということなので「戦い」が最も近い。", "meaning": "戦い。争い。", "kr": "배틀, 싸움", "opts": ["狙い＝目標、ねらうところ", "装い＝身なり、よそおい", "償い＝損害を埋め合わせること", ""], "ex": "人気商品をめぐって、各社の激しい<b>バトル</b>が続いている。"},
"32260": {"point": "「かけがえのない」は、ほかに代わりになるものがないほど大切な様子。写真がとても大切なものだ、ということなので「貴重な」が最も近い。", "meaning": "代わりになるものがないほど大切な。", "kr": "둘도 없는, 소중한", "opts": ["真剣な＝本気でまじめな", "", "地味な＝目立たない、派手でない", "格別な＝ほかと比べて特に程度が違う。代わりがないという意味ではない"], "ex": "家族は私にとって<b>かけがえのない</b>存在だ。"},
"32261": {"point": "「競走」は、走って速さを競うこと。100メートル走の勝負なので「レース」が最も近い。", "meaning": "一定の距離を走って速さを競うこと。", "kr": "경주, 레이스", "opts": ["バトル＝戦い、争い。速さを競う意味はない", "スコア＝得点", "", "スピード＝速さ。競う行為ではない"], "ex": "運動会の<b>競走</b>で、弟は一等になった。"},
"32262": {"point": "「どんより」は、空が曇っていて重く暗い様子。「どんよりした天気」は曇っていて暗い天気なので「曇っていて暗い」が最も近い。", "meaning": "空が雲におおわれて、重く暗い様子。", "kr": "잔뜩 흐린, 우중충한", "opts": ["晴れていて明るい＝逆の意味", "", "風が吹いて涼しい＝風の様子で、暗さの意味はない", "雨が降って蒸し暑い＝雨と暑さの意味で、「どんより」とは違う"], "ex": "朝から空が<b>どんより</b>曇っていて、気分も重い。"},
"32263": {"point": "「こぞって」は、全員がそろって、残らずみんなで、という意味。西側諸国がみんなそろって支持した、ということなので「すべて」が最も近い。", "meaning": "全員がそろって。残らずみんなで。", "kr": "모두, 다 함께", "opts": ["おのおの＝それぞれ。一人一人別々に", "ほとんど＝大部分。全部ではない", "", "あんのじょう＝思ったとおり"], "ex": "村の人々は<b>こぞって</b>祭りの準備に参加した。"},
"32264": {"point": "「告げる」は、事柄を人に言い知らせること。チャイムが終業を知らせた、ということなので「知らせる」が最も近い。", "meaning": "言葉や合図で知らせること。", "kr": "알리다, 고하다", "opts": ["閉じる＝開いていたものを閉める", "", "伝わる＝自動詞。「終業を伝わる」とは言えない", "叫ぶ＝大きな声を出す"], "ex": "春の訪れを<b>告げる</b>梅の花が咲き始めた。"},
"32265": {"point": "「慌ただしい」は、忙しくて落ち着かない様子。彼は急いで出発した、ということなので「急いで」が最も近い。", "meaning": "することが多くて忙しく、落ち着かない様子。", "kr": "황망하다, 분주하다", "opts": ["喜んで＝うれしく思って", "いさぎよく＝未練がなく、さっぱりと", "", "こころよく＝気持ちよく、嫌がらずに"], "ex": "年末は何かと<b>慌ただしく</b>過ぎていく。"},
"32266": {"point": "「ルート」は、道筋、経路のこと。情報がどんな道筋で入ってきたか、ということなので「経路」が最も近い。", "meaning": "道筋。物や情報が伝わる経路。", "kr": "루트, 경로", "opts": ["会議＝集まって相談すること", "議論＝意見を述べ合うこと", "", "流通＝商品などが生産者から消費者に渡ること。道筋そのものではない"], "ex": "山頂までは、いくつかの<b>ルート</b>がある。"},
"32267": {"point": "「オーケー」は、承知すること、許可すること。父から許可をもらっている、ということなので「承認」が最も近い。", "meaning": "承知・許可すること。", "kr": "오케이, 승낙, 허락", "opts": ["推薦＝よいと思う人や物を人にすすめること", "誤解＝間違った理解", "紹介＝知らない人同士を引き合わせること", ""], "ex": "部長から企画の<b>オーケー</b>が出た。"},
"32268": {"point": "「軽率」は、よく考えずに軽々しく行動すること。理由も聞かずに叱ったのは注意が足りなかった、ということなので「不注意」が最も近い。", "meaning": "よく考えずに、軽々しく物事をすること。", "kr": "경솔", "opts": ["", "不機嫌＝機嫌が悪いこと", "非常識＝常識に外れていること。考えの浅さとは違う", "非合法＝法律に違反していること"], "ex": "確かめもせずに人のうわさを広めるのは<b>軽率</b>だ。"},
"32269": {"point": "「ストップ」は、止まること、止めること。エンジンが止まった、ということなので「停止」が最も近い。", "meaning": "止まること。止めること。", "kr": "정지, 스톱", "opts": ["故障＝機械などが壊れて動かなくなること。止まった原因の一つで、同じ意味ではない", "", "燃焼＝燃えること", "爆発＝急に激しく破裂すること"], "ex": "大雪で、電車の運行が<b>ストップ</b>した。"},
"32270": {"point": "「バランス」は、つり合いのこと。綱の上でつり合いを取りながら歩いた、ということなので「均衡」が最も近い。", "meaning": "つり合い。釣り合いのとれた状態。", "kr": "균형, 밸런스", "opts": ["", "屈折＝折れ曲がること", "姿勢＝体の構え", "好調＝調子がよいこと"], "ex": "栄養の<b>バランス</b>を考えて食事をする。"},
"32271": {"point": "「欺く」は、うそを言って人をだますこと。彼女をだましてお金を取り上げた、ということなので「だまして」が最も近い。", "meaning": "うそを言って、人をだますこと。", "kr": "속이다, 기만하다", "opts": ["きずつけて＝体や心に傷を負わせて", "くるしませて＝つらい思いをさせて", "", "まよわせて＝どうしてよいか分からなくさせて"], "ex": "敵を<b>欺く</b>には、まず味方からと言う。"},
"32272": {"point": "「オーバー」は、ここでは実際以上に大げさな様子。形式的なほめ言葉を大げさに並べた、ということなので「おおげさで」が最も近い。", "meaning": "実際より大げさな様子。", "kr": "과장된, 오버하는", "opts": ["はなやかで＝明るく美しく目立って", "", "なめらかで＝すべすべして、またはよどみなく", "きよらかで＝汚れがなく美しく"], "ex": "彼はいつも話が<b>オーバー</b>なので、半分に聞いておいたほうがいい。"},
"32273": {"point": "「ややこしい」は、入り組んでいて分かりにくい様子。文の構造が入り組んでいる、ということなので「複雑だ」が最も近い。", "meaning": "入り組んでいて、分かりにくい様子。", "kr": "복잡하다, 까다롭다", "opts": ["明確だ＝はっきりしていて確かだ。逆の意味", "奇妙だ＝普通と違っていて不思議だ", "簡潔だ＝簡単で要領よくまとまっている。逆の意味", ""], "ex": "この手続きは書類が多くて<b>ややこしい</b>。"},
"32274": {"point": "「円滑に」は、物事が引っかかりなく順調に進む様子。会議が滞りなく進んだ、ということなので「スムーズに」が最も近い。", "meaning": "物事が引っかかりなく、順調に進む様子。", "kr": "원활하게, 순조롭게", "opts": ["エレガントに＝上品に、優雅に", "", "オープンに＝隠さず、開放的に", "ドライに＝感情にとらわれず割り切って"], "ex": "引き継ぎは<b>円滑に</b>行われた。"},
"32275": {"point": "「とっさに」は、その瞬間に、すぐさま反応する様子。落石をその瞬間によけた、ということなので「瞬間的に」が最も近い。", "meaning": "その瞬間に。すぐさま。", "kr": "순간적으로, 엉겁결에", "opts": ["一般的に＝広く全体に当てはまって", "間接的に＝間に何かを置いて、遠回しに", "", "積極的に＝自分から進んで"], "ex": "名前を聞かれて、<b>とっさに</b>うその名前を答えてしまった。"},
"32276": {"point": "「きわめて」は、程度がこの上なく高い様子。とても親切だった、ということなので「非常に」が最も近い。", "meaning": "この上なく。非常に。", "kr": "극히, 매우", "opts": ["いっこうに＝（下に否定を伴って）少しも", "", "初めて＝それまでになく、最初に", "不意に＝突然、思いがけなく"], "ex": "この手術が成功する可能性は<b>きわめて</b>低い。"},
"32277": {"point": "「ピンチ」は、追いつめられた苦しい状況、危ない状態のこと。「危機」が最も近い。", "meaning": "追いつめられた危ない状態。", "kr": "핀치, 위기", "opts": ["不況＝景気が悪いこと", "切実＝身にしみて強く感じる様子", "貧困＝貧しくて生活に困ること。お金の意味に限られる", ""], "ex": "チームは九回に最大の<b>ピンチ</b>を迎えた。"},
"32278": {"point": "「ギャグ」は、人を笑わせるための冗談やしぐさ。みんなが爆笑した、ということなので「冗談」が最も近い。", "meaning": "人を笑わせるための冗談やしぐさ。", "kr": "개그, 농담", "opts": ["", "挨拶＝会ったときや別れるときに交わす言葉", "物語＝ある話の筋を語ったもの", "説話＝昔から語り伝えられた話"], "ex": "彼の<b>ギャグ</b>はいつも少し古い。"},
"32279": {"point": "「幼い」は、ここでは考えや行動が子どもっぽく未熟な様子。中学生とは思えないほど子どもっぽい、ということなので「幼稚で」が最も近い。", "meaning": "年が小さい。考えや行動が子どもっぽく、未熟な様子。", "kr": "어리다, 유치하다", "opts": ["物騒で＝危険なことが起こりそうで", "", "膨大で＝数や量が非常に多くて", "乱暴で＝荒々しく、無理に事をして"], "ex": "大人なのに、彼の考え方は少し<b>幼い</b>。"},
"32280": {"point": "「しょっちゅう」は、いつも、始終という意味。愚痴ばかりいつもこぼしている、ということなので「いつも」が最も近い。", "meaning": "いつも。始終。", "kr": "늘, 언제나, 노상", "opts": ["たびたび＝何度も繰り返して。回数が多いことで、「始終」という意味までは表さない", "にわかに＝急に、突然", "たまたま＝偶然に、時々。逆の意味", ""], "ex": "兄は<b>しょっちゅう</b>財布をなくしている。"},
"32281": {"point": "「肝心」は、特に大切なこと。何事も努力が大切だ、ということなので「重要だ」が最も近い。", "meaning": "物事の中で特に大切な様子。", "kr": "중요하다, 가장 중요하다", "opts": ["有利だ＝都合がよく、得になる", "妥当だ＝よく当てはまっていて適切だ", "", "得意だ＝自信があってうまくできる"], "ex": "外国語は毎日続けることが<b>肝心</b>だ。"},
"32282": {"point": "「なんだか」は、はっきりした理由はないが、何となくそう感じる様子。理由もなく好きになれない、ということなので「なんとなく」が最も近い。", "meaning": "理由ははっきりしないが、何となく。", "kr": "왠지, 어쩐지", "opts": ["しみじみ＝心に深く感じる様子", "", "いまにも＝もうすぐ、今すぐにも", "つくづく＝よくよく、心の底から"], "ex": "今日は<b>なんだか</b>体がだるい。"},
"32283": {"point": "「容易ならない」は「簡単には済まない、油断できないほど深刻だ」という意味。情勢が軽く考えられない状態になった、ということなので「重大な」が最も近い。", "meaning": "簡単には片づかない。軽く考えられないほど深刻だ。", "kr": "만만치 않은, 심상치 않은", "opts": ["迅速な＝非常に速い。深刻さの意味はない", "", "明白な＝はっきりしていて疑いがない", "無茶な＝筋道が通らず、程度がひどい"], "ex": "原油価格の急騰で、経済は<b>容易ならない</b>局面を迎えている。"},
"32284": {"point": "「コマーシャル」は商品などを宣伝するための放送（CM）。番組の途中で流すものなので「宣伝」が最も近い。", "meaning": "テレビ・ラジオなどで流す商業用の宣伝・広告。", "kr": "광고, 커머셜", "opts": ["予告＝前もって知らせること（「次回予告」）", "", "沈黙＝黙っていること", "抽選＝くじ引きで選ぶこと"], "ex": "ドラマのいいところで<b>コマーシャル</b>に切り替わった。"},
"32285": {"point": "「ギャップ」は二つのものの間の食い違い・隔たり。人と人の間にある考え方の隔たりを表す「溝」が最も近い。", "meaning": "食い違い。考え方などの隔たり。", "kr": "격차, 차이, 갭", "opts": ["", "同感＝同じように感じること。隔たりとは反対", "しこり＝争いの後に残るわだかまり。隔たりそのものではない", "ふた＝容器の口をふさぐもの"], "ex": "理想と現実の<b>ギャップ</b>に悩む新入社員は多い。"},
"32286": {"point": "「手軽に」は手間や費用がかからず、簡単にできる様子。誰でも簡単に海外旅行に行ける、ということなので「簡単に」。", "meaning": "手間がかからず、簡単にできる様子。", "kr": "손쉽게, 간편하게", "opts": ["見事に＝すばらしく、立派に", "", "退屈に＝することがなく、つまらなく", "冷静に＝感情に動かされず落ち着いて"], "ex": "電子レンジで<b>手軽に</b>作れる料理を紹介します。"},
"32287": {"point": "「ばったり」は思いがけず人に出会う様子。「ばったり会う」は予定していないのに偶然会うことなので「偶然」。", "meaning": "思いがけなく出会う様子。", "kr": "딱, 우연히 (마주치다)", "opts": ["自然＝人の手を加えないそのままの状態", "突然＝前ぶれなく急に。思いがけなさより急な点に重点がある", "断然＝きっぱりと、ずば抜けて", ""], "ex": "駅前で高校時代の先生に<b>ばったり</b>出くわした。"},
"32288": {"point": "「ほっとする」は心配や緊張がなくなって安心すること。彼が無事で心配がなくなった、ということなので「安心した」。", "meaning": "心配や緊張がとけて、安心する様子。", "kr": "안도하다, 한시름 놓다", "opts": ["残念だった＝期待どおりにならず心残りだ", "不安だった＝心配で落ち着かなかった。反対の意味", "心中した＝二人以上が一緒に自殺した", ""], "ex": "試験に合格したと聞いて、<b>ほっとした</b>。"},
"32289": {"point": "「カット」は一部を切り取ること。台本の数か所が取り除かれていた、ということなので「削除」が最も近い。", "meaning": "一部分を切って取り除くこと。", "kr": "삭제, 컷", "opts": ["補強＝足りない所を補って強くすること", "", "修正＝誤りや不十分な所を直すこと。取り除くとは限らない", "添削＝他人の文章などに書き加えたり削ったりして直すこと"], "ex": "放送時間の都合で、インタビューの一部が<b>カット</b>された。"},
"32290": {"point": "「どうせ」は「どのような経過をたどっても結局は」という意味。いつかは必ず死ぬ、という文なので「いずれにしても」が最も近い。", "meaning": "どのみち。結局は。", "kr": "어차피, 어쨌든", "opts": ["もしかしたら＝ひょっとすると。可能性が低いことを推量する", "きっと＝確信をもって推量する。「結局は」の意味はない", "しらずしらずのうちに＝気づかないうちに", ""], "ex": "<b>どうせ</b>間に合わないのだから、ゆっくり行こう。"},
"32291": {"point": "「はかどる」は仕事などが順調に進むこと。仕事の様子を答えているので「順調に進んでいます」。", "meaning": "仕事などが順調に進む。", "kr": "진척되다, (일이) 잘 되어 가다", "opts": ["徐々に減っています＝少しずつ減っている。進み具合ではない", "", "予想外に遅れています＝思ったより遅れている。反対の意味", "急激に増えています＝急に増えている"], "ex": "静かな図書館のほうが勉強が<b>はかどる</b>。"},
"32292": {"point": "「あさましい」は品性が卑しく、情けない様子。賄賂を受け取るという卑しい行いなので「卑劣な」が最も近い。", "meaning": "心や行いが卑しく、情けない。", "kr": "비열한, 치사한, 한심한", "opts": ["冷静な＝感情に動かされず落ち着いた", "勇敢な＝勇ましく、恐れずに立ち向かう", "極端な＝程度が普通から大きく外れた", ""], "ex": "人の不幸で金もうけをしようとは、<b>あさましい</b>考えだ。"},
"32293": {"point": "「いまだに」は「今になってもまだ」という意味。以前から今まで独身のままだ、ということなので「今でも」。", "meaning": "今になってもまだ。", "kr": "아직까지도, 여태", "opts": ["", "そこまで＝その程度・その所まで", "今さら＝今になって（もう遅い）。「今さら言っても遅い」", "これから＝今から先"], "ex": "十年前の約束を、彼は<b>いまだに</b>覚えている。"},
"32294": {"point": "「いくらか」は数量や程度が少しある様子。お茶がまだ少し残っている、ということなので「少し」。", "meaning": "少し。いくぶん。", "kr": "얼마간, 조금", "opts": ["まったく＝（否定とともに）全然。「残っている」と合わない", "", "たっぷり＝十分にある様子。量が多い", "全然＝（否定とともに）少しも"], "ex": "薬を飲んで、痛みが<b>いくらか</b>和らいだ。"},
"32295": {"point": "「キャリア」は職業上の経験や経歴。法律家として長い経験を積んでいる、ということなので「経歴」。", "meaning": "職業上の経験・経歴。", "kr": "경력, 커리어", "opts": ["", "運転＝車などを動かすこと", "長身＝背が高いこと", "美人＝顔や姿の美しい女性"], "ex": "彼女は通訳として二十年の<b>キャリア</b>がある。"},
"32296": {"point": "「打ち明ける」は隠していたことを包み隠さず人に話すこと。すべてを彼女に話してしまった、ということなので「告白して」。", "meaning": "隠さずに、ありのままを話す。", "kr": "털어놓다, 고백하다", "opts": ["申告して＝役所などに正式に申し出て", "通告して＝決まったことを相手に知らせて", "", "密告して＝こっそり当局などに知らせて"], "ex": "悩みを親友に<b>打ち明けたら</b>、気持ちが楽になった。"},
"32297": {"point": "「ステップ」はここでは足の運び、歩き方の意味。休みを前に軽い足どりで帰る、ということなので「歩み」。", "meaning": "足の運び。歩調。また、段階。", "kr": "스텝, 발걸음", "opts": ["", "働き＝仕事をすること、作用", "舞台＝演劇などを演じる場所", "つえ＝歩くときに体を支える棒"], "ex": "合格の知らせを聞いて、軽い<b>ステップ</b>で家に帰った。"},
"32298": {"point": "「くろうと（玄人）」はその道の専門家。「くろうと並み」は専門家と同じくらいうまいことなので「プロ」。", "meaning": "その道に熟達した人。専門家。", "kr": "전문가, 프로", "opts": ["アマチュア＝素人。「くろうと」と反対の意味", "ゼロ＝何もないこと", "", "スマート＝細身で格好がよい、気が利いている"], "ex": "彼の料理の腕は<b>玄人</b>はだしだ。"},
"32299": {"point": "「頻繁に」は同じことが何度も繰り返し起こる様子。「しきりに」も何度も繰り返す様子を表すので最も近い。", "meaning": "何度も繰り返して起こる様子。", "kr": "빈번하게, 자주", "opts": ["", "にわかに＝急に、突然", "きわめて＝この上なく、非常に", "いっこうに＝（否定とともに）少しも"], "ex": "この交差点では事故が<b>頻繁に</b>起きている。"},
"32300": {"point": "「ポイント」は物事の大切な点・要点。説明の大事なところがわからなかった、ということなので「要点」。", "meaning": "大切な点。要点。", "kr": "요점, 포인트", "opts": ["視点＝物事を見たり考えたりする立場", "対処＝状況に合わせて適切に処理すること", "", "対策＝問題に対して取る方法"], "ex": "話の<b>ポイント</b>を三つにまとめてください。"},
"32301": {"point": "「しのぎを削る」は刀の部分をすり合わせるほど激しく争うこと。顧客獲得で激しく競っている、ということなので「競争し合って」。", "meaning": "互いに激しく争う。", "kr": "치열하게 경쟁하다, 각축을 벌이다", "opts": ["譲歩し合って＝互いに相手に譲って。反対の意味", "他人より優れて＝ほかの人よりまさって。争う意味はない", "鉛筆を削って＝文字どおりの意味で、慣用句の意味ではない", ""], "ex": "優勝をめぐって、二つのチームが<b>しのぎを削って</b>いる。"},
"32302": {"point": "「惜しむ」は失ったものを残念に思うこと。「死を惜しむ」は人の死を残念がり悲しむことなので「残念がっている」。", "meaning": "失ったものなどを残念に思う。", "kr": "애석해하다, 아까워하다", "opts": ["異常に思っている＝普通ではないと思っている", "面倒がっている＝手間がかかって嫌がっている", "妥当に思っている＝適切だと思っている", ""], "ex": "多くのファンが、彼の早すぎる引退を<b>惜しんだ</b>。"},
"32303": {"point": "「腹を決める」は覚悟して心を決めること。リーダーが決心すれば、ということなので「決心すれば」。", "meaning": "覚悟を決める。決心する。", "kr": "각오하다, 마음을 굳히다", "opts": ["じっとがまんすれば＝耐え忍べば。決める意味はない", "うらみをはらせば＝仕返しをして恨みをなくせば", "おこり出せば＝「腹を立てれば」の意味。「腹を決める」とは別", ""], "ex": "反対されても、彼は会社を辞めると<b>腹を決めた</b>。"},
"32304": {"point": "「プラス」はここでは有利な点・役立つことの意味。英語が話せることが彼の有利な点になっている、ということなので「利点」。", "meaning": "有利な点。役に立つこと。", "kr": "플러스, 이점", "opts": ["視点＝物事を見たり考えたりする立場", "", "観点＝物事を見たり考えたりする立場・角度", "欠点＝足りない点、悪い点。「プラス」と反対で「マイナス」に当たる"], "ex": "海外での生活経験が、就職活動で<b>プラス</b>に働いた。"},
"32305": {"point": "「ぞんざい」は物事の扱い方がいい加減で丁寧でない様子。物を雑に扱ってはいけない、ということなので「いいかげん」。", "meaning": "扱い方が雑で丁寧でない様子。", "kr": "소홀히, 함부로, 건성으로", "opts": ["じゅうぶん＝足りないところがない様子", "だいたい＝おおよそ", "わずか＝ほんの少し", ""], "ex": "客に<b>ぞんざいな</b>口のきき方をしてはいけない。"},
"32306": {"point": "「批評」は物事のよしあしなどについて意見を述べること。番組について意見を求めているので「コメント」が最も近い。", "meaning": "物事のよしあし・価値などを判断して意見を述べること。", "kr": "비평, 논평", "opts": ["インタビュー＝人に会って話を聞くこと", "アンケート＝多くの人に同じ質問をして答えてもらう調査", "チェック＝点検・確認すること", ""], "ex": "新作映画について、専門家の<b>批評</b>が新聞に載った。"},
"32307": {"point": "「閉口する」はどうにもならなくて困ること。この問題に困らされている、ということなので「なやまされて」。", "meaning": "どうしようもなく困ること。手に負えないこと。", "kr": "질림, 손듦, 곤란함", "opts": ["けなされて＝悪く言われて", "みなされて＝そうだと判断されて", "", "まよわされて＝どうしたらよいか迷うようにされて"], "ex": "毎晩続く隣の工事の騒音には<b>閉口して</b>いる。"},
"32308": {"point": "「うりふたつ（瓜二つ）」は顔かたちがよく似ていること。双子がよく似ている、ということなので「そっくり」。", "meaning": "顔かたちなどが非常によく似ていること。", "kr": "꼭 닮음, 판박이", "opts": ["めっきり＝変化がはっきり感じられる様子（「めっきり寒くなった」）", "ぶつぶつ＝小声で文句を言う様子", "にこにこ＝うれしそうに笑う様子", ""], "ex": "彼は若いころの父親と<b>瓜二つ</b>だ。"},
"32309": {"point": "「乗り越える」はここでは困難を切り抜けること。難関に打ち勝てなかった、ということなので「克服する」。", "meaning": "困難を切り抜ける。打ち勝つ。", "kr": "극복하다, 넘어서다", "opts": ["模倣する＝まねをする", "匹敵する＝力や価値が同じくらいである", "", "指摘する＝問題点などを取り上げて示す"], "ex": "多くの困難を<b>乗り越えて</b>、ついに店を開いた。"},
"32310": {"point": "「ケース」はここでは「場合・事例」の意味。診断が難しい場合が多い、ということなので「場合」。", "meaning": "場合。事例。", "kr": "경우, 케이스", "opts": ["しかけ＝工夫して作った仕組み", "はこ＝物を入れる容器。「ケース」の別の意味だが、この文には合わない", "経路＝通ってきた道筋", ""], "ex": "子どもが薬を誤って飲む<b>ケース</b>が増えている。"},
"32311": {"point": "「いかにも」はここでは「本当に・まったく」と程度を強める意味。本当に奇妙な事件だった、ということなので「実に」。", "meaning": "本当に。まったく。", "kr": "정말로, 참으로", "opts": ["", "異常に＝普通とは違って", "実は＝本当のことを言うと。前置きの言葉", "微妙に＝わずかな違いがあって、はっきりしない"], "ex": "それは<b>いかにも</b>残念な結果だった。"},
"32312": {"point": "「ポーズ」は体の構え・格好。モデルが写真のために構えをとった、ということなので「姿勢」。", "meaning": "体の構え・格好。", "kr": "포즈, 자세", "opts": ["", "雰囲気＝その場や人が持つ感じ", "均衡＝つり合いがとれていること", "態度＝物事に対する心の持ち方が表れた様子"], "ex": "カメラに向かって、子どもたちがかわいい<b>ポーズ</b>をとった。"},
"32313": {"point": "「世間話」は世の中の出来事などについての気軽なおしゃべり。決まったテーマのない話なので「雑談」。", "meaning": "世の中の出来事などについての気楽な話。", "kr": "잡담, 세상 이야기", "opts": ["", "講演＝大勢の前である題目について話すこと", "解説＝物事をわかりやすく説明すること", "議論＝互いに意見を述べて論じ合うこと"], "ex": "近所の人と<b>世間話</b>をしているうちに、一時間も過ぎていた。"},
"32314": {"point": "「じっくり」は落ち着いて時間をかけ、念入りに物事をする様子。どの道を選ぶべきか念入りに考えた、ということなので「慎重に」。", "meaning": "落ち着いて時間をかけ、念入りにする様子。", "kr": "차분히, 곰곰이", "opts": ["上手に＝うまく、巧みに", "地味に＝目立たない様子で", "", "巨大に＝非常に大きく"], "ex": "大事なことなので、<b>じっくり</b>話し合って決めよう。"},
"32315": {"point": "「あたかも」は「まるで〜のようだ」と、たとえる言い方。「あたかも真昼のような」は「まるで真昼のような」と同じ。", "meaning": "（後に「〜ようだ」が続いて）まるで。", "kr": "마치", "opts": ["いったん＝一度、ひとまず", "", "つまり＝言いかえると", "やがて＝まもなく、そのうちに"], "ex": "彼は<b>あたかも</b>自分が見てきたかのように話した。"},
"32316": {"point": "「目下」は「ただいま・今のところ」の意味。その問題は現在検討中だ、ということなので「現在」。", "meaning": "ただいま。今のところ。", "kr": "현재, 목하", "opts": ["将来＝これから先", "過去＝過ぎ去った時", "", "最中＝物事がいちばん盛んに行われているとき。「〜の最中」と使い、「目下」の言い換えにはならない"], "ex": "新製品は<b>目下</b>開発中で、来年発売の予定だ。"},
"32317": {"point": "「うとましい」は嫌で遠ざけたい気持ちを表す。大騒ぎされて嫌な気分になる、ということなので「いやな」。", "meaning": "嫌な感じがして遠ざけたい。わずらわしい。", "kr": "싫은, 귀찮은, 꺼림칙한", "opts": ["残念な＝期待どおりにならず心残りな", "よく知らない＝なじみがない。「疎い（うとい）」と混同しやすい", "", "なつかしい＝昔のことが思い出されて心がひかれる"], "ex": "毎日しつこく連絡してくる彼が<b>うとましく</b>なってきた。"},
"32318": {"point": "「ランクする」は順位・等級をつけること。ヒットチャートの第１位に位置づけられている、ということなので「順位づけ」。", "meaning": "順位・等級（をつけること）。", "kr": "순위, 랭크", "opts": ["忘却＝忘れてしまうこと", "決定＝はっきり決めること。順位の意味はない", "差別＝不当に区別して扱うこと", ""], "ex": "そのホテルは世界のトップ10に<b>ランク</b>されている。"},
"32319": {"point": "「判断する」はここでは「（笑ったことを）そういう意味だと考えた」こと。相手の行動の意味を理解した、という点で「解釈した」が最も近い。", "meaning": "物事を考えて、そうだと決めること。", "kr": "판단하다", "opts": ["拒否した＝要求などを断った", "断絶した＝関係などを断ち切った", "", "承諾した＝相手の頼みを引き受けた。文中の「承知した」に当たる語で、主語は彼女"], "ex": "空の様子から、午後は雨になると<b>判断した</b>。"},
"32320": {"point": "「一向に」は否定とともに使い、「少しも〜ない」という意味。お金に困っていることを全く知らなかった、ということなので「少しも」。", "meaning": "（否定とともに）少しも。全然。", "kr": "전혀, 조금도", "opts": ["", "むしろ＝どちらかと言えば", "すべて＝全部。否定と使っても「全部は〜ない」と部分否定になる", "かえって＝予想とは反対に"], "ex": "薬を飲んでいるのに、熱が<b>一向に</b>下がらない。"},
"32321": {"point": "「円滑」は、物事が支障なくすらすらと進む様子。「円滑に進む」「円滑な運営」のように物事の進み方に使い、人の性格や評価には使わない。②の仕事の進み方が正しい。", "meaning": "物事が滞りなく、すらすらと運ぶ様子。", "kr": "원활함, 순조로움", "opts": ["「円滑」は物事の進み方に使い、人の性格には使わない → 慎重だ（奥手だ）", "", "人の能力や評価を表す語ではない → 有能な（老練な）政治家", "「当然・不思議だ」という判断の意味はない → 不思議ではない（当然だ）"], "ex": "会議が<b>円滑</b>に進むよう、資料を事前に配っておいた。"},
"32322": {"point": "「はかどる」は、仕事や作業が順調に進むこと。「仕事がはかどる」「勉強がはかどらない」のように作業を主語にして使う。②の名簿作成が正しい。", "meaning": "仕事や作業が順調に進む。", "kr": "진척되다, 잘 되어 가다", "opts": ["場所を通り抜ける意味はない → 中心部を横切って（貫いて）流れる", "", "他動詞ではなく、「〜をはかどる」とは言わない → バランスを保つ（取る）", "許可・容認の意味はない → 署名してもかまわない（差し支えない）"], "ex": "静かな図書館だと、勉強がよく<b>はかどる</b>。"},
"32323": {"point": "「とりわけ」は、多くのものの中で特に目立って、という意味の副詞。②は「手先が器用」な中でも特に編み物が上手、と範囲の中の一つを取り立てているので正しい。", "meaning": "多くの中で特に。ことさら。", "kr": "특히, 유달리", "opts": ["予想に反するという意味はない → かえって（意外に）良い結果を生む", "", "手間をかけて、という意味はない → わざわざ行ったのに", "願望の強さを表す語ではない → 何とか（せめて）泳げるように"], "ex": "今年の夏は暑かったが、<b>とりわけ</b>八月はひどかった。"},
"32324": {"point": "「了承」は、相手の事情や申し出を理解して承知すること。「了承を得る」「ご了承ください」の形で使う。④の委員会の了承を得る、が正しい。", "meaning": "事情や申し出を理解して、認めること。", "kr": "양해, 승낙", "opts": ["終わる意味はない → ようやく終了した（終わった）", "仕事を終える意味はない → 完了する（終える）のに", "「〜のように」と知っている事柄を示すのは「ご存じ」 → ご存じ（ご承知）のように", ""], "ex": "工事中はご不便をおかけしますが、ご<b>了承</b>ください。"},
"32325": {"point": "「キャリア」は、仕事上の経歴や経験。「キャリアを積む」「長いキャリア」のように使う。③の転職で評価される経歴が正しい。", "meaning": "職業上の経歴・経験。", "kr": "경력, 커리어", "opts": ["購入できる物ではない → 新しいパソコン（設備）を購入した", "部署の中の地位を表す語ではない → 新しい部署のポスト（ポジション）に移る", "", "習得する技術の意味はない → ひとつの技（テクニック）を習得する"], "ex": "彼女は通訳として二十年の<b>キャリア</b>がある。"},
"32331": {"point": "「けなす」は、人や物の欠点を取り上げて悪く言うこと。「褒める」の反対。①の課長を悪く言う、が正しい。", "meaning": "欠点を取り上げて悪く言う。", "kr": "헐뜯다, 깎아내리다", "opts": ["", "しつこく頼む意味はない → 買ってくれとねだった", "体に触れる動作ではない → ほおをなでた（つねった）", "苦しんで努力する意味はない → いくらもがいても（工夫しても）"], "ex": "人の作品をむやみに<b>けなす</b>のはよくない。"},
"32332": {"point": "「うつろ」は、中がからっぽな様子、また心がぼんやりして目に生気がない様子。「うつろな目」「うつろな表情」の形でよく使う。④が正しい。", "meaning": "中身がない様子。気が抜けてぼんやりしている様子。", "kr": "공허함, 멍함", "opts": ["柄や色の派手さの意味はない → しまの（派手な）シャツ", "名詞として「うまい」とは結びつかない → うそ（口）がうまい", "でたらめの意味はない → でたらめな（いいかげんな）こと", ""], "ex": "徹夜明けの彼は、<b>うつろ</b>な目で画面を見つめていた。"},
"32333": {"point": "「ドライ」は、感情や人情に流されず割り切っている様子。「ドライな性格」「ドライな関係」のようにナ形容詞として使う。③が正しい。", "meaning": "感情に流されず、割り切っている様子。", "kr": "냉정함, 드라이함", "opts": ["「ドライした」とは言わず、意味も合わない → しっかりした（はっきりした）個性", "「ドライとした」とは言わない → しっとりとした（ほのぼのとした）雰囲気", "", "先に立つという意味はない → 諸外国をリードしている"], "ex": "彼は仕事とプライベートを<b>ドライ</b>に分けている。"},
"32334": {"point": "「へきえき（辟易）」は、相手や状況の勢いに困りはて、うんざりすること。「暑さにへきえきする」「長話にへきえきする」の形で使う。④が正しい。", "meaning": "困りはてて、うんざりすること。", "kr": "질림, 진저리남", "opts": ["相手に合わせて無理をする意味はない → 無理をして（へつらって）機嫌をとる", "上手になる意味はない → 驚くほど絵が上達した", "がっかりして元気をなくすのは「しょげる」 → しょげて（落ち込んで）しまった", ""], "ex": "上司の自慢話には、みんな<b>へきえき</b>している。"},
"32335": {"point": "「ろくに」は後ろに打ち消し（〜ない）を伴い、「満足に〜ない・十分に〜ない」と、あるべき程度に達していないことを不満や非難を込めて言う。②の「ろくに字も書けない」が正しい。①③④はどれも後ろに打ち消しがなく、意味も合わない。", "meaning": "（打ち消しを伴って）満足に。十分に。", "kr": "제대로 (~못하다), 변변히", "opts": ["打ち消しがなく、「ひどく・異様に」と程度を強める意味もない → やけに（いやに）暑い", "", "打ち消しがなく、「とても」の意味もない → いたって（とても）元気だ", "打ち消しがなく、「すぐに・反射的に」の意味もない → とっさに子どもをかばった"], "ex": "忙しくて、昼ご飯も<b>ろくに</b>食べられなかった。"},
"32341": {"point": "「しとやか」は、女性の言葉づかいや動作が上品で落ち着いている様子。①の「しとやかな女性」が正しい。", "meaning": "（主に女性の）言動が上品で落ち着いている様子。", "kr": "얌전함, 정숙함", "opts": ["", "自然の様子には使わない → 海はおだやかで", "数字や内容の正確さの意味はない → 正確な（細かい）見積もり", "柔らかくよく曲がる様子は「しなやか」 → 指はしなやかだ"], "ex": "彼女は着物姿で<b>しとやか</b>にお茶を運んできた。"},
"32342": {"point": "「いじる」は、指先でもてあそんだり、むやみに手を加えたりすること。③の「書類をいじらないで」（勝手に触らないで）が正しい。", "meaning": "指で触ってもてあそぶ。むやみに手を加える。", "kr": "만지작거리다, 손대다", "opts": ["軽く突く動作は「つつく」 → ひじで背中をつついた", "取り去る意味はない → ボタンを取られた（ちぎられた）", "", "相手を責めるのは「なじる」 → ついなじる（責める）ような言い方"], "ex": "会議中、彼はずっとペンを<b>いじって</b>いた。"},
"32343": {"point": "「しみじみ」は、心の底から深く感じる様子。「しみじみ（と）感じる・思う」の形で使う。②の母のありがたみを感じる場面が正しい。", "meaning": "心の底から深く感じる様子。", "kr": "절실히, 곰곰이", "opts": ["好みの程度を強める語ではない → とても（大）好きだ", "", "大変さの程度を表す語ではない → なかなか（かなり）たいへんだ", "漠然とした不調を表す語ではない → どうも体の調子が悪い"], "ex": "久しぶりに故郷に帰り、家族のありがたさを<b>しみじみ</b>と感じた。"},
"32344": {"point": "「余地」は、まだ何かをする余裕や可能性。「疑う余地がない」「改善の余地がある」の形で使う。①が正しい。", "meaning": "まだ何かをする余裕・可能性。", "kr": "여지", "opts": ["", "物理的な空き席の意味では使わない → 乗せてもらう余裕（席）", "休みの時間は「余暇」 → 余暇（休日）を楽しむ", "宴会などの出し物は「余興」 → 余興に手品を"], "ex": "この計画には、まだ検討の<b>余地</b>がある。"},
"32345": {"point": "「やけに」は、理由がわからないほど程度が普通ではない様子。「やけに暑い」「やけに機嫌がいい」のように使う。①が正しい。", "meaning": "程度が普通ではない様子。妙に。", "kr": "몹시, 유난히", "opts": ["", "仮定を表す語ではない → たとえ（仮に）雨だとしても", "各自が持つ様子は「手に手に」 → 手に手に武器を持って", "打ち消しを伴う「満足に〜ない」は「ろくに」 → ろくに勉強もしないのに"], "ex": "今日は朝から<b>やけに</b>静かだね。"},
"32351": {"point": "「目下（もっか）」は、ちょうど今、現在のところ。「目下練習中」「目下検討中」のように使う。②が正しい。", "meaning": "ちょうど今。現在。", "kr": "목하, 현재", "opts": ["未来を表す語ではない → この先（将来）どんなことがあるか", "", "「〜したとたん」の意味はない → 部屋に入った途端（瞬間）に", "「〜の最中」の意味では使わない → 暑い最中でも"], "ex": "新しい店舗は<b>目下</b>建設中です。"},
"32352": {"point": "「手配」は、物事がうまく運ぶよう前もって準備や指図をすること。「車を手配する」「チケットの手配」のように使う。④が正しい。", "meaning": "必要な物や人を前もって準備・用意すること。", "kr": "수배, 준비", "opts": ["傷の処置は「手当て」 → 手当て（処置）をしてもらった", "仕事に取りかかるのは「着手」 → すぐ仕事に着手した", "人にかける労力・面倒は「手間」 → 手間（迷惑）をかけて", ""], "ex": "出張のホテルの<b>手配</b>は秘書に任せている。"},
"32353": {"point": "「やたら」は、根拠や節度がなく、むやみな様子。「やたらなことを言うものではない」は、いいかげんなことを軽々しく言うな、の意味。④が正しい。", "meaning": "節度や根拠がなく、むやみな様子。", "kr": "함부로, 마구", "opts": ["眠りの深さを表す語ではない → ぐっすり（すぐに）眠って", "自分の思いどおりにするのは「勝手に」 → 勝手に決めて", "一生懸命の意味はない → 懸命に（必死に）働いた", ""], "ex": "知らない人に<b>やたら</b>と個人情報を教えてはいけない。"},
"32354": {"point": "「オープン」は、隠し立てがなく開放的な様子。「オープンな考え方」「オープンな性格」のように使う。④が正しい。", "meaning": "隠さず開放的な様子。公開されている様子。", "kr": "개방적, 오픈", "opts": ["「オープンとして」とは言わない → 情報をオープンにして（公開して）", "決まった場所の意味はない → 決まった（決められた）所", "止まる意味はない → エンジンがストップした（止まった）", ""], "ex": "うちの会社は<b>オープン</b>な雰囲気で、若手も意見を言いやすい。"},
"32355": {"point": "「むやみに」は、結果をよく考えずに度を越して行う様子。「むやみに木を切る」が正しい（②）。", "meaning": "あと先を考えず、度を越して。", "kr": "함부로, 무턱대고", "opts": ["量が十分な意味はない → たっぷり（十分に）ある", "", "直接受ける意味はない → もろに（まともに）受けて", "余計に払う意味はない → 余分に（多く）払っていた"], "ex": "薬は<b>むやみに</b>飲むと体に悪い。"},
"32361": {"point": "「没収」は、国や公的機関などが、所有物を強制的に取り上げること。③の不正に手に入れた土地を取り上げられた場面が正しい。", "meaning": "所有物を強制的に取り上げること。", "kr": "몰수, 압수", "opts": ["使えなくなる意味は「無効」 → 切符は無効になります", "まとめて一つにするのは「統合」 → 一つに統合する", "", "自分から断るのは「辞退」 → 出場を辞退する"], "ex": "授業中に使っていた携帯電話を先生に<b>没収</b>された。"},
"32362": {"point": "「無茶」は、道理に合わない、度を越した乱暴な様子。「無茶な運転」「無茶を言う」のように使う。④が正しい。", "meaning": "筋道が立たず、度を越している様子。", "kr": "터무니없음, 무모함", "opts": ["豊かな量の意味はない → 豊富な（莫大な）天然資源", "「無茶した」で増減は表せない → 急増した（激減した）", "疑わしい様子は「不審」 → 原因不明の不審な火災", ""], "ex": "徹夜を続けるなんて<b>無茶</b>はやめなさい。"},
"32363": {"point": "「かばう」は、他から害や非難を受けないよう守ること。④の飛んできたボールから子どもを守る場面が正しい。", "meaning": "害や非難から守る。", "kr": "감싸다, 두둔하다", "opts": ["隠したりうそをついたりする意味はない → 年齢を偽って（隠して）いた", "奪われる意味は「さらう」 → 優勝をさらわれた", "注意をよそへ向けるのは「そらす」 → 注意をそらそうとした", ""], "ex": "兄はいつも、叱られる弟を<b>かばって</b>くれた。"},
"32364": {"point": "「うんざり」は、同じことが続いたり程度がひどかったりして、すっかり嫌になること。②の決まりきった毎日の仕事に飽きている場面が正しい。", "meaning": "飽きたりひどすぎたりして、すっかり嫌になる様子。", "kr": "지긋지긋함, 질림", "opts": ["一度の失望は「がっかり」 → がっかりしている", "", "考えがしっかりした様子ではない → 考え方がしっかりしている", "完全に、の意味は「すっかり」 → すっかりよくなったら"], "ex": "毎日同じ弁当で、もう<b>うんざり</b>だ。"},
"32365": {"point": "「本音」は、表に出さない本当の気持ち。「建前」の反対。②の、かかわりたくないというのが本当の気持ちだ、が正しい。", "meaning": "表向きではない、本当の気持ち。", "kr": "본심, 속마음", "opts": ["実際の性質を表す語ではない → 本当は（実は）利口者だ", "", "「本音的」という語はない → 本格的ではない", "真剣な気持ちは「本気」 → 本気になって"], "ex": "酒の席になって、ようやく彼は<b>本音</b>を話し始めた。"},
"32371": {"point": "「キャッチ」は、捕らえること。情報や電波などをとらえる意味でも使う。①の「情報をキャッチする」が正しい。", "meaning": "捕らえること。情報などをつかむこと。", "kr": "캐치, 포착", "opts": ["", "削る意味は「カット」 → 予算をカットして（削って）", "後ろ盾の意味は「バック」 → 世論をバックにした", "初めて世に出るのは「デビュー」 → デビューして以来"], "ex": "ラジオで台風の最新情報を<b>キャッチ</b>した。"},
"32372": {"point": "「冷酷」は、思いやりがなく、むごいことを平気でする様子。①の非情な犯行が正しい。", "meaning": "思いやりがなく、むごい様子。", "kr": "냉혹함", "opts": ["", "規模が小さく地味なのは「質素」「ささやか」 → 質素な（ささやかな）もの", "強く願う様子は「切実」 → 切実な（熱烈な）願い", "人をひきつける性格とは逆の意味 → 温厚な（誠実な）人柄"], "ex": "部下を<b>冷酷</b>に切り捨てる上司に、皆が反発した。"},
"32373": {"point": "「ことごとく」は、一つ残らず全部、という意味の副詞。①の書いてあることを全部理解した、が正しい。", "meaning": "残らず全部。すべて。", "kr": "모조리, 남김없이", "opts": ["", "変化の進み方を表す語ではない → だんだん（すっかり）暗くなって", "推量を表す語ではない → おそらく（たぶん）電車は遅れる", "簡単に済ませる意味は「そこそこに」 → 朝食もそこそこに"], "ex": "反対派の意見は<b>ことごとく</b>退けられた。"},
"32374": {"point": "「がっくり」は、急に力が抜けたり、ひどく気落ちしたりする様子。②の息子に死なれて気落ちしている場面が正しい。", "meaning": "急に力が抜ける様子。ひどく気落ちする様子。", "kr": "맥이 탁 풀림, 낙심함", "opts": ["頑丈な様子は「がっしり」 → がっしりした（頑丈な）倉庫", "", "しっかり組む様子は「がっちり」 → がっちりとスクラムを組んだ", "ちょうど合う様子は「ぴったり」 → ぴったり合う"], "ex": "あと一点で負けて、選手たちは<b>がっくり</b>と肩を落とした。"},
"32375": {"point": "「心中（しんじゅう）」は、二人以上の人が一緒に自殺すること。①の生活苦から心中する事例が正しい。なお「しんちゅう」と読むと「心の中」の意味。", "meaning": "二人以上が一緒に自殺すること。", "kr": "동반 자살", "opts": ["", "心を決めるのは「決心」 → 一生をささげようと決心した", "その時の気持ちは「気分」 → さわやかな気分になった", "心の働きに関するのは「心理的」 → 心理的な（精神的な）もの"], "ex": "その映画は、追い詰められた恋人たちの<b>心中</b>を描いている。"},
"32381": {"point": "「いまにも」は、すぐにもある事態が起こりそうな様子で、「いまにも〜そうだ」の形で使う。④の「いまにも雨が降りだしそうだ」が正しい。", "meaning": "すぐにも。今すぐにも起こりそうな様子。", "kr": "당장이라도, 금방이라도", "opts": ["相手の気持ちを推し量る語は「さぞ」 → さぞ（どんなにか）喜んでいる", "程度がはなはだしい推量は「よほど」 → よほどくやしかった", "すぐに行動する意味は「さっそく」 → さっそく今夜作って", ""], "ex": "彼女は<b>いまにも</b>泣き出しそうな顔をしていた。"},
"32382": {"point": "「いたわる」は、弱い立場の人や苦労した人に同情して大切に扱うこと。①の病人をいたわる、が正しい。", "meaning": "弱い人や苦労した人を思いやって大切にする。", "kr": "위로하다, 돌보다", "opts": ["", "努力が成果となるのは「報われる」 → 報われる（実を結ぶ）努力", "お金を払って使うのは「借りる」 → アパートを借りている", "人を通して世話する意味はない → 紹介して（世話して）もらった"], "ex": "長旅で疲れた両親を<b>いたわって</b>、温泉に連れて行った。"},
"32383": {"point": "「折衷」は、異なる考えや様式からよいところを取り合わせて一つにまとめること。「和洋折衷」「案を折衷する」の形で使う。④が正しい。", "meaning": "異なるものの良い所を取り合わせて、一つにまとめること。", "kr": "절충", "opts": ["「折衷な」とは言わない → 融合した（併設した）事業展開", "身にしみて感じるのは「痛切」 → 痛切に感じた", "取り締まりの手段は「措置」 → 厳しい措置（態度）をとった", ""], "ex": "この旅館は和室と洋室を<b>折衷</b>した造りになっている。"},
"32384": {"point": "「質素」は、ぜいたくをせず、つつましい様子。「質素な生活」「質素な食事」のように使う。①が正しい。", "meaning": "ぜいたくをせず、つつましい様子。", "kr": "검소함, 수수함", "opts": ["", "話し方の正直さを表す語ではない → 率直に（冷静に）話し合おう", "すなおに受け入れる意味は「素直」 → 素直に誤りを認めた", "ありのままに言うのは「率直」 → 率直に（端的に）言うと"], "ex": "祖父は年金だけで<b>質素</b>に暮らしている。"},
"32385": {"point": "「だぶだぶ」は、衣服などが体に比べて大きすぎ、ゆるくて余っている様子。④の兄の洋服が大きすぎる場面が正しい。", "meaning": "衣服などが大きすぎて、ゆるい様子。", "kr": "헐렁헐렁", "opts": ["物事にゆっくり取りかかる様子は「ぼちぼち」 → ぼちぼち（そろそろ）勉強にかかる", "目が回る様子は「くらくら」 → くらくら目まいがして", "ためらって落ち着かない様子は「もじもじ」 → もじもじ（おどおど）して", ""], "ex": "やせたので、ズボンが<b>だぶだぶ</b>になってしまった。"},
"32391": {"point": "「すみやか」は、物事を行うのが早い様子。「すみやかに行動する」「すみやかな対応」のように使う。②が正しい。", "meaning": "物事の処理や行動が早い様子。", "kr": "신속함, 조속함", "opts": ["柔らかくよく曲がる様子は「しなやか」 → しなやかな体", "", "傾きがなだらかなのは「ゆるやか」 → ゆるやかな坂", "上品で落ち着いた女性は「しとやか」 → しとやかな女性"], "ex": "地震が起きたら、<b>すみやか</b>に建物の外へ避難してください。"},
"32392": {"point": "「つくづく」は、心の底から深く感じたり、念入りに考えたりする様子。「つくづく思う・考えさせられる」の形で使う。②が正しい。", "meaning": "心の底から深く。よくよく。", "kr": "절실히, 곰곰이", "opts": ["胸の高鳴りは「どきどき」 → むねがどきどきした", "", "思いがけず、の意味は「偶然」 → 偶然（たまたま）あの店で", "液体が続いて出る様子は「ずるずる」 → 鼻水がずるずる出てきて"], "ex": "病気になって、健康のありがたさを<b>つくづく</b>感じた。"},
"32393": {"point": "「内緒」は、他人に知らせず秘密にしておくこと。「内緒にする」「内緒の話」の形で使う。②が正しい。", "meaning": "人に知らせず秘密にすること。", "kr": "비밀", "opts": ["財産を受け継ぐのは「相続」 → 全財産を相続した", "", "自分の立場を意識するのは「自覚」 → 責任を自覚している", "同じ時の意味は「同時」 → 卒業と同時に結婚した"], "ex": "これは二人だけの<b>内緒</b>の話だよ。"},
"32394": {"point": "「シック」は、あか抜けていて上品なこと。服装や色づかいについて「シックな装い」のように使う。②が正しい。", "meaning": "あか抜けていて上品な様子。", "kr": "세련됨, 시크함", "opts": ["体の過敏な反応は「アレルギー」 → アレルギー（炎症）を起こす", "", "声の調子は「トーン」 → 声のトーン（調子）", "感覚・素質は「センス」 → 音楽のセンス"], "ex": "黒でまとめた<b>シック</b>な服装で、パーティーに出かけた。"},
"32395": {"point": "「前途」は、これから先の道のり・将来。「前途を祝す」「前途有望」の形で使う。③の新婚夫婦の将来を祝う場面が正しい。", "meaning": "これから先の行く手。将来。", "kr": "전도, 앞날", "opts": ["行く途中は「途中」 → 途中で引き返した", "何かが起こる前のしるしは「前兆」 → 大地震の前兆", "", "空間的な前の方は「前方」 → 私の車の前方に"], "ex": "<b>前途</b>ある若者たちに、大きな期待が寄せられている。"},
"32401": {"point": "「ゆるやか」は、傾きや変化がなだらかで急でない様子。「ゆるやかな坂」「ゆるやかに傾斜する」のように使う。③が正しい。", "meaning": "傾きや動きが急でなく、なだらかな様子。", "kr": "완만함, 느슨함", "opts": ["連絡の取り方を表す語ではない → ひそかに（頻繁に）連絡を取り合って", "音の小ささは「かすか」 → かすかな（わずかな）物音", "", "水面の様子は「なめらか」 → 鏡のようになめらかだった（静かだった）"], "ex": "景気は<b>ゆるやか</b>に回復している。"},
"32402": {"point": "「中断」は、続いていた物事を途中で一時切ること。「試合が中断される」「演説を中断する」のように使う。②が正しい。", "meaning": "続いていた物事が途中で一時止まること。", "kr": "중단", "opts": ["「中断で」とは言わない → 中途半端で（途中で）やめては", "", "どちらにも付かない態度は「中立」 → 中立的な（あいまいな）態度", "現地から送る放送は「中継」 → 中継放送された"], "ex": "大雨のため、試合は三十分間<b>中断</b>した。"},
"32403": {"point": "「サボる」は、すべき仕事や勉強を怠けて休むこと。「授業をサボる」「当番をサボる」のように使う。②が正しい。", "meaning": "すべきことを怠ける。", "kr": "땡땡이치다, 게으름 피우다", "opts": ["見て見ないふりは「目をつぶる」 → 目をつぶった", "", "乗り損なうのは「のがす」 → この電車をのがす（乗り遅れる）と", "急ぐ意味はない → 合意を急ぐことはない"], "ex": "彼は部活を<b>サボって</b>ゲームセンターに行っていた。"},
"32404": {"point": "「同調」は、他人の意見や行動に調子を合わせること。③の仲間が少年に合わせて学校をさぼった、が正しい。", "meaning": "他人の意見や行動に調子を合わせること。", "kr": "동조", "opts": ["同じ考えだという意味は「同感」 → まったく同感だ", "調子がよいのは「好調」 → 好調を維持している", "", "身をもって感じるのは「実感」 → 生きる喜びを実感した"], "ex": "周りの意見に<b>同調</b>するだけでなく、自分の考えも言うべきだ。"},
"32405": {"point": "「じっくり」は、落ち着いて時間をかけ、念入りに物事をする様子。「じっくり考える」が正しい（①）。", "meaning": "落ち着いて、時間をかけて念入りに行う様子。", "kr": "차분히, 곰곰이", "opts": ["", "ひどく気落ちする様子は「がっくり」 → がっくりしている", "失望する様子は「がっかり」 → がっかりしている", "味が淡い様子は「あっさり」 → あっさりしている"], "ex": "この問題は、時間をかけて<b>じっくり</b>話し合おう。"},
"32411": {"point": "「追及」は、責任や原因などをどこまでも問いただすこと。「責任を追及する」「容疑者を追及する」のように使う。①が正しい。", "meaning": "責任や原因などを、どこまでも問いただすこと。", "kr": "추궁", "opts": ["", "遠くへ追い出すのは「追放」 → その島に追放され", "後から加えるのは「追加」 → あと３人まえ追加して", "足りない所を満たすのは「補う」 → 短所を補い合っている"], "ex": "記者たちは大臣の責任を厳しく<b>追及</b>した。"},
"32412": {"point": "「こっけい（滑稽）」は、言動がおもしろおかしく、人を笑わせる様子。③の「こっけいなことを言ってみんなを笑わせる」が正しい。", "meaning": "おもしろおかしく、笑いを誘う様子。", "kr": "익살스러움, 우스꽝스러움", "opts": ["住まいを褒める語ではない → すてきな（けっこうな）お住まい", "何度も繰り返す様子は「しきりに」 → しきりに水をほしがった", "", "打ち消しを伴う「満足に〜ない」は「ろくに」 → ろくに寝てない"], "ex": "ピエロの<b>こっけい</b>な動きに、子どもたちは大笑いした。"},
"32413": {"point": "「さぞ」は、他人の気持ちやその場の様子を推し量る副詞で、「さぞ〜だろう・に違いない」と推量の表現と結びつく。③が正しい。", "meaning": "（推量を伴って）きっと。どんなにか。", "kr": "필시, 얼마나", "opts": ["危ないところだった意味は「あやうく」 → あやうく（もう少しで）死ぬところだった", "比較の差の大きさは「はるかに」 → はるかに優れている", "", "全く〜ない、は「まるで」 → まるで（てんで）聞こうともしない"], "ex": "一人で子どもを三人育てるのは、<b>さぞ</b>大変だっただろう。"},
"32414": {"point": "「コントロール」は、思いどおりに調節・管理すること。「感情をコントロールする」が正しい（③）。", "meaning": "思いどおりに調節・管理すること。", "kr": "컨트롤, 조절", "opts": ["距離の意味は「間隔」 → 同じ間隔（スペース）を空けて", "前もって決めた筋書きは「シナリオ」 → シナリオ（筋書き）", "", "分類の意味は「カテゴリー」 → 製品カテゴリー（モデル）"], "ex": "体重を<b>コントロール</b>するために、毎朝走っている。"},
"32415": {"point": "「動機」は、人がある行動を起こすきっかけ・理由となる気持ち。④の「〜という動機から医者になった」が正しい。", "meaning": "人が行動を起こす直接の原因となる気持ち。", "kr": "동기", "opts": ["配慮する意味は「考慮」 → 年齢を考慮しては（配慮しては）くれなかった", "「動機した」とは言わない → いい薬になった（教訓になった）", "体の動きで示すのは「手振り」 → 手振り（身振り）で示した", ""], "ex": "犯人の<b>動機</b>はいまだにわかっていない。"},
"32501": {"point": "「瓦解」は「がかい」。「瓦」は音読みで「ガ」（訓は「かわら」）、「解」は「カイ」。一部が崩れて全体がばらばらになること。", "meaning": "組織や関係などの一部が崩れたことから、全体がばらばらに崩れること。", "kr": "와해", "opts": ["うかい：「瓦」は「が」。「うかい」は「迂回」の読み", "", "ごかい：「瓦」は「が」。「ごかい」は「誤解」の読み", "わかい：「瓦」は「が」。「わかい」は「和解」の読み"], "ex": "内部の対立によって、連立政権は<b>瓦解</b>した。"},
"32502": {"point": "「懇談会」は「こんだんかい」。「懇」は「コン」（懇親会・懇願）、「談」は「ダン」。打ち解けて話し合う会のこと。", "meaning": "打ち解けて話し合う会。", "kr": "간담회", "opts": ["", "かんだんかい：「懇」は「こん」。「かんだん」は「歓談」の読み", "ざだんかい：「座談会」の読み。「懇」は「こん」", "えだんかい：「懇」を「え」とは読まない"], "ex": "新入社員と社長の<b>懇談会</b>が開かれた。"},
"32503": {"point": "「値する」は「あたいする」。「〜に値する」で、それだけの価値があるという意味。「値」を「ね」と読む「値段・値引き」と区別すること。", "meaning": "それだけの価値があること。", "kr": "~할 만하다, 가치가 있다", "opts": ["ねする：「値」を「ね」と読むのは「値段」など。「値する」は「あたいする」", "ちする：音読み「チ」（数値）を使った形で、誤り", "", "いこいする：「憩い」の読み。「値」の読みではない"], "ex": "この映画は一見に<b>値する</b>。"},
"32504": {"point": "「督促」は「とくそく」。「督」は「トク」（監督）、「促」は「ソク」（促進）で、濁らない。意味の近い「催促（さいそく）」と混同しないこと。", "meaning": "約束の実行、特に支払いなどを早くするように促すこと。", "kr": "독촉", "opts": ["さいぞく：「催促」と混同した形。「督」は「とく」で、「促」も濁らない", "さいそく：「催促」の読み。意味は近いが漢字が違う", "とくぞく：「促」は濁らず「そく」", ""], "ex": "家賃の支払いが遅れ、大家から<b>督促</b>状が届いた。"},
"32505": {"point": "「鑑定」は「かんてい」。「鑑」は「カン」（図鑑）、「定」は「テイ」。「定」を「ジョウ」と読む「勘定（かんじょう）」と混同しないこと。", "meaning": "美術品などの真偽・価値・良し悪しを、専門的に見きわめること。", "kr": "감정", "opts": ["かんじょう：「勘定」の読み。「定」はここでは「てい」", "", "けんじょう：「献上」の読み。「鑑」は「かん」", "けんてい：「検定」の読み。「鑑」は「かん」"], "ex": "古い掛け軸を<b>鑑定</b>してもらったところ、本物だとわかった。"},
"32506": {"point": "「傑作」は「けっさく」。「傑（ケツ）」が促音化して「けっ」、「作」は「サク」。ここでは、とてもこっけいで面白いという、くだけた意味で使われている。", "meaning": "非常にすぐれた作品。また、くだけた言い方で、とてもこっけいで面白いこと。", "kr": "걸작, 아주 웃김", "opts": ["", "けっさ：「作」はこの語では「さく」", "がっさく：「傑」は「けつ」→「けっ」", "がっさ：「傑」は「けっ」、「作」は「さく」"], "ex": "この絵は画家の晩年の<b>傑作</b>として知られている。"},
"32507": {"point": "「よい教訓となる」は、その経験から今後に役立つ教えが得られること。事件が皆にとって学びになった、という意味なので「教訓」。", "meaning": "経験から得た、今後に生かすべき教え。", "kr": "교훈", "opts": ["", "教養＝学問や知識によって身についた心の豊かさ", "啓発＝気づかなかったことを教え、理解を深めさせること。「よい啓発となる」は不自然", "触発＝刺激を受けて行動や感情が起こること（「〜に触発される」）"], "ex": "今回の失敗を<b>教訓</b>にして、次は慎重に準備しよう。"},
"32508": {"point": "「合意が得られる」は、話し合いで双方の意見が一致すること。「両者間の〜」とあるので「合意」。", "meaning": "互いの意見が一致すること。", "kr": "합의", "opts": ["集結＝一か所に集まること（「部隊が集結する」）", "適用＝規則などを当てはめること", "順応＝環境や状況に合わせて変わること", ""], "ex": "労使の間で、ようやく賃金についての<b>合意</b>が成立した。"},
"32509": {"point": "「幅広い知識」は、いろいろな分野にわたる知識。知識の範囲の広さを言うときは「幅広い」を使う。", "meaning": "範囲が広く、いろいろな方面にわたっている。", "kr": "폭넓다", "opts": ["", "分厚い＝厚みがある（「分厚い本」）。知識には使わない", "広大な＝面積が広くて大きい（「広大な土地」）。知識には使わない", "重厚な＝重々しく落ち着いている（「重厚な建物」）"], "ex": "彼は<b>幅広い</b>分野に興味を持っている。"},
"32510": {"point": "「条件に該当する」は、ある条件や項目に当てはまること。「次の条件に〜する場合」とあるので「該当」。", "meaning": "ある条件・項目などに当てはまること。", "kr": "해당", "opts": ["適応＝環境などに合うように変わること（「新しい環境に適応する」）", "相当＝ある価値や程度に見合うこと（「1万円相当の品」）。条件には「該当」", "順応＝環境や状況に慣れて合わせること", ""], "ex": "<b>該当</b>する項目に丸をつけてください。"},
"32511": {"point": "「非を暴く」は、相手の悪い点や過ちを明らかにすること。「非」は、正しくないこと・過ち。友人の過ちを明らかにするのはつらかった、という文脈に合う。", "meaning": "正しくないこと。あやまち。", "kr": "잘못, 허물", "opts": ["悪＝よくないこと。「悪を暴く」は不自然で、「悪事を暴く」となる", "", "苦＝苦しみ。暴くものではない", "没＝しずむ、ない。単独では使わない"], "ex": "彼は自分の<b>非</b>を認めて、みんなに謝った。"},
"32512": {"point": "「心細い」は、頼るものがなく不安な気持ち。雨で空が薄暗い、という状況で感じる気持ちとして合うのは「心細い」。", "meaning": "頼りになるものがなくて不安な様子。", "kr": "불안하다, 허전하다", "opts": ["かすかな＝わずかに感じられる（「かすかな音」）。気持ちの種類を表さない", "ひそかな＝人に知られないようにする（「ひそかな楽しみ」）", "", "心無い＝思いやりがない（「心無い言葉」）"], "ex": "知らない町で道に迷い、とても<b>心細かった</b>。"},
"32513": {"point": "「落ち着きを取り戻す」は、乱れていた気持ちが元の静かな状態に戻ること。コーヒーを飲んで落ち着いた、という意味なので「取り戻した」。", "meaning": "一度失ったものを、再び自分のものにする。", "kr": "되찾다", "opts": ["受け入れた＝人や意見などを受け取って認めること", "", "呼び込んだ＝客などを声をかけて招き入れること", "引き寄せた＝近くへ引いてくること"], "ex": "休養を取って、彼はすっかり元気を<b>取り戻した</b>。"},
"32514": {"point": "「端的に」は要点をはっきりと表す様子。グラフが気象異変をはっきり示している、ということなので「明白に」。", "meaning": "要点をはっきり、手短に表す様子。", "kr": "단적으로, 명백하게", "opts": ["主に＝大部分は、中心として", "大げさに＝実際より大きく", "", "部分的に＝一部分だけ"], "ex": "この数字が不況の深刻さを<b>端的に</b>物語っている。"},
"32515": {"point": "「鼻にかける」は自分の長所などを得意になって自慢すること。美人であることを自慢している、ということなので「自慢して」。", "meaning": "得意になって自慢する。", "kr": "뽐내다, 자랑하다, 코가 높다", "opts": ["張りあって＝互いに負けまいと競って", "打ち込んで＝一つのことに熱中して", "", "誇張して＝実際より大げさに表して。自慢とは違う"], "ex": "彼は有名大学の出身であることを<b>鼻にかけて</b>いる。"},
"32516": {"point": "「かねて」は「以前から、前もって」という意味。前もって知らせたとおり、ということなので「まえもって」。", "meaning": "以前から。前もって。", "kr": "미리, 전부터", "opts": ["ふたたび＝もう一度", "", "ほとんど＝大部分", "どうしても＝どんなにしても"], "ex": "<b>かねて</b>から希望していた部署に異動が決まった。"},
"32517": {"point": "「あるいは」は二つのうちどちらか一方であることを表す。今夜か明朝のどちらか、ということなので「または」。", "meaning": "または。もしくは。", "kr": "또는, 혹은", "opts": ["もしも＝仮に（〜なら）", "そのまま＝その状態で", "", "たしか＝はっきりしないが、たぶん"], "ex": "申し込みは電話<b>あるいは</b>メールで受け付けます。"},
"32518": {"point": "「ささいな」は取り上げるほどでもない、わずかな様子。小さなことが大事件に発展する、ということなので「小さな」。", "meaning": "取るに足りない、わずかな。", "kr": "사소한", "opts": ["重要な＝大切な。反対の意味", "深刻な＝事態が重大で厳しい。反対の意味", "新たな＝新しい", ""], "ex": "<b>ささいな</b>ことで夫婦げんかになった。"},
"32519": {"point": "「淡い」はここでは気持ちが強くなくほのかな様子。「淡い恋心」はほのかな、かすかな恋心なので「わずかな」が最も近い。", "meaning": "色・味・気持ちなどが薄く、かすかな様子。", "kr": "엷은, 희미한, 어렴풋한", "opts": ["みじめな＝情けなく哀れな", "ひそかな＝人に知られないようにする様子。隠す意味で、程度の薄さではない", "", "たんする＝このような語はない"], "ex": "空が<b>淡い</b>ピンク色に染まっていた。"},
"32520": {"point": "「規制」は、規則によって行動や活動を制限すること。主に法律・行政による制限に使い、「交通規制」「輸入規制」のように使う。③が正しい。", "meaning": "規則によって行動などを制限すること。", "kr": "규제", "opts": ["個人が量を減らす意味はない → ３キロに減らした", "範囲に閉じ込める意味は「限定」 → 狭い範囲に限定されている（限られている）", "", "小さくとどめる意味は「抑える」 → 最小限に抑える（食い止める）"], "ex": "マラソン大会の当日は、周辺道路で交通<b>規制</b>が行われる。"},
"32521": {"point": "「帯びる」は、ある性質・様子・雰囲気をうっすらと持つこと。「現実味を帯びる」「赤みを帯びる」の形で使う。①が正しい。", "meaning": "ある性質や様子を含み持つ。", "kr": "띠다", "opts": ["", "拍手などを受けるのは「浴びる」 → 拍手を浴びて", "うらみを持つのは「抱く」 → うらみを抱く者", "家庭を構えるのは「持つ」 → 家庭を持っている"], "ex": "夕焼けで、空が赤みを<b>帯びて</b>きた。"},
"32522": {"point": "「没頭」は、他のことを忘れて一つのことに熱中すること。④の「すべてを忘れて没頭できるもの」が正しい。", "meaning": "他を忘れて一つのことに熱中すること。", "kr": "몰두", "opts": ["治療に集中する意味は「専念」 → 治療に専念してほしい", "生活の様子を表す語ではない → 充実した生活", "感情にひたるのは「浸る」 → 充実感に浸った", ""], "ex": "彼は研究に<b>没頭</b>して、食事も忘れることがある。"},
"32523": {"point": "「耐えがたい」は、我慢できないほどつらい様子。「耐えがたい暑さ」「耐えがたい苦痛」のように使う。①が正しい。", "meaning": "我慢できないほど、つらい。", "kr": "견디기 어렵다", "opts": ["", "声の様子を表す語ではない → ひどく苦しそうな（弱々しい）声", "驚きの程度を強める語ではない → ひどく（とても）驚いた", "程度が極端な様子は「はなはだしい」 → 不注意もはなはだしい"], "ex": "工事の騒音は、住民にとって<b>耐えがたい</b>ものだった。"},
"32524": {"point": "「退く（しりぞく）」は、後ろへ下がること、また地位や職から離れること。④の長年勤めた職場を去る、が正しい。", "meaning": "後ろへ下がる。地位や職から身を引く。", "kr": "물러나다, 은퇴하다", "opts": ["やめる・こりごりだの意味では使わない → 犠牲にするのはやめた（もうこりごりだ）", "数値を上回る意味は「超える」 → 80キロを超えていた", "毎日続ける意味は「欠かさず」 → １日も欠かさず", ""], "ex": "社長は今年度限りで経営の第一線から<b>退く</b>ことになった。"},
"32525": {"point": "「復旧」は、壊れた設備や施設などを元の状態に戻すこと。「道路を復旧する」「電気が復旧する」のように使う。①が正しい。", "meaning": "壊れたものを元の状態に戻すこと。", "kr": "복구", "opts": ["", "中断したものを再び始めるのは「再開」 → 試合が再開した", "元の地位に戻るのは「復帰」 → 現役に復帰した", "仲の回復は「仲直り」 → あっという間に仲直りする"], "ex": "地震で止まった電車は、夕方には<b>復旧</b>した。"},
"32531": {"point": "「架空」は「かくう」。「架」は「カ」（架橋）で濁らず、「空」は長音の「クウ」。想像で作り出したもののこと。", "meaning": "事実に基づかず、想像で作り出したこと。", "kr": "가공, 허구", "opts": ["", "がくう：「架」は濁らず「か」", "かこう：「空」は「くう」。「かこう」は「加工・下降」の読み", "がこう：「架」は「か」、「空」は「くう」"], "ex": "この小説に出てくる町は<b>架空</b>の場所だ。"},
"32532": {"point": "「蓄える」は「たくわえる」。お金や物を将来のためにためておくこと。音読みは「チク」（貯蓄・蓄積）。", "meaning": "お金や物を、将来のためにためておくこと。", "kr": "저축하다, 비축하다", "opts": ["たずさえて＝携えて。「蓄」の読みではない", "", "そなえて＝備えて。「蓄」の読みではない", "かかえて＝抱えて。「蓄」の読みではない"], "ex": "冬に備えて、食料を<b>蓄えて</b>おく。"},
"32533": {"point": "「随時」は「ずいじ」。「随」は「ズイ」（随筆・随分）と濁って読む。必要なときにはいつでも、という意味。", "meaning": "必要なときにはいつでも。その時々に応じて。", "kr": "수시로", "opts": ["しゅうじ：「習字」の読み。「随」は「ずい」", "じゅうじ：「従事」の読み。「随」は「ずい」", "すいじ：「随」は濁って「ずい」。「すいじ」は「炊事」の読み", ""], "ex": "入会の申し込みは<b>随時</b>受け付けています。"},
"32534": {"point": "「漂う」は「ただよう」。空中や水面にふわふわと浮かぶこと、においや雰囲気がその場に満ちていること。音読みは「ヒョウ」（漂流）。", "meaning": "空中や水面にふわふわと浮かんで動くこと。また、においや雰囲気がその場に満ちていること。", "kr": "떠돌다, 감돌다", "opts": ["うるおって＝潤って。「漂」の読みではない", "", "さまよって＝あてもなく歩き回って。「漂」の読みではない", "さからって＝逆らって。「漂」の読みではない"], "ex": "会議室には重苦しい空気が<b>漂って</b>いた。"},
"32535": {"point": "「秀逸」は「しゅういつ」。「秀」は長音の「シュウ」（優秀）、「逸」は「イツ」（逸話）。他より抜きんでて優れていること。", "meaning": "他より抜きんでて優れていること。", "kr": "빼어남, 탁월함", "opts": ["", "しゅういち：「逸」は「いつ」", "しゅいつ：「秀」は長音で「しゅう」", "しゅいち：「秀」は「しゅう」、「逸」は「いつ」"], "ex": "彼の論文は着眼点が<b>秀逸</b>だと評価された。"},
"32536": {"point": "「隆盛」は「りゅうせい」。「隆」は長音の「リュウ」（隆起）、「盛」は「セイ」（全盛）。「盛」を「ジョウ」と読む「繁盛（はんじょう）」と混同しないこと。", "meaning": "勢いが盛んで、栄えていること。", "kr": "융성", "opts": ["りゅうじょう：「盛」を「じょう」と読むのは「繁盛」など。この語は「せい」", "りゅじょう：「隆」は長音で「りゅう」、「盛」は「せい」", "", "りゅせい：「隆」は長音で「りゅう」"], "ex": "江戸時代、この港町は貿易で<b>隆盛</b>を誇った。"},
"32537": {"point": "「自白を強制される」は、無理に自白させられること。被告が、自白は警察に無理にさせられたものだ、と主張しているので「強制」。", "meaning": "力によって無理にさせること。", "kr": "강제", "opts": ["圧倒＝ずば抜けた力で相手を押さえつけること（「相手を圧倒する」）。自白には使わない", "束縛＝行動の自由を制限すること。「自白を束縛される」とは言わない", "", "固執＝自分の考えを強く守ってゆずらないこと"], "ex": "参加は自由で、誰にも<b>強制</b>はしない。"},
"32538": {"point": "「センスのよさ」は、物事の微妙な点を感じとる感覚・才能がすぐれていること。マーケティングの才能について言うので「センス」。", "meaning": "物事の微妙な感じを感じとる能力。", "kr": "센스, 감각", "opts": ["", "クレーム＝苦情。「よさ」とは結びつかない", "ステップ＝段階、足の運び", "ニュアンス＝微妙な意味合い"], "ex": "彼女は服の<b>センス</b>がいいので、いつもおしゃれだ。"},
"32539": {"point": "「稼働」は、機械や工場が動いて仕事をすること。「工場は24時間体制で〜している」とあるので「稼働」。", "meaning": "機械・工場などが動いて生産すること。", "kr": "가동", "opts": ["展開＝物事を広げること、話が進んでいくこと", "起動＝機械やコンピューターを動かし始めること。24時間続く状態には使わない", "運行＝列車やバスが決まった道筋を走ること", ""], "ex": "新しい発電所が来月から<b>稼働</b>する予定だ。"},
"32540": {"point": "「報道陣」は、取材のために集まった記者やカメラマンの集団。接尾語「陣」は、ある目的で集まった人々を表す。", "meaning": "（接尾語）ある目的のために集まった人々の集団。", "kr": "진(陣), 단", "opts": ["", "網＝網の目のように張りめぐらしたもの（「通信網」）。人の集団ではない", "隊＝組織された集団（「探検隊」）。「報道隊」とは言わない", "派＝主義などを同じくする仲間（「改革派」）"], "ex": "空港には、到着した選手を待つ報道<b>陣</b>が大勢集まっていた。"},
"32541": {"point": "「被害を最小限に食い止める」は、悪いことがそれ以上広がらないように防ぐこと。台風の被害について言うので「食い止める」。", "meaning": "悪い事態がそれ以上広がらないように防ぐ。", "kr": "막다, 저지하다", "opts": ["吸い上げる＝吸って上に上げること、利益を取り上げること", "投げ出す＝放り出すこと、途中でやめること", "", "打ち切る＝途中で終わりにすること"], "ex": "消防士の活躍で、火事の延焼を<b>食い止める</b>ことができた。"},
"32542": {"point": "「へとへとに疲れる」は、ひどく疲れて力がなくなる様子。一日じゅう立ち続けだったので「へとへとに」。", "meaning": "ひどく疲れて、力がなくなった様子。", "kr": "녹초가 되어", "opts": ["ぎっしり＝すきまなく詰まっている様子", "", "すっきり＝さわやかで気持ちがいい様子。疲れとは合わない", "からからに＝すっかり乾いている様子（「のどがからからだ」）"], "ex": "マラソンを走り終えて、<b>へとへとに</b>なった。"},
"32543": {"point": "「しいて言えば」は、無理に一つ選ぶとすれば、という言い方。みんな好きだが、あえて言うとモネ、という文脈なので「しいて」。", "meaning": "無理に。あえて。", "kr": "굳이", "opts": ["よほど＝かなり、相当に（「よほど疲れていたのだろう」）", "いっそう＝さらに程度が増す様子", "いかにも＝本当にそれらしい様子", ""], "ex": "嫌いな食べ物はないが、<b>しいて</b>言えばピーマンが苦手だ。"},
"32544": {"point": "「とりわけ」は多くの中で特に、という意味。ハイキングの中でも特に秋がよい、ということなので「格別に」。", "meaning": "多くの中で特に。", "kr": "특히, 유달리", "opts": ["無性に＝むやみに、わけもなく", "大幅に＝変化の幅が大きく", "丹念に＝細かい所まで念入りに", ""], "ex": "今年の夏は、<b>とりわけ</b>暑さが厳しかった。"},
"32545": {"point": "「照会する」は不明な点を問い合わせて確かめること。経歴について教授に問い合わせてほしい、ということなので「問い合わせて」。", "meaning": "問い合わせて確かめること。", "kr": "조회하다, 문의하다", "opts": ["知らせて＝情報を伝えて。こちらから伝える意味", "申し込んで＝参加などを申し出て", "", "訪ねて＝その人の所へ行って"], "ex": "在庫の有無をメーカーに<b>照会した</b>。"},
"32546": {"point": "「案の定」は思ったとおり、予想どおりという意味。怠けていたので予想どおり落ちた、ということなので「思ったとおりに」。", "meaning": "思ったとおり。予想どおり。", "kr": "아니나 다를까, 예상대로", "opts": ["驚いたことに＝意外なことに。予想どおりとは反対", "それと同時に＝同じときに", "あいにく＝都合の悪いことに", ""], "ex": "傘を持たずに出かけたら、<b>案の定</b>雨に降られた。"},
"32547": {"point": "「思わず」はそうするつもりがないのに、ついしてしまう様子。腹が立って、つい彼をどなった、ということなので「無意識に」。", "meaning": "そのつもりはないのに。つい。", "kr": "무심코, 나도 모르게", "opts": ["思ったとおり＝予想どおり。「案の定」に当たる", "", "わざとらしく＝わざとしているようで不自然に", "十分に＝足りないところがなく"], "ex": "あまりのおかしさに、<b>思わず</b>笑ってしまった。"},
"32548": {"point": "「もろもろ（諸々）」は多くのいろいろなもの。いろいろな事情があって、ということなので「いろいろの」。", "meaning": "いろいろなもの。数多く。", "kr": "여러 가지, 제반", "opts": ["", "いかなる＝どのような", "個人的な＝その人自身に関する", "やむをえない＝しかたがない"], "ex": "引っ越しに伴う<b>もろもろの</b>手続きを済ませた。"},
"32549": {"point": "「とまどう」はどうしたらよいかわからなくて迷う、困ること。次々と出てくる要求にどう対応すべきか困った、ということなので「困った」。", "meaning": "どうしてよいかわからず、まごつく。", "kr": "당황하다, 어리둥절하다", "opts": ["驚いた＝意外なことに心が動いた。対応に迷う意味はない", "", "怖がった＝恐ろしく思った", "悔やんだ＝後悔した"], "ex": "初めての海外で、習慣の違いに<b>とまどった</b>。"},
"32550": {"point": "「抱え込む」は、物を腕に抱く、また問題や仕事を自分一人で背負うこと。②の悩み事を一人で抱え込む、が正しい。", "meaning": "腕に抱く。問題や仕事を一人で背負い込む。", "kr": "떠안다, 혼자 끌어안다", "opts": ["体力が続く意味は「持つ」 → 体が持たない", "", "見つける意味は「発見する」 → 遺体はまだ発見されていない（収容されていない）", "要求を認める意味は「受け入れる」 → 要求を受け入れる"], "ex": "彼は仕事を一人で<b>抱え込んで</b>、体を壊してしまった。"},
"32551": {"point": "「入手」は、物や情報を手に入れること。「情報を入手する」「入手経路」のように使う。③が正しい。", "meaning": "物や情報を手に入れること。", "kr": "입수", "opts": ["人から贈られる場合は「もらう」 → プレゼントをもらった", "努力して得るのは「勝ち取る」 → 自由を勝ち取った", "", "許可は「得る」「取る」 → 許可を得なければ"], "ex": "限定版のチケットをようやく<b>入手</b>した。"},
"32552": {"point": "「見落とす」は、見ていながら気づかずに見過ごすこと。③の監督のサインに気づかなかった、が正しい。", "meaning": "見ていながら気づかずに過ごす。", "kr": "못 보고 넘기다, 간과하다", "opts": ["注意して見守るのは「見張る」 → 見張っていてください", "自信を失う意味はない → 自分自身を見失った", "", "先を予測するのは「見通す」 → ５年先を見通す"], "ex": "メールの大事な一文を<b>見落として</b>いた。"},
"32553": {"point": "「一律に」は、すべてを同じ基準・同じ扱いにする様子。「一律に無料化する」「一律に値上げする」のように使う。②が正しい。", "meaning": "すべてを同じ扱いにする様子。", "kr": "일률적으로", "opts": ["一度にまとめて出る様子は「どっと」 → 疲れがどっと出て", "", "いつもそうする意味は「すぐに」「決まって」 → すぐに人のせいにする", "広く行き渡る様子は「広く」 → 広く（一般に）普及した"], "ex": "全社員の給料が<b>一律に</b>３パーセント上がった。"},
"32554": {"point": "「はなはだしい」は、程度が非常に激しい様子。主に好ましくないことに使い、「誤解もはなはだしい」「はなはだしく傷つく」のようにいう。③が正しい。", "meaning": "（好ましくないことの）程度が非常に激しい。", "kr": "심하다, 지나치다", "opts": ["よい活躍を褒めるときには使わない → めざましい活躍", "難しさを表す語ではない → かなり難しい（大変だ）", "", "よい活躍には使わない → めざましい（すばらしい）活躍"], "ex": "それは私への誤解も<b>はなはだしい</b>。"},
"32555": {"point": "「還元」は、得たものを元の所へ返すこと。「利益を社会に還元する」のように使う。④が正しい。", "meaning": "得たものを元に返すこと。", "kr": "환원", "opts": ["料金を返すのは「払い戻し」 → 料金の払い戻し（返金）", "数量が減るのは「減少」 → 30パーセント減少した", "元の状態に戻るのは「回復」 → 景気が回復する", ""], "ex": "売り上げの一部をポイントとして客に<b>還元</b>している。"},
"32561": {"point": "「虚構」は「きょこう」。「虚」は「キョ」（虚偽）、「構」は「コウ」（構造）で、どちらも濁らない。事実でないことを作り上げること。", "meaning": "事実ではないことを、事実らしく作り上げること。フィクション。", "kr": "허구", "opts": ["きょごう：「構」は濁らず「こう」", "ぎょごう：「虚」は「きょ」、「構」は「こう」で、どちらも濁らない", "", "ぎょこう：「虚」は濁らず「きょ」。「ぎょこう」は「漁港」の読み"], "ex": "この映画は実話ではなく、すべて<b>虚構</b>の物語だ。"},
"32562": {"point": "「臨む」は「のぞむ」。「記者会見に臨む」のように、重要な場面に出ること。同じ音の「望む」と使い分ける。音読みは「リン」（臨時）。", "meaning": "重要な場面や場所に出ること。また、ある場所に面すること。", "kr": "임하다, 면하다", "opts": ["はげんだ＝励んだ。「臨」の読みではない", "いどんだ＝挑んだ。意味は近いが「挑」の読み", "からんだ＝絡んだ。「臨」の読みではない", ""], "ex": "選手たちは万全の準備で決勝戦に<b>臨んだ</b>。"},
"32563": {"point": "「陳列」は「ちんれつ」。「陳」は「チン」（陳述・陳謝）、「列」は「レツ」（行列）。品物を並べて見せること。", "meaning": "人に見せるため、品物を並べておくこと。", "kr": "진열", "opts": ["", "しんれつ：「陳」は「ちん」", "ちんれい：「列」は「れつ」。「れい」は「例」などの読み", "しんれい：「陳」は「ちん」、「列」は「れつ」"], "ex": "博物館には古代の土器が<b>陳列</b>されている。"},
"32564": {"point": "「索漠」は「さくばく」。「索」は「サク」（検索・思索）、「漠」は「バク」（砂漠）。「索漠たる」の形で、心が満たされずもの寂しい様子を表す。", "meaning": "心が満たされず、もの寂しい様子。", "kr": "삭막함", "opts": ["せきまく：「索」は「さく」、「漠」は「ばく」", "せきばく：「寂寞（せきばく）」と混同した読み。「索」は「さく」", "さくまく：「漠」は「ばく」", ""], "ex": "都会の<b>索漠</b>とした暮らしに疲れ、田舎に移り住んだ。"},
"32565": {"point": "「痛罵」は「つうば」。「痛」は「ツウ」（痛烈）、「罵」は「バ」（罵倒・罵声）。激しくののしること。", "meaning": "激しくののしること。", "kr": "통렬한 매도, 호된 욕", "opts": ["", "つうは：「罵」は濁って「ば」", "うつばい：「痛」は「つう」、「罵」は「ば」", "つうはい：「罵」は「ば」と読み、「はい」とは読まない"], "ex": "彼は会議で部下の失敗を人前で<b>痛罵</b>した。"},
"32566": {"point": "「萌芽」は「ほうが」。「萌」は音読みで「ホウ」（訓は「もえる」）、「芽」は「ガ」（発芽）。物事の始まり・きざしの意味でよく使う。", "meaning": "草木の芽が出ること。転じて、物事の始まり・きざし。", "kr": "맹아, 싹", "opts": ["ほうげ：「芽」は「が」", "", "もうげ：「萌」は「ほう」、「芽」は「が」", "もうが：「萌」は「ほう」と読み、「もう」とは読まない"], "ex": "この時代の作品には、近代文学の<b>萌芽</b>が見られる。"},
"32567": {"point": "「感情の起伏が激しい」は、気分が上がったり下がったりする変化が大きいこと。「感情の〜が激しい」と結びつくのは「起伏」。", "meaning": "高くなったり低くなったりすること。感情などの変化。", "kr": "기복", "opts": ["高低＝高さの違い（「音の高低」）。感情には使わない", "出没＝現れたり隠れたりすること（「クマが出没する」）", "", "明暗＝明るさと暗さ、幸と不幸（「明暗を分ける」）"], "ex": "この辺りは土地の<b>起伏</b>が多く、自転車で走るのは大変だ。"},
"32568": {"point": "「もっぱら」は、他のことはせず、そのことばかりする様子。休日の時間をほとんどゴルフの練習に使った、という意味なので「もっぱら」。", "meaning": "そのことばかりに集中する様子。", "kr": "오로지, 주로", "opts": ["", "しきりに＝何度も繰り返して（「しきりに時計を見る」）", "ますます＝前よりいっそう", "せめて＝少なくとも（「せめて一日だけでも」）"], "ex": "最近は<b>もっぱら</b>家で映画を見て過ごしている。"},
"32569": {"point": "「問題に直面する」は、困難な問題に直接向き合うこと。「〜している問題」とあるので「直面」。", "meaning": "ある物事・事態に直接向き合うこと。", "kr": "직면", "opts": ["近接＝すぐ近くにあること", "対面＝顔と顔を合わせること（「初対面」）。問題には使わない", "", "隣接＝となり合っていること（「隣接する町」）"], "ex": "その会社は深刻な経営危機に<b>直面</b>している。"},
"32570": {"point": "「最善を尽くす」は、できる限りのことをすべて行うこと。決まった組み合わせで「尽くした」。", "meaning": "（「最善を尽くす」で）できる限りのことをする。", "kr": "다하다", "opts": ["果たした＝役目や約束をやり遂げる（「責任を果たす」）。「最善を果たす」とは言わない", "", "極めた＝最後まで究める（「頂上を極める」）。「最善を極める」とは言わない", "遂げた＝目的をなしとげる（「成長を遂げる」）"], "ex": "結果はだめだったが、全力を<b>尽くした</b>ので後悔はない。"},
"32571": {"point": "「ノルマ」は、一定の期間内に果たすよう割り当てられた仕事の量。「取り締まりの〜が課されている」とあるので「ノルマ」。", "meaning": "個人や集団に割り当てられた仕事の量。", "kr": "할당량", "opts": ["チーフ＝主任、責任者", "コスト＝費用", "", "キャリア＝経歴"], "ex": "営業部員には毎月の販売<b>ノルマ</b>がある。"},
"32572": {"point": "「人込みにまぎれる」は、多くの人の中に入り込んで区別がつかなくなること。少年が見えなくなった、という意味なので「まぎれて」。", "meaning": "他のものに入りまじって、区別がつかなくなる。", "kr": "섞이다, 뒤섞이다", "opts": ["なじんで＝慣れて親しむ（「新しい環境になじむ」）", "からんで＝巻きつく、関係する", "おさまって＝中にきちんと入る、静かになる", ""], "ex": "犯人は夜の闇に<b>まぎれて</b>逃げた。"},
"32573": {"point": "「すさまじい勢い」は、恐ろしいほど激しい勢い。知らせを聞いてすぐに飛び出した様子なので「すさまじい」。", "meaning": "恐ろしいほど程度が激しい様子。", "kr": "무시무시하다, 굉장하다", "opts": ["いさましい＝勇気があって元気がいい。「勢い」の激しさを表さない", "", "やかましい＝うるさい、口うるさい", "あわただしい＝落ち着かず忙しい。「あわただしい勢い」とは言わない"], "ex": "台風が<b>すさまじい</b>勢いで町を通過していった。"},
"32574": {"point": "「往来」はここでは人や車が行き来する道の意味。道の真ん中でけんかをするな、ということなので「道路」。", "meaning": "人や車が行き来すること。また、その道。", "kr": "길거리, 한길, 왕래", "opts": ["", "広場＝人が集まれる広く開けた場所", "公園＝人々が休んだり遊んだりする場所", "跡地＝建物などがなくなった後の土地"], "ex": "子どもたちが<b>往来</b>でボール遊びをしていて危ない。"},
"32575": {"point": "「フォローする」は人の足りないところを補って助けること。社長や先輩が自分を補い助けてくれた、ということなので「助けて」。", "meaning": "足りないところを補って助けること。", "kr": "도와주다, 뒷받침하다", "opts": ["援助して＝お金や物などで助けて。補う意味が弱い", "救助して＝危険な状態から救い出して", "", "教えて＝知識や技術を伝えて"], "ex": "ミスをしたが、同僚がすぐに<b>フォローして</b>くれた。"},
"32576": {"point": "「かろうじて」はやっとのことで、何とか、という意味。法案がぎりぎり過半数を得た、ということなので「何とか」。", "meaning": "やっとのことで。ぎりぎりで。", "kr": "간신히, 겨우", "opts": ["", "なぜか＝理由はわからないが", "すぐに＝時間をおかずに", "たまたま＝偶然に"], "ex": "終電に<b>かろうじて</b>間に合った。"},
"32577": {"point": "「そわそわ」は気になることがあって落ち着かない様子。面接を前に落ち着かない、ということなので「緊張して」が最も近い。", "meaning": "気になることがあって、落ち着かない様子。", "kr": "안절부절못하다, 들썩들썩", "opts": ["感動して＝深く心を動かされて", "", "振動して＝揺れ動いて。物理的な揺れの意味", "出張している＝仕事でよそへ出かけている"], "ex": "発表を待つ間、彼は朝から<b>そわそわして</b>いる。"},
"32578": {"point": "「けげん（怪訝）な」はわけがわからず、不思議に思う様子。花束を渡されて不思議そうな顔をした、ということなので「疑わしい」が最も近い。", "meaning": "わけがわからず、不思議に思う様子。", "kr": "의아한, 이상하다는 듯한", "opts": ["面倒くさい＝手間がかかって嫌だ", "不愉快な＝嫌な気持ちがする。不思議に思う意味はない", "", "機嫌よい＝気分がよい"], "ex": "突然話しかけると、彼は<b>けげんな</b>顔でこちらを見た。"},
"32579": {"point": "「プロセス」は物事が進んでいく道筋・途中の段階。実験の途中の段階で問題点がわかった、ということなので「過程」。", "meaning": "物事が進む道筋。過程。", "kr": "과정, 프로세스", "opts": ["証明＝正しいことを明らかにすること", "結果＝最後に出た状態。過程とは反対", "装置＝ある目的のために備えつけた機械や道具", ""], "ex": "結果だけでなく、そこに至る<b>プロセス</b>も大切だ。"},
"32580": {"point": "「安静」は、病気やけがの回復のため、体を動かさず静かに休んでいること。「安静にする」の形で使う。②が正しい。", "meaning": "体を動かさず静かに休むこと。", "kr": "안정 (휴식)", "opts": ["落ち着いて判断するのは「冷静」 → 冷静な判断", "", "住む環境が静かなのは「閑静」 → 閑静で暮らしやすい", "変化がなく落ち着いているのは「安定」 → 安定した仕事"], "ex": "医者から一週間は<b>安静</b>にするように言われた。"},
"32581": {"point": "「はがす」は、表面に貼りついている物を取り去ること。「ラベルをはがす」「シールをはがす」のように使う。④が正しい。", "meaning": "貼りついている物を取り去る。", "kr": "벗기다, 떼다", "opts": ["歴史の新しい展開は「開く」「加える」 → 新たな１ページを開いた（加えた）", "めがねは「かける」 → めがねをかけないと", "果物の皮は「むく」 → りんごの皮をむいて", ""], "ex": "壁に貼ってあったポスターを<b>はがした</b>。"},
"32582": {"point": "「素早い」は、動作や反応がとても速い様子。主に人の動き・対応に使う。②の素早く対応した、が正しい。", "meaning": "動作や反応がとても速い。", "kr": "재빠르다, 날쌔다", "opts": ["時間がたたずに、の意味は「すぐに」 → すぐに（早晩）すたれる", "", "発展の速さは「急速に」 → 最も急速に発展し", "前ぶれなく、の意味は「突然」「急に」 → 音楽が突然やんで"], "ex": "彼は<b>素早く</b>ボールを拾って、味方にパスした。"},
"32583": {"point": "「今更」は、今になってから、もう時機が遅いという気持ち。「今更〜まで（も）ない」「今更言っても遅い」のように使う。④が正しい。", "meaning": "今になって。もう遅いという気持ち。", "kr": "새삼스럽게, 이제 와서", "opts": ["今もまだ続く意味は「いまだに」 → いまだに内戦の傷跡が残っている", "すぐにも起こりそうな様子は「今にも」 → 今にも倒れそうな", "現在も変わらない意味は「依然として」 → 依然として（いまだに）女性の昇進は難しい", ""], "ex": "<b>今更</b>謝られても、もう遅い。"},
"32584": {"point": "「もはや」は、事態が変化して、もう今となっては、という意味。「もはや〜ない」「もはや手遅れだ」のように使う。④が正しい。", "meaning": "今となっては、もう。", "kr": "이미, 이제는", "opts": ["過去を表す語ではない → 以前は（かつて）桜の並木があった", "過去の状態を表す語ではない → かつて（以前は）高校教師だった", "今すぐ、の意味は「今すぐ」「ただちに」 → 今すぐこの場で", ""], "ex": "ここまで来たら、<b>もはや</b>引き返すことはできない。"},
"32585": {"point": "「統合」は、いくつかのものを一つにまとめ合わせること。「経済統合」「組織を統合する」のように使う。①が正しい。", "meaning": "複数のものを一つにまとめ合わせること。", "kr": "통합", "opts": ["", "色を揃えるのは「統一」 → 焦げ茶系の色に統一しても", "人と落ち合うのは「合流」 → 彼と１時間後に合流する", "費用を足すのは「合計」 → 費用を合計してみた"], "ex": "二つの部署を<b>統合</b>して、新しい部を作った。"},
"32591": {"point": "「啓発」は「けいはつ」。「啓」は「ケイ」（拝啓）、「発」は「ハツ」。前が「い」で終わるので半濁音にならない（「出発（しゅっぱつ）」とは違う）。", "meaning": "知識を与えて、人を新しい考えや理解に導くこと。", "kr": "계발, 깨우침", "opts": ["", "けいぱつ：「発」は半濁音にならず「はつ」", "かいはつ：「開発」の読み。「啓」は「けい」", "かいぱつ：「啓」は「けい」、「発」は「はつ」"], "ex": "友人の生き方に<b>啓発</b>されて、ボランティアを始めた。"},
"32592": {"point": "「沈潜」は「ちんせん」。「沈」は「チン」（沈黙）、「潜」は「セン」（潜水）。ここでは、一つのことに深く没頭するという意味。", "meaning": "水の底深く沈むこと。転じて、一つのことに深く没頭すること。", "kr": "침잠, 몰두", "opts": ["しんせん：「沈」は「ちん」。「しんせん」は「新鮮」の読み", "しんさん：「辛酸」の読み。「沈」は「ちん」、「潜」は「せん」", "", "ちんさん：「潜」は「せん」"], "ex": "彼は研究に<b>沈潜</b>し、何年も論文を書き続けた。"},
"32593": {"point": "「拒む」は「こばむ」。相手の要求や申し出を受け入れず、断ること。音読みは「キョ」（拒否・拒絶）。", "meaning": "相手の要求や申し出を受け入れず、断ること。", "kr": "거부하다, 거절하다", "opts": ["うらんだ＝恨んだ。「拒」の読みではない", "おがんだ＝拝んだ。「拒」の読みではない", "にくんだ＝憎んだ。「拒」の読みではない", ""], "ex": "容疑者は質問に答えることを<b>拒んだ</b>。"},
"32594": {"point": "「華やか」は「はなやか」。「華」を訓読みの「はな」と読む。明るく美しく人目を引く様子。音読みは「カ」（豪華）。", "meaning": "明るく美しく、人目を引く様子。", "kr": "화려하다", "opts": ["あざやかな＝鮮やかな。「華」の読みではない", "", "なごやかな＝和やかな。「華」の読みではない", "かろやかな＝軽やかな。「華」の読みではない"], "ex": "パーティー会場は<b>華やかな</b>ドレスの女性たちでいっぱいだった。"},
"32595": {"point": "「脈絡」は「みゃくらく」。「脈」は「ミャク」（山脈）、「絡」は「ラク」（連絡）。物事の筋道やつながりのこと。", "meaning": "物事の筋道やつながり。", "kr": "맥락", "opts": ["びゃくりゃく：「脈」は「みゃく」、「絡」は「らく」", "びゃくらく：「脈」は「みゃく」", "みゃくりゃく：「絡」は「らく」。「りゃく」は「略」の読み", ""], "ex": "彼の話は<b>脈絡</b>がなく、何を言いたいのかわからない。"},
"32596": {"point": "「淡い」は「あわい」。色や味が薄い様子、気持ちがかすかな様子。音読みは「タン」（冷淡・淡水）。形の似た「浅い（あさい）」と混同しないこと。", "meaning": "色や味などが薄い様子。また、光や気持ちなどがかすかである様子。", "kr": "옅다, 희미하다", "opts": ["", "きよい＝清い。「淡」の読みではない", "あさい＝浅い。形が似ているが別の字", "はかない＝儚い。「淡」の読みではない"], "ex": "彼女は初恋の<b>淡い</b>思い出を語った。"},
"32597": {"point": "「犯罪の抑止」は、悪いことが起こらないように抑えて止めること。罰則の強化が犯罪を防ぐ効果を持つ、という意味なので「抑止」。", "meaning": "抑えて止めること。", "kr": "억지, 억제", "opts": ["抑揚＝声や文章の調子の上がり下がり", "", "予期＝前もって予想して待つこと", "予測＝前もって推し量ること"], "ex": "防犯カメラには犯罪を<b>抑止</b>する効果がある。"},
"32598": {"point": "「おおらかな性格」は、小さなことにこだわらず、ゆったりとした性格。「明るく」「毎日楽しく」と合うのは「おおらかな」。", "meaning": "心がゆったりとしていて、小さなことにこだわらない様子。", "kr": "대범하다, 너그럽다", "opts": ["", "あざやかな＝色や形がはっきりして美しい、手際がよい", "ささやかな＝規模が小さくつつましい（「ささやかな贈り物」）", "すみやかな＝すばやい（「すみやかに対応する」）"], "ex": "彼は<b>おおらかな</b>人で、小さな失敗はまったく気にしない。"},
"32599": {"point": "「データが流出する」は、情報などが外部に漏れ出ること。顧客データについて言うので「流出」。", "meaning": "中にあるものが外部へ出ること。", "kr": "유출", "opts": ["転向＝立場や考えを変えること", "展開＝広げること、物事が進むこと", "発散＝内にこもったものを外に出すこと（「ストレスを発散する」）", ""], "ex": "会社の機密情報が外部に<b>流出</b>した。"},
"32600": {"point": "「くよくよする」は、小さなことをいつまでも気にして悩むこと。「病気になるよ」と注意しているので「くよくよ」。", "meaning": "小さなことをいつまでも気にして、思い悩む様子。", "kr": "끙끙 앓다, 연연하다", "opts": ["ふんわり＝柔らかくふくらんだ様子", "ひっそり＝静かで人の気配がない様子", "のろのろ＝動作が遅い様子", ""], "ex": "終わったことを<b>くよくよ</b>しても仕方がない。"},
"32601": {"point": "「法案が可決される」は、会議で提出された案をよいと認めて決めること。「圧倒的多数で」とあるので「可決」。", "meaning": "会議で、議案をよいと認めて決めること。", "kr": "가결", "opts": ["選出＝選び出すこと。人に使う", "", "採取＝研究などのために取ること（「指紋を採取する」）", "判別＝見分けること"], "ex": "予算案は賛成多数で<b>可決</b>された。"},
"32602": {"point": "「卓越する」は、他よりはるかにすぐれていること。雄弁家としてすぐれている、という意味なので「卓越」。", "meaning": "他よりはるかにすぐれていること。", "kr": "탁월하다", "opts": ["没頭＝一つのことに夢中になること", "露呈＝隠れていたことが表に現れること（「弱点が露呈する」）", "", "装飾＝飾ること"], "ex": "彼女は語学の才能に<b>卓越</b>している。"},
"32603": {"point": "「話を切り出す」は、言いにくい話を始めること。別れ話をどう始めればいいかわからない、という意味なので「切り出して」。", "meaning": "話を始める。特に、言いにくい話を口に出す。", "kr": "말을 꺼내다", "opts": ["", "割り当てて＝全体をいくつかに分けて配ること", "押し込んで＝無理に中に入れること", "持ち上げて＝上にあげること、人をおだてること"], "ex": "上司に転勤の話をどう<b>切り出そう</b>か迷っている。"},
"32604": {"point": "「手本」はここでは見習うべき行いや人の意味。子どもに見習うべきよい行いを示す、ということなので「模範」。", "meaning": "見習うべき物事や人。模範。", "kr": "본보기, 모범", "opts": ["方法＝目的のためのやり方", "", "手順＝物事を行う順序", "見本＝商品の質などを示すための品物（サンプル）。行いのお手本には「模範」が合う"], "ex": "親が<b>手本</b>を見せれば、子どもも自然とあいさつをするようになる。"},
"32605": {"point": "「いかにも」はここでは「まさにそれらしい」という意味。日本人らしさがよく表れた考え方だ、ということなので「典型的に」。", "meaning": "まさにそれらしい様子。", "kr": "정말 ~답게, 전형적으로", "opts": ["具体的に＝はっきりした形や内容を備えて", "全体的に＝全体として", "", "一般的に＝広く普通に"], "ex": "<b>いかにも</b>学者らしい慎重な答え方だった。"},
"32606": {"point": "「こらえる」は苦しさや感情を外に出さずに我慢すること。眠いのを我慢して勉強した、ということなので「辛抱して」。", "meaning": "苦しさなどを我慢する。", "kr": "참다, 견디다", "opts": ["調整して＝具合よく整えて", "", "封鎖して＝出入りできないように閉ざして", "協議して＝集まって相談して"], "ex": "涙を<b>こらえて</b>、最後まで話した。"},
"32607": {"point": "「自尊心」は自分の人格や能力に誇りを持つ心。それが傷ついた、ということなので「プライド」。", "meaning": "自分の人格や能力に誇りを持つ心。", "kr": "자존심", "opts": ["", "スタイル＝体つき、型、やり方", "イメージ＝心に浮かぶ姿、印象", "コントロール＝思いどおりに操ること"], "ex": "人前で叱られて、<b>自尊心</b>を傷つけられた。"},
"32608": {"point": "「いっこうに」は否定とともに使い、「少しも〜ない」という意味。何を言われても少しも気にしない、ということなので「全然」。", "meaning": "（否定とともに）少しも。全然。", "kr": "전혀, 조금도", "opts": ["もう一度＝さらに一回", "少しずつ＝わずかずつ", "一斉に＝みんなが同時に", ""], "ex": "いくら待っても、バスは<b>いっこうに</b>来なかった。"},
"32609": {"point": "「エスカレートする」は物事の程度や規模が段階的に大きくなること。紛争がだんだん拡大していった、ということなので「段階的に拡大して」。", "meaning": "程度や規模が段階的に大きく、激しくなること。", "kr": "확대되다, 격화되다, 에스컬레이트되다", "opts": ["段階的に縮小して＝だんだん小さくなって。反対の意味", "組織的に縮小して＝組織として小さくなって", "", "組織的に拡大して＝組織としてまとまって大きくなって。「エスカレート」は「段階的に」の意味"], "ex": "最初は小さな口論だったが、次第に<b>エスカレートして</b>いった。"},
"32610": {"point": "「人一倍」は、普通の人以上に、という意味で、人の努力や感情の程度について使う。③の「人一倍努力した」が正しい。", "meaning": "普通の人よりも程度がずっと大きいこと。", "kr": "남보다 갑절, 남달리", "opts": ["物事の程度が増す意味は「一段と」 → 一段と（いっそう）楽しくなる", "数値が倍になる意味は「倍増」 → 視聴率が倍増した", "", "人の努力や気持ち以外には使わない → いつも上位に（決勝トーナメントに）進出している"], "ex": "彼女は<b>人一倍</b>負けず嫌いだ。"},
"32611": {"point": "「携わる」は、ある仕事や事柄に関係して従事すること。「経営に携わる」「研究に携わる」のように使う。④が正しい。", "meaning": "ある仕事や事柄にかかわる。従事する。", "kr": "종사하다, 관여하다", "opts": ["結果が何かになる意味はない → 大変な業績になる", "実際に行う意味は「実行」 → 実際に実行する（実現する）のは", "最後までやり通す意味は「やり抜く」 → 最後までやり抜いた", ""], "ex": "父は四十年間、教育に<b>携わって</b>きた。"},
"32612": {"point": "「軌道」は、天体や物の通る道、また物事が進む道筋・方向。「軌道に乗る」「軌道を修正する」のように使う。③が正しい。", "meaning": "物が通る道。物事の進む道筋。", "kr": "궤도", "opts": ["作業の順序は「手順」 → インストールする手順", "政府の考えの方向は「方針」 → 明確な方針", "", "目指す対象は「目標」「手本」 → 木村先生を目標に"], "ex": "新しい事業がようやく<b>軌道</b>に乗ってきた。"},
"32613": {"point": "「経緯（いきさつ・けいい）」は、物事がそうなるまでの細かな事情・成り行き。「事件の経緯」のように使う。④が正しい。", "meaning": "物事がそうなるまでの事情や成り行き。", "kr": "경위, 자초지종", "opts": ["船の進む道は「針路」「航路」 → 針路（航路）からそれないように", "製品を作る段階は「工程」 → 生産工程でのミス", "時間の使い方は「過ごし方」 → 有意義な過ごし方", ""], "ex": "会議では、計画が中止になった<b>経緯</b>が説明された。"},
"32614": {"point": "「思い詰める」は、一つのことばかりを深く考えて悩み込むこと。①の思い詰めた表情（深刻に悩んでいる顔）が正しい。", "meaning": "一つのことばかり考えて、深く悩む。", "kr": "골똘히 생각하다, 깊이 고민하다", "opts": ["", "荷物を入れる意味は「詰める」 → スーツケースに荷物を詰めた", "やめる意味は「見送る」「あきらめる」 → 購入は見送ることにした", "記憶をよみがえらせるのは「思い出す」 → はっきりと思い出す"], "ex": "一人で<b>思い詰め</b>ないで、誰かに相談してね。"},
"32615": {"point": "「心構え」は、物事に対処するための前もっての心の準備。「日頃の心構え」「受験生としての心構え」のように使う。②が正しい。", "meaning": "物事に備える、前もっての心の準備。", "kr": "마음가짐, 각오", "opts": ["相手への気配りは「心配り」 → 全宿泊客への心配り（気配り）", "", "予定・意図は「つもり」 → 勉強するつもりだった", "隠れた意図は「魂胆」「考え」 → 何か魂胆（考え）があって"], "ex": "社会人としての<b>心構え</b>を、先輩から教わった。"}
};
